-- Source: 040_multi_tenant_rbac.sql
-- 3. Context Switcher RPC
CREATE OR REPLACE FUNCTION public.switch_user_context(
    p_organization_id UUID,
    p_brand_id UUID DEFAULT NULL,
    p_location_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_user_id UUID;
    v_role TEXT;
BEGIN
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Verify membership in the organization
    SELECT role INTO v_role
    FROM public.organization_members
    WHERE organization_id = p_organization_id AND user_id = v_user_id;

    IF v_role IS NULL AND (SELECT COALESCE(auth.jwt() -> 'app_metadata' ->> 'role', '') != 'platform_admin') THEN
        RAISE EXCEPTION 'User is not a member of this organization';
    END IF;

    IF v_role IS NULL THEN
        -- If platform admin, keep their role
        v_role := 'platform_admin';
    END IF;

    -- Update app_metadata for fast RLS checks (Preserves existing workflow)
    UPDATE auth.users
    SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
        'role', v_role,
        'organization_id', p_organization_id::text,
        'brand_id', COALESCE(p_brand_id::text, null),
        'location_id', COALESCE(p_location_id::text, null)
    )
    WHERE id = v_user_id;

    -- Also update profile to keep legacy queries from breaking
    UPDATE public.profiles
    SET organization_id = p_organization_id,
        brand_id = p_brand_id,
        location_id = p_location_id,
        role = v_role,
        updated_at = now()
    WHERE id = v_user_id;

    RETURN jsonb_build_object(
        'success', true,
        'role', v_role,
        'organization_id', p_organization_id,
        'brand_id', p_brand_id,
        'location_id', p_location_id
    );
END;
$$;

-- 4. Update setup_organization_full to insert into members table
CREATE OR REPLACE FUNCTION public.setup_organization_full(
  p_user_id UUID,
  p_org_name TEXT,
  p_org_slug TEXT,
  p_brand_name TEXT,
  p_location_name TEXT,
  p_location_address TEXT DEFAULT ''
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  INSERT INTO public.organizations (name, slug, owner_id)
  VALUES (p_org_name, p_org_slug, p_user_id)
  RETURNING id INTO v_org_id;

  INSERT INTO public.brands (organization_id, name)
  VALUES (v_org_id, p_brand_name)
  RETURNING id INTO v_brand_id;

  INSERT INTO public.locations (organization_id, brand_id, name, address)
  VALUES (v_org_id, v_brand_id, p_location_name, p_location_address)
  RETURNING id INTO v_location_id;

  -- Insert into new multi-tenant tables
  INSERT INTO public.organization_members (organization_id, user_id, role) VALUES (v_org_id, p_user_id, 'org_owner');
  INSERT INTO public.brand_members (brand_id, user_id, role) VALUES (v_brand_id, p_user_id, 'org_owner');
  INSERT INTO public.location_members (location_id, user_id, role) VALUES (v_location_id, p_user_id, 'org_owner');

  -- Update profiles for fallback
  UPDATE public.profiles
  SET organization_id = v_org_id,
      brand_id        = v_brand_id,
      location_id     = v_location_id,
      role            = 'org_owner',
      access_level    = 'organization',
      updated_at      = now()
  WHERE id = p_user_id;

  -- Update app_metadata
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'org_owner',
    'organization_id', v_org_id::text
  )
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'org_id',      v_org_id,
    'brand_id',    v_brand_id,
    'location_id', v_location_id
  );
END;
$$;

-- 5. Update accept_invitation to insert into members table
CREATE OR REPLACE FUNCTION public.accept_invitation(p_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite RECORD;
  v_user_id UUID;
  v_user_email TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND LOWER(email) = LOWER(v_user_email);

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  -- Insert into new multi-tenant tables
  INSERT INTO public.organization_members (organization_id, user_id, role) 
  VALUES (v_invite.organization_id, v_user_id, v_invite.role)
  ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  
  IF v_invite.brand_id IS NOT NULL THEN
      INSERT INTO public.brand_members (brand_id, user_id, role) 
      VALUES (v_invite.brand_id, v_user_id, v_invite.role)
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
      INSERT INTO public.location_members (location_id, user_id, role) 
      VALUES (v_invite.location_id, v_user_id, v_invite.role)
      ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET role            = v_invite.role,
      organization_id = v_invite.organization_id,
      brand_id        = COALESCE(v_invite.brand_id, brand_id),
      location_id     = COALESCE(v_invite.location_id, location_id),
      updated_at      = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id
  WHERE id = v_invite.id;

  -- Update app_metadata for fast RLS
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_invite.role,
    'organization_id', v_invite.organization_id::text
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success',         true,
    'role',            v_invite.role,
    'organization_id', v_invite.organization_id
  );
END;
$$;

-- 6. Update admin_update_user_role to update members table
CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id    UUID,
  new_role          TEXT,
  new_status        TEXT         DEFAULT NULL,
  new_department    TEXT         DEFAULT NULL,
  new_location      TEXT         DEFAULT NULL,
  new_permissions   JSONB        DEFAULT NULL,
  new_brand_id      UUID         DEFAULT NULL,
  new_location_id   UUID         DEFAULT NULL,
  new_access_level  TEXT         DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
  target_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := public.get_auth_org();

  IF caller_role NOT IN ('org_owner', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can update user roles';
  END IF;

  SELECT organization_id INTO target_org
  FROM public.profiles
  WHERE id = target_user_id;

  IF caller_role = 'org_owner' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND new_role IS NOT NULL THEN
    IF NOT public.can_invite_role(new_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND caller_role = 'org_owner' AND new_role != 'org_owner' THEN
    RAISE EXCEPTION 'Cannot change your own role. Transfer ownership first.';
  END IF;
  
  -- Update membership tables
  IF new_role IS NOT NULL AND target_org IS NOT NULL THEN
      INSERT INTO public.organization_members (organization_id, user_id, role)
      VALUES (target_org, target_user_id, new_role)
      ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET role         = COALESCE(new_role, role),
      status       = COALESCE(new_status, status),
      department   = COALESCE(new_department, department),
      permissions  = COALESCE(new_permissions, permissions),
      brand_id     = COALESCE(new_brand_id, brand_id),
      location_id  = COALESCE(new_location_id, location_id),
      access_level = COALESCE(new_access_level, access_level),
      updated_at   = now()
  WHERE id = target_user_id;

  -- Only update app_metadata if this is their ACTIVE org, otherwise let it be
  -- (If we update their app_metadata here blindly, we might kick them out of their current context)
  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = target_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
        'role', COALESCE(new_role, (SELECT role FROM public.profiles WHERE id = target_user_id))
      )
      WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- 7. Add fetch_user_access_tree RPC for Frontend Context Initialization
CREATE OR REPLACE FUNCTION public.fetch_user_access_tree()
RETURNS JSONB
LANGUAGE sql
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT jsonb_agg(
    jsonb_build_object(
      'organization', row_to_json(o.*),
      'role', om.role,
      'brands', (
        SELECT jsonb_agg(
          jsonb_build_object(
            'brand', row_to_json(b.*),
            'role', bm.role,
            'locations', (
              SELECT jsonb_agg(
                jsonb_build_object(
                  'location', row_to_json(l.*),
                  'role', lm.role
                )
              )
              FROM public.location_members lm
              JOIN public.locations l ON l.id = lm.location_id
              WHERE lm.user_id = auth.uid() AND l.brand_id = b.id
            )
          )
        )
        FROM public.brand_members bm
        JOIN public.brands b ON b.id = bm.brand_id
        WHERE bm.user_id = auth.uid() AND b.organization_id = o.id
      )
    )
  )
  FROM public.organization_members om
  JOIN public.organizations o ON o.id = om.organization_id
  WHERE om.user_id = auth.uid();
$$;

-- Source: 041_admin_delete_user.sql
-- 2. Function to safely delete and archive a user
CREATE OR REPLACE FUNCTION public.admin_delete_user(target_user_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    caller_role TEXT;
    v_email TEXT;
    v_full_name TEXT;
    v_role TEXT;
BEGIN
    -- 1. Check if caller is authenticated
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- 2. Verify the caller is a platform_admin
    caller_role := COALESCE(auth.jwt() -> 'app_metadata' ->> 'role', '');
    
    IF caller_role != 'platform_admin' THEN
        RAISE EXCEPTION 'Insufficient permissions: only platform_admin can delete users permanently';
    END IF;

    -- 3. Prevent self-deletion via this route
    IF target_user_id = auth.uid() THEN
        RAISE EXCEPTION 'You cannot delete your own account.';
    END IF;

    -- 4. Gather user details before deletion for the archive
    SELECT email, full_name, role INTO v_email, v_full_name, v_role
    FROM public.profiles
    WHERE id = target_user_id;

    -- If profile was missing, fallback to auth.users for email
    IF v_email IS NULL THEN
        SELECT email INTO v_email FROM auth.users WHERE id = target_user_id;
    END IF;

    -- 5. Archive the user
    INSERT INTO public.archived_users (original_user_id, email, full_name, role, deleted_by)
    VALUES (target_user_id, v_email, v_full_name, v_role, auth.uid());

    -- 6. Delete the user from auth.users
    -- Because this function is SECURITY DEFINER, it runs with the privileges 
    -- of the user who created it (postgres superuser during migrations),
    -- allowing it to safely bypass the auth schema restrictions.
    DELETE FROM auth.users WHERE id = target_user_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Source: 042_org_member_management_rpcs.sql
-- ============================================================
-- Migration 042: Org Member Management RPCs
-- ============================================================

-- 1. org_remove_member
-- Allows an org_owner to safely remove a user from their organization.
CREATE OR REPLACE FUNCTION public.org_remove_member(
    target_user_id UUID,
    target_org_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
  active_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := COALESCE(target_org_id, public.get_auth_org());

  IF caller_role != 'org_owner' AND caller_role != 'platform_admin' THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can remove users';
  END IF;

  IF target_user_id = auth.uid() THEN
    RAISE EXCEPTION 'You cannot remove yourself. Transfer ownership first.';
  END IF;

  -- Remove from organization_members
  DELETE FROM public.organization_members 
  WHERE user_id = target_user_id AND organization_id = caller_org;
  
  -- Remove from brand_members for this org
  DELETE FROM public.brand_members 
  WHERE user_id = target_user_id 
    AND brand_id IN (SELECT id FROM public.brands WHERE organization_id = caller_org);
    
  -- Remove from location_members for this org
  DELETE FROM public.location_members 
  WHERE user_id = target_user_id 
    AND location_id IN (SELECT id FROM public.locations WHERE organization_id = caller_org);

  -- Update profiles if this was their active org
  UPDATE public.profiles 
  SET organization_id = NULL, brand_id = NULL, location_id = NULL, role = 'ground_staff'
  WHERE id = target_user_id AND organization_id = caller_org;

  -- Update app_metadata if this is their active context
  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = caller_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = raw_app_meta_data - 'organization_id' - 'role' - 'brand_id' - 'location_id'
      WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- 2. Update admin_update_user_role to support signing_privileges
CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id    UUID,
  new_role          TEXT         DEFAULT NULL,
  new_status        TEXT         DEFAULT NULL,
  new_department    TEXT         DEFAULT NULL,
  new_location      TEXT         DEFAULT NULL,
  new_permissions   JSONB        DEFAULT NULL,
  new_brand_id      UUID         DEFAULT NULL,
  new_location_id   UUID         DEFAULT NULL,
  new_access_level  TEXT         DEFAULT NULL,
  new_signing_privileges JSONB   DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
  target_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := public.get_auth_org();

  IF caller_role NOT IN ('org_owner', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can update user roles';
  END IF;

  SELECT organization_id INTO target_org
  FROM public.profiles
  WHERE id = target_user_id;

  IF caller_role = 'org_owner' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND new_role IS NOT NULL THEN
    IF NOT public.can_invite_role(new_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND caller_role = 'org_owner' AND new_role != 'org_owner' THEN
    RAISE EXCEPTION 'Cannot change your own role. Transfer ownership first.';
  END IF;
  
  -- Update membership tables
  IF new_role IS NOT NULL AND target_org IS NOT NULL THEN
      INSERT INTO public.organization_members (organization_id, user_id, role)
      VALUES (target_org, target_user_id, new_role)
      ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET role               = COALESCE(new_role, role),
      status             = COALESCE(new_status, status),
      department         = COALESCE(new_department, department),
      permissions        = COALESCE(new_permissions, permissions),
      signing_privileges = COALESCE(new_signing_privileges, signing_privileges),
      brand_id           = COALESCE(new_brand_id, brand_id),
      location_id        = COALESCE(new_location_id, location_id),
      access_level       = COALESCE(new_access_level, access_level),
      updated_at         = now()
  WHERE id = target_user_id;

  -- Only update app_metadata if this is their ACTIVE org
  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = target_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
        'role', COALESCE(new_role, (SELECT role FROM public.profiles WHERE id = target_user_id))
      )
      WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Source: 044_recipe_margin_protection.sql
-- 2. Create the trigger function for product price updates
CREATE OR REPLACE FUNCTION public.recalculate_recipe_costs_on_price_change()
RETURNS TRIGGER AS $$
DECLARE
    r RECORD;
    new_ingredients JSONB;
    new_ingredient_cost NUMERIC(10,2);
    new_total_cost NUMERIC(10,2);
    new_cost_per_serving NUMERIC(10,2);
    new_margin NUMERIC(5,2);
    price_to_use NUMERIC(10,2);
BEGIN
    -- Only proceed if the price actually changed
    IF NEW.latest_price IS NULL OR NEW.latest_price = OLD.latest_price THEN
        RETURN NEW;
    END IF;

    -- Find recipes that use this product in their ingredients jsonb
    -- We cast id to text because jsonb typically stores it as text.
    FOR r IN 
        SELECT * FROM public.recipes 
        WHERE ingredients @> jsonb_build_array(jsonb_build_object('product_id', NEW.id::text))
    LOOP
        -- Rebuild the ingredients array with the new price
        SELECT 
            jsonb_agg(
                CASE 
                    WHEN elem->>'product_id' = NEW.id::text THEN
                        jsonb_set(
                            jsonb_set(
                                elem, 
                                '{unit_cost}', 
                                to_jsonb(NEW.latest_price)
                            ),
                            '{total_cost}',
                            to_jsonb(ROUND(((elem->>'quantity')::numeric * NEW.latest_price), 2))
                        )
                    ELSE elem
                END
            ),
            SUM(
                CASE 
                    WHEN elem->>'product_id' = NEW.id::text THEN ROUND(((elem->>'quantity')::numeric * NEW.latest_price), 2)
                    ELSE COALESCE((elem->>'total_cost')::numeric, 0)
                END
            )
        INTO new_ingredients, new_ingredient_cost
        FROM jsonb_array_elements(r.ingredients) AS elem;

        -- Recalculate totals
        new_total_cost := COALESCE(new_ingredient_cost, 0) + COALESCE(r.total_packaging_cost, 0) + COALESCE(r.labor_cost, 0);
        
        IF COALESCE(r.yield_quantity, 0) > 0 THEN
            new_cost_per_serving := new_total_cost / r.yield_quantity;
        ELSE
            new_cost_per_serving := new_total_cost;
        END IF;

        -- Check margin
        IF r.margin_alert_enabled AND COALESCE(r.selling_price, 0) > 0 AND r.target_margin_percent IS NOT NULL THEN
            new_margin := ((r.selling_price - new_cost_per_serving) / r.selling_price) * 100;
            
            -- If margin drops below target, create an alert
            IF new_margin < r.target_margin_percent THEN
                -- Check if an alert already exists in the last 24h to avoid spam
                IF NOT EXISTS (
                    SELECT 1 FROM public.ai_insights 
                    WHERE insight_type = 'margin_alert' 
                      AND organization_id = r.organization_id 
                      AND metadata->>'recipe_id' = r.id::text
                      AND created_at > now() - interval '24 hours'
                ) THEN
                    INSERT INTO public.ai_insights (
                        organization_id,
                        insight_type,
                        severity,
                        title,
                        description,
                        metadata
                    ) VALUES (
                        r.organization_id,
                        'margin_alert',
                        'high',
                        'Margin Alert: ' || r.name,
                        'The cost of ' || NEW.name || ' increased to $' || NEW.latest_price || '. The estimated margin for ' || r.name || ' has dropped to ' || round(new_margin, 1) || '%, which is below your target of ' || r.target_margin_percent || '%.',
                        jsonb_build_object(
                            'recipe_id', r.id, 
                            'product_id', NEW.id, 
                            'new_margin', new_margin,
                            'target_margin', r.target_margin_percent,
                            'action', jsonb_build_object(
                                'type', 'adjust_recipe_price',
                                'label', 'Update Pricing',
                                'payload', jsonb_build_object('recipe_id', r.id)
                            )
                        )
                    );
                END IF;
            END IF;
        END IF;

        -- Update the recipe
        UPDATE public.recipes 
        SET 
            ingredients = new_ingredients,
            total_ingredient_cost = new_ingredient_cost,
            total_cost = new_total_cost,
            cost_per_serving = new_cost_per_serving,
            updated_at = now()
        WHERE id = r.id;

    END LOOP;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Source: 045_pos_avt_costing.sql
-- 4. Trigger Function for Theoretical Inventory Depletion
CREATE OR REPLACE FUNCTION public.process_pos_sales_to_inventory()
RETURNS TRIGGER AS $$
DECLARE
    v_recipe_id UUID;
    r RECORD;
    v_inventory_id UUID;
    v_old_qty NUMERIC(10,2);
    v_new_qty NUMERIC(10,2);
    v_movement_qty NUMERIC(10,2);
BEGIN
    -- Find mapped recipe
    SELECT recipe_id INTO v_recipe_id 
    FROM public.pos_menu_mapping 
    WHERE pos_item_id = NEW.pos_item_id AND organization_id = NEW.organization_id
    LIMIT 1;

    -- If there's a mapping, deplete ingredients
    IF v_recipe_id IS NOT NULL THEN
        FOR r IN 
            SELECT p.product_id AS prod_text_id, ri.quantity AS recipe_qty
            FROM public.recipe_ingredients ri
            JOIN public.products p ON p.id = ri.product_id
            WHERE ri.recipe_id = v_recipe_id AND ri.organization_id = NEW.organization_id
        LOOP
            -- Find inventory record by product_id (text)
            SELECT id, current_quantity 
            INTO v_inventory_id, v_old_qty 
            FROM public.inventory 
            WHERE product_id = r.prod_text_id AND organization_id = NEW.organization_id
            LIMIT 1;

            IF v_inventory_id IS NOT NULL THEN
                -- Calculate movement quantity (theoretical consumption)
                v_movement_qty := r.recipe_qty * NEW.quantity_sold;
                v_new_qty := COALESCE(v_old_qty, 0) - v_movement_qty;

                -- Update inventory
                UPDATE public.inventory 
                SET current_quantity = v_new_qty, updated_at = now()
                WHERE id = v_inventory_id;

                -- Insert into inventory_movements
                INSERT INTO public.inventory_movements (
                    organization_id, location_id, inventory_id, movement_type, 
                    quantity, source_type, source_id, previous_quantity, new_quantity
                ) VALUES (
                    NEW.organization_id, NEW.location_id, v_inventory_id, 'recipe_consumption',
                    -v_movement_qty, 'pos_sale', NEW.id, COALESCE(v_old_qty, 0), v_new_qty
                );
            END IF;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 046_storage_security.sql
-- Migration 046: Storage Security Policies
-- Enforces file type (MIME) and file size constraints on uploads to prevent malicious payloads

-- 1. Create a secure database-driven helper for platform_admin role
CREATE OR REPLACE FUNCTION public.is_platform_admin()
RETURNS boolean AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = auth.uid() AND role = 'platform_admin'
  );
$$ LANGUAGE sql SECURITY DEFINER STABLE;

CREATE OR REPLACE FUNCTION public.check_file_security(bucket text, metadata jsonb)
RETURNS boolean AS $$
DECLARE
    file_size int;
    mime_type text;
BEGIN
    file_size := (metadata->>'size')::int;
    mime_type := metadata->>'mimetype';

    -- 1. Restrict File Size to 10MB (10 * 1024 * 1024 = 10485760 bytes)
    IF file_size > 10485760 THEN
        RETURN false;
    END IF;

    -- 2. Restrict MIME Types
    IF bucket = 'avatars' THEN
        IF mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp') THEN
            RETURN false;
        END IF;
    ELSIF bucket = 'invoices' THEN
        IF mime_type NOT IN ('application/pdf', 'image/jpeg', 'image/png', 'text/csv') THEN
            RETURN false;
        END IF;
    ELSE
        -- Fallback for any future bucket
        IF mime_type NOT IN ('application/pdf', 'image/jpeg', 'image/png', 'text/csv', 'image/webp') THEN
            RETURN false;
        END IF;
    END IF;

    RETURN true;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

