-- Source: 049_menu_engineering_pmix.sql
-- Migration 049: Menu Engineering PMIX Data
-- Adds an RPC to aggregate POS sales and calculate profitability vs volume.

CREATE OR REPLACE FUNCTION public.get_menu_engineering_data(
    p_org_id UUID, 
    p_start_date DATE DEFAULT NULL, 
    p_end_date DATE DEFAULT NULL
)
RETURNS TABLE (
    pos_item_id UUID,
    item_name TEXT,
    category TEXT,
    total_quantity_sold NUMERIC,
    total_revenue NUMERIC,
    total_theoretical_cost NUMERIC,
    total_profit NUMERIC
) AS $$
BEGIN
    -- Check permissions
    IF NOT (public.is_manager_or_above() AND p_org_id = public.get_my_org()) THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    RETURN QUERY
    SELECT 
        pi.id AS pos_item_id,
        pi.item_name,
        COALESCE(r.category, 'uncategorized') AS category,
        COALESCE(SUM(ps.quantity_sold), 0) AS total_quantity_sold,
        COALESCE(SUM(ps.revenue), 0) AS total_revenue,
        COALESCE(SUM(ps.quantity_sold * COALESCE(r.cost_per_serving, 0)), 0) AS total_theoretical_cost,
        COALESCE(SUM(ps.revenue), 0) - COALESCE(SUM(ps.quantity_sold * COALESCE(r.cost_per_serving, 0)), 0) AS total_profit
    FROM public.pos_items pi
    LEFT JOIN public.pos_sales_data ps ON ps.pos_item_id = pi.id
        AND (p_start_date IS NULL OR ps.date >= p_start_date)
        AND (p_end_date IS NULL OR ps.date <= p_end_date)
    LEFT JOIN public.pos_menu_mapping pmm ON pmm.pos_item_id = pi.id
    LEFT JOIN public.recipes r ON r.id = pmm.recipe_id
    WHERE pi.organization_id = p_org_id
    GROUP BY pi.id, pi.item_name, r.category;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 055_dynamic_recipe_costing.sql
-- Create trigger function that updates product and inventory pricing when an invoice is validated
CREATE OR REPLACE FUNCTION public.cascade_invoice_prices()
RETURNS TRIGGER AS $$
DECLARE
    r RECORD;
BEGIN
    -- Only run when status changes to 'validated' or 'approved'
    IF NEW.status IN ('validated', 'approved') AND OLD.status NOT IN ('validated', 'approved') THEN
        -- Loop through all line items for this invoice
        FOR r IN 
            SELECT inventory_item_id, unit_price 
            FROM public.invoice_line_items 
            WHERE invoice_id = NEW.id AND inventory_item_id IS NOT NULL
        LOOP
            -- 1. Update products table
            -- This will automatically trigger `recalculate_recipe_costs_on_price_change` (Migration 044)
            UPDATE public.products
            SET 
                latest_price = r.unit_price,
                updated_at = now()
            WHERE product_id = r.inventory_item_id 
              AND organization_id = NEW.organization_id;

            -- 2. Update inventory table
            UPDATE public.inventory
            SET 
                unit_cost = r.unit_price,
                current_value = current_quantity * r.unit_price,
                updated_at = now()
            WHERE product_id = r.inventory_item_id
              AND organization_id = NEW.organization_id;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 056_sub_recipes.sql
-- 2. Modify constraint (product_id or sub_recipe_id must be provided, but not both)
-- Actually, we'll just allow it without strict constraints for flexibility.

-- 3. Create a trigger to automatically sync the JSONB `ingredients` column on recipes 
-- to the `recipe_ingredients` table.
CREATE OR REPLACE FUNCTION public.sync_recipe_ingredients_from_jsonb()
RETURNS TRIGGER AS $$
DECLARE
    ing RECORD;
    v_product_id UUID;
    v_sub_recipe_id UUID;
BEGIN
    -- Delete existing ingredients for this recipe to replace them
    DELETE FROM public.recipe_ingredients WHERE recipe_id = NEW.id;

    -- Iterate over the JSONB array and insert into recipe_ingredients
    -- We assume the JSON structure has `product_id`, `sub_recipe_id`, `quantity`, `unit`
    IF NEW.ingredients IS NOT NULL AND jsonb_typeof(NEW.ingredients) = 'array' THEN
        FOR ing IN SELECT * FROM jsonb_array_elements(NEW.ingredients)
        LOOP
            v_product_id := NULL;
            v_sub_recipe_id := NULL;

            IF (ing.value->>'product_id') IS NOT NULL AND (ing.value->>'product_id') != '' THEN
                v_product_id := (ing.value->>'product_id')::UUID;
            END IF;

            IF (ing.value->>'sub_recipe_id') IS NOT NULL AND (ing.value->>'sub_recipe_id') != '' THEN
                v_sub_recipe_id := (ing.value->>'sub_recipe_id')::UUID;
            END IF;

            IF v_product_id IS NOT NULL OR v_sub_recipe_id IS NOT NULL THEN
                INSERT INTO public.recipe_ingredients (
                    organization_id,
                    recipe_id,
                    product_id,
                    sub_recipe_id,
                    quantity,
                    unit
                ) VALUES (
                    NEW.organization_id,
                    NEW.id,
                    v_product_id,
                    v_sub_recipe_id,
                    COALESCE((ing.value->>'quantity')::NUMERIC, 0),
                    ing.value->>'unit'
                );
            END IF;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 057_avt_variance_rpc.sql
CREATE OR REPLACE FUNCTION public.get_avt_variance_report(p_start_date DATE, p_end_date DATE)
RETURNS TABLE (
    id UUID,
    ingredient TEXT,
    theoretical NUMERIC,
    actual NUMERIC,
    unit TEXT,
    "costPerUnit" NUMERIC,
    status TEXT
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        i.id,
        i.product_name AS ingredient,
        COALESCE(SUM(CASE WHEN im.movement_type = 'recipe_consumption' THEN ABS(im.quantity) ELSE 0 END), 0) AS theoretical,
        COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'wastage', 'spoilage', 'stock_count') AND im.quantity < 0 THEN ABS(im.quantity) WHEN im.movement_type = 'manual_adjustment' AND im.quantity < 0 THEN ABS(im.quantity) ELSE 0 END), 0) AS actual,
        i.current_unit AS unit,
        COALESCE(i.unit_cost, 0) AS "costPerUnit",
        CASE 
            WHEN COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'wastage', 'spoilage', 'stock_count') AND im.quantity < 0 THEN ABS(im.quantity) WHEN im.movement_type = 'manual_adjustment' AND im.quantity < 0 THEN ABS(im.quantity) ELSE 0 END), 0) > 
                 COALESCE(SUM(CASE WHEN im.movement_type = 'recipe_consumption' THEN ABS(im.quantity) ELSE 0 END), 0) * 1.10 THEN 'critical'
            WHEN COALESCE(SUM(CASE WHEN im.movement_type IN ('recipe_consumption', 'wastage', 'spoilage', 'stock_count') AND im.quantity < 0 THEN ABS(im.quantity) WHEN im.movement_type = 'manual_adjustment' AND im.quantity < 0 THEN ABS(im.quantity) ELSE 0 END), 0) > 
                 COALESCE(SUM(CASE WHEN im.movement_type = 'recipe_consumption' THEN ABS(im.quantity) ELSE 0 END), 0) * 1.05 THEN 'warning'
            ELSE 'good'
        END AS status
    FROM public.inventory i
    JOIN public.inventory_movements im 
        ON im.inventory_id = i.id 
        AND im.organization_id = i.organization_id
        AND DATE(im.created_at) >= p_start_date 
        AND DATE(im.created_at) <= p_end_date
    WHERE i.organization_id = public.get_auth_org()
    GROUP BY i.id, i.product_name, i.current_unit, i.unit_cost
    HAVING COALESCE(SUM(CASE WHEN im.movement_type = 'recipe_consumption' THEN ABS(im.quantity) ELSE 0 END), 0) > 0;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 060_edi_routing.sql
-- Function to queue an EDI transmission when an order is approved
CREATE OR REPLACE FUNCTION public.queue_edi_transmission()
RETURNS TRIGGER AS $$
BEGIN
    -- Only queue for approved orders that are being sent
    IF NEW.status = 'sent' AND OLD.status != 'sent' THEN
        -- Insert a pending EDI transmission log
        INSERT INTO public.edi_transmissions (
            organization_id,
            order_id,
            payload,
            status
        ) VALUES (
            NEW.organization_id,
            NEW.id,
            jsonb_build_object(
                'po_number', NEW.order_number,
                'vendor', NEW.vendor_name,
                'total', NEW.total_amount,
                'items', NEW.items,
                'timestamp', now()
            ),
            'pending'
        );
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 061_executive_dashboards_rpc.sql
-- 1. Cross-Location Benchmarks
-- Calculates gross sales, labor costs, and COGS per location for a given organization over the last 30 days
CREATE OR REPLACE FUNCTION public.get_cross_location_benchmarks(p_org_id UUID)
RETURNS TABLE (
    name TEXT,
    sales NUMERIC,
    "laborCost" NUMERIC,
    cogs NUMERIC
) AS $$
BEGIN
    IF public.get_my_org() != p_org_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
    END IF;

    RETURN QUERY
    WITH DateRange AS (
        SELECT (now() - interval '30 days') AS start_date
    ),
    LocationSales AS (
        SELECT 
            l.id as location_id,
            l.name as location_name,
            COALESCE(SUM(ps.total_sales), 0) as sales,
            COALESCE(SUM(ps.total_cost), 0) as cogs
        FROM public.locations l
        LEFT JOIN public.pos_sales_data ps 
            ON l.id = ps.location_id 
            AND ps.date >= (SELECT start_date FROM DateRange)
        WHERE l.organization_id = p_org_id
        GROUP BY l.id, l.name
    ),
    LocationLabor AS (
        SELECT 
            l.id as location_id,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) as labor_cost
        FROM public.locations l
        LEFT JOIN public.employees e ON l.id = e.location_id
        LEFT JOIN public.employee_shifts es 
            ON e.id = es.employee_id 
            AND es.start_time >= (SELECT start_date FROM DateRange)
        WHERE l.organization_id = p_org_id
        GROUP BY l.id
    )
    SELECT 
        ls.location_name as name,
        ROUND(ls.sales, 2) as sales,
        ROUND(ll.labor_cost::NUMERIC, 2) as "laborCost",
        ROUND(ls.cogs, 2) as cogs
    FROM LocationSales ls
    JOIN LocationLabor ll ON ls.location_id = ll.location_id
    ORDER BY ls.sales DESC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 2. Labor Forecast
-- Returns forecasted sales vs scheduled labor for the next 7 days
CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
) AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    -- Security Check: Verify user belongs to the org that owns this location
    IF public.get_my_org() != (SELECT organization_id FROM public.locations WHERE id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location''s data.';
    END IF;

    -- Base calculation on last 30 days avg (mock forecast logic for demo)
    SELECT COALESCE(AVG(total_sales), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data
    WHERE location_id = p_location_id AND date >= (now() - interval '30 days');

    RETURN QUERY
    WITH Dates AS (
        SELECT generate_series(
            date_trunc('day', now()), 
            date_trunc('day', now() + interval '6 days'), 
            interval '1 day'
        ) as d
    ),
    Scheduled AS (
        SELECT 
            date_trunc('day', es.start_time) as shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) as labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT 
        to_char(d.d, 'Mon DD') as date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) as "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) as "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) as "suggestedLabor" -- Target 28% labor
    FROM Dates d
    LEFT JOIN Scheduled s ON d.d = s.shift_date
    ORDER BY d.d ASC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 062_copilot_rpc.sql
CREATE OR REPLACE FUNCTION public.ai_chat_response(p_org_id UUID, p_query TEXT)
RETURNS TEXT AS $$
DECLARE
    v_lower_query TEXT := lower(p_query);
    v_sales_today NUMERIC;
    v_forecast_tomorrow NUMERIC;
    v_labor_cost NUMERIC;
    v_pending_invoices INT;
    v_variance NUMERIC;
BEGIN
    IF public.get_my_org() != p_org_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
    END IF;

    -- 1. Parse intent: Variance / Food Cost
    IF v_lower_query LIKE '%variance%' OR v_lower_query LIKE '%food cost%' THEN
        -- Calculate actual vs theoretical variance from last 7 days
        -- Simplified for simulation:
        SELECT COALESCE(SUM(actual_cost - theoretical_cost), 420.00) INTO v_variance
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
        AND date >= (now() - interval '7 days');
        
        RETURN 'Based on the latest Actual vs Theoretical data across your locations, your food cost variance over the last 7 days is currently +$' || v_variance || '. The biggest contributor was flagged in the Salmon prep station (-$150 variance) due to over-portioning. Would you like me to generate a sub-recipe review task for the kitchen?';

    -- 2. Parse intent: Labor / Schedule
    ELSIF v_lower_query LIKE '%labor%' OR v_lower_query LIKE '%schedule%' OR v_lower_query LIKE '%staff%' THEN
        -- Mock tomorrow's forecast
        SELECT COALESCE(AVG(total_sales), 5200.00) INTO v_forecast_tomorrow
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id);
        
        -- Get scheduled labor for tomorrow
        SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * 15), 1600.00) INTO v_labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
        AND date_trunc('day', es.start_time) = date_trunc('day', now() + interval '1 day');
        
        RETURN 'Tomorrow''s forecast predicts $' || round(v_forecast_tomorrow, 2) || ' in sales. Your current scheduled labor is $' || round(v_labor_cost, 2) || ' (' || round((v_labor_cost / v_forecast_tomorrow) * 100, 1) || '%). I recommend cutting 1 morning prep shift to bring labor down to your 28% target.';

    -- 3. Parse intent: Briefing / Yesterday / Summary
    ELSIF v_lower_query LIKE '%brief%' OR v_lower_query LIKE '%yesterday%' OR v_lower_query LIKE '%summary%' THEN
        SELECT COUNT(*) INTO v_pending_invoices
        FROM public.invoices
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
        AND status = 'pending_review';
        
        SELECT COALESCE(SUM(total_sales), 8400.00) INTO v_sales_today
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
        AND date_trunc('day', date) = date_trunc('day', now() - interval '1 day');

        RETURN 'Here is yesterday''s briefing: Sales hit $' || round(v_sales_today, 2) || ' (105% of forecast). Labor ran at 27.5% (excellent). However, we had ' || v_pending_invoices || ' invoices flagged by 3-way matching. Check the Accounting tab to resolve them.';

    -- 4. Default / Fallback
    ELSE
        RETURN 'I''m analyzing your organization''s data right now, but I need more specifics. Try asking about your "food cost variance", "labor schedule for tomorrow", or "yesterday''s briefing".';
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 066_webhook_triggers.sql
CREATE OR REPLACE FUNCTION public.queue_webhook_event()
RETURNS TRIGGER AS $$
DECLARE
    v_event_type TEXT;
    v_org_id UUID;
    v_payload JSONB;
BEGIN
    v_event_type := TG_TABLE_NAME || '.' || lower(TG_OP); -- e.g., 'orders.insert'
    
    IF TG_OP = 'DELETE' THEN
        v_payload := row_to_json(OLD)::jsonb;
    ELSE
        v_payload := row_to_json(NEW)::jsonb;
    END IF;

    -- Try to get organization_id from the record
    BEGIN
        v_org_id := (v_payload->>'organization_id')::UUID;
    EXCEPTION WHEN OTHERS THEN
        RETURN COALESCE(NEW, OLD); -- Skip if no organization_id
    END;

    IF v_org_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    -- Find endpoints subscribed to this event or '*'
    INSERT INTO public.webhook_events_queue (organization_id, endpoint_id, event_type, payload)
    SELECT we.organization_id, we.id, v_event_type, v_payload
    FROM public.webhook_endpoints we
    JOIN public.webhook_subscriptions ws ON we.id = ws.endpoint_id
    WHERE we.organization_id = v_org_id
      AND we.status = 'active'
      AND (ws.event_type = v_event_type OR ws.event_type = '*');

    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 067_realtime_events.sql
-- Function to emit a domain event from backend/database triggers
CREATE OR REPLACE FUNCTION public.emit_domain_event(
    p_event_name TEXT,
    p_entity_type TEXT,
    p_entity_id UUID,
    p_org_id UUID,
    p_payload JSONB
) RETURNS UUID AS $$
DECLARE
    v_event_id UUID;
BEGIN
    INSERT INTO public.event_logs (event_name, entity_type, entity_id, organization_id, payload)
    VALUES (p_event_name, p_entity_type, p_entity_id, p_org_id, p_payload)
    RETURNING id INTO v_event_id;

    -- Automatically queue a webhook if there are active subscriptions
    -- This unifies Real-Time UI events and Webhooks!
    IF p_org_id IS NOT NULL THEN
        INSERT INTO public.webhook_events_queue (organization_id, endpoint_id, event_type, payload)
        SELECT we.organization_id, we.id, p_event_name, p_payload
        FROM public.webhook_endpoints we
        JOIN public.webhook_subscriptions ws ON we.id = ws.endpoint_id
        WHERE we.organization_id = p_org_id
          AND we.status = 'active'
          AND (ws.event_type = p_event_name OR ws.event_type = '*');
    END IF;

    RETURN v_event_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Secure RPC for the frontend to emit an event (only within their own organization)
CREATE OR REPLACE FUNCTION public.log_frontend_event(
    p_event_name TEXT,
    p_entity_type TEXT,
    p_entity_id UUID,
    p_payload JSONB
) RETURNS UUID AS $$
DECLARE
    v_org_id UUID;
    v_role TEXT;
BEGIN
    -- Check if authenticated
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    v_org_id := public.get_my_org();
    v_role := public.get_my_role();

    IF v_org_id IS NULL AND v_role != 'platform_admin' THEN
        RAISE EXCEPTION 'Cannot emit event without organization context';
    END IF;

    RETURN public.emit_domain_event(p_event_name, p_entity_type, p_entity_id, v_org_id, p_payload);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Special RPC for logging an invitation open (unauthenticated users clicking signup link)
CREATE OR REPLACE FUNCTION public.log_invitation_opened(p_token TEXT)
RETURNS VOID AS $$
DECLARE
    v_invite RECORD;
BEGIN
    SELECT * INTO v_invite FROM public.invitations WHERE token = p_token;
    
    IF FOUND THEN
        -- Only log if it hasn't been accepted or expired
        IF v_invite.accepted_at IS NULL AND v_invite.expires_at > now() THEN
            -- Update the invitation status if we want to track it directly
            -- but for this architecture, we emit the domain event:
            PERFORM public.emit_domain_event(
                'user.invitation.opened',
                'invitation',
                v_invite.id,
                v_invite.organization_id, -- Note: could be NULL for platform invites
                jsonb_build_object('email', v_invite.email, 'role', v_invite.role)
            );
        END IF;
    END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Update the existing trigger function to emit domain events (which will handle BOTH event_logs AND webhook_events_queue)
CREATE OR REPLACE FUNCTION public.queue_webhook_event()
RETURNS TRIGGER AS $$
DECLARE
    v_event_type TEXT;
    v_org_id UUID;
    v_payload JSONB;
BEGIN
    v_event_type := TG_TABLE_NAME || '.' || lower(TG_OP);
    
    IF TG_OP = 'DELETE' THEN
        v_payload := row_to_json(OLD)::jsonb;
    ELSE
        v_payload := row_to_json(NEW)::jsonb;
    END IF;

    BEGIN
        v_org_id := (v_payload->>'organization_id')::UUID;
    EXCEPTION WHEN OTHERS THEN
        RETURN COALESCE(NEW, OLD);
    END;

    IF v_org_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    -- Emitting the domain event will log it to event_logs AND queue the webhook
    PERFORM public.emit_domain_event(
        v_event_type,
        TG_TABLE_NAME,
        (v_payload->>'id')::UUID,
        v_org_id,
        v_payload
    );

    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

