-- Add secure integration credential storage function
CREATE OR REPLACE FUNCTION public.save_secure_integration_credential(
  p_organization_id UUID,
  p_provider TEXT,
  p_metadata JSONB,
  p_secret TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_secret_id UUID;
  v_integration_id UUID;
  v_result JSONB;
BEGIN
  -- Validate permissions
  IF NOT public.is_platform_admin() AND NOT (public.is_manager_or_above() AND public.get_my_org() = p_organization_id) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Store secret in vault
  SELECT id INTO v_secret_id FROM vault.secrets WHERE name = p_provider || '_' || p_organization_id::text;
  IF v_secret_id IS NOT NULL THEN
    -- Update existing secret (pgsodium/vault does not support direct update easily, so delete and insert)
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;
  
  SELECT * INTO v_secret_id FROM vault.create_secret(p_secret, p_provider || '_' || p_organization_id::text, 'Email IMAP Password');

  -- Update or insert integration
  SELECT id INTO v_integration_id FROM public.integrations WHERE organization_id = p_organization_id AND provider = p_provider;
  
  -- Create new metadata with secret_id instead of raw password
  p_metadata = p_metadata - 'password' || jsonb_build_object('secret_id', v_secret_id);

  IF v_integration_id IS NOT NULL THEN
    UPDATE public.integrations SET metadata = p_metadata WHERE id = v_integration_id RETURNING jsonb_build_object('id', id, 'metadata', metadata) INTO v_result;
  ELSE
    INSERT INTO public.integrations (organization_id, provider, metadata, is_active) VALUES (p_organization_id, p_provider, p_metadata, true) RETURNING jsonb_build_object('id', id, 'metadata', metadata) INTO v_result;
  END IF;

  RETURN v_result;
END;
$$;

-- Source: 081_vendor_item_matching.sql
CREATE OR REPLACE FUNCTION public.match_vendor(p_org_id UUID, p_vendor_name TEXT)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_vendor_id UUID;
  v_exact_match UUID;
  v_alias_match UUID;
  v_fuzzy_match UUID;
BEGIN
  -- 1. Exact match on vendors table
  SELECT id INTO v_exact_match FROM public.vendors 
  WHERE organization_id = p_org_id AND LOWER(name) = LOWER(p_vendor_name)
  LIMIT 1;
  
  IF v_exact_match IS NOT NULL THEN
    RETURN v_exact_match;
  END IF;

  -- 2. Exact match on vendor_aliases
  SELECT canonical_vendor_id INTO v_alias_match FROM public.vendor_aliases
  WHERE organization_id = p_org_id AND LOWER(alias_name) = LOWER(p_vendor_name) AND is_verified = true
  LIMIT 1;

  IF v_alias_match IS NOT NULL THEN
    RETURN v_alias_match;
  END IF;

  -- 3. Fuzzy match using Levenshtein distance
  -- Only consider if distance <= 3 (e.g. slight typo)
  SELECT id INTO v_fuzzy_match FROM public.vendors
  WHERE organization_id = p_org_id AND extensions.levenshtein(LOWER(name), LOWER(p_vendor_name)) <= 3
  ORDER BY extensions.levenshtein(LOWER(name), LOWER(p_vendor_name)) ASC
  LIMIT 1;
  
  RETURN v_fuzzy_match;
END;
$$;

-- Source: 082_three_way_reconciliation.sql
-- RPC: Reconcile Invoice Lines
-- Automatically matches lines and calculates variances
CREATE OR REPLACE FUNCTION public.reconcile_invoice_lines(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_org_id UUID;
  v_vendor_id UUID;
  v_po_id UUID;
  v_line RECORD;
  v_match_id UUID;
  v_variance_id UUID;
  v_tolerance RECORD;
BEGIN
  SELECT organization_id, vendor_id, purchase_order_id INTO v_org_id, v_vendor_id, v_po_id 
  FROM public.invoices WHERE id = p_invoice_id;

  -- Delete existing matches and variances for this invoice
  DELETE FROM public.invoice_line_matches WHERE invoice_line_id IN (SELECT id FROM public.invoice_line_items WHERE invoice_id = p_invoice_id);
  DELETE FROM public.reconciliation_variances WHERE invoice_id = p_invoice_id;

  -- Load Tolerance config (fallback to defaults if none exist)
  SELECT * INTO v_tolerance FROM public.tolerance_configurations 
  WHERE organization_id = v_org_id AND vendor_id = v_vendor_id LIMIT 1;
  IF NOT FOUND THEN
    v_tolerance := (NULL, v_org_id, v_vendor_id, NULL, NULL, 0.05, 1.00, 0.00, 0.00, now(), now())::public.tolerance_configurations;
  END IF;

  FOR v_line IN (SELECT * FROM public.invoice_line_items WHERE invoice_id = p_invoice_id) LOOP
    -- Simple exact match stub for demonstration. In full production, this maps to PO lines and Receipt movements.
    
    INSERT INTO public.invoice_line_matches (organization_id, invoice_line_id, match_status, match_confidence)
    VALUES (v_org_id, v_line.id, 'unmatched', 0.0)
    RETURNING id INTO v_match_id;

    -- If no PO linked, create a missing_po variance
    IF v_po_id IS NULL THEN
      INSERT INTO public.reconciliation_variances 
      (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES (v_org_id, p_invoice_id, v_line.id, 'missing_po', 0, v_line.total_price, v_line.total_price);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'reconciled_lines', (SELECT count(*) FROM public.invoice_line_items WHERE invoice_id = p_invoice_id));
END;
$$;

-- Source: 083_invoice_allocations.sql
-- RPC: Calculate Default Invoice Allocations
-- Automatically buckets line items and fees into their default GL categories
CREATE OR REPLACE FUNCTION public.calculate_invoice_allocations(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_org_id UUID;
  v_tax NUMERIC;
  v_fuel NUMERIC;
  v_delivery NUMERIC;
  v_other NUMERIC;
  
  v_cat_record RECORD;
BEGIN
  -- Get invoice details
  SELECT organization_id, tax_amount, fuel_surcharge, delivery_fee, other_charges 
  INTO v_org_id, v_tax, v_fuel, v_delivery, v_other
  FROM public.invoices WHERE id = p_invoice_id;

  -- Clear existing auto-generated allocations (this could be enhanced to preserve manual splits in the future)
  DELETE FROM public.invoice_allocations WHERE invoice_id = p_invoice_id;

  -- 1. Aggregate Line Items by Product Category
  FOR v_cat_record IN (
    SELECT 
      COALESCE(p.category, 'uncategorized') as cat_name, 
      SUM(ili.extended_price) as total_amount
    FROM public.invoice_line_items ili
    LEFT JOIN public.products p ON ili.product_id = p.id
    WHERE ili.invoice_id = p_invoice_id
    GROUP BY COALESCE(p.category, 'uncategorized')
  ) LOOP
    IF v_cat_record.total_amount > 0 THEN
      -- Attempt to find a matching GL code
      INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, gl_code, amount)
      SELECT 
        v_org_id, p_invoice_id, 'line_items', v_cat_record.cat_name, 
        (SELECT gl_code FROM public.gl_mappings WHERE organization_id = v_org_id AND LOWER(category) = LOWER(v_cat_record.cat_name) LIMIT 1),
        v_cat_record.total_amount;
    END IF;
  END LOOP;

  -- 2. Add Tax
  IF v_tax > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'tax', 'Tax', v_tax);
  END IF;

  -- 3. Add Delivery
  IF v_delivery > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'delivery', 'Delivery Fee', v_delivery);
  END IF;

  -- 4. Add Fuel
  IF v_fuel > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'fuel', 'Fuel Surcharge', v_fuel);
  END IF;

  -- 5. Add Other
  IF v_other > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'other', 'Other Charges', v_other);
  END IF;

  RETURN jsonb_build_object('success', true, 'message', 'Allocations calculated');
END;
$$;

-- Source: 084_approval_workflows.sql
-- RPC to Evaluate Policies and Start Workflow
CREATE OR REPLACE FUNCTION public.evaluate_invoice_approval_policy(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_org_id UUID;
  v_amount NUMERIC;
  v_instance_id UUID;
  v_policy RECORD;
  v_steps_created INT := 0;
BEGIN
  -- Get invoice details
  SELECT organization_id, total_amount INTO v_org_id, v_amount
  FROM public.invoices WHERE id = p_invoice_id;

  -- Cancel any existing pending instances for this invoice (e.g. if it was edited)
  UPDATE public.approval_instances 
  SET status = 'cancelled', updated_at = now()
  WHERE invoice_id = p_invoice_id AND status = 'pending';

  -- Create a new instance
  INSERT INTO public.approval_instances (invoice_id, status)
  VALUES (p_invoice_id, 'pending')
  RETURNING id INTO v_instance_id;

  -- Find matching policies
  FOR v_policy IN (
    SELECT required_role FROM public.approval_policies
    WHERE organization_id = v_org_id
      AND (min_amount IS NULL OR v_amount >= min_amount)
      AND (max_amount IS NULL OR v_amount <= max_amount)
  ) LOOP
    -- Insert a step for this policy
    -- Parallel approvals: We insert them all. Any user with the required_role can approve their step.
    INSERT INTO public.approval_steps (instance_id, required_role)
    VALUES (v_instance_id, v_policy.required_role);
    
    v_steps_created := v_steps_created + 1;
  END LOOP;

  IF v_steps_created = 0 THEN
    -- Auto-approve if no policies apply
    UPDATE public.approval_instances SET status = 'approved', updated_at = now() WHERE id = v_instance_id;
    UPDATE public.invoices SET status = 'approved', updated_at = now() WHERE id = p_invoice_id;
    RETURN jsonb_build_object('status', 'auto_approved');
  ELSE
    -- Set to pending approval
    UPDATE public.invoices SET status = 'pending_approval', updated_at = now() WHERE id = p_invoice_id;
    RETURN jsonb_build_object('status', 'pending_approval', 'steps', v_steps_created);
  END IF;
END;
$$;

-- RPC to Execute an Approval Step
CREATE OR REPLACE FUNCTION public.execute_approval_step(p_step_id UUID, p_status TEXT, p_comments TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_instance_id UUID;
  v_invoice_id UUID;
  v_pending_count INT;
BEGIN
  -- Update the step
  UPDATE public.approval_steps
  SET status = p_status::approval_step_status,
      approver_id = auth.uid(),
      comments = p_comments,
      acted_at = now()
  WHERE id = p_step_id
  RETURNING instance_id INTO v_instance_id;

  SELECT invoice_id INTO v_invoice_id FROM public.approval_instances WHERE id = v_instance_id;

  IF p_status = 'rejected' THEN
    -- If one rejects, the whole instance is rejected
    UPDATE public.approval_instances SET status = 'rejected', updated_at = now() WHERE id = v_instance_id;
    UPDATE public.invoices SET status = 'rejected', updated_at = now() WHERE id = v_invoice_id;
    RETURN jsonb_build_object('status', 'rejected');
  END IF;

  IF p_status = 'approved' THEN
    -- Check if any pending steps remain for this instance
    SELECT count(*) INTO v_pending_count FROM public.approval_steps WHERE instance_id = v_instance_id AND status = 'pending';
    
    IF v_pending_count = 0 THEN
      -- All steps approved!
      UPDATE public.approval_instances SET status = 'approved', updated_at = now() WHERE id = v_instance_id;
      UPDATE public.invoices SET status = 'approved', updated_at = now() WHERE id = v_invoice_id;
      RETURN jsonb_build_object('status', 'fully_approved');
    ELSE
      RETURN jsonb_build_object('status', 'partially_approved', 'pending_steps', v_pending_count);
    END IF;
  END IF;

  RETURN jsonb_build_object('status', 'unknown');
END;
$$;

-- Source: 085_payment_accounts.sql
-- 4. RPC to Schedule Payment
CREATE OR REPLACE FUNCTION public.schedule_invoice_payment(
  p_invoice_id UUID, 
  p_payment_account_id UUID, 
  p_date DATE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_invoice_status TEXT;
  v_org_id UUID;
BEGIN
  -- Verify the invoice exists and get its status/org
  SELECT status, organization_id INTO v_invoice_status, v_org_id 
  FROM public.invoices WHERE id = p_invoice_id;

  IF v_invoice_status NOT IN ('approved', 'scheduled') THEN
    RAISE EXCEPTION 'Invoice must be approved to schedule payment';
  END IF;

  -- Update the invoice
  UPDATE public.invoices
  SET payment_account_id = p_payment_account_id,
      scheduled_payment_date = p_date,
      status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
      ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
      updated_at = now()
  WHERE id = p_invoice_id;

  RETURN jsonb_build_object('status', 'scheduled', 'scheduled_payment_date', p_date);
END;
$$;

-- 5. RPC to Record Payment
CREATE OR REPLACE FUNCTION public.record_invoice_payment(
  p_invoice_id UUID,
  p_amount NUMERIC,
  p_reference TEXT,
  p_payment_method TEXT DEFAULT 'manual'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_invoice RECORD;
  v_new_paid_amount NUMERIC;
  v_new_status TEXT;
  v_payment_id UUID;
BEGIN
  -- Lock the row to prevent race conditions on payment processing
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + p_amount;
  
  -- Determine new payment status based on remaining balance
  IF v_new_paid_amount >= v_invoice.total_amount THEN
    v_new_status := 'paid';
  ELSE
    v_new_status := 'partially_paid'; -- or keep 'scheduled' / 'approved'
  END IF;

  -- Update invoice
  UPDATE public.invoices
  SET paid_amount = v_new_paid_amount,
      payment_status = CASE WHEN v_new_paid_amount >= total_amount THEN 'paid' ELSE 'partial' END,
      status = CASE WHEN v_new_paid_amount >= total_amount THEN 'paid' ELSE 'partially_paid' END,
      ap_status = CASE WHEN v_new_paid_amount >= total_amount THEN 'paid' ELSE ap_status END,
      payment_reference = p_reference,
      updated_at = now()
  WHERE id = p_invoice_id;

  -- Create a payment record in the ledger
  INSERT INTO public.payments (
    invoice_id, vendor_id, vendor_name, invoice_number,
    amount, payment_method, status, transaction_id, payment_date,
    payment_account_id, organization_id, created_by
  )
  VALUES (
    v_invoice.id, v_invoice.vendor_id, v_invoice.vendor_name, v_invoice.invoice_number,
    p_amount, p_payment_method, 'completed', p_reference, CURRENT_DATE,
    v_invoice.payment_account_id, v_invoice.organization_id, auth.uid()
  )
  RETURNING id INTO v_payment_id;

  RETURN jsonb_build_object(
    'status', v_new_status,
    'paid_amount', v_new_paid_amount,
    'payment_id', v_payment_id
  );
END;
$$;

-- Source: 086_invoice_audit_events.sql
-- Function to record audit event
CREATE OR REPLACE FUNCTION public.log_invoice_audit_event(
  p_invoice_id UUID,
  p_action TEXT,
  p_description TEXT DEFAULT NULL,
  p_old_value JSONB DEFAULT NULL,
  p_new_value JSONB DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_org_id UUID;
BEGIN
  SELECT organization_id INTO v_org_id FROM public.invoices WHERE id = p_invoice_id;
  
  IF v_org_id IS NOT NULL THEN
    INSERT INTO public.invoice_audit_events (
      invoice_id, organization_id, user_id, action, description, old_value, new_value
    ) VALUES (
      p_invoice_id, v_org_id, auth.uid(), p_action, p_description, p_old_value, p_new_value
    );
  END IF;
END;
$$;

-- Trigger to auto-log status changes
CREATE OR REPLACE FUNCTION public.trigger_invoice_status_audit()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    PERFORM public.log_invoice_audit_event(
      NEW.id,
      'status_changed',
      'Invoice status changed from ' || COALESCE(OLD.status, 'none') || ' to ' || NEW.status,
      jsonb_build_object('status', OLD.status),
      jsonb_build_object('status', NEW.status)
    );
  END IF;
  RETURN NEW;
END;
$$;

