-- Source: 096_fix_labor_forecast_revenue_column.sql
CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
) AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF public.get_my_org() != (SELECT organization_id FROM public.locations WHERE id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location''s data.';
    END IF;

    SELECT COALESCE(AVG(revenue), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data
    WHERE location_id = p_location_id
      AND date >= (now() - interval '30 days')::date;

    RETURN QUERY
    WITH dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS d
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(es.end_time, es.start_time) - es.start_time)) / 3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(d.d, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM dates d
    LEFT JOIN scheduled s ON d.d = s.shift_date
    ORDER BY d.d ASC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 097_finalize_payment_rbac_and_labor_forecast.sql
CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
) AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF public.get_my_org() != (SELECT l.organization_id FROM public.locations l WHERE l.id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location''s data.';
    END IF;

    SELECT COALESCE(AVG(ps.revenue), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data ps
    WHERE ps.location_id = p_location_id
      AND ps.date >= (now() - interval '30 days')::date;

    RETURN QUERY
    WITH forecast_dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS forecast_day
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(es.end_time, es.start_time) - es.start_time)) / 3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(fd.forecast_day, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM forecast_dates fd
    LEFT JOIN scheduled s ON fd.forecast_day = s.shift_date
    ORDER BY fd.forecast_day ASC;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 098_vendor_item_price_intelligence.sql
CREATE OR REPLACE FUNCTION public.refresh_vendor_item_mapping_status(p_vendor_item_id UUID)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_verified_count INTEGER;
  v_suggested_count INTEGER;
BEGIN
  SELECT
    COUNT(*) FILTER (WHERE is_verified = true),
    COUNT(*)
  INTO v_verified_count, v_suggested_count
  FROM public.vendor_item_mappings
  WHERE vendor_item_id = p_vendor_item_id;

  UPDATE public.vendor_items
  SET mapping_status = CASE
      WHEN v_verified_count > 0 THEN 'verified'
      WHEN v_suggested_count > 0 THEN 'suggested'
      ELSE 'unmapped'
    END,
    updated_at = now()
  WHERE id = p_vendor_item_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.touch_vendor_item_mapping_status()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor_item_id UUID;
BEGIN
  v_vendor_item_id := COALESCE(NEW.vendor_item_id, OLD.vendor_item_id);
  PERFORM public.refresh_vendor_item_mapping_status(v_vendor_item_id);
  RETURN COALESCE(NEW, OLD);
END;
$$;

-- Source: 100_scheduled_payments.sql
-- RPC for bulk scheduling
CREATE OR REPLACE FUNCTION public.schedule_payment_batch(
    p_vendor_id UUID,
    p_payment_account_id UUID,
    p_scheduled_date DATE,
    p_invoice_ids UUID[],
    p_amounts NUMERIC[]
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_scheduled_payment_id UUID;
    v_total NUMERIC := 0;
    i INT;
BEGIN
    -- Calculate total
    FOR i IN 1 .. array_length(p_amounts, 1) LOOP
        v_total := v_total + p_amounts[i];
    END LOOP;

    -- Create scheduled payment record
    INSERT INTO public.scheduled_payments (
        organization_id,
        vendor_id,
        payment_account_id,
        total_amount,
        scheduled_date,
        status,
        created_by
    ) VALUES (
        public.get_my_org(),
        p_vendor_id,
        p_payment_account_id,
        v_total,
        p_scheduled_date,
        'scheduled',
        auth.uid()
    ) RETURNING id INTO v_scheduled_payment_id;

    -- Insert intersection records
    FOR i IN 1 .. array_length(p_invoice_ids, 1) LOOP
        INSERT INTO public.scheduled_payment_invoices (
            scheduled_payment_id,
            invoice_id,
            amount_applied
        ) VALUES (
            v_scheduled_payment_id,
            p_invoice_ids[i],
            p_amounts[i]
        );
        
        -- Update invoice status
        UPDATE public.invoices 
        SET scheduled_payment_date = p_scheduled_date,
            status = 'scheduled'
        WHERE id = p_invoice_ids[i];
    END LOOP;

    RETURN v_scheduled_payment_id;
END;
$$;

-- Source: 101_vendor_statements.sql
-- RPC for auto-matching statement lines to invoices
CREATE OR REPLACE FUNCTION public.auto_match_statement_lines(p_statement_id UUID)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_vendor_id UUID;
    v_org_id UUID;
    v_matched_count INTEGER := 0;
    v_line RECORD;
    v_invoice_id UUID;
BEGIN
    SELECT vendor_id, organization_id INTO v_vendor_id, v_org_id 
    FROM public.vendor_statements WHERE id = p_statement_id;

    FOR v_line IN SELECT * FROM public.vendor_statement_lines WHERE statement_id = p_statement_id AND status = 'unmatched' LOOP
        -- Try to find an exact match on invoice_number and amount and vendor
        SELECT id INTO v_invoice_id
        FROM public.invoices
        WHERE organization_id = v_org_id 
          AND vendor_id = v_vendor_id
          AND invoice_number = v_line.invoice_number
          AND total_amount = v_line.amount
        LIMIT 1;

        IF v_invoice_id IS NOT NULL THEN
            UPDATE public.vendor_statement_lines
            SET status = 'matched', matched_invoice_id = v_invoice_id
            WHERE id = v_line.id;
            
            v_matched_count := v_matched_count + 1;
        END IF;
    END LOOP;

    -- Update parent statement status if all lines are matched
    IF NOT EXISTS (SELECT 1 FROM public.vendor_statement_lines WHERE statement_id = p_statement_id AND status != 'matched') THEN
        UPDATE public.vendor_statements SET status = 'matched' WHERE id = p_statement_id;
    ELSE
        UPDATE public.vendor_statements SET status = 'needs_review' WHERE id = p_statement_id;
    END IF;

    RETURN v_matched_count;
END;
$$;

-- Source: 102_accounting_sync.sql
-- Function to queue an invoice for export when it's approved
CREATE OR REPLACE FUNCTION public.queue_approved_invoice()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    -- If status changed to approved and it's not already in the queue
    IF NEW.status = 'approved' AND OLD.status != 'approved' THEN
        INSERT INTO public.accounting_export_queue (
            organization_id,
            entity_type,
            entity_id,
            status
        ) VALUES (
            NEW.organization_id,
            'invoice',
            NEW.id,
            'ready'
        ) ON CONFLICT DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;

-- Source: 105_performance_optimization.sql
-- ============================================================
-- Migration 105: Performance Optimization (RLS & Indexes)
-- ============================================================

-- This migration must NOT be run inside a transaction block because
-- CREATE INDEX CONCURRENTLY cannot run inside a transaction.
-- Removing BEGIN/COMMIT wrappers for this migration.

-- 1. Redefine RLS Helper Functions for Maximum Performance
--    We pull directly from app_metadata instead of user_metadata
--    because migration 040 stores the current org context in app_metadata.
--    We ensure these functions are STABLE so PostgreSQL caches the result
--    per-query, preventing millions of redundant JWT parsing operations.

CREATE OR REPLACE FUNCTION public.get_auth_org()
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT (COALESCE(
    auth.jwt() -> 'app_metadata' ->> 'organization_id',
    auth.jwt() -> 'user_metadata' ->> 'organization_id'
  ))::uuid;
$$;

CREATE OR REPLACE FUNCTION public.get_auth_role()
RETURNS TEXT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT COALESCE(
    auth.jwt() -> 'app_metadata' ->> 'role',
    auth.jwt() -> 'user_metadata' ->> 'role',
    'ground_staff'
  );
$$;

-- Source: 107_dashboard_materialized_views.sql
-- 4. Create a unified refresh function
-- This function refreshes the views CONCURRENTLY (meaning zero locking/downtime for readers)
CREATE OR REPLACE FUNCTION public.refresh_dashboard_materialized_views()
RETURNS void AS $$
BEGIN
    -- Concurrent refresh ensures the dashboard never hangs while updating
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_daily_sales_summary;
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_inventory_valuation_summary;
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_invoice_spend_summary;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 108_dashboard_rpc_cache_wiring.sql
CREATE OR REPLACE FUNCTION public.get_role_dashboard_summary(
  p_scope TEXT,
  p_org_id UUID,
  p_brand_id UUID DEFAULT NULL,
  p_location_id UUID DEFAULT NULL,
  p_period_start DATE DEFAULT date_trunc('month', now())::date,
  p_period_end DATE DEFAULT (date_trunc('month', now()) + interval '1 month' - interval '1 day')::date
)
RETURNS JSONB AS $$
DECLARE
  v_today DATE := current_date;
  v_week_start DATE := date_trunc('week', current_date)::date;
  v_last_week_start DATE := (date_trunc('week', current_date) - interval '7 days')::date;
  v_last_year_week_start DATE := (date_trunc('week', current_date) - interval '1 year')::date;
  v_payload JSONB;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization id is required.';
  END IF;

  IF NOT public.is_platform_admin() AND public.get_my_org() != p_org_id THEN
    RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
  END IF;

  IF p_scope NOT IN ('org', 'brand', 'location', 'staff') THEN
    RAISE EXCEPTION 'Invalid dashboard scope: %', p_scope;
  END IF;

  IF p_scope = 'brand' AND p_brand_id IS NULL THEN
    RAISE EXCEPTION 'Brand id is required for brand dashboard scope.';
  END IF;

  IF p_scope IN ('location', 'staff') AND p_location_id IS NULL THEN
    RAISE EXCEPTION 'Location id is required for location dashboard scope.';
  END IF;

  WITH scoped_locations AS (
    SELECT l.id
    FROM public.locations l
    WHERE l.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND l.brand_id = p_brand_id)
        OR (p_scope IN ('location', 'staff') AND l.id = p_location_id)
      )
  ),
  -- ====== NEW OPTIMIZED CTEs using Materialized Views ======
  scoped_sales_mv AS (
    SELECT mv.*
    FROM public.mv_daily_sales_summary mv
    WHERE mv.organization_id = p_org_id
      AND mv.date BETWEEN (v_last_year_week_start - interval '7 days')::date AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (mv.brand_id = p_brand_id OR mv.brand_id = '00000000-0000-0000-0000-000000000000'::uuid))
        OR (p_scope IN ('location', 'staff') AND (mv.location_id = p_location_id OR mv.location_id = '00000000-0000-0000-0000-000000000000'::uuid))
      )
  ),
  scoped_invoice_spend_mv AS (
    SELECT mv.*
    FROM public.mv_invoice_spend_summary mv
    WHERE mv.organization_id = p_org_id
      AND mv.date <= p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (mv.brand_id = p_brand_id OR mv.brand_id = '00000000-0000-0000-0000-000000000000'::uuid))
        OR (p_scope IN ('location', 'staff') AND (mv.location_id = p_location_id OR mv.location_id = '00000000-0000-0000-0000-000000000000'::uuid))
      )
  ),
  scoped_inventory_mv AS (
    SELECT mv.*
    FROM public.mv_inventory_valuation_summary mv
    WHERE mv.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (mv.brand_id = p_brand_id OR mv.brand_id = '00000000-0000-0000-0000-000000000000'::uuid))
        OR (p_scope IN ('location', 'staff') AND (mv.location_id = p_location_id OR mv.location_id = '00000000-0000-0000-0000-000000000000'::uuid))
      )
  ),
  -- =========================================================
  scoped_invoices AS (
    SELECT i.*
    FROM public.invoices i
    WHERE i.organization_id = p_org_id
      AND COALESCE(i.invoice_date, i.created_at::date) <= p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (i.brand_id = p_brand_id OR (i.brand_id IS NULL AND i.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (i.location_id = p_location_id OR i.location_id IS NULL))
      )
  ),
  period_invoices AS (
    SELECT *
    FROM scoped_invoices
    WHERE COALESCE(invoice_date, created_at::date) BETWEEN p_period_start AND p_period_end
  ),
  scoped_products AS (
    SELECT p.*
    FROM public.products p
    WHERE p.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (p.brand_id = p_brand_id OR (p.brand_id IS NULL AND p.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (p.location_id = p_location_id OR p.location_id IS NULL))
      )
  ),
  scoped_orders AS (
    SELECT ao.*
    FROM public.auto_orders ao
    WHERE ao.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (ao.brand_id = p_brand_id OR (ao.brand_id IS NULL AND ao.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (ao.location_id = p_location_id OR ao.location_id IS NULL))
      )
  ),
  scoped_payments AS (
    SELECT p.*
    FROM public.payments p
    WHERE p.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (p.brand_id = p_brand_id OR (p.brand_id IS NULL AND p.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (p.location_id = p_location_id OR p.location_id IS NULL))
      )
  ),
  scoped_wastage AS (
    SELECT w.*
    FROM public.wastage_logs w
    WHERE w.organization_id = p_org_id
      AND COALESCE(w.created_at::date, v_today) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (w.brand_id = p_brand_id OR (w.brand_id IS NULL AND w.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (w.location_id = p_location_id OR w.location_id IS NULL))
      )
  ),
  scoped_shifts AS (
    SELECT es.*
    FROM public.employee_shifts es
    WHERE es.organization_id = p_org_id
      AND COALESCE(es.shift_start::date, es.start_time::date) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND es.location_id IN (SELECT id FROM scoped_locations))
        OR (p_scope IN ('location', 'staff') AND es.location_id = p_location_id)
      )
  ),
  budget_targets AS (
    SELECT bt.*
    FROM public.budget_targets bt
    WHERE bt.organization_id = p_org_id
      AND bt.period_start = p_period_start
      AND bt.period_end = p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (bt.brand_id = p_brand_id OR bt.brand_id IS NULL))
        OR (p_scope IN ('location', 'staff') AND (bt.location_id = p_location_id OR bt.location_id IS NULL))
      )
  ),
  kpis AS (
    SELECT
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date = v_today), 0) AS sales_today,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN v_week_start AND (v_week_start + 6)), 0) AS sales_week_to_date,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN v_last_week_start AND (v_last_week_start + 6)), 0) AS sales_last_week,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN v_last_year_week_start AND (v_last_year_week_start + 6)), 0) AS sales_last_year,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN p_period_start AND p_period_end), 0) AS sales_period
    FROM scoped_sales_mv ps
  ),
  costs AS (
    SELECT
      COALESCE((SELECT SUM(total_spend) FROM scoped_invoice_spend_mv WHERE date BETWEEN p_period_start AND p_period_end), 0) AS invoice_spend,
      COALESCE((SELECT SUM(labor_cost) FROM scoped_shifts), 0) AS labor_cost,
      COALESCE((SELECT SUM(value) FROM scoped_wastage), 0) AS wastage_cost,
      COALESCE((SELECT SUM(unpaid_amount) FROM scoped_invoice_spend_mv), 0) AS unpaid_amount,
      COALESCE((SELECT SUM(pending_count) FROM scoped_invoice_spend_mv), 0) AS pending_invoices,
      COALESCE((SELECT SUM(low_stock_items) FROM scoped_inventory_mv), 0) AS low_stock_items,
      COALESCE((SELECT COUNT(*) FROM scoped_orders WHERE COALESCE(status, 'pending') NOT IN ('completed', 'received', 'cancelled')), 0) AS open_orders,
      COALESCE((SELECT SUM(invoice_count) FROM scoped_invoice_spend_mv), 0) AS total_invoices,
      COALESCE((SELECT COUNT(*) FROM scoped_payments), 0) AS total_payments,
      COALESCE((SELECT COUNT(*) FROM scoped_products), 0) AS total_products,
      COALESCE((SELECT SUM(total_items) FROM scoped_inventory_mv), 0) AS total_inventory_items
  ),
  sales_rows AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'name', to_char(day_date, 'Dy'),
        'actual', actual,
        'lastWeek', last_week,
        'lastYear', last_year,
        'vsLastWeek', CASE WHEN last_week = 0 THEN 0 ELSE ((actual - last_week) / last_week) * 100 END,
        'vsLastYear', CASE WHEN last_year = 0 THEN 0 ELSE ((actual - last_year) / last_year) * 100 END
      )
      ORDER BY day_date
    ) AS rows
    FROM (
      SELECT
        d::date AS day_date,
        COALESCE((SELECT SUM(total_revenue) FROM scoped_sales_mv WHERE date = d::date), 0) AS actual,
        COALESCE((SELECT SUM(total_revenue) FROM scoped_sales_mv WHERE date = (d::date - interval '7 days')::date), 0) AS last_week,
        COALESCE((SELECT SUM(total_revenue) FROM scoped_sales_mv WHERE date = (d::date - interval '1 year')::date), 0) AS last_year
      FROM generate_series(v_week_start, v_week_start + 6, interval '1 day') AS d
    ) s
  ),
  invoice_json_categories AS (
    SELECT
      COALESCE(item->>'category', item->>'accounting_category', 'Other') AS category,
      COALESCE((item->>'extended_price')::numeric, (item->>'total_price')::numeric, (item->>'amount')::numeric, 0) AS amount
    FROM period_invoices pi
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(pi.line_items, '[]'::jsonb)) item
  ),
  normalized_line_categories AS (
    SELECT
      'Other'::text AS category,
      COALESCE(SUM(ili.total_price), 0) AS amount
    FROM public.invoice_line_items ili
    JOIN period_invoices pi ON pi.id = ili.invoice_id
  ),
  category_spend AS (
    SELECT category, SUM(amount) AS amount
    FROM (
      SELECT * FROM invoice_json_categories
      UNION ALL
      SELECT * FROM normalized_line_categories
    ) c
    GROUP BY category
    HAVING SUM(amount) > 0
  ),
  spend_payload AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('name', category, 'value', amount) ORDER BY amount DESC), '[]'::jsonb) AS items
    FROM category_spend
  ),
  budget_payload AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'category', category,
        'actual', actual,
        'target', target,
        'remaining', target - actual,
        'pacing', CASE WHEN target = 0 THEN 0 ELSE ((actual - target) / target) * 100 END,
        'isGood', CASE WHEN category = 'Sales' THEN actual >= target ELSE actual <= target END
      )
      ORDER BY sort_order, category
    ), '[]'::jsonb) AS items
    FROM (
      SELECT 1 AS sort_order, 'Sales'::text AS category, (SELECT sales_period FROM kpis) AS actual, COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'Sales' LIMIT 1), NULLIF((SELECT sales_period FROM kpis) * 1.05, 0), 0) AS target
      UNION ALL
      SELECT 2, 'COGS', (SELECT invoice_spend FROM costs), COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'COGS' LIMIT 1), NULLIF((SELECT invoice_spend FROM costs) * 0.95, 0), 0)
      UNION ALL
      SELECT 3, 'Labor', (SELECT labor_cost FROM costs), COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'Labor' LIMIT 1), NULLIF((SELECT sales_period FROM kpis) * 0.28, 0), 0)
      UNION ALL
      SELECT 4, 'Prime Cost', (SELECT invoice_spend + labor_cost FROM costs), COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'Prime Cost' LIMIT 1), NULLIF((SELECT sales_period FROM kpis) * 0.6, 0), 0)
    ) b
  ),
  alerts_payload AS (
    SELECT jsonb_agg(alert_obj) AS items
    FROM (
      SELECT jsonb_build_object('tone', 'red', 'title', low_stock_items || ' low stock items', 'body', 'Review reorder points and replenishment orders.', 'href', 'Inventory') AS alert_obj
      FROM costs WHERE low_stock_items > 0
      UNION ALL
      SELECT jsonb_build_object('tone', 'orange', 'title', pending_invoices || ' invoices pending', 'body', 'Clear pending review so AP and inventory stay current.', 'href', 'Invoices')
      FROM costs WHERE pending_invoices > 0
      UNION ALL
      SELECT jsonb_build_object('tone', 'blue', 'title', 'POS sales not flowing yet', 'body', 'Connect or map POS data to unlock daily sales benchmarking.', 'href', 'RestaurantSetup?tab=pos')
      FROM kpis WHERE sales_period = 0
      UNION ALL
      SELECT jsonb_build_object('tone', 'red', 'title', 'Labor above target', 'body', 'Labor is above the 28% operating target for this period.', 'href', 'Labor')
      FROM kpis, costs WHERE sales_period > 0 AND (labor_cost / sales_period) > 0.28
    ) a
  )
  SELECT jsonb_build_object(
    'scope', p_scope,
    'period', jsonb_build_object('start', p_period_start, 'end', p_period_end),
    'kpis', jsonb_build_object(
      'salesToday', k.sales_today,
      'salesWeekToDate', k.sales_week_to_date,
      'salesLastWeek', k.sales_last_week,
      'salesLastYear', k.sales_last_year,
      'salesPeriod', k.sales_period,
      'salesVsLastWeek', CASE WHEN k.sales_last_week = 0 THEN 0 ELSE ((k.sales_week_to_date - k.sales_last_week) / k.sales_last_week) * 100 END,
      'salesVsLastYear', CASE WHEN k.sales_last_year = 0 THEN 0 ELSE ((k.sales_week_to_date - k.sales_last_year) / k.sales_last_year) * 100 END,
      'invoiceSpend', c.invoice_spend,
      'laborCost', c.labor_cost,
      'cogsPercent', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.invoice_spend / k.sales_period) * 100 END,
      'laborPercent', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.labor_cost / k.sales_period) * 100 END,
      'primeCostPercent', CASE WHEN k.sales_period = 0 THEN 0 ELSE ((c.invoice_spend + c.labor_cost) / k.sales_period) * 100 END,
      'unpaidAmount', c.unpaid_amount,
      'pendingInvoices', c.pending_invoices,
      'lowStockItems', c.low_stock_items,
      'openOrders', c.open_orders,
      'wastageCost', c.wastage_cost
    ),
    'salesPerformance', COALESCE(sr.rows, '[]'::jsonb),
    'budgetPacing', bp.items,
    'spendByCategory', sp.items,
    'workflows', jsonb_build_object(
      'invoices', c.total_invoices,
      'payments', c.total_payments,
      'openOrders', c.open_orders,
      'lowStock', c.low_stock_items,
      'products', c.total_products,
      'inventoryItems', c.total_inventory_items,
      'wasteCost', c.wastage_cost
    ),
    'alerts', COALESCE(ap.items, '[]'::jsonb),
    'benchmarks', jsonb_build_array(
      jsonb_build_object('name', 'Sales', 'actual', k.sales_week_to_date, 'benchmark', COALESCE(NULLIF(k.sales_last_week, 0), k.sales_week_to_date)),
      jsonb_build_object('name', 'COGS', 'actual', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.invoice_spend / k.sales_period) * 100 END, 'benchmark', 32),
      jsonb_build_object('name', 'Labor', 'actual', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.labor_cost / k.sales_period) * 100 END, 'benchmark', 28),
      jsonb_build_object('name', 'Prime', 'actual', CASE WHEN k.sales_period = 0 THEN 0 ELSE ((c.invoice_spend + c.labor_cost) / k.sales_period) * 100 END, 'benchmark', 60)
    )
  )
  INTO v_payload
  FROM kpis k
  CROSS JOIN costs c
  CROSS JOIN sales_rows sr
  CROSS JOIN spend_payload sp
  CROSS JOIN budget_payload bp
  CROSS JOIN alerts_payload ap;

  RETURN v_payload;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 110_server_side_metrics_and_sync.sql
-- 2. get_inventory_totals RPC
CREATE OR REPLACE FUNCTION public.get_inventory_totals(
  p_org_id UUID,
  p_search_term TEXT DEFAULT NULL,
  p_location_id UUID DEFAULT NULL
) RETURNS JSONB AS $$
DECLARE
  v_payload JSONB;
BEGIN
  -- Strict multi-tenant enforcement
  IF NOT public.is_platform_admin() AND p_org_id::text != (auth.jwt() ->> 'organization_id') THEN
    RAISE EXCEPTION 'Access Denied: Tenant Context Violations Precluded Processing.';
  END IF;

  WITH filtered_inventory AS (
    SELECT *
    FROM public.inventory
    WHERE organization_id = p_org_id
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND (p_search_term IS NULL OR p_search_term = '' OR product_name ILIKE '%' || p_search_term || '%')
  ),
  filtered_wastage AS (
    SELECT value
    FROM public.wastage_logs
    WHERE organization_id = p_org_id
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND created_at >= date_trunc('month', now())
  )
  SELECT jsonb_build_object(
    'totalItems', count(*),
    'totalValue', coalesce(sum(current_quantity * unit_cost), 0),
    'lowStock', count(*) FILTER (WHERE current_quantity <= coalesce(reorder_point, 5)),
    'totalWastageValue', coalesce((SELECT sum(value) FROM filtered_wastage), 0)
  )
  INTO v_payload
  FROM filtered_inventory;

  RETURN v_payload;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 3. calculate_theoretical_depletion RPC
CREATE OR REPLACE FUNCTION public.calculate_theoretical_depletion(
  p_org_id UUID,
  p_sales_json JSONB
) RETURNS JSONB AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF NOT public.is_platform_admin() AND p_org_id::text != (auth.jwt() ->> 'organization_id') THEN
    RAISE EXCEPTION 'Access Denied: Tenant Context Violations Precluded Processing.';
  END IF;

  WITH sales AS (
    SELECT 
      (elem->>'name')::TEXT as sale_name,
      (elem->>'qty')::NUMERIC as sale_qty
    FROM jsonb_array_elements(p_sales_json) elem
  ),
  matched_recipes AS (
    SELECT 
      s.sale_qty,
      r.id as recipe_id,
      r.name as recipe_name
    FROM sales s
    JOIN public.recipes r ON lower(trim(r.name)) = lower(trim(s.sale_name))
    WHERE r.organization_id = p_org_id
  ),
  depletions AS (
    SELECT 
      ri.product_id,
      ri.name as product_name,
      sum(ri.quantity * mr.sale_qty) as total_used,
      max(ri.unit) as unit
    FROM matched_recipes mr
    JOIN public.recipe_ingredients ri ON ri.recipe_id = mr.recipe_id
    WHERE ri.organization_id = p_org_id
    GROUP BY ri.product_id, ri.name
  )
  SELECT coalesce(jsonb_agg(
    jsonb_build_object(
      'product_id', d.product_id,
      'product_name', d.product_name,
      'total_used', d.total_used,
      'unit', d.unit
    ) ORDER BY d.total_used DESC
  ), '[]'::jsonb)
  INTO v_result
  FROM depletions d;

  RETURN v_result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 4. execute_inventory_depletion RPC
CREATE OR REPLACE FUNCTION public.execute_inventory_depletion(
  p_org_id UUID,
  p_depletion_json JSONB
) RETURNS VOID AS $$
DECLARE
  v_elem JSONB;
  v_inv_id UUID;
  v_old_qty NUMERIC;
  v_new_qty NUMERIC;
BEGIN
  IF NOT public.is_platform_admin() AND p_org_id::text != (auth.jwt() ->> 'organization_id') THEN
    RAISE EXCEPTION 'Access Denied: Tenant Context Violations Precluded Processing.';
  END IF;

  FOR v_elem IN SELECT * FROM jsonb_array_elements(p_depletion_json)
  LOOP
    SELECT id, current_quantity INTO v_inv_id, v_old_qty
    FROM public.inventory
    WHERE organization_id = p_org_id
      AND product_id = (v_elem->>'product_id')::TEXT
    LIMIT 1;

    IF v_inv_id IS NOT NULL THEN
      v_new_qty := greatest(0, coalesce(v_old_qty, 0) - (v_elem->>'total_used')::NUMERIC);

      UPDATE public.inventory
      SET current_quantity = v_new_qty, previous_quantity = v_old_qty
      WHERE id = v_inv_id;
    END IF;
  END LOOP;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 111_fix_dashboard_performance.sql
-- Redefine the refresh function to ONLY refresh daily sales
CREATE OR REPLACE FUNCTION public.refresh_dashboard_materialized_views()
RETURNS void AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_daily_sales_summary;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 4. Redefine the Dashboard RPC with real-time queries and strict date boundaries
CREATE OR REPLACE FUNCTION public.get_role_dashboard_summary(
  p_scope TEXT,
  p_org_id UUID,
  p_brand_id UUID DEFAULT NULL,
  p_location_id UUID DEFAULT NULL,
  p_period_start DATE DEFAULT date_trunc('month', now())::date,
  p_period_end DATE DEFAULT (date_trunc('month', now()) + interval '1 month' - interval '1 day')::date
)
RETURNS JSONB AS $$
DECLARE
  v_today DATE := current_date;
  v_week_start DATE := date_trunc('week', current_date)::date;
  v_last_week_start DATE := (date_trunc('week', current_date) - interval '7 days')::date;
  v_last_year_week_start DATE := (date_trunc('week', current_date) - interval '1 year')::date;
  v_payload JSONB;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization id is required.';
  END IF;

  IF NOT public.is_platform_admin() AND public.get_my_org() != p_org_id THEN
    RAISE EXCEPTION 'Unauthorized: You do not have access to this organization''s data.';
  END IF;

  IF p_scope NOT IN ('org', 'brand', 'location', 'staff') THEN
    RAISE EXCEPTION 'Invalid dashboard scope: %', p_scope;
  END IF;

  WITH scoped_locations AS (
    SELECT l.id
    FROM public.locations l
    WHERE l.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND l.brand_id = p_brand_id)
        OR (p_scope IN ('location', 'staff') AND l.id = p_location_id)
      )
  ),
  scoped_sales_mv AS (
    SELECT mv.*
    FROM public.mv_daily_sales_summary mv
    WHERE mv.organization_id = p_org_id
      AND mv.date BETWEEN (v_last_year_week_start - interval '7 days')::date AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (mv.brand_id = p_brand_id OR mv.brand_id = '00000000-0000-0000-0000-000000000000'::uuid))
        OR (p_scope IN ('location', 'staff') AND (mv.location_id = p_location_id OR mv.location_id = '00000000-0000-0000-0000-000000000000'::uuid))
      )
  ),
  -- REAL-TIME INVOICE SPEND (Replaces Materialized View)
  scoped_invoice_spend AS (
    SELECT 
      COUNT(*) as invoice_count,
      COALESCE(SUM(total_amount), 0) as total_spend,
      COALESCE(SUM(total_amount) FILTER (WHERE payment_status = 'unpaid' OR status = 'approved'), 0) as unpaid_amount,
      COUNT(*) FILTER (WHERE status = 'pending_review') as pending_count
    FROM public.invoices i
    WHERE i.organization_id = p_org_id
      AND COALESCE(i.invoice_date, (i.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (i.brand_id = p_brand_id OR (i.brand_id IS NULL AND i.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (i.location_id = p_location_id OR i.location_id IS NULL))
      )
  ),
  -- REAL-TIME INVENTORY (Replaces Materialized View)
  scoped_inventory AS (
    SELECT 
      COUNT(*) as total_items,
      COALESCE(SUM(current_value), 0) as total_valuation,
      COUNT(*) FILTER (WHERE current_quantity <= COALESCE(reorder_point, 5)) as low_stock_items
    FROM public.inventory i
    WHERE i.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (i.location_id IN (SELECT id FROM scoped_locations)))
        OR (p_scope IN ('location', 'staff') AND (i.location_id = p_location_id OR i.location_id IS NULL))
      )
  ),
  period_invoices AS (
    SELECT i.id
    FROM public.invoices i
    WHERE i.organization_id = p_org_id
      AND COALESCE(i.invoice_date, (i.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (i.brand_id = p_brand_id OR (i.brand_id IS NULL AND i.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (i.location_id = p_location_id OR i.location_id IS NULL))
      )
  ),
  -- FAST CATEGORY SPEND (No JSON array elements!)
  category_spend AS (
    SELECT 
      COALESCE(p.accounting_category, 'Other') AS category, 
      SUM(ili.total_price) AS amount
    FROM public.invoice_line_items ili
    JOIN period_invoices pi ON pi.id = ili.invoice_id
    LEFT JOIN public.products p ON p.id = ili.internal_product_id
    GROUP BY COALESCE(p.accounting_category, 'Other')
    HAVING SUM(ili.total_price) > 0
  ),
  scoped_products AS (
    SELECT COUNT(*) as product_count
    FROM public.products p
    WHERE p.organization_id = p_org_id
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (p.brand_id = p_brand_id OR (p.brand_id IS NULL AND p.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (p.location_id = p_location_id OR p.location_id IS NULL))
      )
  ),
  scoped_orders AS (
    SELECT COUNT(*) as open_orders_count
    FROM public.auto_orders ao
    WHERE ao.organization_id = p_org_id
      AND COALESCE(status, 'pending') NOT IN ('completed', 'received', 'cancelled')
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (ao.brand_id = p_brand_id OR (ao.brand_id IS NULL AND ao.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (ao.location_id = p_location_id OR ao.location_id IS NULL))
      )
  ),
  scoped_payments AS (
    SELECT COUNT(*) as payments_count
    FROM public.payments p
    WHERE p.organization_id = p_org_id
      AND COALESCE(p.payment_date, (p.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (p.brand_id = p_brand_id OR (p.brand_id IS NULL AND p.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (p.location_id = p_location_id OR p.location_id IS NULL))
      )
  ),
  scoped_wastage AS (
    SELECT w.*
    FROM public.wastage_logs w
    WHERE w.organization_id = p_org_id
      AND COALESCE(w.created_at::date, v_today) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (w.brand_id = p_brand_id OR (w.brand_id IS NULL AND w.location_id IN (SELECT id FROM scoped_locations))))
        OR (p_scope IN ('location', 'staff') AND (w.location_id = p_location_id OR w.location_id IS NULL))
      )
  ),
  scoped_shifts AS (
    SELECT es.*
    FROM public.employee_shifts es
    WHERE es.organization_id = p_org_id
      AND COALESCE(es.shift_start::date, es.start_time::date) BETWEEN p_period_start AND p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND es.location_id IN (SELECT id FROM scoped_locations))
        OR (p_scope IN ('location', 'staff') AND es.location_id = p_location_id)
      )
  ),
  budget_targets AS (
    SELECT bt.*
    FROM public.budget_targets bt
    WHERE bt.organization_id = p_org_id
      AND bt.period_start = p_period_start
      AND bt.period_end = p_period_end
      AND (
        p_scope = 'org'
        OR (p_scope = 'brand' AND (bt.brand_id = p_brand_id OR bt.brand_id IS NULL))
        OR (p_scope IN ('location', 'staff') AND (bt.location_id = p_location_id OR bt.location_id IS NULL))
      )
  ),
  kpis AS (
    SELECT
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date = v_today), 0) AS sales_today,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN v_week_start AND (v_week_start + 6)), 0) AS sales_week_to_date,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN v_last_week_start AND (v_last_week_start + 6)), 0) AS sales_last_week,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN v_last_year_week_start AND (v_last_year_week_start + 6)), 0) AS sales_last_year,
      COALESCE(SUM(ps.total_revenue) FILTER (WHERE ps.date BETWEEN p_period_start AND p_period_end), 0) AS sales_period
    FROM scoped_sales_mv ps
  ),
  costs AS (
    SELECT
      (SELECT total_spend FROM scoped_invoice_spend) AS invoice_spend,
      COALESCE((SELECT SUM(labor_cost) FROM scoped_shifts), 0) AS labor_cost,
      COALESCE((SELECT SUM(value) FROM scoped_wastage), 0) AS wastage_cost,
      (SELECT unpaid_amount FROM scoped_invoice_spend) AS unpaid_amount,
      (SELECT pending_count FROM scoped_invoice_spend) AS pending_invoices,
      (SELECT low_stock_items FROM scoped_inventory) AS low_stock_items,
      (SELECT open_orders_count FROM scoped_orders) AS open_orders,
      (SELECT invoice_count FROM scoped_invoice_spend) AS total_invoices,
      (SELECT payments_count FROM scoped_payments) AS total_payments,
      (SELECT product_count FROM scoped_products) AS total_products,
      (SELECT total_items FROM scoped_inventory) AS total_inventory_items
  ),
  sales_rows AS (
    SELECT jsonb_agg(
      jsonb_build_object(
        'name', to_char(day_date, 'Dy'),
        'actual', actual,
        'lastWeek', last_week,
        'lastYear', last_year,
        'vsLastWeek', CASE WHEN last_week = 0 THEN 0 ELSE ((actual - last_week) / last_week) * 100 END,
        'vsLastYear', CASE WHEN last_year = 0 THEN 0 ELSE ((actual - last_year) / last_year) * 100 END
      )
      ORDER BY day_date
    ) AS rows
    FROM (
      SELECT
        d::date AS day_date,
        COALESCE((SELECT SUM(total_revenue) FROM scoped_sales_mv WHERE date = d::date), 0) AS actual,
        COALESCE((SELECT SUM(total_revenue) FROM scoped_sales_mv WHERE date = (d::date - interval '7 days')::date), 0) AS last_week,
        COALESCE((SELECT SUM(total_revenue) FROM scoped_sales_mv WHERE date = (d::date - interval '1 year')::date), 0) AS last_year
      FROM generate_series(v_week_start, v_week_start + 6, interval '1 day') AS d
    ) s
  ),
  spend_payload AS (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('name', category, 'value', amount) ORDER BY amount DESC), '[]'::jsonb) AS items
    FROM category_spend
  ),
  budget_payload AS (
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'category', category,
        'actual', actual,
        'target', target,
        'remaining', target - actual,
        'pacing', CASE WHEN target = 0 THEN 0 ELSE ((actual - target) / target) * 100 END,
        'isGood', CASE WHEN category = 'Sales' THEN actual >= target ELSE actual <= target END
      )
      ORDER BY sort_order, category
    ), '[]'::jsonb) AS items
    FROM (
      SELECT 1 AS sort_order, 'Sales'::text AS category, (SELECT sales_period FROM kpis) AS actual, COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'Sales' LIMIT 1), NULLIF((SELECT sales_period FROM kpis) * 1.05, 0), 0) AS target
      UNION ALL
      SELECT 2, 'COGS', (SELECT invoice_spend FROM costs), COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'COGS' LIMIT 1), NULLIF((SELECT invoice_spend FROM costs) * 0.95, 0), 0)
      UNION ALL
      SELECT 3, 'Labor', (SELECT labor_cost FROM costs), COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'Labor' LIMIT 1), NULLIF((SELECT sales_period FROM kpis) * 0.28, 0), 0)
      UNION ALL
      SELECT 4, 'Prime Cost', (SELECT invoice_spend + labor_cost FROM costs), COALESCE((SELECT target_amount FROM budget_targets WHERE category = 'Prime Cost' LIMIT 1), NULLIF((SELECT sales_period FROM kpis) * 0.6, 0), 0)
    ) b
  ),
  alerts_payload AS (
    SELECT jsonb_agg(alert_obj) AS items
    FROM (
      SELECT jsonb_build_object('tone', 'red', 'title', low_stock_items || ' low stock items', 'body', 'Review reorder points and replenishment orders.', 'href', 'Inventory') AS alert_obj
      FROM costs WHERE low_stock_items > 0
      UNION ALL
      SELECT jsonb_build_object('tone', 'orange', 'title', pending_invoices || ' invoices pending', 'body', 'Clear pending review so AP and inventory stay current.', 'href', 'Invoices')
      FROM costs WHERE pending_invoices > 0
      UNION ALL
      SELECT jsonb_build_object('tone', 'blue', 'title', 'POS sales not flowing yet', 'body', 'Connect or map POS data to unlock daily sales benchmarking.', 'href', 'RestaurantSetup?tab=pos')
      FROM kpis WHERE sales_period = 0
      UNION ALL
      SELECT jsonb_build_object('tone', 'red', 'title', 'Labor above target', 'body', 'Labor is above the 28% operating target for this period.', 'href', 'Labor')
      FROM kpis, costs WHERE sales_period > 0 AND (labor_cost / sales_period) > 0.28
    ) a
  )
  SELECT jsonb_build_object(
    'scope', p_scope,
    'period', jsonb_build_object('start', p_period_start, 'end', p_period_end),
    'kpis', jsonb_build_object(
      'salesToday', k.sales_today,
      'salesWeekToDate', k.sales_week_to_date,
      'salesLastWeek', k.sales_last_week,
      'salesLastYear', k.sales_last_year,
      'salesPeriod', k.sales_period,
      'salesVsLastWeek', CASE WHEN k.sales_last_week = 0 THEN 0 ELSE ((k.sales_week_to_date - k.sales_last_week) / k.sales_last_week) * 100 END,
      'salesVsLastYear', CASE WHEN k.sales_last_year = 0 THEN 0 ELSE ((k.sales_week_to_date - k.sales_last_year) / k.sales_last_year) * 100 END,
      'invoiceSpend', c.invoice_spend,
      'laborCost', c.labor_cost,
      'cogsPercent', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.invoice_spend / k.sales_period) * 100 END,
      'laborPercent', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.labor_cost / k.sales_period) * 100 END,
      'primeCostPercent', CASE WHEN k.sales_period = 0 THEN 0 ELSE ((c.invoice_spend + c.labor_cost) / k.sales_period) * 100 END,
      'unpaidAmount', c.unpaid_amount,
      'pendingInvoices', c.pending_invoices,
      'lowStockItems', c.low_stock_items,
      'openOrders', c.open_orders,
      'wastageCost', c.wastage_cost
    ),
    'salesPerformance', COALESCE(sr.rows, '[]'::jsonb),
    'budgetPacing', bp.items,
    'spendByCategory', sp.items,
    'workflows', jsonb_build_object(
      'invoices', c.total_invoices,
      'payments', c.total_payments,
      'openOrders', c.open_orders,
      'lowStock', c.low_stock_items,
      'products', c.total_products,
      'inventoryItems', c.total_inventory_items,
      'wasteCost', c.wastage_cost
    ),
    'alerts', COALESCE(ap.items, '[]'::jsonb),
    'benchmarks', jsonb_build_array(
      jsonb_build_object('name', 'Sales', 'actual', k.sales_week_to_date, 'benchmark', COALESCE(NULLIF(k.sales_last_week, 0), k.sales_week_to_date)),
      jsonb_build_object('name', 'COGS', 'actual', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.invoice_spend / k.sales_period) * 100 END, 'benchmark', 32),
      jsonb_build_object('name', 'Labor', 'actual', CASE WHEN k.sales_period = 0 THEN 0 ELSE (c.labor_cost / k.sales_period) * 100 END, 'benchmark', 28),
      jsonb_build_object('name', 'Prime', 'actual', CASE WHEN k.sales_period = 0 THEN 0 ELSE ((c.invoice_spend + c.labor_cost) / k.sales_period) * 100 END, 'benchmark', 60)
    )
  )
  INTO v_payload
  FROM kpis k
  CROSS JOIN costs c
  CROSS JOIN sales_rows sr
  CROSS JOIN spend_payload sp
  CROSS JOIN budget_payload bp
  CROSS JOIN alerts_payload ap;

  RETURN v_payload;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 117_fix_fetch_user_access_tree.sql
CREATE OR REPLACE FUNCTION public.fetch_user_access_tree()
RETURNS JSONB
LANGUAGE sql
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT jsonb_agg(
    jsonb_build_object(
      'organization', row_to_json(o.*),
      'role', om.role,
      'brands', (
        SELECT jsonb_agg(
          jsonb_build_object(
            'brand', row_to_json(b.*),
            'role', bm.role,
            'locations', (
              SELECT jsonb_agg(
                jsonb_build_object(
                  'location', row_to_json(l.*),
                  'role', lm.role
                )
              )
              FROM public.location_members lm
              JOIN public.locations l ON l.id = lm.location_id
              WHERE lm.user_id = auth.uid() AND l.brand_id = b.brand_id
            )
          )
        )
        FROM public.brand_members bm
        JOIN public.brands b ON b.brand_id = bm.brand_id
        WHERE bm.user_id = auth.uid() AND b.organization_id = o.id
      )
    )
  )
  FROM public.organization_members om
  JOIN public.organizations o ON o.id = om.organization_id
  WHERE om.user_id = auth.uid();
$$;

-- Source: 118_live_schema_repair_and_security.sql
-- Auth helpers must not trust user_metadata. app_metadata is server-controlled.
CREATE OR REPLACE FUNCTION public.get_auth_org()
RETURNS UUID
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT NULLIF(auth.jwt() -> 'app_metadata' ->> 'organization_id', '')::uuid;
$$;

CREATE OR REPLACE FUNCTION public.get_auth_role()
RETURNS TEXT
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT COALESCE(NULLIF(auth.jwt() -> 'app_metadata' ->> 'role', ''), 'ground_staff');
$$;

-- brands uses brand_id in the live schema.
CREATE OR REPLACE FUNCTION public.setup_organization_full(
  p_user_id UUID,
  p_org_name TEXT,
  p_org_slug TEXT,
  p_brand_name TEXT,
  p_location_name TEXT,
  p_location_address TEXT DEFAULT ''
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  INSERT INTO public.organizations (name, slug, owner_id)
  VALUES (p_org_name, p_org_slug, p_user_id)
  RETURNING id INTO v_org_id;

  INSERT INTO public.brands (organization_id, name)
  VALUES (v_org_id, p_brand_name)
  RETURNING brand_id INTO v_brand_id;

  INSERT INTO public.locations (organization_id, brand_id, name, address)
  VALUES (v_org_id, v_brand_id, p_location_name, p_location_address)
  RETURNING id INTO v_location_id;

  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (v_org_id, p_user_id, 'org_owner')
  ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.brand_members (brand_id, user_id, role)
  VALUES (v_brand_id, p_user_id, 'org_owner')
  ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  INSERT INTO public.location_members (location_id, user_id, role)
  VALUES (v_location_id, p_user_id, 'org_owner')
  ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET organization_id = v_org_id,
      brand_id        = v_brand_id,
      location_id     = v_location_id,
      role            = 'org_owner',
      access_level    = 'organization',
      updated_at      = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'org_owner',
    'organization_id', v_org_id::text,
    'brand_id', v_brand_id::text,
    'location_id', v_location_id::text
  )
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'org_id',      v_org_id,
    'brand_id',    v_brand_id,
    'location_id', v_location_id
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite RECORD;
  v_user_id UUID;
  v_user_email TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND LOWER(email) = LOWER(v_user_email);

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (v_invite.organization_id, v_user_id, v_invite.role)
  ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_invite.role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_invite.role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET role            = v_invite.role,
      organization_id = v_invite.organization_id,
      brand_id        = COALESCE(v_invite.brand_id, brand_id),
      location_id     = COALESCE(v_invite.location_id, location_id),
      access_level    = COALESCE(v_invite.access_level, access_level),
      updated_at      = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id
  WHERE id = v_invite.id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_invite.role,
    'organization_id', v_invite.organization_id::text,
    'brand_id', COALESCE(v_invite.brand_id::text, ''),
    'location_id', COALESCE(v_invite.location_id::text, '')
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success',         true,
    'role',            v_invite.role,
    'organization_id', v_invite.organization_id,
    'brand_id',        v_invite.brand_id,
    'location_id',     v_invite.location_id
  );
END;
$$;

-- invoice_line_items uses internal_product_id and total_price in the live schema.
CREATE OR REPLACE FUNCTION public.calculate_invoice_allocations(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_tax NUMERIC;
  v_fuel NUMERIC;
  v_delivery NUMERIC;
  v_other NUMERIC;
  v_cat_record RECORD;
BEGIN
  SELECT organization_id,
         COALESCE(tax_amount, 0),
         COALESCE(fuel_surcharge, 0),
         COALESCE(delivery_fee, 0),
         COALESCE(other_charges, 0)
  INTO v_org_id, v_tax, v_fuel, v_delivery, v_other
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  DELETE FROM public.invoice_allocations WHERE invoice_id = p_invoice_id;

  FOR v_cat_record IN (
    SELECT
      COALESCE(p.category, 'uncategorized') AS cat_name,
      SUM(COALESCE(ili.total_price, ili.quantity * ili.unit_price, 0)) AS total_amount
    FROM public.invoice_line_items ili
    LEFT JOIN public.products p ON ili.internal_product_id = p.id
    WHERE ili.invoice_id = p_invoice_id
    GROUP BY COALESCE(p.category, 'uncategorized')
  ) LOOP
    IF COALESCE(v_cat_record.total_amount, 0) > 0 THEN
      INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, gl_code, amount)
      SELECT
        v_org_id,
        p_invoice_id,
        'line_items',
        v_cat_record.cat_name,
        (SELECT gl_code FROM public.gl_mappings WHERE organization_id = v_org_id AND LOWER(category) = LOWER(v_cat_record.cat_name) LIMIT 1),
        v_cat_record.total_amount;
    END IF;
  END LOOP;

  IF v_tax > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'tax', 'Tax', v_tax);
  END IF;

  IF v_delivery > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'delivery', 'Delivery Fee', v_delivery);
  END IF;

  IF v_fuel > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'fuel', 'Fuel Surcharge', v_fuel);
  END IF;

  IF v_other > 0 THEN
    INSERT INTO public.invoice_allocations (organization_id, invoice_id, allocation_type, category_name, amount)
    VALUES (v_org_id, p_invoice_id, 'other', 'Other Charges', v_other);
  END IF;

  RETURN jsonb_build_object('success', true, 'message', 'Allocations calculated');
END;
$$;

CREATE OR REPLACE FUNCTION public.record_invoice_payment(
  p_invoice_id UUID,
  p_amount NUMERIC,
  p_reference TEXT,
  p_payment_method TEXT DEFAULT 'manual'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_new_paid_amount NUMERIC;
  v_new_status TEXT;
  v_payment_id UUID;
BEGIN
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + COALESCE(p_amount, 0);
  v_new_status := CASE WHEN v_new_paid_amount >= COALESCE(v_invoice.total_amount, 0) THEN 'paid' ELSE 'partially_paid' END;

  UPDATE public.invoices
  SET paid_amount = v_new_paid_amount,
      payment_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE 'partial' END,
      status = v_new_status,
      ap_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE ap_status END,
      payment_reference = p_reference,
      updated_at = now()
  WHERE id = p_invoice_id;

  INSERT INTO public.payments (
    invoice_id, vendor_id, vendor_name, invoice_number,
    amount, payment_method, status, transaction_id, payment_date,
    payment_account_id, organization_id, brand_id, location_id, created_by
  )
  VALUES (
    v_invoice.id, v_invoice.vendor_id, v_invoice.vendor_name, v_invoice.invoice_number,
    p_amount, p_payment_method, 'completed', p_reference, CURRENT_DATE,
    v_invoice.payment_account_id, v_invoice.organization_id, v_invoice.brand_id, v_invoice.location_id, auth.uid()
  )
  RETURNING id INTO v_payment_id;

  RETURN jsonb_build_object(
    'status', v_new_status,
    'paid_amount', v_new_paid_amount,
    'payment_id', v_payment_id
  );
END;
$$;

-- recipe_ingredients does not store name; join products for display names.
CREATE OR REPLACE FUNCTION public.calculate_theoretical_depletion(
  p_org_id UUID,
  p_sales_json JSONB
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF NOT public.is_platform_admin() AND p_org_id != public.get_auth_org() THEN
    RAISE EXCEPTION 'Access Denied: Tenant context violation.';
  END IF;

  WITH sales AS (
    SELECT
      (elem->>'name')::TEXT AS sale_name,
      COALESCE((elem->>'qty')::NUMERIC, 0) AS sale_qty
    FROM jsonb_array_elements(p_sales_json) elem
  ),
  matched_recipes AS (
    SELECT
      s.sale_qty,
      r.id AS recipe_id
    FROM sales s
    JOIN public.recipes r ON lower(trim(r.name)) = lower(trim(s.sale_name))
    WHERE r.organization_id = p_org_id
  ),
  depletions AS (
    SELECT
      ri.product_id,
      COALESCE(p.name, ri.product_id::text) AS product_name,
      SUM(ri.quantity * mr.sale_qty) AS total_used,
      MAX(ri.unit) AS unit
    FROM matched_recipes mr
    JOIN public.recipe_ingredients ri ON ri.recipe_id = mr.recipe_id
    LEFT JOIN public.products p ON p.id = ri.product_id
    WHERE ri.organization_id = p_org_id
    GROUP BY ri.product_id, COALESCE(p.name, ri.product_id::text)
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'product_id', d.product_id,
      'product_name', d.product_name,
      'total_used', d.total_used,
      'unit', d.unit
    ) ORDER BY d.total_used DESC
  ), '[]'::jsonb)
  INTO v_result
  FROM depletions d;

  RETURN v_result;
END;
$$;

-- POS data exposes revenue and quantity_sold, not total_sales/actual_cost.
CREATE OR REPLACE FUNCTION public.get_cross_location_benchmarks(p_org_id UUID)
RETURNS TABLE (
    name TEXT,
    sales NUMERIC,
    "laborCost" NUMERIC,
    cogs NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
    IF NOT public.is_platform_admin() AND public.get_my_org() != p_org_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization data.';
    END IF;

    RETURN QUERY
    WITH date_range AS (
        SELECT (now() - interval '30 days') AS start_date
    ),
    sales_by_location AS (
        SELECT ps.location_id, COALESCE(SUM(ps.revenue), 0) AS sales
        FROM public.pos_sales_data ps
        WHERE ps.date >= (SELECT start_date FROM date_range)
        GROUP BY ps.location_id
    ),
    cogs_by_location AS (
        SELECT i.location_id, COALESCE(SUM(i.total_amount), 0) AS cogs
        FROM public.invoices i
        WHERE COALESCE(i.invoice_date, i.created_at::date) >= (SELECT start_date::date FROM date_range)
        GROUP BY i.location_id
    ),
    location_sales AS (
        SELECT
            l.id AS location_id,
            l.name AS location_name,
            COALESCE(s.sales, 0) AS sales,
            COALESCE(c.cogs, 0) AS cogs
        FROM public.locations l
        LEFT JOIN sales_by_location s ON l.id = s.location_id
        LEFT JOIN cogs_by_location c ON l.id = c.location_id
        WHERE l.organization_id = p_org_id
        GROUP BY l.id, l.name, s.sales, c.cogs
    ),
    location_labor AS (
        SELECT
            l.id AS location_id,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.locations l
        LEFT JOIN public.employees e ON l.id = e.location_id
        LEFT JOIN public.employee_shifts es
            ON e.id = es.employee_id
            AND es.start_time >= (SELECT start_date FROM date_range)
        WHERE l.organization_id = p_org_id
        GROUP BY l.id
    )
    SELECT
        ls.location_name AS name,
        ROUND(ls.sales, 2) AS sales,
        ROUND(ll.labor_cost::NUMERIC, 2) AS "laborCost",
        ROUND(ls.cogs, 2) AS cogs
    FROM location_sales ls
    JOIN location_labor ll ON ls.location_id = ll.location_id
    ORDER BY ls.sales DESC;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF NOT public.is_platform_admin()
       AND public.get_my_org() != (SELECT organization_id FROM public.locations WHERE id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location data.';
    END IF;

    SELECT COALESCE(AVG(revenue), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data
    WHERE location_id = p_location_id AND date >= (now() - interval '30 days');

    RETURN QUERY
    WITH dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS d
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(d.d, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM dates d
    LEFT JOIN scheduled s ON d.d = s.shift_date
    ORDER BY d.d ASC;
END;
$$;

CREATE OR REPLACE FUNCTION public.ai_chat_response(p_org_id UUID, p_query TEXT)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_lower_query TEXT := lower(p_query);
    v_sales_yesterday NUMERIC;
    v_forecast_tomorrow NUMERIC;
    v_labor_cost NUMERIC;
    v_pending_invoices INT;
    v_variance NUMERIC;
BEGIN
    IF NOT public.is_platform_admin() AND public.get_my_org() != p_org_id THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this organization data.';
    END IF;

    IF v_lower_query LIKE '%variance%' OR v_lower_query LIKE '%food cost%' THEN
        WITH invoice_spend AS (
            SELECT COALESCE(SUM(i.total_amount), 0) AS amount
            FROM public.invoices i
            WHERE i.location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
              AND COALESCE(i.invoice_date, i.created_at::date) >= (now() - interval '7 days')::date
        ),
        sales AS (
            SELECT COALESCE(SUM(ps.revenue), 0) AS amount
            FROM public.pos_sales_data ps
            WHERE ps.location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
              AND ps.date >= (now() - interval '7 days')::date
        )
        SELECT invoice_spend.amount - (sales.amount * 0.30)
        INTO v_variance
        FROM invoice_spend, sales;

        RETURN 'Based on available invoice and POS data, estimated food cost variance over the last 7 days is $' || round(v_variance, 2) || '.';

    ELSIF v_lower_query LIKE '%labor%' OR v_lower_query LIKE '%schedule%' OR v_lower_query LIKE '%staff%' THEN
        SELECT COALESCE(AVG(revenue), 5200.00) INTO v_forecast_tomorrow
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id);

        SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 1600.00)
        INTO v_labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
          AND date_trunc('day', es.start_time) = date_trunc('day', now() + interval '1 day');

        RETURN 'Tomorrow forecast predicts $' || round(v_forecast_tomorrow, 2) || ' in sales. Current scheduled labor is $' || round(v_labor_cost, 2) || ' (' || round((v_labor_cost / NULLIF(v_forecast_tomorrow, 0)) * 100, 1) || '%).';

    ELSIF v_lower_query LIKE '%brief%' OR v_lower_query LIKE '%yesterday%' OR v_lower_query LIKE '%summary%' THEN
        SELECT COUNT(*) INTO v_pending_invoices
        FROM public.invoices
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
          AND status = 'pending_review';

        SELECT COALESCE(SUM(revenue), 0) INTO v_sales_yesterday
        FROM public.pos_sales_data
        WHERE location_id IN (SELECT id FROM public.locations WHERE organization_id = p_org_id)
          AND date_trunc('day', date) = date_trunc('day', now() - interval '1 day');

        RETURN 'Yesterday briefing: sales were $' || round(v_sales_yesterday, 2) || '. There are ' || v_pending_invoices || ' invoices pending review.';

    ELSE
        RETURN 'I am analyzing your organization data. Try asking about food cost variance, labor schedule, or yesterday briefing.';
    END IF;
END;
$$;

-- Source: 119_fix_labor_forecast_date_ambiguity.sql
-- Migration 119: Fix get_labor_forecast date ambiguity

CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF NOT public.is_platform_admin()
       AND public.get_my_org() != (SELECT l.organization_id FROM public.locations l WHERE l.id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location data.';
    END IF;

    SELECT COALESCE(AVG(ps.revenue), 3000)
    INTO avg_daily_sales
    FROM public.pos_sales_data ps
    WHERE ps.location_id = p_location_id
      AND ps.date >= (now() - interval '30 days');

    RETURN QUERY
    WITH forecast_dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS forecast_day
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(fd.forecast_day, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM forecast_dates fd
    LEFT JOIN scheduled s ON fd.forecast_day = s.shift_date
    ORDER BY fd.forecast_day ASC;
END;
$$;

-- Source: 120_native_workflow_triggers.sql
-- 1. Create a generic trigger function that dispatches events to Edge Functions
CREATE OR REPLACE FUNCTION public.invoke_edge_function()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  function_name TEXT := TG_ARGV[0];
  v_url TEXT;
  v_service_role_key TEXT;
  v_headers JSONB;
  v_payload JSONB;
BEGIN
  -- Construct the Edge Function URL. 
  -- We default to the known production URL, but allow overrides via custom settings if needed.
  v_url := COALESCE(current_setting('app.settings.functions_url', true), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/' || function_name;
  v_service_role_key := current_setting('app.settings.service_role_key', true);

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE EXCEPTION 'app.settings.service_role_key is required for invoke_edge_function';
  END IF;
  
  v_headers := jsonb_build_object(
    'Content-Type', 'application/json',
    'Authorization', 'Bearer ' || v_service_role_key
  );

  v_payload := jsonb_build_object(
    'type', TG_OP,
    'table', TG_TABLE_NAME,
    'schema', TG_TABLE_SCHEMA,
    'record', CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) ELSE null END,
    'old_record', CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD) ELSE null END
  );

  PERFORM net.http_post(
      url := v_url,
      body := v_payload,
      headers := v_headers
  );
  
  RETURN NULL; -- AFTER trigger
END;
$$;

-- Source: 121_safe_updated_at_trigger.sql
-- Migration 121: Make shared updated_at trigger safe on mixed schemas
--
-- Some live workflow inserts fail with:
--   record "new" has no field "updated_at"
-- That happens when the generic updated_at trigger function is attached to an
-- object that does not expose an updated_at column. Keep the trigger behavior
-- for normal tables, but no-op safely for tables without that column.

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  IF to_jsonb(NEW) ? 'updated_at' THEN
    NEW := jsonb_populate_record(NEW, jsonb_build_object('updated_at', now()));
  END IF;

  RETURN NEW;
END;
$$;

