-- 3. UPDATE setup_organization_full RPC to write to app_metadata
CREATE OR REPLACE FUNCTION public.setup_organization_full(
  p_user_id UUID,
  p_org_name TEXT,
  p_org_slug TEXT,
  p_brand_name TEXT,
  p_location_name TEXT,
  p_location_address TEXT DEFAULT ''
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  INSERT INTO public.organizations (name, slug, owner_id)
  VALUES (p_org_name, p_org_slug, p_user_id)
  RETURNING id INTO v_org_id;

  INSERT INTO public.brands (organization_id, name)
  VALUES (v_org_id, p_brand_name)
  RETURNING id INTO v_brand_id;

  INSERT INTO public.locations (organization_id, brand_id, name, address)
  VALUES (v_org_id, v_brand_id, p_location_name, p_location_address)
  RETURNING id INTO v_location_id;

  UPDATE public.profiles
  SET organization_id = v_org_id,
      brand_id        = v_brand_id,
      location_id     = v_location_id,
      role            = 'org_owner',
      access_level    = 'organization',
      updated_at      = now()
  WHERE id = p_user_id;

  -- Use raw_app_meta_data
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'org_owner',
    'organization_id', v_org_id::text
  )
  WHERE id = p_user_id;

  RETURN jsonb_build_object(
    'org_id',      v_org_id,
    'brand_id',    v_brand_id,
    'location_id', v_location_id
  );
END;
$$;

-- 4. UPDATE accept_invitation RPC to write to app_metadata
CREATE OR REPLACE FUNCTION public.accept_invitation(p_token TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite RECORD;
  v_user_id UUID;
  v_user_email TEXT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND LOWER(email) = LOWER(v_user_email);

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  UPDATE public.profiles
  SET role            = v_invite.role,
      organization_id = v_invite.organization_id,
      brand_id        = COALESCE(v_invite.brand_id, brand_id),
      location_id     = COALESCE(v_invite.location_id, location_id),
      updated_at      = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id
  WHERE id = v_invite.id;

  -- Use raw_app_meta_data
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_invite.role,
    'organization_id', v_invite.organization_id::text
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success',         true,
    'role',            v_invite.role,
    'organization_id', v_invite.organization_id
  );
END;
$$;

-- 5. UPDATE admin_update_user_role RPC to write to app_metadata
CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id    UUID,
  new_role          TEXT,
  new_status        TEXT         DEFAULT NULL,
  new_department    TEXT         DEFAULT NULL,
  new_location      TEXT         DEFAULT NULL,
  new_permissions   JSONB        DEFAULT NULL,
  new_brand_id      UUID         DEFAULT NULL,
  new_location_id   UUID         DEFAULT NULL,
  new_access_level  TEXT         DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
  target_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := public.get_auth_org();

  IF caller_role NOT IN ('org_owner', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can update user roles';
  END IF;

  SELECT organization_id INTO target_org
  FROM public.profiles
  WHERE id = target_user_id;

  IF caller_role = 'org_owner' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND new_role IS NOT NULL THEN
    IF NOT public.can_invite_role(new_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND caller_role = 'org_owner' AND new_role != 'org_owner' THEN
    RAISE EXCEPTION 'Cannot change your own role. Transfer ownership first.';
  END IF;

  UPDATE public.profiles
  SET role         = COALESCE(new_role, role),
      status       = COALESCE(new_status, status),
      department   = COALESCE(new_department, department),
      permissions  = COALESCE(new_permissions, permissions),
      brand_id     = COALESCE(new_brand_id, brand_id),
      location_id  = COALESCE(new_location_id, location_id),
      access_level = COALESCE(new_access_level, access_level),
      updated_at   = now()
  WHERE id = target_user_id;

  -- Use raw_app_meta_data
  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', COALESCE(new_role, (SELECT role FROM public.profiles WHERE id = target_user_id))
  )
  WHERE id = target_user_id;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Source: 126_fix_admin_delete_rpc.sql
-- ============================================================
-- Migration 055: Fix admin_delete_user RPC Storage Constraint
-- ============================================================

CREATE OR REPLACE FUNCTION public.admin_delete_user(target_user_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    caller_role TEXT;
    v_email TEXT;
    v_full_name TEXT;
    v_role TEXT;
BEGIN
    -- 1. Check if caller is authenticated
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- 2. Verify the caller is a platform_admin
    caller_role := COALESCE(auth.jwt() -> 'app_metadata' ->> 'role', '');
    
    IF caller_role != 'platform_admin' THEN
        RAISE EXCEPTION 'Insufficient permissions: only platform_admin can delete users permanently';
    END IF;

    -- 3. Prevent self-deletion via this route
    IF target_user_id = auth.uid() THEN
        RAISE EXCEPTION 'You cannot delete your own account.';
    END IF;

    -- 4. Gather user details before deletion for the archive
    SELECT email, full_name, role INTO v_email, v_full_name, v_role
    FROM public.profiles
    WHERE id = target_user_id;

    -- If profile was missing, fallback to auth.users for email
    IF v_email IS NULL THEN
        SELECT email INTO v_email FROM auth.users WHERE id = target_user_id;
    END IF;

    -- 5. Archive the user
    INSERT INTO public.archived_users (original_user_id, email, full_name, role, deleted_by)
    VALUES (target_user_id, v_email, v_full_name, v_role, auth.uid());

    -- 6. Detach any files the user uploaded to prevent Foreign Key constraints from blocking deletion
    UPDATE storage.objects SET owner = NULL WHERE owner = target_user_id;

    -- 7. Delete the user from auth.users
    -- Because this function is SECURITY DEFINER, it runs with the privileges 
    -- of the user who created it (postgres superuser during migrations),
    -- allowing it to safely bypass the auth schema restrictions.
    DELETE FROM auth.users WHERE id = target_user_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Source: 127_vendor_command_center.sql
-- 5. Trigger to auto-update vendor total spent when an invoice is paid or approved
CREATE OR REPLACE FUNCTION public.update_vendor_metrics_on_invoice()
RETURNS TRIGGER AS $$
BEGIN
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN
    UPDATE public.vendors 
    SET total_spent = total_spent + NEW.total_amount,
        unpaid_ap = unpaid_ap + NEW.total_amount
    WHERE id = NEW.vendor_id;
  END IF;

  IF NEW.payment_status = 'paid' AND (OLD.payment_status IS NULL OR OLD.payment_status != 'paid') THEN
    UPDATE public.vendors 
    SET unpaid_ap = GREATEST(unpaid_ap - NEW.total_amount, 0)
    WHERE id = NEW.vendor_id;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 128_fix_lint_errors.sql
-- 1. Fix get_labor_forecast "date" ambiguous reference
CREATE OR REPLACE FUNCTION public.get_labor_forecast(p_location_id UUID)
RETURNS TABLE (
    date TEXT,
    "salesForecast" NUMERIC,
    "scheduledLabor" NUMERIC,
    "suggestedLabor" NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    avg_daily_sales NUMERIC;
BEGIN
    IF NOT public.is_platform_admin()
       AND public.get_my_org() != (SELECT organization_id FROM public.locations WHERE id = p_location_id) THEN
        RAISE EXCEPTION 'Unauthorized: You do not have access to this location data.';
    END IF;

    SELECT COALESCE(AVG(ps.revenue), 3000) INTO avg_daily_sales
    FROM public.pos_sales_data ps
    WHERE ps.location_id = p_location_id AND ps.date >= (now() - interval '30 days');

    RETURN QUERY
    WITH dates AS (
        SELECT generate_series(
            date_trunc('day', now()),
            date_trunc('day', now() + interval '6 days'),
            interval '1 day'
        ) AS d
    ),
    scheduled AS (
        SELECT
            date_trunc('day', es.start_time) AS shift_date,
            COALESCE(SUM(EXTRACT(EPOCH FROM (es.end_time - es.start_time))/3600 * COALESCE(e.hourly_rate, 15)), 0) AS labor_cost
        FROM public.employee_shifts es
        JOIN public.employees e ON es.employee_id = e.id
        WHERE e.location_id = p_location_id
        GROUP BY date_trunc('day', es.start_time)
    )
    SELECT
        to_char(d.d, 'Mon DD') AS date,
        ROUND(avg_daily_sales * (1 + (random() * 0.4 - 0.2))::NUMERIC, 2) AS "salesForecast",
        ROUND(COALESCE(s.labor_cost::NUMERIC, 0), 2) AS "scheduledLabor",
        ROUND(avg_daily_sales * 0.28, 2) AS "suggestedLabor"
    FROM dates d
    LEFT JOIN scheduled s ON d.d = s.shift_date
    ORDER BY d.d ASC;
END;
$$;

-- 2. Fix schedule_invoice_payment: never read variable "v_org_id"
CREATE OR REPLACE FUNCTION public.schedule_invoice_payment(
  p_invoice_id UUID, 
  p_payment_account_id UUID, 
  p_date DATE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice_status TEXT;
BEGIN
  -- Verify the invoice exists and get its status
  SELECT status INTO v_invoice_status
  FROM public.invoices WHERE id = p_invoice_id;

  IF v_invoice_status NOT IN ('approved', 'scheduled') THEN
    RAISE EXCEPTION 'Invoice must be approved to schedule payment';
  END IF;

  -- Update the invoice
  UPDATE public.invoices
  SET payment_account_id = p_payment_account_id,
      scheduled_payment_date = p_date,
      status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
      ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
      updated_at = now()
  WHERE id = p_invoice_id;

  RETURN jsonb_build_object('status', 'scheduled', 'scheduled_payment_date', p_date);
END;
$$;

-- 3. Fix reconcile_invoice_lines: unused variable "v_variance_id", "v_match_id", "v_tolerance"
CREATE OR REPLACE FUNCTION public.reconcile_invoice_lines(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_po_id UUID;
  v_line RECORD;
BEGIN
  SELECT organization_id, purchase_order_id INTO v_org_id, v_po_id 
  FROM public.invoices WHERE id = p_invoice_id;

  -- Delete existing matches and variances for this invoice
  DELETE FROM public.invoice_line_matches WHERE invoice_line_id IN (SELECT id FROM public.invoice_line_items WHERE invoice_id = p_invoice_id);
  DELETE FROM public.reconciliation_variances WHERE invoice_id = p_invoice_id;

  FOR v_line IN (SELECT * FROM public.invoice_line_items WHERE invoice_id = p_invoice_id) LOOP
    INSERT INTO public.invoice_line_matches (organization_id, invoice_line_id, match_status, match_confidence)
    VALUES (v_org_id, v_line.id, 'unmatched', 0.0);

    -- If no PO linked, create a missing_po variance
    IF v_po_id IS NULL THEN
      INSERT INTO public.reconciliation_variances 
      (organization_id, invoice_id, invoice_line_id, variance_type, expected_value, actual_value, variance_amount)
      VALUES (v_org_id, p_invoice_id, v_line.id, 'missing_po', 0, v_line.total_price, v_line.total_price);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'reconciled_lines', (SELECT count(*) FROM public.invoice_line_items WHERE invoice_id = p_invoice_id));
END;
$$;

-- 4. Fix schedule_payment_batch: auto variable "i" shadows a previously defined variable, unused variable "i".
CREATE OR REPLACE FUNCTION public.schedule_payment_batch(
    p_vendor_id UUID,
    p_payment_account_id UUID,
    p_scheduled_date DATE,
    p_invoice_ids UUID[],
    p_amounts NUMERIC[]
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_scheduled_payment_id UUID;
    v_total NUMERIC := 0;
BEGIN
    -- Calculate total
    FOR i IN 1 .. array_length(p_amounts, 1) LOOP
        v_total := v_total + p_amounts[i];
    END LOOP;

    -- Create scheduled payment record
    INSERT INTO public.scheduled_payments (
        organization_id,
        vendor_id,
        payment_account_id,
        total_amount,
        scheduled_date,
        status,
        created_by
    ) VALUES (
        public.get_my_org(),
        p_vendor_id,
        p_payment_account_id,
        v_total,
        p_scheduled_date,
        'scheduled',
        auth.uid()
    ) RETURNING id INTO v_scheduled_payment_id;

    -- Insert intersection records
    FOR i IN 1 .. array_length(p_invoice_ids, 1) LOOP
        INSERT INTO public.scheduled_payment_invoices (
            scheduled_payment_id,
            invoice_id,
            amount_applied
        ) VALUES (
            v_scheduled_payment_id,
            p_invoice_ids[i],
            p_amounts[i]
        );
        
        -- Update invoice status
        UPDATE public.invoices 
        SET scheduled_payment_date = p_scheduled_date,
            status = 'scheduled'
        WHERE id = p_invoice_ids[i];
    END LOOP;

    RETURN v_scheduled_payment_id;
END;
$$;

-- 5. Fix match_vendor: unused variable "v_vendor_id".
CREATE OR REPLACE FUNCTION public.match_vendor(p_org_id UUID, p_vendor_name TEXT)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_exact_match UUID;
  v_alias_match UUID;
  v_fuzzy_match UUID;
BEGIN
  -- 1. Exact match on vendors table
  SELECT id INTO v_exact_match FROM public.vendors 
  WHERE organization_id = p_org_id AND LOWER(name) = LOWER(p_vendor_name)
  LIMIT 1;
  
  IF v_exact_match IS NOT NULL THEN
    RETURN v_exact_match;
  END IF;

  -- 2. Exact match on vendor_aliases
  SELECT canonical_vendor_id INTO v_alias_match FROM public.vendor_aliases
  WHERE organization_id = p_org_id AND LOWER(alias_name) = LOWER(p_vendor_name) AND is_verified = true
  LIMIT 1;

  IF v_alias_match IS NOT NULL THEN
    RETURN v_alias_match;
  END IF;

  -- 3. Fuzzy match using Levenshtein distance
  -- Only consider if distance <= 3 (e.g. slight typo)
  SELECT id INTO v_fuzzy_match FROM public.vendors
  WHERE organization_id = p_org_id AND extensions.levenshtein(LOWER(name), LOWER(p_vendor_name)) <= 3
  ORDER BY extensions.levenshtein(LOWER(name), LOWER(p_vendor_name)) ASC
  LIMIT 1;
  
  RETURN v_fuzzy_match;
END;
$$;

-- 6. Fix admin_update_user_role: unused parameter "new_location".
-- NOTE: Dropping the old signature to prevent duplicated signatures.
DROP FUNCTION IF EXISTS public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, JSONB, UUID, UUID, TEXT, JSONB);

DROP FUNCTION IF EXISTS public.admin_update_user_role(UUID, TEXT, TEXT, TEXT, TEXT, JSONB, UUID, UUID, TEXT);

CREATE OR REPLACE FUNCTION public.admin_update_user_role(
  target_user_id    UUID,
  new_role          TEXT         DEFAULT NULL,
  new_status        TEXT         DEFAULT NULL,
  new_department    TEXT         DEFAULT NULL,
  new_location      TEXT         DEFAULT NULL,
  new_permissions   JSONB        DEFAULT NULL,
  new_brand_id      UUID         DEFAULT NULL,
  new_location_id   UUID         DEFAULT NULL,
  new_access_level  TEXT         DEFAULT NULL,
  new_signing_privileges JSONB   DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
  target_org  UUID;
BEGIN
  -- Suppress unused parameter warning
  IF new_location IS NOT NULL THEN
    -- location string is currently not used but passed by API
  END IF;

  caller_role := public.get_auth_role();
  caller_org  := public.get_auth_org();

  IF caller_role NOT IN ('org_owner', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can update user roles';
  END IF;

  SELECT organization_id INTO target_org
  FROM public.profiles
  WHERE id = target_user_id;

  IF caller_role = 'org_owner' AND target_org IS DISTINCT FROM caller_org THEN
    RAISE EXCEPTION 'Cannot modify users outside your organization';
  END IF;

  IF caller_role != 'platform_admin' AND new_role IS NOT NULL THEN
    IF NOT public.can_invite_role(new_role) THEN
      RAISE EXCEPTION 'Cannot assign a role equal to or above your own';
    END IF;
  END IF;

  IF target_user_id = auth.uid() AND caller_role = 'org_owner' AND new_role != 'org_owner' THEN
    RAISE EXCEPTION 'Cannot change your own role. Transfer ownership first.';
  END IF;
  
  -- Update membership tables
  IF new_role IS NOT NULL AND target_org IS NOT NULL THEN
      INSERT INTO public.organization_members (organization_id, user_id, role)
      VALUES (target_org, target_user_id, new_role)
      ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET role               = COALESCE(new_role, role),
      status             = COALESCE(new_status, status),
      department         = COALESCE(new_department, department),
      permissions        = COALESCE(new_permissions, permissions),
      signing_privileges = COALESCE(new_signing_privileges, signing_privileges),
      brand_id           = COALESCE(new_brand_id, brand_id),
      location_id        = COALESCE(new_location_id, location_id),
      access_level       = COALESCE(new_access_level, access_level),
      updated_at         = now()
  WHERE id = target_user_id;

  -- Only update app_metadata if this is their ACTIVE org
  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = target_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
        'role', COALESCE(new_role, (SELECT role FROM public.profiles WHERE id = target_user_id))
      )
      WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- 7. Fix org_remove_member: unused variable "active_org".
CREATE OR REPLACE FUNCTION public.org_remove_member(
    target_user_id UUID,
    target_org_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := COALESCE(target_org_id, public.get_auth_org());

  IF caller_role != 'org_owner' AND caller_role != 'platform_admin' THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_owner or platform_admin can remove users';
  END IF;

  IF target_user_id = auth.uid() THEN
    RAISE EXCEPTION 'You cannot remove yourself. Transfer ownership first.';
  END IF;

  -- Remove from organization_members
  DELETE FROM public.organization_members 
  WHERE user_id = target_user_id AND organization_id = caller_org;
  
  -- Remove from brand_members for this org
  DELETE FROM public.brand_members 
  WHERE user_id = target_user_id 
    AND brand_id IN (SELECT id FROM public.brands WHERE organization_id = caller_org);
    
  -- Remove from location_members for this org
  DELETE FROM public.location_members 
  WHERE user_id = target_user_id 
    AND location_id IN (SELECT id FROM public.locations WHERE organization_id = caller_org);

  -- Update profiles if this was their active org
  UPDATE public.profiles 
  SET organization_id = NULL, brand_id = NULL, location_id = NULL, role = 'ground_staff'
  WHERE id = target_user_id AND organization_id = caller_org;

  -- Update app_metadata if this is their active context
  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = caller_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = raw_app_meta_data - 'organization_id' - 'role' - 'brand_id' - 'location_id'
      WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Source: 129_server_side_pnl.sql
-- Migration 124: Server-Side PnL Aggregation RPC

-- Create or Replace the RPC for PnL Summary
CREATE OR REPLACE FUNCTION public.get_pnl_summary(
  p_org_id UUID,
  p_start_date DATE,
  p_end_date DATE,
  p_brand_id UUID DEFAULT NULL,
  p_location_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_total_revenue NUMERIC(15,2) := 0;
  v_total_labor NUMERIC(15,2) := 0;
  v_total_cogs_allocated NUMERIC(15,2) := 0;
  v_total_invoices_raw NUMERIC(15,2) := 0;
  v_total_cogs NUMERIC(15,2) := 0;
BEGIN
  -- 1. Calculate Total Revenue from mv_daily_sales_summary
  SELECT COALESCE(SUM(total_revenue), 0) INTO v_total_revenue
  FROM public.mv_daily_sales_summary
  WHERE organization_id = p_org_id
    AND date >= p_start_date 
    AND date <= p_end_date
    AND (p_brand_id IS NULL OR brand_id = p_brand_id)
    AND (p_location_id IS NULL OR location_id = p_location_id);

  -- 2. Calculate Total Labor from employee_shifts
  SELECT COALESCE(SUM(labor_cost), 0) INTO v_total_labor
  FROM public.employee_shifts
  WHERE organization_id = p_org_id
    AND shift_start >= p_start_date 
    AND shift_start <= p_end_date
    AND (p_location_id IS NULL OR location_id = p_location_id);

  -- 3. Calculate Total COGS 
  -- We first check invoice_allocations specifically for 'line_items' within the period.
  -- Because invoice_allocations lacks a date field natively (unless joined to invoices),
  -- we join it to invoices here to apply the date filter.
  SELECT COALESCE(SUM(a.amount), 0) INTO v_total_cogs_allocated
  FROM public.invoice_allocations a
  JOIN public.invoices i ON i.id = a.invoice_id
  WHERE a.organization_id = p_org_id
    AND a.allocation_type = 'line_items'
    AND i.invoice_date >= p_start_date
    AND i.invoice_date <= p_end_date
    AND (p_brand_id IS NULL OR i.brand_id = p_brand_id)
    AND (p_location_id IS NULL OR i.location_id = p_location_id);

  -- If allocated COGS is zero, we fallback to raw total_amount of invoices
  IF v_total_cogs_allocated > 0 THEN
    v_total_cogs := v_total_cogs_allocated;
  ELSE
    SELECT COALESCE(SUM(total_amount), 0) INTO v_total_invoices_raw
    FROM public.invoices
    WHERE organization_id = p_org_id
      AND invoice_date >= p_start_date
      AND invoice_date <= p_end_date
      AND status != 'void'
      AND (p_brand_id IS NULL OR brand_id = p_brand_id)
      AND (p_location_id IS NULL OR location_id = p_location_id);
      
    v_total_cogs := v_total_invoices_raw;
  END IF;

  RETURN jsonb_build_object(
    'total_revenue', v_total_revenue,
    'total_labor_cost', v_total_labor,
    'total_cogs', v_total_cogs,
    'prime_cost', (v_total_cogs + v_total_labor)
  );
END;
$$;

-- Source: 130_labor_schedule_variance.sql
-- Migration 130: Labor Schedule Variance

-- Drop if exists to avoid return type mismatch errors on replace
DROP FUNCTION IF EXISTS public.get_labor_schedule_variance(DATE, DATE, UUID);

CREATE OR REPLACE FUNCTION public.get_labor_schedule_variance(
  p_start_date DATE,
  p_end_date DATE,
  p_location_id UUID
)
RETURNS TABLE (
  date DATE,
  projected_sales NUMERIC(15,2),
  scheduled_labor NUMERIC(15,2),
  suggested_labor NUMERIC(15,2),
  variance_amount NUMERIC(15,2)
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  WITH date_series AS (
    SELECT generate_series(p_start_date, p_end_date, '1 day'::interval)::date AS d
  ),
  daily_sales AS (
    SELECT 
      m.date,
      SUM(m.total_revenue) as projected_sales
    FROM public.mv_daily_sales_summary m
    WHERE m.date >= p_start_date AND m.date <= p_end_date
      AND (p_location_id IS NULL OR m.location_id = p_location_id)
    GROUP BY m.date
  ),
  daily_labor AS (
    SELECT 
      s.shift_start::date AS date,
      SUM(s.labor_cost) as scheduled_labor
    FROM public.employee_shifts s
    WHERE s.shift_start >= p_start_date AND s.shift_start <= p_end_date
      AND (p_location_id IS NULL OR s.location_id = p_location_id)
    GROUP BY s.shift_start::date
  )
  SELECT 
    ds.d AS date,
    COALESCE(s.projected_sales, 0) AS projected_sales,
    COALESCE(l.scheduled_labor, 0) AS scheduled_labor,
    -- Suggested labor is typically ~25% of sales
    (COALESCE(s.projected_sales, 0) * 0.25)::numeric(15,2) AS suggested_labor,
    -- Variance is scheduled minus suggested (positive = overstaffed, negative = understaffed)
    (COALESCE(l.scheduled_labor, 0) - (COALESCE(s.projected_sales, 0) * 0.25))::numeric(15,2) AS variance_amount
  FROM date_series ds
  LEFT JOIN daily_sales s ON ds.d = s.date
  LEFT JOIN daily_labor l ON ds.d = l.date
  ORDER BY ds.d;
END;
$$;

-- Source: 132_three_way_match_rpc.sql
-- Migration 132: Three-Way Match RPC and Trigger

-- 1. Create the RPC to return match status
CREATE OR REPLACE FUNCTION public.get_three_way_match_status(p_purchase_order_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_po RECORD;
  v_invoice RECORD;
  v_receiving RECORD;
  v_po_total NUMERIC := 0;
  v_inv_total NUMERIC := 0;
  v_rec_qty NUMERIC := 0;
  v_po_qty NUMERIC := 0;
  v_variance_amount NUMERIC := 0;
  v_variance_percent NUMERIC := 0;
  v_status TEXT := 'matched';
BEGIN
  -- Get PO details
  SELECT * INTO v_po FROM public.purchase_orders WHERE id = p_purchase_order_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error', 'PO not found'); END IF;

  v_po_total := v_po.total_amount;

  -- Get Invoice details (assume 1 invoice per PO for simplicity)
  SELECT * INTO v_invoice FROM public.invoices WHERE purchase_order_id = p_purchase_order_id ORDER BY created_at DESC LIMIT 1;
  IF FOUND THEN
    v_inv_total := v_invoice.total_amount;
  END IF;

  -- Get total PO quantity
  SELECT COALESCE(SUM(quantity), 0) INTO v_po_qty FROM public.purchase_order_items WHERE purchase_order_id = p_purchase_order_id;

  -- Get total Received quantity
  SELECT COALESCE(SUM(ri.quantity_received), 0) INTO v_rec_qty 
  FROM public.receivings r
  JOIN public.receiving_items ri ON ri.receiving_id = r.id
  WHERE r.purchase_order_id = p_purchase_order_id;

  -- Calculate variance based on invoice vs PO cost
  IF v_inv_total > 0 AND v_po_total > 0 THEN
    v_variance_amount := ABS(v_inv_total - v_po_total);
    v_variance_percent := (v_variance_amount / v_po_total) * 100;
  END IF;

  -- Determine status
  IF v_rec_qty < v_po_qty THEN
    v_status := 'quantity_variance';
  END IF;

  IF v_variance_percent > 5 OR v_variance_amount > 50 THEN
    v_status := 'price_variance';
  END IF;

  -- If both, just say critical_variance
  IF v_rec_qty < v_po_qty AND (v_variance_percent > 5 OR v_variance_amount > 50) THEN
    v_status := 'critical_variance';
  END IF;

  RETURN jsonb_build_object(
    'po_total', v_po_total,
    'invoice_total', v_inv_total,
    'po_quantity', v_po_qty,
    'received_quantity', v_rec_qty,
    'variance_amount', v_variance_amount,
    'variance_percent', v_variance_percent,
    'match_status', v_status
  );
END;
$$;

-- 2. Create Trigger Function to block invoice
CREATE OR REPLACE FUNCTION public.check_three_way_match_before_invoice_approval()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_match_data JSONB;
BEGIN
  -- Only run if there's a PO attached and it's trying to move to approved or pending_payment
  IF NEW.purchase_order_id IS NOT NULL AND NEW.status IN ('approved', 'pending_payment') THEN
    
    -- If it's already pending_match_approval, we don't loop
    IF OLD.status = 'pending_match_approval' AND NEW.status != 'pending_match_approval' THEN
      -- A manager is forcing the approval. Let it pass.
      RETURN NEW;
    END IF;

    v_match_data := public.get_three_way_match_status(NEW.purchase_order_id);
    
    IF v_match_data->>'match_status' IN ('price_variance', 'critical_variance') THEN
      NEW.status := 'pending_match_approval';
      NEW.validation_notes := 'Blocked by Three-Way Match: Variance > 5% or > $50. Requires manager override.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 133_harden_rls_location_access.sql
CREATE OR REPLACE FUNCTION public.get_my_accessible_brand_ids()
RETURNS SETOF UUID
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
  -- 1. Base access from legacy profiles.role
  SELECT b.brand_id
  FROM public.brands b
  WHERE b.organization_id = public.get_auth_org()
    AND (
      public.get_auth_role() IN ('platform_admin', 'org_owner')
      OR (
        public.get_auth_role() = 'branch_manager'
        AND b.brand_id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
      )
    )
  UNION
  -- 2. Location-based brand access from user_roles
  SELECT l.brand_id
  FROM public.locations l
  INNER JOIN public.user_roles ur ON ur.location_id = l.id
  WHERE ur.user_id = auth.uid() AND ur.organization_id = public.get_auth_org()
  UNION
  -- 3. Org-wide access from user_roles (when location_id IS NULL)
  SELECT b.brand_id
  FROM public.brands b
  INNER JOIN public.user_roles ur ON ur.organization_id = b.organization_id
  WHERE ur.user_id = auth.uid() 
    AND ur.organization_id = public.get_auth_org() 
    AND ur.location_id IS NULL;
$$;

COMMENT ON FUNCTION public.get_my_accessible_brand_ids() IS
  'Returns brand IDs the caller can access via profiles or user_roles assignments.';

CREATE OR REPLACE FUNCTION public.get_my_accessible_location_ids()
RETURNS SETOF UUID
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
  -- 1. Base access from legacy profiles.role
  SELECT l.id
  FROM public.locations l
  WHERE l.organization_id = public.get_auth_org()
    AND (
      public.get_auth_role() IN ('platform_admin', 'org_owner')
      OR (
        public.get_auth_role() = 'branch_manager'
        AND l.brand_id IN (
          SELECT b.brand_id FROM public.brands b WHERE b.brand_id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
        )
      )
      OR (
        public.get_auth_role() = 'location_manager'
        AND l.id = (SELECT p.location_id FROM public.profiles p WHERE p.id = auth.uid())
      )
    )
  UNION
  -- 2. Explicit location access from user_roles
  SELECT ur.location_id
  FROM public.user_roles ur
  WHERE ur.user_id = auth.uid() 
    AND ur.organization_id = public.get_auth_org() 
    AND ur.location_id IS NOT NULL
  UNION
  -- 3. Org-wide access from user_roles (when location_id IS NULL)
  SELECT l.id
  FROM public.locations l
  INNER JOIN public.user_roles ur ON ur.organization_id = l.organization_id
  WHERE ur.user_id = auth.uid() 
    AND ur.organization_id = public.get_auth_org() 
    AND ur.location_id IS NULL;
$$;

COMMENT ON FUNCTION public.get_my_accessible_location_ids() IS
  'Returns location IDs the caller can access via profiles or user_roles assignments.';

-- Source: 134_cross_location_benchmarks.sql
-- supabase/migrations/134_cross_location_benchmarks.sql

CREATE OR REPLACE FUNCTION get_location_benchmarks(
  p_organization_id UUID,
  p_start_date DATE,
  p_end_date DATE
)
RETURNS TABLE (
  location_id UUID,
  location_name TEXT,
  total_revenue NUMERIC,
  total_cogs NUMERIC,
  total_labor NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  -- Verify the user has access to this organization
  IF NOT EXISTS (
    SELECT 1 FROM user_profiles
    WHERE id = auth.uid()
    AND organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  RETURN QUERY
  WITH Sales AS (
    SELECT 
      m.location_id,
      SUM(m.total_revenue) as rev
    FROM mv_daily_sales_summary m
    WHERE m.organization_id = p_organization_id
      AND m.date >= p_start_date
      AND m.date <= p_end_date
    GROUP BY m.location_id
  ),
  COGS AS (
    SELECT
      i.location_id,
      SUM(i.total_amount) as cogs
    FROM invoices i
    WHERE i.organization_id = p_organization_id
      AND i.invoice_date >= p_start_date
      AND i.invoice_date <= p_end_date
    GROUP BY i.location_id
  ),
  Labor AS (
    SELECT
      s.location_id,
      SUM(s.labor_cost) as labor
    FROM employee_shifts s
    WHERE s.organization_id = p_organization_id
      AND DATE(s.shift_start) >= p_start_date
      AND DATE(s.shift_start) <= p_end_date
    GROUP BY s.location_id
  )
  SELECT 
    l.id as location_id,
    l.name as location_name,
    COALESCE(s.rev, 0)::NUMERIC as total_revenue,
    COALESCE(c.cogs, 0)::NUMERIC as total_cogs,
    COALESCE(lab.labor, 0)::NUMERIC as total_labor
  FROM locations l
  LEFT JOIN Sales s ON l.id = s.location_id
  LEFT JOIN COGS c ON l.id = c.location_id
  LEFT JOIN Labor lab ON l.id = lab.location_id
  WHERE l.organization_id = p_organization_id
  ORDER BY COALESCE(s.rev, 0) DESC;
END;
$$;

-- Source: 135_prevent_privilege_escalation.sql
CREATE OR REPLACE FUNCTION public.protect_profile_security_columns()
RETURNS TRIGGER AS $$
BEGIN
  -- Check if restricted security columns are being modified
  IF NEW.role IS DISTINCT FROM OLD.role OR
     NEW.organization_id IS DISTINCT FROM OLD.organization_id OR
     NEW.brand_id IS DISTINCT FROM OLD.brand_id OR
     NEW.location_id IS DISTINCT FROM OLD.location_id THEN
     
     -- Only allow modifications if the current database user is NOT authenticated/anon
     -- Typically, standard API requests execute as 'authenticated'. 
     -- System backend actions run as 'postgres' or 'service_role' or 'supabase_admin'.
     IF current_setting('role') IN ('authenticated', 'anon') THEN
        RAISE EXCEPTION '42501: Privilege escalation attempt detected. You cannot modify your own role or organization bindings.';
     END IF;
  END IF;
  
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY INVOKER SET search_path = '';

-- Source: 20260617003000_secure_webhook_dispatcher_cron.sql
CREATE OR REPLACE FUNCTION public.dispatch_webhook_queue()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_url text;
  v_functions_url text;
  v_service_role_key text;
BEGIN
  SELECT setting_value
    INTO v_functions_url
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'functions_url';

  SELECT setting_value
    INTO v_service_role_key
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'service_role_key';

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE EXCEPTION 'private.workflow_runtime_settings.service_role_key is required for dispatch_webhook_queue';
  END IF;

  v_url := COALESCE(
    NULLIF(trim(v_functions_url), ''),
    'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1'
  ) || '/webhook-dispatcher';

  PERFORM net.http_post(
    url := v_url,
    body := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_service_role_key
    )
  );
END;
$$;

-- Source: 20260618051000_resolve_remote_lint_errors.sql
CREATE OR REPLACE FUNCTION public.get_location_benchmarks(
  p_organization_id uuid,
  p_start_date date,
  p_end_date date
)
RETURNS TABLE (
  location_id uuid,
  location_name text,
  total_revenue numeric,
