-- Source: 20260618164500_tenant_backfill_validation.sql
CREATE OR REPLACE FUNCTION public.backfill_tenant_schema(
  p_organization_id UUID,
  p_table_name TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  run_id UUID;
  table_record RECORD;
  table_reg REGCLASS;
  target_reg REGCLASS;
  has_org_id BOOLEAN;
  has_id BOOLEAN;
  column_list TEXT;
  update_list TEXT;
  public_count BIGINT;
  tenant_count BIGINT;
  affected_rows BIGINT;
  copied_tables TEXT[] := ARRAY[]::TEXT[];
  skipped_tables JSONB := '[]'::jsonb;
  failed_tables JSONB := '[]'::jsonb;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can backfill tenant schemas';
  END IF;

  IF p_table_name IS NOT NULL AND p_table_name !~ '^[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Unsafe table name: %', p_table_name;
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF registry_record.organization_id IS NULL OR registry_record.status IN ('planned', 'failed') THEN
    PERFORM public.provision_tenant_schema(p_organization_id);
    SELECT * INTO registry_record
    FROM public.tenant_registry
    WHERE organization_id = p_organization_id
    FOR UPDATE;
  END IF;

  IF registry_record.status NOT IN ('active', 'migrating') THEN
    RAISE EXCEPTION 'Tenant schema must be active before backfill. Current status: %', registry_record.status;
  END IF;

  IF registry_record.schema_name !~ '^tenant_[a-z0-9_]+$' OR length(registry_record.schema_name) > 63 THEN
    RAISE EXCEPTION 'Unsafe tenant schema name: %', registry_record.schema_name;
  END IF;

  INSERT INTO public.tenant_backfill_runs (organization_id, schema_name, status, metadata)
  VALUES (
    p_organization_id,
    registry_record.schema_name,
    'running',
    jsonb_build_object('table_name', p_table_name, 'started_from', 'backfill_tenant_schema')
  )
  RETURNING id INTO run_id;

  UPDATE public.tenant_registry
  SET status = 'migrating',
      metadata = metadata || jsonb_build_object('last_backfill_started_at', now(), 'last_backfill_run_id', run_id)
  WHERE organization_id = p_organization_id;

  FOR table_record IN
    SELECT tmt.table_name
    FROM public.tenant_mirror_tables tmt
    WHERE tmt.enabled = true
      AND (p_table_name IS NULL OR tmt.table_name = p_table_name)
    ORDER BY tmt.table_name
  LOOP
    BEGIN
      table_reg := to_regclass(format('public.%I', table_record.table_name));
      target_reg := to_regclass(format('%I.%I', registry_record.schema_name, table_record.table_name));

      IF table_reg IS NULL OR target_reg IS NULL THEN
        skipped_tables := skipped_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'reason', 'missing source or target table'));
        INSERT INTO public.tenant_backfill_table_results (run_id, organization_id, schema_name, table_name, status, error_message)
        VALUES (run_id, p_organization_id, registry_record.schema_name, table_record.table_name, 'skipped', 'missing source or target table');
        CONTINUE;
      END IF;

      SELECT EXISTS (
        SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'organization_id' AND attnum > 0 AND NOT attisdropped
      ) INTO has_org_id;

      SELECT EXISTS (
        SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'id' AND attnum > 0 AND NOT attisdropped
      ) INTO has_id;

      IF NOT has_org_id OR NOT has_id THEN
        skipped_tables := skipped_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'reason', 'requires id and organization_id columns'));
        INSERT INTO public.tenant_backfill_table_results (run_id, organization_id, schema_name, table_name, status, error_message)
        VALUES (run_id, p_organization_id, registry_record.schema_name, table_record.table_name, 'skipped', 'requires id and organization_id columns');
        CONTINUE;
      END IF;

      SELECT
        string_agg(format('%I', source_columns.column_name), ', ' ORDER BY source_columns.ordinal_position),
        string_agg(format('%I = EXCLUDED.%I', source_columns.column_name, source_columns.column_name), ', ' ORDER BY source_columns.ordinal_position)
      INTO column_list, update_list
      FROM information_schema.columns source_columns
      INNER JOIN information_schema.columns target_columns
        ON target_columns.table_schema = registry_record.schema_name
       AND target_columns.table_name = table_record.table_name
       AND target_columns.column_name = source_columns.column_name
      WHERE source_columns.table_schema = 'public'
        AND source_columns.table_name = table_record.table_name
        AND source_columns.is_generated = 'NEVER'
        AND source_columns.is_identity = 'NO';

      IF column_list IS NULL THEN
        skipped_tables := skipped_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'reason', 'no copyable columns'));
        INSERT INTO public.tenant_backfill_table_results (run_id, organization_id, schema_name, table_name, status, error_message)
        VALUES (run_id, p_organization_id, registry_record.schema_name, table_record.table_name, 'skipped', 'no copyable columns');
        CONTINUE;
      END IF;

      SELECT
        string_agg(format('%I = EXCLUDED.%I', source_columns.column_name, source_columns.column_name), ', ' ORDER BY source_columns.ordinal_position)
      INTO update_list
      FROM information_schema.columns source_columns
      INNER JOIN information_schema.columns target_columns
        ON target_columns.table_schema = registry_record.schema_name
       AND target_columns.table_name = table_record.table_name
       AND target_columns.column_name = source_columns.column_name
      WHERE source_columns.table_schema = 'public'
        AND source_columns.table_name = table_record.table_name
        AND source_columns.column_name <> 'id'
        AND source_columns.is_generated = 'NEVER'
        AND source_columns.is_identity = 'NO';

      EXECUTE format('SELECT count(*) FROM public.%I WHERE organization_id = $1', table_record.table_name)
      INTO public_count
      USING p_organization_id;

      IF update_list IS NULL THEN
        EXECUTE format(
          'INSERT INTO %I.%I (%s) SELECT %s FROM public.%I WHERE organization_id = $1 ON CONFLICT (id) DO NOTHING',
          registry_record.schema_name,
          table_record.table_name,
          column_list,
          column_list,
          table_record.table_name
        )
        USING p_organization_id;
      ELSE
        EXECUTE format(
          'INSERT INTO %I.%I (%s) SELECT %s FROM public.%I WHERE organization_id = $1 ON CONFLICT (id) DO UPDATE SET %s',
          registry_record.schema_name,
          table_record.table_name,
          column_list,
          column_list,
          table_record.table_name,
          update_list
        )
        USING p_organization_id;
      END IF;

      GET DIAGNOSTICS affected_rows = ROW_COUNT;

      EXECUTE format('SELECT count(*) FROM %I.%I WHERE organization_id = $1', registry_record.schema_name, table_record.table_name)
      INTO tenant_count
      USING p_organization_id;

      INSERT INTO public.tenant_backfill_table_results (
        run_id,
        organization_id,
        schema_name,
        table_name,
        public_count,
        tenant_count,
        affected_rows,
        status
      ) VALUES (
        run_id,
        p_organization_id,
        registry_record.schema_name,
        table_record.table_name,
        public_count,
        tenant_count,
        affected_rows,
        CASE WHEN tenant_count >= public_count THEN 'validated' ELSE 'failed' END
      );

      IF tenant_count >= public_count THEN
        copied_tables := array_append(copied_tables, table_record.table_name);
      ELSE
        failed_tables := failed_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'public_count', public_count, 'tenant_count', tenant_count));
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        failed_tables := failed_tables || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'error', SQLERRM));
        INSERT INTO public.tenant_backfill_table_results (run_id, organization_id, schema_name, table_name, status, error_message)
        VALUES (run_id, p_organization_id, registry_record.schema_name, table_record.table_name, 'failed', SQLERRM);
    END;
  END LOOP;

  IF jsonb_array_length(failed_tables) > 0 THEN
    UPDATE public.tenant_backfill_runs
    SET status = 'failed', completed_at = now(), metadata = metadata || jsonb_build_object('failed_tables', failed_tables, 'skipped_tables', skipped_tables)
    WHERE id = run_id;

    UPDATE public.tenant_registry
    SET status = 'failed',
        metadata = metadata || jsonb_build_object('last_backfill_failed_at', now(), 'last_backfill_run_id', run_id, 'failed_tables', failed_tables)
    WHERE organization_id = p_organization_id;
  ELSE
    UPDATE public.tenant_backfill_runs
    SET status = 'completed', completed_at = now(), metadata = metadata || jsonb_build_object('copied_tables', copied_tables, 'skipped_tables', skipped_tables)
    WHERE id = run_id;

    UPDATE public.tenant_registry
    SET status = 'active',
        migrated_at = COALESCE(migrated_at, now()),
        last_validated_at = now(),
        metadata = metadata || jsonb_build_object('last_backfill_completed_at', now(), 'last_backfill_run_id', run_id)
    WHERE organization_id = p_organization_id;
  END IF;

  RETURN jsonb_build_object(
    'success', jsonb_array_length(failed_tables) = 0,
    'run_id', run_id,
    'organization_id', p_organization_id,
    'schema_name', registry_record.schema_name,
    'copied_tables', copied_tables,
    'skipped_tables', skipped_tables,
    'failed_tables', failed_tables
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.validate_tenant_backfill_counts(p_organization_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  table_record RECORD;
  table_reg REGCLASS;
  target_reg REGCLASS;
  public_count BIGINT;
  tenant_count BIGINT;
  mismatches JSONB := '[]'::jsonb;
  checked_tables TEXT[] := ARRAY[]::TEXT[];
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR p_organization_id = public.get_my_org()) THEN
    RAISE EXCEPTION 'Insufficient permissions to validate tenant schema';
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  FOR table_record IN
    SELECT table_name
    FROM public.tenant_mirror_tables
    WHERE enabled = true
    ORDER BY table_name
  LOOP
    table_reg := to_regclass(format('public.%I', table_record.table_name));
    target_reg := to_regclass(format('%I.%I', registry_record.schema_name, table_record.table_name));

    IF table_reg IS NULL OR target_reg IS NULL THEN
      CONTINUE;
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM pg_catalog.pg_attribute WHERE attrelid = table_reg AND attname = 'organization_id' AND attnum > 0 AND NOT attisdropped
    ) THEN
      CONTINUE;
    END IF;

    EXECUTE format('SELECT count(*) FROM public.%I WHERE organization_id = $1', table_record.table_name)
    INTO public_count
    USING p_organization_id;

    EXECUTE format('SELECT count(*) FROM %I.%I WHERE organization_id = $1', registry_record.schema_name, table_record.table_name)
    INTO tenant_count
    USING p_organization_id;

    checked_tables := array_append(checked_tables, table_record.table_name);

    IF tenant_count < public_count THEN
      mismatches := mismatches || jsonb_build_array(jsonb_build_object('table', table_record.table_name, 'public_count', public_count, 'tenant_count', tenant_count));
    END IF;
  END LOOP;

  IF jsonb_array_length(mismatches) = 0 THEN
    UPDATE public.tenant_registry
    SET last_validated_at = now(),
        metadata = metadata || jsonb_build_object('last_count_validation_at', now())
    WHERE organization_id = p_organization_id;
  END IF;

  RETURN jsonb_build_object(
    'success', jsonb_array_length(mismatches) = 0,
    'organization_id', p_organization_id,
    'schema_name', registry_record.schema_name,
    'checked_tables', checked_tables,
    'mismatches', mismatches
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.backfill_planned_tenant_schemas(p_limit INTEGER DEFAULT 5)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  results JSONB := '[]'::jsonb;
  backfill_result JSONB;
  max_count INTEGER;
BEGIN
  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can backfill tenant schemas';
  END IF;

  max_count := greatest(1, least(coalesce(p_limit, 5), 50));

  FOR registry_record IN
    SELECT organization_id
    FROM public.tenant_registry
    WHERE read_mode = 'public'
      AND write_mode = 'public'
      AND status IN ('planned', 'active', 'failed')
    ORDER BY created_at
    LIMIT max_count
  LOOP
    backfill_result := public.backfill_tenant_schema(registry_record.organization_id);
    results := results || jsonb_build_array(backfill_result);
  END LOOP;

  RETURN jsonb_build_object('success', true, 'results', results);
END;
$$;

COMMENT ON FUNCTION public.backfill_tenant_schema(UUID, TEXT) IS
  'Copies one organization from public operational tables into its provisioned tenant schema. Does not change read/write modes.';

COMMENT ON FUNCTION public.validate_tenant_backfill_counts(UUID) IS
  'Compares public and tenant schema row counts for one organization.';

COMMENT ON FUNCTION public.backfill_planned_tenant_schemas(INTEGER) IS
  'Batch helper for backfilling planned/active/failed tenant registry entries that still read/write public tables.';

-- Source: 20260618170000_tenant_read_cutover_controls.sql
CREATE OR REPLACE FUNCTION public.get_tenant_cutover_status(p_organization_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  validation_result JSONB;
  latest_run RECORD;
  blockers JSONB := '[]'::jsonb;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR p_organization_id = public.get_my_org()) THEN
    RAISE EXCEPTION 'Insufficient permissions to inspect tenant cutover status';
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  IF registry_record.status NOT IN ('active', 'migrating') THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant registry is not active', 'status', registry_record.status));
  END IF;

  IF registry_record.schema_name IS NULL OR registry_record.schema_name !~ '^tenant_[a-z0-9_]+$' THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'missing or unsafe tenant schema name'));
  ELSIF to_regnamespace(registry_record.schema_name) IS NULL THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant schema does not exist', 'schema_name', registry_record.schema_name));
  END IF;

  SELECT * INTO latest_run
  FROM public.tenant_backfill_runs
  WHERE organization_id = p_organization_id
    AND schema_name = registry_record.schema_name
  ORDER BY started_at DESC
  LIMIT 1;

  IF latest_run.id IS NULL THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'no backfill run found'));
  ELSIF latest_run.status <> 'completed' THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'latest backfill run is not completed', 'run_id', latest_run.id, 'status', latest_run.status));
  END IF;

  validation_result := public.validate_tenant_backfill_counts(p_organization_id);

  IF COALESCE((validation_result->>'success')::BOOLEAN, false) IS NOT TRUE THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'count validation failed', 'validation', validation_result));
  END IF;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'latest_backfill_run_id', latest_run.id,
    'latest_backfill_status', latest_run.status,
    'validation', validation_result,
    'ready_for_tenant_schema_reads', jsonb_array_length(blockers) = 0,
    'blockers', blockers
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.set_tenant_read_mode(
  p_organization_id UUID,
  p_read_mode TEXT,
  p_force BOOLEAN DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  cutover_status JSONB;
  ready BOOLEAN;
  event_status TEXT;
  event_id UUID;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF p_read_mode NOT IN ('public', 'dual', 'tenant_schema') THEN
    RAISE EXCEPTION 'Invalid read mode: %', p_read_mode;
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can set tenant read mode';
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  cutover_status := public.get_tenant_cutover_status(p_organization_id);
  ready := COALESCE((cutover_status->>'ready_for_tenant_schema_reads')::BOOLEAN, false);

  IF p_read_mode = 'tenant_schema' AND NOT ready AND NOT p_force THEN
    INSERT INTO public.tenant_cutover_events (
      organization_id,
      schema_name,
      previous_read_mode,
      new_read_mode,
      previous_write_mode,
      new_write_mode,
      status,
      validation
    ) VALUES (
      p_organization_id,
      registry_record.schema_name,
      registry_record.read_mode,
      p_read_mode,
      registry_record.write_mode,
      registry_record.write_mode,
      'blocked',
      cutover_status
    ) RETURNING id INTO event_id;

    RETURN jsonb_build_object(
      'success', false,
      'event_id', event_id,
      'organization_id', p_organization_id,
      'requested_read_mode', p_read_mode,
      'current_read_mode', registry_record.read_mode,
      'blocked', true,
      'cutover_status', cutover_status
    );
  END IF;

  UPDATE public.tenant_registry
  SET read_mode = p_read_mode,
      metadata = metadata || jsonb_build_object('last_read_mode_change_at', now(), 'last_read_mode', p_read_mode)
  WHERE organization_id = p_organization_id
  RETURNING * INTO registry_record;

  event_status := CASE
    WHEN p_read_mode = 'public' THEN 'rolled_back'
    ELSE 'applied'
  END;

  INSERT INTO public.tenant_cutover_events (
    organization_id,
    schema_name,
    previous_read_mode,
    new_read_mode,
    previous_write_mode,
    new_write_mode,
    status,
    validation
  ) VALUES (
    p_organization_id,
    registry_record.schema_name,
    cutover_status->>'read_mode',
    p_read_mode,
    registry_record.write_mode,
    registry_record.write_mode,
    event_status,
    cutover_status
  ) RETURNING id INTO event_id;

  RETURN jsonb_build_object(
    'success', true,
    'event_id', event_id,
    'organization_id', registry_record.organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'forced', p_force,
    'cutover_status', cutover_status
  );
END;
$$;

COMMENT ON FUNCTION public.get_tenant_cutover_status(UUID) IS
  'Returns whether a tenant is ready for tenant_schema reads based on provisioning and backfill validation.';

COMMENT ON FUNCTION public.set_tenant_read_mode(UUID, TEXT, BOOLEAN) IS
  'Safely changes tenant read mode. tenant_schema mode is blocked unless validation passes, unless force is true.';

-- Source: 20260619101500_tenant_write_cutover_controls.sql
CREATE OR REPLACE FUNCTION public.get_tenant_write_cutover_status(p_organization_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  read_status JSONB;
  blockers JSONB := '[]'::jsonb;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR p_organization_id = public.get_my_org()) THEN
    RAISE EXCEPTION 'Insufficient permissions to inspect tenant write cutover status';
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  read_status := public.get_tenant_cutover_status(p_organization_id);

  IF COALESCE((read_status->>'ready_for_tenant_schema_reads')::BOOLEAN, false) IS NOT TRUE THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant is not ready for tenant schema reads', 'read_status', read_status));
  END IF;

  IF registry_record.read_mode <> 'tenant_schema' THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'read_mode must be tenant_schema before tenant_schema writes', 'read_mode', registry_record.read_mode));
  END IF;

  IF registry_record.status NOT IN ('active', 'migrating') THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant registry is not active', 'status', registry_record.status));
  END IF;

  IF registry_record.schema_name IS NULL OR registry_record.schema_name !~ '^tenant_[a-z0-9_]+$' THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'missing or unsafe tenant schema name'));
  ELSIF to_regnamespace(registry_record.schema_name) IS NULL THEN
    blockers := blockers || jsonb_build_array(jsonb_build_object('reason', 'tenant schema does not exist', 'schema_name', registry_record.schema_name));
  END IF;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'read_status', read_status,
    'ready_for_tenant_schema_writes', jsonb_array_length(blockers) = 0,
    'blockers', blockers
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.set_tenant_write_mode(
  p_organization_id UUID,
  p_write_mode TEXT,
  p_read_mode TEXT DEFAULT NULL,
  p_force BOOLEAN DEFAULT false
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  previous_read_mode TEXT;
  previous_write_mode TEXT;
  write_status JSONB;
  ready BOOLEAN;
  event_status TEXT;
  event_id UUID;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can set tenant write mode';
  END IF;

  IF p_write_mode NOT IN ('public', 'dual', 'tenant_schema') THEN
    RAISE EXCEPTION 'Invalid write mode: %', p_write_mode;
  END IF;

  IF p_read_mode IS NOT NULL AND p_read_mode NOT IN ('public', 'dual', 'tenant_schema') THEN
    RAISE EXCEPTION 'Invalid read mode: %', p_read_mode;
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  previous_read_mode := registry_record.read_mode;
  previous_write_mode := registry_record.write_mode;
  write_status := public.get_tenant_write_cutover_status(p_organization_id);
  ready := COALESCE((write_status->>'ready_for_tenant_schema_writes')::BOOLEAN, false);

  IF p_write_mode = 'tenant_schema' AND NOT ready AND NOT p_force THEN
    INSERT INTO public.tenant_cutover_events (
      cutover_type,
      organization_id,
      schema_name,
      previous_read_mode,
      new_read_mode,
      previous_write_mode,
      new_write_mode,
      status,
      validation
    ) VALUES (
      'write',
      p_organization_id,
      registry_record.schema_name,
      previous_read_mode,
      COALESCE(p_read_mode, previous_read_mode),
      previous_write_mode,
      p_write_mode,
      'blocked',
      write_status
    ) RETURNING id INTO event_id;

    RETURN jsonb_build_object(
      'success', false,
      'event_id', event_id,
      'organization_id', p_organization_id,
      'requested_write_mode', p_write_mode,
      'current_write_mode', previous_write_mode,
      'blocked', true,
      'write_cutover_status', write_status
    );
  END IF;

  IF p_write_mode IN ('dual', 'tenant_schema') AND registry_record.status NOT IN ('active', 'migrating') THEN
    RAISE EXCEPTION 'Tenant schema must be active before enabling % write mode. Current status: %', p_write_mode, registry_record.status;
  END IF;

  UPDATE public.tenant_registry
  SET write_mode = p_write_mode,
      read_mode = COALESCE(p_read_mode, read_mode),
      metadata = metadata || jsonb_build_object(
        'last_write_mode_change_at', now(),
        'last_write_mode', p_write_mode,
        'last_mode_change_at', now()
      )
  WHERE organization_id = p_organization_id
  RETURNING * INTO registry_record;

  event_status := CASE
    WHEN p_write_mode = 'public' THEN 'rolled_back'
    ELSE 'applied'
  END;

  INSERT INTO public.tenant_cutover_events (
    cutover_type,
    organization_id,
    schema_name,
    previous_read_mode,
    new_read_mode,
    previous_write_mode,
    new_write_mode,
    status,
    validation
  ) VALUES (
    'write',
    p_organization_id,
    registry_record.schema_name,
    previous_read_mode,
    registry_record.read_mode,
    previous_write_mode,
    p_write_mode,
    event_status,
    write_status
  ) RETURNING id INTO event_id;

  RETURN jsonb_build_object(
    'success', true,
    'event_id', event_id,
    'organization_id', registry_record.organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'forced', p_force,
    'write_cutover_status', write_status
  );
END;
$$;

COMMENT ON FUNCTION public.get_tenant_write_cutover_status(UUID) IS
  'Returns whether a tenant is ready for tenant_schema writes. Requires tenant_schema reads and validation readiness.';

COMMENT ON FUNCTION public.set_tenant_write_mode(UUID, TEXT, TEXT, BOOLEAN) IS
  'Safely changes tenant write mode. tenant_schema mode is blocked unless read cutover and validation pass, unless force is true.';

-- Source: 20260619103000_tenant_reporting_snapshots.sql
CREATE OR REPLACE FUNCTION public.count_tenant_reporting_rows(
  p_schema_name TEXT,
  p_table_name TEXT,
  p_organization_id UUID
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  row_count BIGINT := 0;
  has_org_column BOOLEAN := false;
BEGIN
  IF p_schema_name IS NULL OR p_table_name IS NULL THEN
    RETURN 0;
  END IF;

  IF p_schema_name !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' OR p_table_name !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
    RAISE EXCEPTION 'Unsafe schema or table name for tenant reporting count';
  END IF;

  IF to_regclass(format('%I.%I', p_schema_name, p_table_name)) IS NULL THEN
    RETURN 0;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns c
    WHERE c.table_schema = p_schema_name
      AND c.table_name = p_table_name
      AND c.column_name = 'organization_id'
  ) INTO has_org_column;

  IF has_org_column THEN
    EXECUTE format('SELECT count(*) FROM %I.%I WHERE organization_id = $1', p_schema_name, p_table_name)
    INTO row_count
    USING p_organization_id;
  ELSE
    EXECUTE format('SELECT count(*) FROM %I.%I', p_schema_name, p_table_name)
    INTO row_count;
  END IF;

  RETURN COALESCE(row_count, 0);
END;
$$;

CREATE OR REPLACE FUNCTION public.refresh_tenant_reporting_snapshot(p_organization_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  organization_record RECORD;
  latest_backfill RECORD;
  latest_cutover RECORD;
  read_status JSONB;
  write_status JSONB;
  combined_blockers JSONB := '[]'::jsonb;
  public_counts JSONB := '{}'::jsonb;
  tenant_counts JSONB := '{}'::jsonb;
  table_record RECORD;
  public_table_count BIGINT := 0;
  tenant_table_count BIGINT := 0;
  total_public_count BIGINT := 0;
  total_tenant_count BIGINT := 0;
  schema_available BOOLEAN := false;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' OR p_organization_id = public.get_my_org()) THEN
    RAISE EXCEPTION 'Insufficient permissions to refresh tenant reporting snapshot';
  END IF;

  SELECT tr.* INTO registry_record
  FROM public.tenant_registry tr
  WHERE tr.organization_id = p_organization_id;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  SELECT o.id, o.name INTO organization_record
  FROM public.organizations o
  WHERE o.id = p_organization_id;

  schema_available := registry_record.schema_name IS NOT NULL
    AND registry_record.schema_name ~ '^tenant_[a-z0-9_]+$'
    AND to_regnamespace(registry_record.schema_name) IS NOT NULL;

  SELECT br.* INTO latest_backfill
  FROM public.tenant_backfill_runs br
  WHERE br.organization_id = p_organization_id
  ORDER BY br.started_at DESC
  LIMIT 1;

  SELECT ce.* INTO latest_cutover
  FROM public.tenant_cutover_events ce
  WHERE ce.organization_id = p_organization_id
  ORDER BY ce.created_at DESC
  LIMIT 1;

  read_status := public.get_tenant_cutover_status(p_organization_id);
  write_status := public.get_tenant_write_cutover_status(p_organization_id);

  combined_blockers := COALESCE(read_status->'blockers', '[]'::jsonb)
    || COALESCE(write_status->'blockers', '[]'::jsonb);

  FOR table_record IN
    SELECT table_name
    FROM public.tenant_template_tables
    ORDER BY copy_order, table_name
  LOOP
    public_table_count := public.count_tenant_reporting_rows('public', table_record.table_name, p_organization_id);
    tenant_table_count := CASE
      WHEN schema_available THEN public.count_tenant_reporting_rows(registry_record.schema_name, table_record.table_name, p_organization_id)
      ELSE 0
    END;

    total_public_count := total_public_count + public_table_count;
    total_tenant_count := total_tenant_count + tenant_table_count;
    public_counts := public_counts || jsonb_build_object(table_record.table_name, public_table_count);
    tenant_counts := tenant_counts || jsonb_build_object(table_record.table_name, tenant_table_count);
  END LOOP;

  INSERT INTO public.tenant_reporting_snapshots (
    organization_id,
    organization_name,
    schema_name,
    status,
    read_mode,
    write_mode,
    schema_exists,
    latest_backfill_run_id,
    latest_backfill_status,
    latest_backfill_finished_at,
    latest_cutover_event_id,
    latest_cutover_type,
    latest_cutover_status,
    latest_cutover_at,
    public_row_count,
    tenant_schema_row_count,
    row_count_delta,
    ready_for_tenant_schema_reads,
    ready_for_tenant_schema_writes,
    blockers,
    metrics,
    refreshed_at
  ) VALUES (
    p_organization_id,
    organization_record.name,
    registry_record.schema_name,
    registry_record.status,
    registry_record.read_mode,
    registry_record.write_mode,
    schema_available,
    latest_backfill.id,
    latest_backfill.status,
    latest_backfill.completed_at,
    latest_cutover.id,
    latest_cutover.cutover_type,
    latest_cutover.status,
    latest_cutover.created_at,
    total_public_count,
    total_tenant_count,
    total_public_count - total_tenant_count,
    COALESCE((read_status->>'ready_for_tenant_schema_reads')::BOOLEAN, false),
    COALESCE((write_status->>'ready_for_tenant_schema_writes')::BOOLEAN, false),
    combined_blockers,
    jsonb_build_object(
      'public_counts_by_table', public_counts,
      'tenant_counts_by_table', tenant_counts,
      'read_status', read_status,
      'write_status', write_status
    ),
    now()
  )
  ON CONFLICT (organization_id) DO UPDATE
  SET organization_name = EXCLUDED.organization_name,
      schema_name = EXCLUDED.schema_name,
      status = EXCLUDED.status,
      read_mode = EXCLUDED.read_mode,
      write_mode = EXCLUDED.write_mode,
      schema_exists = EXCLUDED.schema_exists,
      latest_backfill_run_id = EXCLUDED.latest_backfill_run_id,
      latest_backfill_status = EXCLUDED.latest_backfill_status,
      latest_backfill_finished_at = EXCLUDED.latest_backfill_finished_at,
      latest_cutover_event_id = EXCLUDED.latest_cutover_event_id,
      latest_cutover_type = EXCLUDED.latest_cutover_type,
      latest_cutover_status = EXCLUDED.latest_cutover_status,
      latest_cutover_at = EXCLUDED.latest_cutover_at,
      public_row_count = EXCLUDED.public_row_count,
      tenant_schema_row_count = EXCLUDED.tenant_schema_row_count,
      row_count_delta = EXCLUDED.row_count_delta,
      ready_for_tenant_schema_reads = EXCLUDED.ready_for_tenant_schema_reads,
      ready_for_tenant_schema_writes = EXCLUDED.ready_for_tenant_schema_writes,
      blockers = EXCLUDED.blockers,
      metrics = EXCLUDED.metrics,
      refreshed_at = EXCLUDED.refreshed_at;

  RETURN jsonb_build_object(
    'success', true,
    'organization_id', p_organization_id,
    'schema_name', registry_record.schema_name,
    'status', registry_record.status,
    'read_mode', registry_record.read_mode,
    'write_mode', registry_record.write_mode,
    'schema_exists', schema_available,
    'public_row_count', total_public_count,
    'tenant_schema_row_count', total_tenant_count,
    'row_count_delta', total_public_count - total_tenant_count,
    'ready_for_tenant_schema_reads', COALESCE((read_status->>'ready_for_tenant_schema_reads')::BOOLEAN, false),
    'ready_for_tenant_schema_writes', COALESCE((write_status->>'ready_for_tenant_schema_writes')::BOOLEAN, false),
    'blocker_count', jsonb_array_length(combined_blockers)
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.refresh_all_tenant_reporting_snapshots(p_limit INTEGER DEFAULT 25)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  tenant_record RECORD;
  refreshed_count INTEGER := 0;
  results JSONB := '[]'::jsonb;
BEGIN
  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can refresh all tenant reporting snapshots';
  END IF;

  FOR tenant_record IN
    SELECT tr.organization_id
    FROM public.tenant_registry tr
    ORDER BY tr.updated_at DESC NULLS LAST, tr.created_at DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 25), 100))
  LOOP
    refreshed_count := refreshed_count + 1;
    results := results || jsonb_build_array(public.refresh_tenant_reporting_snapshot(tenant_record.organization_id));
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'refreshed_count', refreshed_count,
    'results', results
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_tenant_reporting_snapshots(p_organization_id UUID DEFAULT NULL)
RETURNS TABLE (
  organization_id UUID,
  organization_name TEXT,
  schema_name TEXT,
  status TEXT,
  read_mode TEXT,
  write_mode TEXT,
  schema_exists BOOLEAN,
  latest_backfill_status TEXT,
  latest_cutover_type TEXT,
  latest_cutover_status TEXT,
  public_row_count BIGINT,
  tenant_schema_row_count BIGINT,
  row_count_delta BIGINT,
  ready_for_tenant_schema_reads BOOLEAN,
  ready_for_tenant_schema_writes BOOLEAN,
  blocker_count INTEGER,
  blockers JSONB,
  refreshed_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' THEN
    RETURN QUERY
    SELECT
      trs.organization_id,
      trs.organization_name,
      trs.schema_name,
      trs.status,
      trs.read_mode,
      trs.write_mode,
      trs.schema_exists,
      trs.latest_backfill_status,
      trs.latest_cutover_type,
      trs.latest_cutover_status,
      trs.public_row_count,
      trs.tenant_schema_row_count,
      trs.row_count_delta,
      trs.ready_for_tenant_schema_reads,
      trs.ready_for_tenant_schema_writes,
      jsonb_array_length(trs.blockers)::INTEGER AS blocker_count,
      trs.blockers,
      trs.refreshed_at
    FROM public.tenant_reporting_snapshots trs
    WHERE p_organization_id IS NULL OR trs.organization_id = p_organization_id
    ORDER BY trs.refreshed_at DESC, trs.organization_name ASC NULLS LAST;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    trs.organization_id,
    trs.organization_name,
    trs.schema_name,
    trs.status,
    trs.read_mode,
    trs.write_mode,
    trs.schema_exists,
    trs.latest_backfill_status,
    trs.latest_cutover_type,
    trs.latest_cutover_status,
    trs.public_row_count,
    trs.tenant_schema_row_count,
    trs.row_count_delta,
    trs.ready_for_tenant_schema_reads,
    trs.ready_for_tenant_schema_writes,
    jsonb_array_length(trs.blockers)::INTEGER AS blocker_count,
    trs.blockers,
    trs.refreshed_at
  FROM public.tenant_reporting_snapshots trs
  WHERE trs.organization_id = public.get_my_org()
    AND (p_organization_id IS NULL OR trs.organization_id = p_organization_id)
  ORDER BY trs.refreshed_at DESC;
END;
$$;

COMMENT ON FUNCTION public.refresh_tenant_reporting_snapshot(UUID) IS
  'Refreshes a single tenant migration reporting snapshot. Tenant users can refresh their own tenant only; platform admins/service role can refresh any tenant.';

COMMENT ON FUNCTION public.refresh_all_tenant_reporting_snapshots(INTEGER) IS
  'Refreshes migration reporting snapshots for recent tenant registry entries. Platform admin/service role only.';

COMMENT ON FUNCTION public.get_tenant_reporting_snapshots(UUID) IS
  'Reads tenant migration reporting snapshots. Platform admins see all; tenant users see only their own organization.';

