CREATE OR REPLACE FUNCTION public.set_tenant_pilot_cutover_updated_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.select_tenant_pilot_cutover(
  p_organization_id UUID,
  p_notes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  pilot_record RECORD;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can select a tenant pilot';
  END IF;

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id;

  IF registry_record.organization_id IS NULL THEN
    RAISE EXCEPTION 'Tenant registry entry not found for organization %', p_organization_id;
  END IF;

  INSERT INTO public.tenant_pilot_cutovers (organization_id, schema_name, status, notes, validation)
  VALUES (
    p_organization_id,
    registry_record.schema_name,
    'selected',
    p_notes,
    jsonb_build_object('selected_registry', row_to_json(registry_record))
  )
  ON CONFLICT (organization_id) WHERE status IN ('selected', 'preparing', 'prepared', 'read_cutover', 'write_cutover') DO UPDATE
  SET schema_name = EXCLUDED.schema_name,
      notes = COALESCE(EXCLUDED.notes, public.tenant_pilot_cutovers.notes),
      validation = public.tenant_pilot_cutovers.validation || EXCLUDED.validation
  RETURNING * INTO pilot_record;

  RETURN jsonb_build_object(
    'success', true,
    'pilot_id', pilot_record.id,
    'organization_id', pilot_record.organization_id,
    'schema_name', pilot_record.schema_name,
    'status', pilot_record.status
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.prepare_tenant_pilot_cutover(p_organization_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  pilot_record RECORD;
  provision_result JSONB;
  backfill_result JSONB;
  snapshot_result JSONB;
  read_status JSONB;
  registry_record RECORD;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can prepare a tenant pilot';
  END IF;

  PERFORM public.select_tenant_pilot_cutover(p_organization_id, 'Pilot preparation started');

  UPDATE public.tenant_pilot_cutovers
  SET status = 'preparing',
      validation = validation || jsonb_build_object('preparing_at', now())
  WHERE organization_id = p_organization_id
    AND status IN ('selected', 'preparing', 'prepared', 'failed')
  RETURNING * INTO pilot_record;

  provision_result := public.provision_tenant_schema(p_organization_id);
  backfill_result := public.backfill_tenant_schema(p_organization_id);
  snapshot_result := public.refresh_tenant_reporting_snapshot(p_organization_id);
  read_status := public.get_tenant_cutover_status(p_organization_id);

  SELECT * INTO registry_record
  FROM public.tenant_registry
  WHERE organization_id = p_organization_id;

  UPDATE public.tenant_pilot_cutovers
  SET status = CASE
        WHEN COALESCE((read_status->>'ready_for_tenant_schema_reads')::BOOLEAN, false) THEN 'prepared'
        ELSE 'failed'
      END,
      schema_name = registry_record.schema_name,
      prepared_at = CASE
        WHEN COALESCE((read_status->>'ready_for_tenant_schema_reads')::BOOLEAN, false) THEN now()
        ELSE prepared_at
      END,
      validation = validation || jsonb_build_object(
        'provision_result', provision_result,
        'backfill_result', backfill_result,
        'snapshot_result', snapshot_result,
        'read_status', read_status,
        'prepared_at', now()
      )
  WHERE id = pilot_record.id
  RETURNING * INTO pilot_record;

  RETURN jsonb_build_object(
    'success', pilot_record.status = 'prepared',
    'pilot_id', pilot_record.id,
    'organization_id', pilot_record.organization_id,
    'schema_name', pilot_record.schema_name,
    'status', pilot_record.status,
    'read_status', read_status,
    'snapshot_result', snapshot_result
  );
EXCEPTION WHEN OTHERS THEN
  UPDATE public.tenant_pilot_cutovers
  SET status = 'failed',
      validation = validation || jsonb_build_object('error', SQLERRM, 'failed_at', now())
  WHERE organization_id = p_organization_id
    AND status IN ('selected', 'preparing', 'prepared', 'failed');

  RAISE;
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_tenant_pilot_read_cutover(
  p_organization_id UUID,
  p_confirmation TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  pilot_record RECORD;
  cutover_result JSONB;
BEGIN
  IF p_confirmation <> 'CUTOVER_READ' THEN
    RAISE EXCEPTION 'Read cutover confirmation must be CUTOVER_READ';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can apply pilot read cutover';
  END IF;

  SELECT * INTO pilot_record
  FROM public.tenant_pilot_cutovers
  WHERE organization_id = p_organization_id
    AND status = 'prepared'
  ORDER BY updated_at DESC
  LIMIT 1
  FOR UPDATE;

  IF pilot_record.id IS NULL THEN
    RAISE EXCEPTION 'Pilot must be prepared before read cutover';
  END IF;

  cutover_result := public.set_tenant_read_mode(p_organization_id, 'tenant_schema', false);

  IF COALESCE((cutover_result->>'success')::BOOLEAN, false) IS NOT TRUE THEN
    UPDATE public.tenant_pilot_cutovers
    SET status = 'failed',
        validation = validation || jsonb_build_object('read_cutover_result', cutover_result)
    WHERE id = pilot_record.id;
    RETURN cutover_result;
  END IF;

  UPDATE public.tenant_pilot_cutovers
  SET status = 'read_cutover',
      read_cutover_at = now(),
      validation = validation || jsonb_build_object('read_cutover_result', cutover_result)
  WHERE id = pilot_record.id;

  PERFORM public.refresh_tenant_reporting_snapshot(p_organization_id);

  RETURN cutover_result || jsonb_build_object('pilot_status', 'read_cutover');
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_tenant_pilot_write_cutover(
  p_organization_id UUID,
  p_confirmation TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  pilot_record RECORD;
  cutover_result JSONB;
BEGIN
  IF p_confirmation <> 'CUTOVER_WRITE' THEN
    RAISE EXCEPTION 'Write cutover confirmation must be CUTOVER_WRITE';
  END IF;

  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can apply pilot write cutover';
  END IF;

  SELECT * INTO pilot_record
  FROM public.tenant_pilot_cutovers
  WHERE organization_id = p_organization_id
    AND status = 'read_cutover'
  ORDER BY updated_at DESC
  LIMIT 1
  FOR UPDATE;

  IF pilot_record.id IS NULL THEN
    RAISE EXCEPTION 'Pilot must complete read cutover before write cutover';
  END IF;

  cutover_result := public.set_tenant_write_mode(p_organization_id, 'tenant_schema', NULL, false);

  IF COALESCE((cutover_result->>'success')::BOOLEAN, false) IS NOT TRUE THEN
    UPDATE public.tenant_pilot_cutovers
    SET status = 'failed',
        validation = validation || jsonb_build_object('write_cutover_result', cutover_result)
    WHERE id = pilot_record.id;
    RETURN cutover_result;
  END IF;

  UPDATE public.tenant_pilot_cutovers
  SET status = 'write_cutover',
      write_cutover_at = now(),
      validation = validation || jsonb_build_object('write_cutover_result', cutover_result)
  WHERE id = pilot_record.id;

  PERFORM public.refresh_tenant_reporting_snapshot(p_organization_id);

  RETURN cutover_result || jsonb_build_object('pilot_status', 'write_cutover');
END;
$$;

CREATE OR REPLACE FUNCTION public.complete_tenant_pilot_cutover(
  p_organization_id UUID,
  p_notes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  pilot_record RECORD;
BEGIN
  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can complete a tenant pilot';
  END IF;

  UPDATE public.tenant_pilot_cutovers
  SET status = 'completed',
      completed_at = now(),
      notes = COALESCE(p_notes, notes)
  WHERE organization_id = p_organization_id
    AND status = 'write_cutover'
  RETURNING * INTO pilot_record;

  IF pilot_record.id IS NULL THEN
    RAISE EXCEPTION 'Pilot must be in write_cutover status before completion';
  END IF;

  RETURN jsonb_build_object('success', true, 'pilot_id', pilot_record.id, 'status', pilot_record.status);
END;
$$;

CREATE OR REPLACE FUNCTION public.abort_tenant_pilot_cutover(
  p_organization_id UUID,
  p_notes TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  pilot_record RECORD;
BEGIN
  IF NOT (public.is_platform_admin() OR (SELECT auth.role()) = 'service_role') THEN
    RAISE EXCEPTION 'Insufficient permissions: only platform_admin or service_role can abort a tenant pilot';
  END IF;

  UPDATE public.tenant_pilot_cutovers
  SET status = 'aborted',
      aborted_at = now(),
      notes = COALESCE(p_notes, notes)
  WHERE organization_id = p_organization_id
    AND status IN ('selected', 'preparing', 'prepared', 'read_cutover', 'write_cutover', 'failed')
  RETURNING * INTO pilot_record;

  IF pilot_record.id IS NULL THEN
    RAISE EXCEPTION 'No active pilot found for organization %', p_organization_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'pilot_id', pilot_record.id, 'status', pilot_record.status);
END;
$$;

CREATE OR REPLACE FUNCTION public.get_tenant_pilot_cutovers(p_organization_id UUID DEFAULT NULL)
RETURNS TABLE (
  pilot_id UUID,
  organization_id UUID,
  organization_name TEXT,
  schema_name TEXT,
  status TEXT,
  read_mode TEXT,
  write_mode TEXT,
  ready_for_tenant_schema_reads BOOLEAN,
  ready_for_tenant_schema_writes BOOLEAN,
  blocker_count INTEGER,
  selected_at TIMESTAMPTZ,
  prepared_at TIMESTAMPTZ,
  read_cutover_at TIMESTAMPTZ,
  write_cutover_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  aborted_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ,
  notes TEXT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF public.is_platform_admin() OR (SELECT auth.role()) = 'service_role' THEN
    RETURN QUERY
    SELECT
      pc.id,
      pc.organization_id,
      o.name,
      pc.schema_name,
      pc.status,
      trs.read_mode,
      trs.write_mode,
      COALESCE(trs.ready_for_tenant_schema_reads, false),
      COALESCE(trs.ready_for_tenant_schema_writes, false),
      COALESCE(jsonb_array_length(trs.blockers), 0)::INTEGER,
      pc.selected_at,
      pc.prepared_at,
      pc.read_cutover_at,
      pc.write_cutover_at,
      pc.completed_at,
      pc.aborted_at,
      pc.updated_at,
      pc.notes
    FROM public.tenant_pilot_cutovers pc
    LEFT JOIN public.organizations o ON o.id = pc.organization_id
    LEFT JOIN public.tenant_reporting_snapshots trs ON trs.organization_id = pc.organization_id
    WHERE p_organization_id IS NULL OR pc.organization_id = p_organization_id
    ORDER BY pc.updated_at DESC;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    pc.id,
    pc.organization_id,
    o.name,
    pc.schema_name,
    pc.status,
    trs.read_mode,
    trs.write_mode,
    COALESCE(trs.ready_for_tenant_schema_reads, false),
    COALESCE(trs.ready_for_tenant_schema_writes, false),
    COALESCE(jsonb_array_length(trs.blockers), 0)::INTEGER,
    pc.selected_at,
    pc.prepared_at,
    pc.read_cutover_at,
    pc.write_cutover_at,
    pc.completed_at,
    pc.aborted_at,
    pc.updated_at,
    pc.notes
  FROM public.tenant_pilot_cutovers pc
  LEFT JOIN public.organizations o ON o.id = pc.organization_id
  LEFT JOIN public.tenant_reporting_snapshots trs ON trs.organization_id = pc.organization_id
  WHERE pc.organization_id = public.get_my_org()
    AND (p_organization_id IS NULL OR pc.organization_id = p_organization_id)
  ORDER BY pc.updated_at DESC;
END;
$$;

COMMENT ON FUNCTION public.prepare_tenant_pilot_cutover(UUID) IS
  'Provision, backfill, validate, and refresh reporting for one selected pilot tenant. Does not switch read/write modes.';

COMMENT ON FUNCTION public.apply_tenant_pilot_read_cutover(UUID, TEXT) IS
  'Applies tenant_schema reads for a prepared pilot tenant. Requires confirmation text CUTOVER_READ.';

COMMENT ON FUNCTION public.apply_tenant_pilot_write_cutover(UUID, TEXT) IS
  'Applies tenant_schema writes for a pilot tenant after read cutover. Requires confirmation text CUTOVER_WRITE.';

-- Source: 20260619113000_tenant_entity_read_rpc.sql
CREATE OR REPLACE FUNCTION public.tenant_select_rows(
  p_table_name TEXT,
  p_filters JSONB DEFAULT '{}'::jsonb,
  p_gte JSONB DEFAULT '{}'::jsonb,
  p_lte JSONB DEFAULT '{}'::jsonb,
  p_search_column TEXT DEFAULT NULL,
  p_search TEXT DEFAULT NULL,
  p_order_by TEXT DEFAULT NULL,
  p_ascending BOOLEAN DEFAULT TRUE,
  p_limit INTEGER DEFAULT NULL,
  p_offset INTEGER DEFAULT NULL,
  p_include_deleted BOOLEAN DEFAULT FALSE,
  p_single BOOLEAN DEFAULT FALSE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  caller_org UUID;
  target_org UUID;
  brand_filter UUID;
  location_filter UUID;
  route JSONB;
  source_schema TEXT;
  where_clauses TEXT[] := ARRAY[]::TEXT[];
  order_clause TEXT := '';
  limit_clause TEXT := '';
  offset_clause TEXT := '';
  sql TEXT;
  result JSONB;
  filter_key TEXT;
  filter_value JSONB;
  text_value TEXT;
  column_exists BOOLEAN;
  has_org_column BOOLEAN;
  has_deleted_at BOOLEAN;
BEGIN
  IF p_table_name IS NULL OR p_table_name !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
    RAISE EXCEPTION 'Unsafe table name: %', p_table_name;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.tenant_template_tables ttt
    WHERE ttt.table_name = p_table_name
  ) THEN
    RAISE EXCEPTION 'Table is not tenant-routable: %', p_table_name;
  END IF;

  caller_org := public.get_my_org();
  target_org := COALESCE(NULLIF(p_filters->>'organization_id', '')::UUID, caller_org);
  brand_filter := NULLIF(p_filters->>'brand_id', '')::UUID;
  location_filter := NULLIF(p_filters->>'location_id', '')::UUID;

  PERFORM public.assert_tenant_scope(target_org, brand_filter, location_filter);

  route := public.get_tenant_data_route(target_org, brand_filter, location_filter);
  source_schema := COALESCE(route->>'read_source', 'public');

  IF source_schema <> 'public' AND source_schema !~ '^tenant_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Unsafe tenant source schema: %', source_schema;
  END IF;

  IF to_regclass(format('%I.%I', source_schema, p_table_name)) IS NULL THEN
    RAISE EXCEPTION 'Routed table does not exist: %.%', source_schema, p_table_name;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = source_schema
      AND table_name = p_table_name
      AND column_name = 'organization_id'
  ) INTO has_org_column;

  IF NOT has_org_column THEN
    RAISE EXCEPTION 'Tenant-routed table must include organization_id: %', p_table_name;
  END IF;

  where_clauses := where_clauses || format('%I = %L', 'organization_id', target_org::TEXT);

  SELECT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = source_schema
      AND table_name = p_table_name
      AND column_name = 'deleted_at'
  ) INTO has_deleted_at;

  IF has_deleted_at AND NOT p_include_deleted THEN
    where_clauses := where_clauses || format('%I IS NULL', 'deleted_at');
  END IF;

  FOR filter_key, filter_value IN SELECT key, value FROM jsonb_each(COALESCE(p_filters, '{}'::jsonb))
  LOOP
    IF filter_key = 'organization_id' THEN
      CONTINUE;
    END IF;
    IF filter_key !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
      RAISE EXCEPTION 'Unsafe filter column: %', filter_key;
    END IF;

    SELECT EXISTS (
      SELECT 1
      FROM information_schema.columns
      WHERE table_schema = source_schema
        AND table_name = p_table_name
        AND column_name = filter_key
    ) INTO column_exists;

    IF NOT column_exists THEN
      RAISE EXCEPTION 'Filter column does not exist on %.%: %', source_schema, p_table_name, filter_key;
    END IF;

    IF jsonb_typeof(filter_value) = 'null' THEN
      where_clauses := where_clauses || format('%I IS NULL', filter_key);
    ELSE
      text_value := trim(both '"' from filter_value::TEXT);
      where_clauses := where_clauses || format('%I = %L', filter_key, text_value);
    END IF;
  END LOOP;

  FOR filter_key, filter_value IN SELECT key, value FROM jsonb_each(COALESCE(p_gte, '{}'::jsonb))
  LOOP
    IF filter_key !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
      RAISE EXCEPTION 'Unsafe gte column: %', filter_key;
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = source_schema AND table_name = p_table_name AND column_name = filter_key
    ) INTO column_exists;
    IF NOT column_exists THEN
      RAISE EXCEPTION 'GTE column does not exist on %.%: %', source_schema, p_table_name, filter_key;
    END IF;
    IF jsonb_typeof(filter_value) <> 'null' THEN
      text_value := trim(both '"' from filter_value::TEXT);
      where_clauses := where_clauses || format('%I >= %L', filter_key, text_value);
    END IF;
  END LOOP;

  FOR filter_key, filter_value IN SELECT key, value FROM jsonb_each(COALESCE(p_lte, '{}'::jsonb))
  LOOP
    IF filter_key !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
      RAISE EXCEPTION 'Unsafe lte column: %', filter_key;
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = source_schema AND table_name = p_table_name AND column_name = filter_key
    ) INTO column_exists;
    IF NOT column_exists THEN
      RAISE EXCEPTION 'LTE column does not exist on %.%: %', source_schema, p_table_name, filter_key;
    END IF;
    IF jsonb_typeof(filter_value) <> 'null' THEN
      text_value := trim(both '"' from filter_value::TEXT);
      where_clauses := where_clauses || format('%I <= %L', filter_key, text_value);
    END IF;
  END LOOP;

  IF p_search IS NOT NULL AND p_search_column IS NOT NULL AND p_search_column <> '' THEN
    IF p_search_column !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
      RAISE EXCEPTION 'Unsafe search column: %', p_search_column;
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = source_schema AND table_name = p_table_name AND column_name = p_search_column
    ) INTO column_exists;
    IF NOT column_exists THEN
      RAISE EXCEPTION 'Search column does not exist on %.%: %', source_schema, p_table_name, p_search_column;
    END IF;
    where_clauses := where_clauses || format('%I::TEXT ILIKE %L', p_search_column, '%' || p_search || '%');
  END IF;

  IF p_order_by IS NOT NULL AND p_order_by <> '' THEN
    IF p_order_by !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
      RAISE EXCEPTION 'Unsafe order column: %', p_order_by;
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = source_schema AND table_name = p_table_name AND column_name = p_order_by
    ) INTO column_exists;
    IF column_exists THEN
      order_clause := format(' ORDER BY %I %s', p_order_by, CASE WHEN p_ascending THEN 'ASC' ELSE 'DESC' END);
    END IF;
  END IF;

  IF p_single THEN
    limit_clause := ' LIMIT 1';
  ELSIF p_limit IS NOT NULL THEN
    limit_clause := format(' LIMIT %s', LEAST(GREATEST(p_limit, 1), 500));
  END IF;

  IF p_offset IS NOT NULL AND p_offset > 0 THEN
    offset_clause := format(' OFFSET %s', LEAST(p_offset, 100000));
  END IF;

  IF p_single THEN
    sql := format(
      'SELECT COALESCE((SELECT to_jsonb(t) FROM (SELECT * FROM %I.%I WHERE %s%s%s%s) t), ''null''::jsonb)',
      source_schema,
      p_table_name,
      array_to_string(where_clauses, ' AND '),
      order_clause,
      limit_clause,
      offset_clause
    );
  ELSE
    sql := format(
      'SELECT COALESCE(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) FROM (SELECT * FROM %I.%I WHERE %s%s%s%s) t',
      source_schema,
      p_table_name,
      array_to_string(where_clauses, ' AND '),
      order_clause,
      limit_clause,
      offset_clause
    );
  END IF;

  EXECUTE sql INTO result;
  RETURN result;
END;
$$;

