-- Source: 20260619122500_tenant_joined_read_rpcs.sql
CREATE OR REPLACE FUNCTION public.tenant_select_vendor_statements(
  p_organization_id UUID
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  route JSONB;
  source_schema TEXT;
  result JSONB;
  sql TEXT;
BEGIN
  PERFORM public.assert_tenant_scope(p_organization_id, NULL, NULL);

  route := public.get_tenant_data_route(p_organization_id, NULL, NULL);
  source_schema := COALESCE(route->>'read_source', 'public');

  IF source_schema <> 'public' AND source_schema !~ '^tenant_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Unsafe tenant source schema: %', source_schema;
  END IF;

  IF to_regclass(format('%I.vendor_statements', source_schema)) IS NULL THEN
    RAISE EXCEPTION 'Routed vendor_statements table does not exist: %', source_schema;
  END IF;

  IF to_regclass(format('%I.vendor_statement_lines', source_schema)) IS NULL THEN
    RAISE EXCEPTION 'Routed vendor_statement_lines table does not exist: %', source_schema;
  END IF;

  IF to_regclass(format('%I.vendors', source_schema)) IS NULL THEN
    RAISE EXCEPTION 'Routed vendors table does not exist: %', source_schema;
  END IF;

  sql := format(
    'SELECT COALESCE(jsonb_agg(to_jsonb(statement_row)), ''[]''::jsonb)
     FROM (
       SELECT
         vs.*,
         jsonb_build_object(''name'', v.name) AS vendor,
         COALESCE((
           SELECT jsonb_agg(to_jsonb(vsl) ORDER BY vsl.created_at ASC)
           FROM %I.vendor_statement_lines vsl
           WHERE vsl.statement_id = vs.id
         ), ''[]''::jsonb) AS lines
       FROM %I.vendor_statements vs
       LEFT JOIN %I.vendors v ON v.id = vs.vendor_id
       WHERE vs.organization_id = $1
       ORDER BY vs.statement_date DESC
     ) statement_row',
    source_schema,
    source_schema,
    source_schema
  );

  EXECUTE sql USING p_organization_id INTO result;
  RETURN result;
END;
$$;

CREATE OR REPLACE FUNCTION public.tenant_select_webhook_delivery_logs(
  p_organization_id UUID,
  p_limit INTEGER DEFAULT 100
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  route JSONB;
  source_schema TEXT;
  result JSONB;
  safe_limit INTEGER;
  sql TEXT;
BEGIN
  PERFORM public.assert_tenant_scope(p_organization_id, NULL, NULL);

  route := public.get_tenant_data_route(p_organization_id, NULL, NULL);
  source_schema := COALESCE(route->>'read_source', 'public');
  safe_limit := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);

  IF source_schema <> 'public' AND source_schema !~ '^tenant_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Unsafe tenant source schema: %', source_schema;
  END IF;

  IF to_regclass(format('%I.webhook_delivery_logs', source_schema)) IS NULL THEN
    RAISE EXCEPTION 'Routed webhook_delivery_logs table does not exist: %', source_schema;
  END IF;

  IF to_regclass(format('%I.webhook_events_queue', source_schema)) IS NULL THEN
    RAISE EXCEPTION 'Routed webhook_events_queue table does not exist: %', source_schema;
  END IF;

  IF to_regclass(format('%I.webhook_endpoints', source_schema)) IS NULL THEN
    RAISE EXCEPTION 'Routed webhook_endpoints table does not exist: %', source_schema;
  END IF;

  sql := format(
    'SELECT COALESCE(jsonb_agg(to_jsonb(log_row)), ''[]''::jsonb)
     FROM (
       SELECT
         wdl.*,
         jsonb_build_object(''event_type'', weq.event_type, ''payload'', weq.payload) AS webhook_events_queue,
         jsonb_build_object(''url'', we.url) AS webhook_endpoints
       FROM %I.webhook_delivery_logs wdl
       JOIN %I.webhook_endpoints we ON we.id = wdl.endpoint_id
       LEFT JOIN %I.webhook_events_queue weq ON weq.id = wdl.event_id
       WHERE we.organization_id = $1
       ORDER BY wdl.created_at DESC
       LIMIT %s
     ) log_row',
    source_schema,
    source_schema,
    source_schema,
    safe_limit
  );

  EXECUTE sql USING p_organization_id INTO result;
  RETURN result;
END;
$$;

COMMENT ON FUNCTION public.tenant_select_vendor_statements(UUID) IS
  'Tenant-routed joined read for vendor statements with vendor display data and statement lines.';

COMMENT ON FUNCTION public.tenant_select_webhook_delivery_logs(UUID, INTEGER) IS
  'Tenant-routed joined read for webhook delivery logs through scoped webhook endpoints.';

-- Source: 20260620010000_auto_provision_new_tenants_to_schema.sql
CREATE OR REPLACE FUNCTION public.auto_provision_new_tenant_schema()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  schema_name TEXT;
  table_record RECORD;
  created_tables TEXT[] := ARRAY[]::TEXT[];
  skipped_tables TEXT[] := ARRAY[]::TEXT[];
  registry_record RECORD;
BEGIN
  schema_name := public.generate_tenant_schema_name(NEW.id, NEW.slug, NEW.name);

  IF schema_name !~ '^tenant_[a-z0-9_]+$' OR length(schema_name) > 63 THEN
    RAISE EXCEPTION 'Unsafe tenant schema name: %', schema_name;
  END IF;

  INSERT INTO public.tenant_registry (
    organization_id,
    schema_name,
    status,
    read_mode,
    write_mode,
    metadata
  )
  VALUES (
    NEW.id,
    schema_name,
    'provisioning',
    'tenant_schema',
    'tenant_schema',
    jsonb_build_object(
      'provisioned_by', 'auto_provision_new_tenant_schema',
      'provisioning_policy', 'new_tenant_schema_from_day_one'
    )
  )
  ON CONFLICT (organization_id) DO UPDATE
  SET schema_name = EXCLUDED.schema_name,
      status = 'provisioning',
      read_mode = 'tenant_schema',
      write_mode = 'tenant_schema',
      metadata = public.tenant_registry.metadata || EXCLUDED.metadata || jsonb_build_object('last_auto_provision_attempt_at', now())
  RETURNING * INTO registry_record;

  schema_name := registry_record.schema_name;

  EXECUTE format('CREATE SCHEMA IF NOT EXISTS %I', schema_name);
  EXECUTE format('COMMENT ON SCHEMA %I IS %L', schema_name, 'Per-tenant operational schema for organization ' || NEW.id::text);
  EXECUTE format('REVOKE ALL ON SCHEMA %I FROM PUBLIC', schema_name);
  EXECUTE format('REVOKE ALL ON SCHEMA %I FROM anon', schema_name);
  EXECUTE format('REVOKE ALL ON SCHEMA %I FROM authenticated', schema_name);
  EXECUTE format('GRANT USAGE ON SCHEMA %I TO service_role', schema_name);

  FOR table_record IN
    SELECT table_name, is_required
    FROM public.tenant_template_tables
    ORDER BY copy_order, table_name
  LOOP
    IF to_regclass(format('tenant_template.%I', table_record.table_name)) IS NULL THEN
      IF table_record.is_required THEN
        RAISE EXCEPTION 'Required template table tenant_template.% is missing', table_record.table_name;
      END IF;

      skipped_tables := array_append(skipped_tables, table_record.table_name);
      CONTINUE;
    END IF;

    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS %I.%I (LIKE tenant_template.%I INCLUDING ALL)',
      schema_name,
      table_record.table_name,
      table_record.table_name
    );

    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', schema_name, table_record.table_name);
    EXECUTE format('REVOKE ALL ON TABLE %I.%I FROM PUBLIC', schema_name, table_record.table_name);
    EXECUTE format('REVOKE ALL ON TABLE %I.%I FROM anon', schema_name, table_record.table_name);
    EXECUTE format('REVOKE ALL ON TABLE %I.%I FROM authenticated', schema_name, table_record.table_name);
    EXECUTE format('GRANT ALL ON TABLE %I.%I TO service_role', schema_name, table_record.table_name);
    EXECUTE format('COMMENT ON TABLE %I.%I IS %L', schema_name, table_record.table_name, 'Provisioned tenant table for organization ' || NEW.id::text);

    created_tables := array_append(created_tables, table_record.table_name);
  END LOOP;

  UPDATE public.tenant_registry
  SET status = 'active',
      read_mode = 'tenant_schema',
      write_mode = 'tenant_schema',
      provisioned_at = COALESCE(provisioned_at, now()),
      metadata = metadata || jsonb_build_object(
        'last_provisioned_at', now(),
        'created_table_count', coalesce(array_length(created_tables, 1), 0),
        'skipped_tables', skipped_tables,
        'new_tenant_schema_from_day_one', true
      )
  WHERE organization_id = NEW.id
  RETURNING * INTO registry_record;


  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    UPDATE public.tenant_registry
    SET status = 'failed',
        metadata = metadata || jsonb_build_object(
          'last_error', SQLERRM,
          'last_failed_at', now(),
          'failed_during', 'auto_provision_new_tenant_schema'
        )
    WHERE organization_id = NEW.id;

    RAISE;
END;
$$;

COMMENT ON FUNCTION public.auto_provision_new_tenant_schema() IS
  'Organization insert trigger that provisions future tenants directly into tenant_schema read/write mode.';

-- Source: 20260620012000_fix_location_manager_brand_scope.sql
CREATE OR REPLACE FUNCTION public.get_my_accessible_brand_ids()
RETURNS SETOF UUID
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
  -- Org/platform roles and branch-level profile assignments.
  SELECT b.brand_id
  FROM public.brands b
  WHERE b.organization_id = public.get_auth_org()
    AND (
      public.get_auth_role() IN ('platform_admin', 'org_owner')
      OR (
        public.get_auth_role() = 'branch_manager'
        AND b.brand_id = (SELECT p.brand_id FROM public.profiles p WHERE p.id = auth.uid())
      )
    )
  UNION
  -- Location managers inherit the brand for their assigned location.
  SELECT l.brand_id
  FROM public.locations l
  INNER JOIN public.profiles p ON p.location_id = l.id
  WHERE p.id = auth.uid()
    AND p.organization_id = public.get_auth_org()
    AND p.role = 'location_manager'
  UNION
  -- Explicit location access from user_roles grants access to the parent brand.
  SELECT l.brand_id
  FROM public.locations l
  INNER JOIN public.user_roles ur ON ur.location_id = l.id
  WHERE ur.user_id = auth.uid()
    AND ur.organization_id = public.get_auth_org()
  UNION
  -- Org-wide user_roles rows can see every brand in the organization.
  SELECT b.brand_id
  FROM public.brands b
  INNER JOIN public.user_roles ur ON ur.organization_id = b.organization_id
  WHERE ur.user_id = auth.uid()
    AND ur.organization_id = public.get_auth_org()
    AND ur.location_id IS NULL;
$$;

COMMENT ON FUNCTION public.get_my_accessible_brand_ids() IS
  'Returns brand IDs the caller can access via profile scope or user_roles assignments.';

-- Source: 20260622210000_invoice_performance_optimization.sql
-- 1. Upsert Line Items RPC
CREATE OR REPLACE FUNCTION public.upsert_invoice_line_items(p_invoice_id UUID, p_items JSONB)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_item RECORD;
  v_incoming_ids UUID[] := '{}';
  v_org_id UUID;
BEGIN
  SELECT organization_id INTO v_org_id FROM public.invoices WHERE id = p_invoice_id;

  FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(
    id UUID,
    inventory_item_id UUID,
    internal_product_id UUID,
    item_name TEXT,
    quantity NUMERIC,
    unit_price NUMERIC,
    total_price NUMERIC,
    vendor_item_code TEXT,
    vendor_unit TEXT
  ) LOOP
    IF v_item.id IS NULL THEN
      v_item.id := gen_random_uuid();
      INSERT INTO public.invoice_line_items (
        id, invoice_id, organization_id, inventory_item_id, internal_product_id, item_name, quantity, unit_price, total_price, vendor_item_code, vendor_unit
      ) VALUES (
        v_item.id, p_invoice_id, v_org_id, v_item.inventory_item_id, v_item.internal_product_id, v_item.item_name, v_item.quantity, v_item.unit_price, v_item.total_price, v_item.vendor_item_code, v_item.vendor_unit
      );
    ELSE
      UPDATE public.invoice_line_items SET
        inventory_item_id = v_item.inventory_item_id,
        internal_product_id = v_item.internal_product_id,
        item_name = v_item.item_name,
        quantity = v_item.quantity,
        unit_price = v_item.unit_price,
        total_price = v_item.total_price,
        vendor_item_code = v_item.vendor_item_code,
        vendor_unit = v_item.vendor_unit
      WHERE id = v_item.id AND invoice_id = p_invoice_id;
    END IF;
    v_incoming_ids := array_append(v_incoming_ids, v_item.id);
  END LOOP;

  DELETE FROM public.invoice_line_items 
  WHERE invoice_id = p_invoice_id AND id != ALL(v_incoming_ids);
END;
$$;

-- 2. Sync Products RPC
CREATE OR REPLACE FUNCTION public.sync_invoice_products(p_invoice_id UUID, p_user_id UUID DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_invoice RECORD;
  v_item RECORD;
  v_product_id UUID;
  v_inventory_id UUID;
  v_vendor_item_id UUID;
  v_previous_price NUMERIC;
  v_price_variance_flag BOOLEAN;
  v_price_variance_percent NUMERIC;
  v_threshold NUMERIC := 10;
  v_updates_count INT := 0;
BEGIN
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id;
  IF v_invoice IS NULL THEN RETURN jsonb_build_object('status', 'error', 'message', 'Invoice not found'); END IF;

  -- Phase 8: Idempotency Check
  IF EXISTS (
    SELECT 1 FROM public.invoice_sync_log 
    WHERE invoice_id = p_invoice_id AND operation = 'sync_invoice_products'
  ) THEN
    RETURN jsonb_build_object('status', 'success', 'updates_count', 0, 'idempotent', true);
  END IF;

  FOR v_item IN SELECT * FROM public.invoice_line_items WHERE invoice_id = p_invoice_id LOOP
    v_product_id := v_item.internal_product_id;
    v_price_variance_flag := false;
    v_price_variance_percent := 0;

    IF v_product_id IS NULL AND v_item.item_name IS NOT NULL THEN
      SELECT id INTO v_product_id FROM public.products 
      WHERE organization_id = v_invoice.organization_id AND lower(name) = lower(v_item.item_name) LIMIT 1;
    END IF;

    IF v_invoice.vendor_id IS NOT NULL THEN
      SELECT id, last_price, price_variance_threshold_percent INTO v_vendor_item_id, v_previous_price, v_threshold 
      FROM public.vendor_items 
      WHERE organization_id = v_invoice.organization_id 
        AND vendor_id = v_invoice.vendor_id 
        AND lower(vendor_item_name) = lower(v_item.item_name) LIMIT 1;
        
      IF v_threshold IS NULL THEN v_threshold := 10; END IF;

      IF v_vendor_item_id IS NOT NULL THEN
        IF v_previous_price > 0 AND v_item.unit_price > 0 THEN
          v_price_variance_percent := ((v_item.unit_price - v_previous_price) / v_previous_price) * 100;
          IF abs(v_price_variance_percent) >= v_threshold THEN v_price_variance_flag := true; END IF;
        END IF;

        UPDATE public.vendor_items SET 
          last_price = v_item.unit_price, 
          previous_price = v_previous_price,
          last_invoice_id = p_invoice_id,
          last_price_change_percent = v_price_variance_percent,
          price_variance_flag = v_price_variance_flag,
          updated_at = now()
        WHERE id = v_vendor_item_id;
      ELSE
        INSERT INTO public.vendor_items (organization_id, vendor_id, vendor_item_name, default_price, last_price, last_invoice_id, updated_at) 
        VALUES (v_invoice.organization_id, v_invoice.vendor_id, v_item.item_name, v_item.unit_price, v_item.unit_price, p_invoice_id, now()) 
        RETURNING id INTO v_vendor_item_id;
      END IF;

      UPDATE public.invoice_line_items SET 
        vendor_item_id = v_vendor_item_id,
        price_variance_flag = v_price_variance_flag,
        price_variance_percent = v_price_variance_percent,
        internal_product_id = v_product_id
      WHERE id = v_item.id;
    END IF;

    IF v_product_id IS NOT NULL THEN
      SELECT id INTO v_inventory_id FROM public.inventory 
      WHERE product_id = v_product_id AND organization_id = v_invoice.organization_id FOR UPDATE LIMIT 1;

      IF v_inventory_id IS NOT NULL THEN
        UPDATE public.inventory SET 
          current_quantity = current_quantity + COALESCE(v_item.quantity, 0),
          current_value = current_value + COALESCE(v_item.total_price, 0),
          updated_at = now()
        WHERE id = v_inventory_id;
      ELSE
        INSERT INTO public.inventory (organization_id, product_id, product_name, current_quantity, current_value, updated_at)
        VALUES (v_invoice.organization_id, v_product_id, v_item.item_name, COALESCE(v_item.quantity, 0), COALESCE(v_item.total_price, 0), now());
      END IF;
      v_updates_count := v_updates_count + 1;
    END IF;
  END LOOP;

  -- Phase 9: Audit Logging
  INSERT INTO public.invoice_event_log (invoice_id, event_type, new_value, actor_id)
  VALUES (p_invoice_id, 'inventory_synced', jsonb_build_object('updates_count', v_updates_count), p_user_id);

  -- Phase 8: Record Idempotency
  INSERT INTO public.invoice_sync_log (invoice_id, operation, hash)
  VALUES (p_invoice_id, 'sync_invoice_products', md5(p_invoice_id::text || now()::text));

  RETURN jsonb_build_object('status', 'success', 'updates_count', v_updates_count);
END;
$$;

-- 3. Bulk Process Invoices RPC
CREATE OR REPLACE FUNCTION public.bulk_process_invoices(p_invoice_ids UUID[], p_status TEXT)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_id UUID;
  v_processed INT := 0;
BEGIN
  FOREACH v_id IN ARRAY p_invoice_ids LOOP
    UPDATE public.invoices SET status = p_status, updated_at = now() WHERE id = v_id;
    
    IF p_status = 'approved' THEN
      PERFORM public.sync_invoice_products(v_id);
    ELSIF p_status = 'pending_approval' THEN
      PERFORM public.evaluate_invoice_approval_policy(v_id);
    END IF;
    
    v_processed := v_processed + 1;
  END LOOP;

  RETURN jsonb_build_object('status', 'success', 'processed', v_processed);
END;
$$;

-- Source: 20260622210002_price_variance_tracking.sql
-- 2. Create RPC to fetch flagged vendor items
CREATE OR REPLACE FUNCTION public.get_flagged_vendor_items(p_organization_id UUID)
RETURNS TABLE (
    id UUID,
    vendor_item_name TEXT,
    vendor_name TEXT,
    internal_product_id UUID,
    internal_product_name TEXT,
    previous_price NUMERIC,
    latest_price NUMERIC,
    variance_percent NUMERIC,
    invoice_date TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    RETURN QUERY
    SELECT 
        vi.id,
        vi.vendor_item_name,
        v.name AS vendor_name,
        vim.internal_product_id,
        p.name AS internal_product_name,
        vi.previous_price,
        vi.last_price AS latest_price,
        vi.last_price_change_percent AS variance_percent,
        i.invoice_date::timestamptz
    FROM public.vendor_items vi
    JOIN public.vendors v ON vi.vendor_id = v.id
    LEFT JOIN public.vendor_item_mappings vim ON vim.vendor_item_id = vi.id
    LEFT JOIN public.products p ON vim.internal_product_id = p.id
    LEFT JOIN public.invoices i ON vi.last_invoice_id = i.id
    WHERE vi.organization_id = p_organization_id
      AND vi.price_variance_flag = true
    ORDER BY vi.updated_at DESC;
END;
$$;

-- 3. Create RPC to resolve price variance
CREATE OR REPLACE FUNCTION public.resolve_price_variance(p_vendor_item_id UUID, p_update_product BOOLEAN)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_vendor_item RECORD;
    v_product_id UUID;
BEGIN
    -- Get the vendor item
    SELECT * INTO v_vendor_item FROM public.vendor_items WHERE id = p_vendor_item_id;
    
    IF v_vendor_item IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Vendor item not found');
    END IF;
    
    -- Clear the flag
    UPDATE public.vendor_items 
    SET price_variance_flag = false, updated_at = NOW() 
    WHERE id = p_vendor_item_id;
    
    -- Optionally update master product
    IF p_update_product THEN
        -- Find mapped internal product
        SELECT internal_product_id INTO v_product_id 
        FROM public.vendor_item_mappings 
        WHERE vendor_item_id = p_vendor_item_id 
        LIMIT 1;
        
        IF v_product_id IS NOT NULL THEN
            UPDATE public.products 
            SET latest_price = v_vendor_item.last_price, updated_at = NOW() 
            WHERE id = v_product_id;
        END IF;
    END IF;

    RETURN jsonb_build_object('success', true, 'updated_product_id', v_product_id);
END;
$$;

-- Source: 20260622210003_inventory_count_optimization.sql
CREATE OR REPLACE FUNCTION public.complete_count_session(
    p_organization_id UUID,
    p_location_id UUID,
    p_count_sheet_id UUID,
    p_counts JSONB,
    p_user_id UUID
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_sheet RECORD;
    v_item JSONB;
    v_inv_id UUID;
    v_counted_qty NUMERIC;
    v_expected_qty NUMERIC;
    v_variance_qty NUMERIC;
    v_unit_cost NUMERIC;
    v_variance_dollar NUMERIC;
    v_total_variance_value NUMERIC := 0;
    
    v_counted_data JSONB := '{}'::jsonb;
    v_variance_data JSONB := '{}'::jsonb;
    
    v_count_session_id UUID;
    v_is_favorable BOOLEAN;
    
    v_current_inventory RECORD;
BEGIN
    -- 1. Load the count sheet
    SELECT * INTO v_sheet FROM public.count_sheets WHERE id = p_count_sheet_id AND organization_id = p_organization_id FOR UPDATE;
    
    IF v_sheet IS NULL THEN
        RAISE EXCEPTION 'Count sheet not found';
    END IF;

    -- 2. Process counts and calculate variances
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_sheet.items)
    LOOP
        v_inv_id := (v_item->>'inventory_id')::UUID;
        v_expected_qty := COALESCE((v_item->>'expected_quantity')::NUMERIC, 0);
        
        -- Check if counted value exists in payload, otherwise default to expected
        IF p_counts ? v_inv_id::TEXT THEN
            v_counted_qty := COALESCE((p_counts->>v_inv_id::TEXT)::NUMERIC, 0);
        ELSE
            v_counted_qty := v_expected_qty;
        END IF;

        -- Get current inventory state to get unit_cost and lock row
        SELECT * INTO v_current_inventory FROM public.inventory WHERE id = v_inv_id AND organization_id = p_organization_id FOR UPDATE;
        
        v_unit_cost := COALESCE(v_current_inventory.unit_cost, 0);
        v_variance_qty := v_counted_qty - v_expected_qty;
        v_variance_dollar := v_variance_qty * v_unit_cost;
        
        IF v_variance_dollar <> 0 THEN
            v_total_variance_value := v_total_variance_value + v_variance_dollar;
            v_variance_data := jsonb_set(
                v_variance_data, 
                ARRAY[v_inv_id::TEXT], 
                jsonb_build_object('qty', v_variance_qty, 'value', v_variance_dollar)
            );
        END IF;
        
        v_counted_data := jsonb_set(
            v_counted_data,
            ARRAY[COALESCE(v_inv_id::TEXT, (v_item->>'product_name'))],
            jsonb_build_object(
                'product_name', v_item->>'product_name',
                'expected_quantity', v_expected_qty,
                'counted_quantity', v_counted_qty,
                'unit', COALESCE(v_item->>'unit', 'ea'),
                'unit_cost', v_unit_cost,
                'variance', v_variance_dollar
            )
        );

        -- Update Inventory record
        IF v_counted_qty <> v_expected_qty AND v_current_inventory IS NOT NULL THEN
            UPDATE public.inventory 
            SET 
                current_quantity = v_counted_qty,
                current_value = v_counted_qty * v_unit_cost,
                previous_quantity = v_expected_qty,
                previous_value = v_current_inventory.current_value,
                last_counted_date = CURRENT_DATE,
                updated_at = NOW()
            WHERE id = v_inv_id;
        END IF;
    END LOOP;

    -- 3. Create General Ledger Entry for total variance
    IF abs(v_total_variance_value) > 0.01 THEN
        v_is_favorable := v_total_variance_value > 0;
        
        INSERT INTO public.general_ledger_entries (
            organization_id, date, reference, description, debit_account, credit_account, amount, created_by
        ) VALUES (
            p_organization_id,
            NOW(),
            'INV-VAR-' || extract(epoch from now())::TEXT,
            'Inventory Count Variance Adjustment',
            CASE WHEN v_is_favorable THEN 'Inventory Asset (1210)' ELSE 'COGS - Variance (5100)' END,
            CASE WHEN v_is_favorable THEN 'COGS - Variance (5100)' ELSE 'Inventory Asset (1210)' END,
            abs(v_total_variance_value),
            p_user_id
        );
    END IF;

    -- 4. Create Count Session
    INSERT INTO public.count_sessions (
        organization_id,
        count_sheet_id,
        status,
        counted_data,
        variance_data,
        completed_at,
        counted_by
    ) VALUES (
        p_organization_id,
        p_count_sheet_id,
        'completed',
        v_counted_data,
        v_variance_data,
        NOW(),
        p_user_id
    ) RETURNING id INTO v_count_session_id;

    -- 5. Create Inventory Movements
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_sheet.items)
    LOOP
        v_inv_id := (v_item->>'inventory_id')::UUID;
        v_expected_qty := COALESCE((v_item->>'expected_quantity')::NUMERIC, 0);
        
        IF p_counts ? v_inv_id::TEXT THEN
            v_counted_qty := COALESCE((p_counts->>v_inv_id::TEXT)::NUMERIC, 0);
        ELSE
            v_counted_qty := v_expected_qty;
        END IF;

        IF v_counted_qty <> v_expected_qty THEN
            INSERT INTO public.inventory_movements (
                organization_id,
                location_id,
                inventory_id,
                movement_type,
                quantity,
                source_type,
                source_id,
                previous_quantity,
                new_quantity,
                created_by
            ) VALUES (
                p_organization_id,
                p_location_id,
                v_inv_id,
                'count_variance',
                v_counted_qty - v_expected_qty,
                'count_session',
                v_count_session_id::TEXT,
                v_expected_qty,
                v_counted_qty,
                p_user_id
            );
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'count_session_id', v_count_session_id,
        'total_variance', v_total_variance_value
    );

END;
$$;

-- Source: 20260622210005_logistics_hardening.sql
CREATE OR REPLACE FUNCTION public.receive_purchase_order(
    p_organization_id UUID,
    p_location_id UUID,
    p_order_id UUID,
    p_received_quantities JSONB,
    p_user_id UUID
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_order RECORD;
    v_item JSONB;
    v_expected NUMERIC;
    v_received NUMERIC;
    v_key TEXT;
    
    v_receiving_items JSONB := '[]'::jsonb;
    v_has_discrepancy BOOLEAN := false;
    v_has_short BOOLEAN := false;
    v_order_status TEXT;
    v_receiving_status TEXT;
    
    v_receiving_id UUID;
    v_inventory_id UUID;
    
    v_unit TEXT;
    v_unit_cost NUMERIC;
    v_current_inventory RECORD;
BEGIN
    -- 1. Load the order
    SELECT * INTO v_order FROM public.auto_orders WHERE id = p_order_id AND organization_id = p_organization_id FOR UPDATE;
    
    IF v_order IS NULL THEN
        RAISE EXCEPTION 'Order not found';
    END IF;

    -- 2. Process items to calculate discrepancies
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_order.items)
    LOOP
        v_key := COALESCE(v_item->>'product_id', v_item->>'inventory_id', v_item->>'product_name');
        v_expected := COALESCE((v_item->>'approved_quantity')::NUMERIC, (v_item->>'suggested_quantity')::NUMERIC, (v_item->>'quantity')::NUMERIC, 0);
        
        IF p_received_quantities ? v_key THEN
            v_received := (p_received_quantities->>v_key)::NUMERIC;
        ELSE
            v_received := v_expected;
        END IF;
        
        IF v_received <> v_expected THEN
            v_has_discrepancy := true;
        END IF;
        
        IF v_received < v_expected THEN
            v_has_short := true;
        END IF;

        v_receiving_items := v_receiving_items || jsonb_build_object(
            'product_id', v_item->>'product_id',
            'inventory_id', v_item->>'inventory_id',
            'product_name', v_item->>'product_name',
            'unit', COALESCE(v_item->>'unit', 'ea'),
            'unit_price', COALESCE((v_item->>'unit_price')::NUMERIC, (v_item->>'price')::NUMERIC, 0),
            'expected_quantity', v_expected,
            'received_quantity', v_received,
            'discrepancy', v_expected - v_received,
            'receiving_status', CASE WHEN v_received = v_expected THEN 'matched' WHEN v_received > v_expected THEN 'over' ELSE 'short' END
        );
    END LOOP;

    v_order_status := CASE WHEN v_has_short THEN 'partially_received' ELSE 'received' END;
    v_receiving_status := CASE WHEN v_has_discrepancy THEN 'discrepancy' ELSE 'received' END;

    -- 3. Create Receiving Record
    INSERT INTO public.receivings (
        organization_id,
        order_id,
        vendor_id,
        status,
        items,
        received_by
    ) VALUES (
        p_organization_id,
        p_order_id,
        v_order.vendor_id,
        v_receiving_status,
        v_receiving_items,
        p_user_id
    ) RETURNING id INTO v_receiving_id;

    -- 4. Update Order
    UPDATE public.auto_orders
    SET 
        status = v_order_status,
        last_workflow_step = CASE WHEN v_has_discrepancy THEN 'receiving_discrepancy' ELSE 'received' END
    WHERE id = p_order_id;

    -- 5. Process Inventory Math
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_receiving_items)
    LOOP
        v_received := (v_item->>'received_quantity')::NUMERIC;
        IF v_received <= 0 THEN
            CONTINUE;
        END IF;

        v_unit := COALESCE(v_item->>'unit', 'ea');
        v_unit_cost := (v_item->>'unit_price')::NUMERIC;
        
        -- Try to find existing inventory
        v_current_inventory := NULL;
        IF (v_item->>'product_id') IS NOT NULL THEN
            SELECT * INTO v_current_inventory FROM public.inventory WHERE product_id = v_item->>'product_id' AND organization_id = p_organization_id AND (location_id = p_location_id OR p_location_id IS NULL) LIMIT 1 FOR UPDATE;
        END IF;
        
        IF v_current_inventory IS NULL THEN
            SELECT * INTO v_current_inventory FROM public.inventory WHERE LOWER(product_name) = LOWER(v_item->>'product_name') AND organization_id = p_organization_id AND (location_id = p_location_id OR p_location_id IS NULL) LIMIT 1 FOR UPDATE;
        END IF;

        IF v_current_inventory IS NOT NULL THEN
            -- Update existing
            v_inventory_id := v_current_inventory.id;
            
            UPDATE public.inventory 
            SET 
                current_quantity = v_current_inventory.current_quantity + v_received,
                current_value = (v_current_inventory.current_quantity + v_received) * COALESCE(NULLIF(v_unit_cost, 0), v_current_inventory.unit_cost, 0),
                previous_quantity = v_current_inventory.current_quantity,
                previous_value = v_current_inventory.current_value,
                last_counted_date = CURRENT_DATE,
                updated_at = NOW()
            WHERE id = v_inventory_id;
        ELSE
            -- Create new
            INSERT INTO public.inventory (
                organization_id,
                location_id,
                product_id,
                product_name,
                current_quantity,
                current_unit,
                unit_cost,
                current_value,
                accounting_category,
                par_level,
                reorder_point,
                previous_quantity,
                previous_value
            ) VALUES (
                p_organization_id,
                p_location_id,
                COALESCE(v_item->>'product_id', 'PRD-' || extract(epoch from now())::TEXT),
                v_item->>'product_name',
                v_received,
                v_unit,
                v_unit_cost,
                v_received * v_unit_cost,
                'food',
                0,
                0,
                0,
                0
            ) RETURNING id INTO v_inventory_id;
            
            v_current_inventory := ROW(0, 0); -- Mock for movement previous state
        END IF;

        -- Create movement log
        INSERT INTO public.inventory_movements (
            organization_id,
            location_id,
            inventory_id,
            movement_type,
            quantity,
            source_type,
            source_id,
            previous_quantity,
            new_quantity,
            created_by
        ) VALUES (
            p_organization_id,
            p_location_id,
            v_inventory_id,
            'purchase_order',
            v_received,
            'receiving',
            v_receiving_id::TEXT,
            COALESCE(v_current_inventory.current_quantity, 0),
            COALESCE(v_current_inventory.current_quantity, 0) + v_received,
            p_user_id
        );
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'receiving_id', v_receiving_id,
        'has_discrepancy', v_has_discrepancy,
        'order_status', v_order_status
    );
END;
$$;

CREATE OR REPLACE FUNCTION public.complete_inventory_transfer(
    p_organization_id UUID,
    p_transfer_id UUID,
    p_user_id UUID
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_transfer RECORD;
    v_item JSONB;
    v_qty NUMERIC;
    
    v_source_inv RECORD;
    v_dest_inv RECORD;
    v_dest_inv_id UUID;
    v_unit_cost NUMERIC;
BEGIN
    -- 1. Load the transfer
    SELECT * INTO v_transfer FROM public.transfers WHERE id = p_transfer_id AND organization_id = p_organization_id FOR UPDATE;
    
    IF v_transfer IS NULL THEN
        RAISE EXCEPTION 'Transfer not found';
    END IF;
    
    IF v_transfer.status NOT IN ('pending', 'in_transit') THEN
        RETURN jsonb_build_object('success', true, 'message', 'Transfer already completed');
    END IF;

    -- 2. Process transfer items
    FOR v_item IN SELECT * FROM jsonb_array_elements(v_transfer.items)
    LOOP
        v_qty := (v_item->>'quantity')::NUMERIC;
        v_unit_cost := COALESCE((v_item->>'unit_cost')::NUMERIC, 0);
        
        -- Source Inventory
        SELECT * INTO v_source_inv FROM public.inventory WHERE id = (v_item->>'inventory_id')::UUID FOR UPDATE;
        IF v_source_inv IS NOT NULL THEN
            UPDATE public.inventory 
            SET 
                current_quantity = GREATEST(0, current_quantity - v_qty),
                current_value = GREATEST(0, current_quantity - v_qty) * COALESCE(unit_cost, v_unit_cost),
                previous_quantity = current_quantity,
                previous_value = current_value
            WHERE id = v_source_inv.id;
            
            INSERT INTO public.inventory_movements (
                organization_id, location_id, inventory_id, movement_type, quantity, source_type, source_id, previous_quantity, new_quantity, created_by
            ) VALUES (
                p_organization_id, COALESCE(v_transfer.from_location_id, v_source_inv.location_id), v_source_inv.id, 'transfer_out', -v_qty, 'transfer', p_transfer_id::TEXT, v_source_inv.current_quantity, GREATEST(0, v_source_inv.current_quantity - v_qty), p_user_id
            );
        END IF;

        -- Destination Inventory
        v_dest_inv := NULL;
        IF (v_item->>'product_id') IS NOT NULL THEN
            SELECT * INTO v_dest_inv FROM public.inventory WHERE product_id = v_item->>'product_id' AND organization_id = p_organization_id AND location_id = v_transfer.to_location_id LIMIT 1 FOR UPDATE;
        END IF;
        
        IF v_dest_inv IS NULL THEN
            SELECT * INTO v_dest_inv FROM public.inventory WHERE LOWER(product_name) = LOWER(v_item->>'product_name') AND organization_id = p_organization_id AND location_id = v_transfer.to_location_id LIMIT 1 FOR UPDATE;
        END IF;

        IF v_dest_inv IS NOT NULL THEN
            v_dest_inv_id := v_dest_inv.id;
            UPDATE public.inventory 
            SET 
                current_quantity = current_quantity + v_qty,
                current_value = (current_quantity + v_qty) * COALESCE(unit_cost, v_unit_cost),
                previous_quantity = current_quantity,
                previous_value = current_value
            WHERE id = v_dest_inv.id;
        ELSE
            INSERT INTO public.inventory (
                organization_id, location_id, product_id, product_name, current_quantity, current_unit, unit_cost, current_value, accounting_category, par_level, reorder_point, previous_quantity, previous_value
            ) VALUES (
                p_organization_id, v_transfer.to_location_id, COALESCE(v_item->>'product_id', 'PRD-' || extract(epoch from now())::TEXT), v_item->>'product_name', v_qty, COALESCE(v_item->>'unit', 'ea'), v_unit_cost, v_qty * v_unit_cost, 'food', 0, 0, 0, 0
            ) RETURNING id INTO v_dest_inv_id;
            
            v_dest_inv := ROW(0, 0);
        END IF;

        INSERT INTO public.inventory_movements (
            organization_id, location_id, inventory_id, movement_type, quantity, source_type, source_id, previous_quantity, new_quantity, created_by
        ) VALUES (
            p_organization_id, v_transfer.to_location_id, v_dest_inv_id, 'transfer_in', v_qty, 'transfer', p_transfer_id::TEXT, COALESCE(v_dest_inv.current_quantity, 0), COALESCE(v_dest_inv.current_quantity, 0) + v_qty, p_user_id
        );
        
    END LOOP;

    -- 3. Complete transfer
    UPDATE public.transfers
    SET status = 'completed', completed_at = NOW(), completed_by = p_user_id
    WHERE id = p_transfer_id;

    RETURN jsonb_build_object('success', true);
END;
$$;

-- Source: 20260622210006_accounting_ledger_hardening.sql
-- code/supabase/migrations/138_accounting_ledger_hardening.sql

CREATE OR REPLACE FUNCTION record_payment_ledger(
    p_organization_id UUID,
    p_bill_id UUID,
    p_source_payment_id UUID,
    p_payment_method TEXT,
    p_amount NUMERIC,
    p_payment_date TIMESTAMP WITH TIME ZONE,
    p_user_id UUID
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_ledger_payment_id UUID;
    v_existing_payment_id UUID;
BEGIN
    -- Check if payment already exists
    SELECT id INTO v_existing_payment_id
    FROM ledger_payments
    WHERE source_payment_id = p_source_payment_id;

    IF v_existing_payment_id IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'ledger_payment_id', v_existing_payment_id, 'message', 'Payment already recorded.');
    END IF;

    -- Create Ledger Payment
    INSERT INTO ledger_payments (
        organization_id, bill_id, source_payment_id, payment_method, amount, payment_date, status, created_by
    ) VALUES (
        p_organization_id, p_bill_id, p_source_payment_id, p_payment_method, p_amount, p_payment_date, 'completed', p_user_id
    ) RETURNING id INTO v_ledger_payment_id;

    -- Create Debit Ledger Entry (Accounts Payable)
    INSERT INTO ledger_entries (
        organization_id, account_code, debit, credit, reference_type, reference_id
    ) VALUES (
        p_organization_id, '2000', p_amount, 0, 'payment', p_source_payment_id
    );

    -- Create Credit Ledger Entry (Cash/Bank)
    INSERT INTO ledger_entries (
        organization_id, account_code, debit, credit, reference_type, reference_id
    ) VALUES (
        p_organization_id, '1000', 0, p_amount, 'payment', p_source_payment_id
    );

    RETURN jsonb_build_object('success', true, 'ledger_payment_id', v_ledger_payment_id);
END;
$$;

-- Source: 20260622210007_analytics_hardening.sql
-- code/supabase/migrations/139_analytics_hardening.sql

CREATE OR REPLACE FUNCTION get_performance_dashboard_metrics(
    p_organization_id UUID,
    p_start_date DATE,
    p_end_date DATE,
    p_brand_id UUID DEFAULT NULL,
    p_location_id UUID DEFAULT NULL
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_total_sales NUMERIC := 0;
    v_total_cogs NUMERIC := 0;
    v_total_labor NUMERIC := 0;
    v_today_sales NUMERIC := 0;
    v_today_cogs NUMERIC := 0;
    v_today_labor NUMERIC := 0;
    v_trend_data JSONB;
    v_movers_data JSONB;
    v_category_data JSONB;
    v_pending_invoices_count INT := 0;
BEGIN
    -- 1. Sales & Trends
    SELECT 
        COALESCE(SUM(total_revenue), 0),
        COALESCE(SUM(CASE WHEN date = CURRENT_DATE THEN total_revenue ELSE 0 END), 0)
    INTO v_total_sales, v_today_sales
    FROM mv_daily_sales_summary
    WHERE organization_id = p_organization_id
      AND (p_brand_id IS NULL OR brand_id = p_brand_id)
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND date >= p_start_date AND date <= p_end_date;

    SELECT jsonb_agg(
        jsonb_build_object(
            'date', date,
            'name', to_char(date, 'Dy'),
            'actual', total_revenue,
            'forecast', total_revenue * 1.05
        )
    ) INTO v_trend_data
    FROM mv_daily_sales_summary
    WHERE organization_id = p_organization_id
      AND (p_brand_id IS NULL OR brand_id = p_brand_id)
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND date >= p_start_date AND date <= p_end_date
    ORDER BY date ASC;

    -- 2. COGS & Invoices
    SELECT 
        COALESCE(SUM(total_amount), 0),
        COALESCE(SUM(CASE WHEN invoice_date = CURRENT_DATE THEN total_amount ELSE 0 END), 0),
        COUNT(CASE WHEN status IN ('pending_review', 'validated', 'flagged') THEN 1 END)
    INTO v_total_cogs, v_today_cogs, v_pending_invoices_count
    FROM invoices
    WHERE organization_id = p_organization_id
      AND (p_brand_id IS NULL OR brand_id = p_brand_id)
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND invoice_date >= p_start_date AND invoice_date <= p_end_date;

    -- 3. Category Spend
    SELECT jsonb_agg(
        jsonb_build_object(
            'name', COALESCE(category_name, 'Uncategorized'),
            'spend', amount
        )
    ) INTO v_category_data
    FROM (
        SELECT category_name, SUM(amount) as amount
        FROM invoice_allocations
        WHERE organization_id = p_organization_id
          AND (p_location_id IS NULL OR location_id = p_location_id)
        GROUP BY category_name
        ORDER BY amount DESC
    ) categories;

    -- 4. Labor
    SELECT 
        COALESCE(SUM(labor_cost), 0),
        COALESCE(SUM(CASE WHEN DATE(shift_start) = CURRENT_DATE THEN labor_cost ELSE 0 END), 0)
    INTO v_total_labor, v_today_labor
    FROM employee_shifts
    WHERE organization_id = p_organization_id
      AND (p_location_id IS NULL OR location_id = p_location_id)
      AND DATE(shift_start) >= p_start_date AND DATE(shift_start) <= p_end_date;

    -- 5. Top Price Movers
    -- Finds the latest and previous distinct prices for items
    SELECT jsonb_agg(
        jsonb_build_object(
            'item', item_name,
            'currentPrice', current_price,
            'previousPrice', previous_price,
            'change', ROUND(((current_price - previous_price) / previous_price * 100), 1),
            'status', CASE 
                        WHEN ((current_price - previous_price) / previous_price * 100) > 5 THEN 'critical'
                        WHEN ((current_price - previous_price) / previous_price * 100) > 0 THEN 'warning'
                        WHEN ((current_price - previous_price) / previous_price * 100) < 0 THEN 'positive'
                        ELSE 'neutral'
                      END
        )
    ) INTO v_movers_data
    FROM (
        SELECT 
            item_name,
            MAX(CASE WHEN rn = 1 THEN unit_price END) as current_price,
            MAX(CASE WHEN rn = 2 THEN unit_price END) as previous_price
        FROM (
            SELECT 
                item_name,
                unit_price,
                ROW_NUMBER() OVER(PARTITION BY item_name ORDER BY created_at DESC) as rn
            FROM (
                -- Get distinct prices chronologically
                SELECT DISTINCT ON (item_name, unit_price) 
                    item_name, unit_price, created_at
                FROM invoice_line_items
                WHERE organization_id = p_organization_id
                ORDER BY item_name, unit_price, created_at DESC
            ) distinct_prices
        ) ranked_prices
        GROUP BY item_name
        HAVING MAX(CASE WHEN rn = 1 THEN unit_price END) != MAX(CASE WHEN rn = 2 THEN unit_price END)
           AND MAX(CASE WHEN rn = 2 THEN unit_price END) > 0
        ORDER BY ABS((MAX(CASE WHEN rn = 1 THEN unit_price END) - MAX(CASE WHEN rn = 2 THEN unit_price END)) / MAX(CASE WHEN rn = 2 THEN unit_price END)) DESC
        LIMIT 50
    ) movers;

    RETURN jsonb_build_object(
        'total_sales', v_total_sales,
        'today_sales', v_today_sales,
        'total_cogs', v_total_cogs,
        'today_cogs', v_today_cogs,
        'total_labor', v_total_labor,
        'today_labor', v_today_labor,
        'prime_cost', v_total_cogs + v_total_labor,
        'pending_invoices_count', v_pending_invoices_count,
        'trend_data', COALESCE(v_trend_data, '[]'::jsonb),
        'category_data', COALESCE(v_category_data, '[]'::jsonb),
        'movers_data', COALESCE(v_movers_data, '[]'::jsonb)
    );
END;
$$;

-- Source: 20260622210008_rbac_approval_limits.sql
CREATE OR REPLACE FUNCTION update_user_approval_limit(
    target_user_id UUID,
    new_limit NUMERIC
) RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
    UPDATE profiles
    SET invoice_approval_limit = new_limit,
        updated_at = NOW()
    WHERE id = target_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION approve_invoice_with_limit(
    p_invoice_id UUID,
    p_user_id UUID,
    p_amount NUMERIC
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_user_limit NUMERIC;
BEGIN
    SELECT invoice_approval_limit INTO v_user_limit 
    FROM profiles 
    WHERE id = p_user_id;

    IF v_user_limit IS NULL OR p_amount > v_user_limit THEN
        RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.', COALESCE(v_user_limit, 0), p_amount;
    END IF;

    -- If approved, update the invoice
    UPDATE invoices
    SET status = 'approved',
        updated_at = NOW()
    WHERE id = p_invoice_id;

    RETURN jsonb_build_object('success', true, 'message', 'Invoice approved successfully');
END;
$$;

