-- Source: 20260624000007_vendor_ap_routing.sql
CREATE OR REPLACE FUNCTION public.update_vendor_ap_routing(
  p_vendor_id UUID,
  p_ap_routing_preference TEXT,
  p_organization_id UUID DEFAULT NULL,
  p_source TEXT DEFAULT 'reconciliation'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
VOLATILE
SET search_path = ''
AS $$
DECLARE
  target_org UUID;
  route JSONB;
  target_schema TEXT;
  old_preference TEXT;
  updated_vendor JSONB;
  sql TEXT;
BEGIN
  IF p_vendor_id IS NULL THEN
    RAISE EXCEPTION 'vendor id is required';
  END IF;

  IF p_ap_routing_preference NOT IN ('payments', 'storage', 'accounting', 'manual_paid_only') THEN
    RAISE EXCEPTION 'Invalid AP routing preference: %', p_ap_routing_preference;
  END IF;

  IF NOT public.is_manager_or_above() AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'Insufficient permissions to update vendor AP routing';
  END IF;

  target_org := COALESCE(p_organization_id, public.get_my_org());
  PERFORM public.assert_tenant_scope(target_org, NULL, NULL);

  route := public.get_tenant_data_route(target_org, NULL, NULL);
  target_schema := COALESCE(route->>'write_target', 'public');

  IF target_schema <> 'public' AND target_schema !~ '^tenant_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Unsafe tenant target schema: %', target_schema;
  END IF;

  IF to_regclass(format('%I.vendors', target_schema)) IS NULL THEN
    RAISE EXCEPTION 'Routed vendor table does not exist: %.vendors', target_schema;
  END IF;

  sql := format('SELECT ap_routing_preference FROM %I.vendors WHERE id = $1 AND organization_id = $2', target_schema);
  EXECUTE sql USING p_vendor_id, target_org INTO old_preference;

  IF old_preference IS NULL THEN
    RAISE EXCEPTION 'Vendor not found for organization';
  END IF;

  sql := format(
    'UPDATE %I.vendors
       SET ap_routing_preference = $1,
           ap_routing_updated_at = now(),
           ap_routing_updated_by = auth.uid(),
           file_routing_preference = CASE
             WHEN $1 IN (''payments'', ''storage'', ''accounting'') THEN $1
             ELSE file_routing_preference
           END
     WHERE id = $2 AND organization_id = $3
     RETURNING to_jsonb(%I.vendors.*)',
    target_schema,
    target_schema
  );
  EXECUTE sql USING p_ap_routing_preference, p_vendor_id, target_org INTO updated_vendor;

  INSERT INTO public.audit_logs (
    organization_id,
    user_id,
    action,
    table_name,
    record_id,
    module,
    entity_type,
    entity_id,
    field_changed,
    old_value,
    new_value,
    details,
    created_at
  ) VALUES (
    target_org,
    auth.uid(),
    'vendor_ap_routing_changed',
    'vendors',
    p_vendor_id,
    'reconciliation',
    'vendor',
    p_vendor_id::TEXT,
    'ap_routing_preference',
    old_preference,
    p_ap_routing_preference,
    'Vendor AP routing changed from ' || old_preference || ' to ' || p_ap_routing_preference || ' via ' || COALESCE(p_source, 'reconciliation'),
    now()
  );

  RETURN updated_vendor;
END;
$$;

-- Source: 20260624000009_batch2_supply_chain.sql
-- 2. Transactional RPC for Inventory Transfers
-- This wraps creating the transfer record and updating inventory into a single atomic transaction
-- to prevent network drops from causing partial state.
CREATE OR REPLACE FUNCTION public.execute_internal_transfer(
    p_organization_id UUID,
    p_from_location_id UUID,
    p_to_location_id UUID,
    p_items JSONB,
    p_user_id UUID
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
    v_transfer_id UUID;
    v_item JSONB;
    v_qty NUMERIC;
    v_source_inv RECORD;
    v_dest_inv RECORD;
    v_unit_cost NUMERIC;
BEGIN
    -- 1. Create the transfer record in completed state
    INSERT INTO public.transfers (
        organization_id, from_location_id, to_location_id, status, items, created_by, completed_at, completed_by
    ) VALUES (
        p_organization_id, p_from_location_id, p_to_location_id, 'completed', p_items, p_user_id, now(), p_user_id
    ) RETURNING id INTO v_transfer_id;

    -- 2. Process transfer items to adjust inventory atomically
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_qty := (v_item->>'quantity')::NUMERIC;
        v_unit_cost := COALESCE((v_item->>'unit_cost')::NUMERIC, 0);
        
        -- Source Inventory Deduction
        SELECT * INTO v_source_inv FROM public.inventory WHERE id = (v_item->>'inventory_id')::UUID FOR UPDATE;
        IF v_source_inv IS NOT NULL THEN
            UPDATE public.inventory 
            SET 
                current_quantity = GREATEST(0, current_quantity - v_qty),
                current_value = GREATEST(0, current_quantity - v_qty) * COALESCE(unit_cost, v_unit_cost),
                previous_quantity = current_quantity,
                previous_value = current_value
            WHERE id = v_source_inv.id;
            
            INSERT INTO public.inventory_movements (
                organization_id, location_id, inventory_id, movement_type, quantity, source_type, source_id, previous_quantity, new_quantity, created_by
            ) VALUES (
                p_organization_id, COALESCE(p_from_location_id, v_source_inv.location_id), v_source_inv.id, 'transfer_out', -v_qty, 'transfer', v_transfer_id::TEXT, v_source_inv.current_quantity, GREATEST(0, v_source_inv.current_quantity - v_qty), p_user_id
            );
        END IF;

        -- Destination Inventory Addition
        v_dest_inv := NULL;
        IF (v_item->>'product_id') IS NOT NULL THEN
            SELECT * INTO v_dest_inv FROM public.inventory WHERE product_id = v_item->>'product_id' AND organization_id = p_organization_id AND location_id = p_to_location_id LIMIT 1 FOR UPDATE;
        END IF;
        
        IF v_dest_inv IS NULL THEN
            SELECT * INTO v_dest_inv FROM public.inventory WHERE LOWER(product_name) = LOWER(v_item->>'product_name') AND organization_id = p_organization_id AND location_id = p_to_location_id LIMIT 1 FOR UPDATE;
        END IF;

        IF v_dest_inv IS NOT NULL THEN
            UPDATE public.inventory 
            SET 
                current_quantity = current_quantity + v_qty,
                current_value = (current_quantity + v_qty) * COALESCE(unit_cost, v_unit_cost),
                previous_quantity = current_quantity,
                previous_value = current_value
            WHERE id = v_dest_inv.id;
            
            INSERT INTO public.inventory_movements (
                organization_id, location_id, inventory_id, movement_type, quantity, source_type, source_id, previous_quantity, new_quantity, created_by
            ) VALUES (
                p_organization_id, p_to_location_id, v_dest_inv.id, 'transfer_in', v_qty, 'transfer', v_transfer_id::TEXT, v_dest_inv.current_quantity, v_dest_inv.current_quantity + v_qty, p_user_id
            );
        ELSE
            -- Create new inventory record in destination if it doesn't exist
            WITH new_inv AS (
                INSERT INTO public.inventory (
                    organization_id, location_id, product_id, product_name, current_quantity, current_unit, unit_cost, current_value, accounting_category, par_level, reorder_point, previous_quantity, previous_value
                ) VALUES (
                    p_organization_id, p_to_location_id, COALESCE(v_item->>'product_id', 'PRD-' || extract(epoch from now())::TEXT), v_item->>'product_name', v_qty, COALESCE(v_item->>'unit', 'ea'), v_unit_cost, v_qty * v_unit_cost, 'food', 0, 0, 0, 0
                ) RETURNING id, current_quantity
            )
            INSERT INTO public.inventory_movements (
                organization_id, location_id, inventory_id, movement_type, quantity, source_type, source_id, previous_quantity, new_quantity, created_by
            ) SELECT p_organization_id, p_to_location_id, id, 'transfer_in', v_qty, 'transfer', v_transfer_id::TEXT, 0, current_quantity, p_user_id FROM new_inv;
        END IF;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'transfer_id', v_transfer_id);
END;
$$;

-- Source: 20260624000011_batch4_admin_accounting.sql
-- 2. Prevent updating organization_id to null or empty in tenant_update_row
CREATE OR REPLACE FUNCTION public.tenant_update_row(
  p_table_name TEXT,
  p_id TEXT,
  p_payload JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
VOLATILE
SET search_path = ''
AS $$
DECLARE
  target_org UUID;
  brand_filter UUID;
  location_filter UUID;
  route JSONB;
  target_schema TEXT;
  sanitized_payload JSONB;
  payload_key TEXT;
  column_exists BOOLEAN;
  has_org_column BOOLEAN;
  set_clauses TEXT[] := ARRAY[]::TEXT[];
  result JSONB;
  sql TEXT;
BEGIN
  IF p_table_name IS NULL OR p_table_name !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
    RAISE EXCEPTION 'Unsafe table name: %', p_table_name;
  END IF;

  IF p_id IS NULL OR p_id = '' THEN
    RAISE EXCEPTION 'id is required';
  END IF;

  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'Payload must be a JSON object';
  END IF;

  IF p_payload ? 'organization_id' AND (p_payload->>'organization_id' IS NULL OR p_payload->>'organization_id' = '') THEN
    RAISE EXCEPTION 'Cannot set organization_id to null or empty';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.tenant_template_tables WHERE table_name = p_table_name) THEN
    RAISE EXCEPTION 'Table is not tenant-routable: %', p_table_name;
  END IF;

  target_org := COALESCE(NULLIF(p_payload->>'organization_id', '')::UUID, public.get_my_org());
  brand_filter := NULLIF(p_payload->>'brand_id', '')::UUID;
  location_filter := NULLIF(p_payload->>'location_id', '')::UUID;

  PERFORM public.assert_tenant_scope(target_org, brand_filter, location_filter);

  route := public.get_tenant_data_route(target_org, brand_filter, location_filter);
  target_schema := COALESCE(route->>'write_target', 'public');

  IF target_schema <> 'public' AND target_schema !~ '^tenant_[a-z0-9_]+$' THEN
    RAISE EXCEPTION 'Unsafe tenant target schema: %', target_schema;
  END IF;

  IF to_regclass(format('%I.%I', target_schema, p_table_name)) IS NULL THEN
    RAISE EXCEPTION 'Routed table does not exist: %.%', target_schema, p_table_name;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = target_schema AND table_name = p_table_name AND column_name = 'organization_id'
  ) INTO has_org_column;

  IF NOT has_org_column THEN
    RAISE EXCEPTION 'Tenant-routed table must include organization_id: %', p_table_name;
  END IF;

  sanitized_payload := p_payload - 'id' - 'created_at';

  FOR payload_key IN SELECT key FROM jsonb_each(sanitized_payload)
  LOOP
    IF payload_key !~ '^[a-zA-Z_][a-zA-Z0-9_]*$' THEN
      RAISE EXCEPTION 'Unsafe payload column: %', payload_key;
    END IF;

    SELECT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = target_schema AND table_name = p_table_name AND column_name = payload_key
    ) INTO column_exists;

    IF NOT column_exists THEN
      RAISE EXCEPTION 'Payload column does not exist on %.%: %', target_schema, p_table_name, payload_key;
    END IF;

    set_clauses := set_clauses || format('%I = source.%I', payload_key, payload_key);
  END LOOP;

  IF array_length(set_clauses, 1) IS NULL THEN
    RAISE EXCEPTION 'No update columns provided';
  END IF;

  sql := format(
    'WITH source AS (
       SELECT * FROM jsonb_populate_record(NULL::%I.%I, $1)
     ),
     updated AS (
       UPDATE %I.%I AS target
       SET %s
       FROM source
       WHERE target.id::TEXT = $2
         AND target.organization_id = $3
       RETURNING target.*
     )
     SELECT COALESCE((SELECT to_jsonb(updated) FROM updated), ''null''::jsonb)',
    target_schema,
    p_table_name,
    target_schema,
    p_table_name,
    array_to_string(set_clauses, ', ')
  );

  EXECUTE sql USING sanitized_payload, p_id, target_org INTO result;
  RETURN result;
END;
$$;

-- 3. Atomically record ledger GL entry when payment is completed
CREATE OR REPLACE FUNCTION public.record_invoice_payment(
  p_invoice_id UUID,
  p_amount NUMERIC,
  p_reference TEXT,
  p_payment_method TEXT DEFAULT 'manual'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_new_paid_amount NUMERIC;
  v_new_status TEXT;
  v_payment_id UUID;
  v_bill_id UUID;
  v_org_id UUID;
BEGIN
  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  v_org_id := v_invoice.organization_id;
  v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + COALESCE(p_amount, 0);
  v_new_status := CASE WHEN v_new_paid_amount >= COALESCE(v_invoice.total_amount, 0) THEN 'paid' ELSE 'partially_paid' END;

  UPDATE public.invoices
  SET paid_amount = v_new_paid_amount,
      payment_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE 'partial' END,
      status = v_new_status,
      ap_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE ap_status END,
      payment_reference = p_reference,
      updated_at = now()
  WHERE id = p_invoice_id;

  INSERT INTO public.payments (
    organization_id,
    invoice_id,
    vendor_id,
    amount,
    payment_method,
    reference_number,
    status,
    payment_date,
    created_by
  ) VALUES (
    v_org_id,
    p_invoice_id,
    v_invoice.vendor_id,
    p_amount,
    p_payment_method,
    p_reference,
    'completed',
    now(),
    auth.uid()
  ) RETURNING id INTO v_payment_id;

  -- Ensure Ledger Bill exists or create it
  SELECT id INTO v_bill_id FROM public.ledger_bills WHERE invoice_id = p_invoice_id LIMIT 1;
  
  IF v_bill_id IS NULL THEN
    INSERT INTO public.ledger_bills (
      organization_id,
      vendor_id,
      invoice_id,
      subtotal,
      tax,
      total,
      due_date,
      status
    ) VALUES (
      v_org_id,
      v_invoice.vendor_id,
      p_invoice_id,
      COALESCE(v_invoice.subtotal, 0),
      COALESCE(v_invoice.tax_amount, 0),
      COALESCE(v_invoice.total_amount, 0),
      v_invoice.due_date,
      'paid'
    ) RETURNING id INTO v_bill_id;
  ELSE
    UPDATE public.ledger_bills 
    SET status = 'paid' 
    WHERE id = v_bill_id;
  END IF;

  -- Insert into financial metrics for the GL entry
  INSERT INTO public.financial_metrics (
    organization_id,
    metric_type,
    metric_name,
    metric_value,
    period_start,
    period_end,
    metadata,
    created_by
  ) VALUES (
    v_org_id,
    'payment_ledger',
    'ledger_entry',
    p_amount,
    now(),
    now(),
    jsonb_build_object(
      'bill_id', v_bill_id,
      'payment_id', v_payment_id,
      'payment_method', p_payment_method
    ),
    auth.uid()
  );

  RETURN jsonb_build_object(
    'status', v_new_status,
    'payment_id', v_payment_id,
    'bill_id', v_bill_id
  );
END;
$$;

-- Source: 20260624000012_payment_routing_guardrails.sql
CREATE OR REPLACE FUNCTION public.schedule_invoice_payment(
  p_invoice_id UUID,
  p_payment_account_id UUID,
  p_date DATE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
BEGIN
  SELECT id, status, payment_status, ap_status, ap_routing_destination
    INTO v_invoice
    FROM public.invoices
   WHERE id = p_invoice_id
   FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
    RAISE EXCEPTION 'Invoice is routed to %, not Payments', v_invoice.ap_routing_destination;
  END IF;

  IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
    RAISE EXCEPTION 'Paid invoices cannot be scheduled for payment';
  END IF;

  IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
    RAISE EXCEPTION 'Invoice must be approved before scheduling payment';
  END IF;

  UPDATE public.invoices
     SET payment_account_id = p_payment_account_id,
         scheduled_payment_date = p_date,
         status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
         ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('status', 'scheduled', 'scheduled_payment_date', p_date);
END;
$$;

CREATE OR REPLACE FUNCTION public.record_invoice_payment(
  p_invoice_id UUID,
  p_amount NUMERIC,
  p_reference TEXT,
  p_payment_method TEXT DEFAULT 'manual'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_remaining NUMERIC;
  v_new_paid_amount NUMERIC;
  v_new_status TEXT;
  v_payment_id UUID;
BEGIN
  IF COALESCE(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be greater than zero';
  END IF;

  IF NULLIF(trim(COALESCE(p_reference, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Payment reference is required';
  END IF;

  SELECT * INTO v_invoice
    FROM public.invoices
   WHERE id = p_invoice_id
   FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
    RAISE EXCEPTION 'Invoice is routed to %, not Payments', v_invoice.ap_routing_destination;
  END IF;

  IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
    RAISE EXCEPTION 'Paid invoices cannot receive another payment';
  END IF;

  IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
    RAISE EXCEPTION 'Invoice must be approved before recording payment';
  END IF;

  v_remaining := GREATEST(0, COALESCE(v_invoice.total_amount, 0) - COALESCE(v_invoice.paid_amount, 0));
  IF p_amount > v_remaining THEN
    RAISE EXCEPTION 'Payment amount % exceeds remaining balance %', p_amount, v_remaining;
  END IF;

  v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + p_amount;
  v_new_status := CASE
    WHEN v_new_paid_amount >= COALESCE(v_invoice.total_amount, 0) THEN 'paid'
    ELSE 'partially_paid'
  END;

  UPDATE public.invoices
     SET paid_amount = v_new_paid_amount,
         payment_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE 'partial' END,
         status = v_new_status,
         ap_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE ap_status END,
         payment_reference = p_reference,
         updated_at = now()
   WHERE id = p_invoice_id;

  INSERT INTO public.payments (
    invoice_id,
    vendor_id,
    vendor_name,
    invoice_number,
    amount,
    payment_method,
    status,
    transaction_id,
    payment_date,
    payment_account_id,
    organization_id,
    brand_id,
    location_id,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.vendor_id,
    v_invoice.vendor_name,
    v_invoice.invoice_number,
    p_amount,
    p_payment_method,
    'completed',
    p_reference,
    CURRENT_DATE,
    v_invoice.payment_account_id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    auth.uid()
  )
  RETURNING id INTO v_payment_id;

  RETURN jsonb_build_object(
    'status', v_new_status,
    'paid_amount', v_new_paid_amount,
    'payment_id', v_payment_id
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.schedule_payment_batch(
  p_vendor_id UUID,
  p_payment_account_id UUID,
  p_scheduled_date DATE,
  p_invoice_ids UUID[],
  p_amounts NUMERIC[]
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_scheduled_payment_id UUID;
  v_total NUMERIC := 0;
  v_invoice RECORD;
  v_index INTEGER;
BEGIN
  IF array_length(p_invoice_ids, 1) IS NULL OR array_length(p_invoice_ids, 1) = 0 THEN
    RAISE EXCEPTION 'At least one invoice is required';
  END IF;

  IF array_length(p_invoice_ids, 1) <> array_length(p_amounts, 1) THEN
    RAISE EXCEPTION 'Invoice and amount arrays must have the same length';
  END IF;

  FOR v_index IN 1 .. array_length(p_invoice_ids, 1) LOOP
    SELECT id, vendor_id, status, payment_status, ap_routing_destination
      INTO v_invoice
      FROM public.invoices
     WHERE id = p_invoice_ids[v_index]
     FOR UPDATE;

    IF v_invoice.id IS NULL THEN
      RAISE EXCEPTION 'Invoice % not found', p_invoice_ids[v_index];
    END IF;

    IF v_invoice.vendor_id IS DISTINCT FROM p_vendor_id THEN
      RAISE EXCEPTION 'All selected invoices must belong to the selected vendor';
    END IF;

    IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
      RAISE EXCEPTION 'Invoice % is not routed to Payments', v_invoice.id;
    END IF;

    IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
      RAISE EXCEPTION 'Paid invoice % cannot be scheduled', v_invoice.id;
    END IF;

    IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
      RAISE EXCEPTION 'Invoice % must be approved before scheduling payment', v_invoice.id;
    END IF;

    IF COALESCE(p_amounts[v_index], 0) <= 0 THEN
      RAISE EXCEPTION 'Scheduled amount must be greater than zero';
    END IF;

    v_total := v_total + p_amounts[v_index];
  END LOOP;

  INSERT INTO public.scheduled_payments (
    organization_id,
    vendor_id,
    payment_account_id,
    total_amount,
    scheduled_date,
    status,
    created_by
  ) VALUES (
    public.get_my_org(),
    p_vendor_id,
    p_payment_account_id,
    v_total,
    p_scheduled_date,
    'scheduled',
    auth.uid()
  ) RETURNING id INTO v_scheduled_payment_id;

  FOR v_index IN 1 .. array_length(p_invoice_ids, 1) LOOP
    INSERT INTO public.scheduled_payment_invoices (
      scheduled_payment_id,
      invoice_id,
      amount_applied
    ) VALUES (
      v_scheduled_payment_id,
      p_invoice_ids[v_index],
      p_amounts[v_index]
    );

    UPDATE public.invoices
       SET scheduled_payment_date = p_scheduled_date,
           payment_account_id = p_payment_account_id,
           status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
           ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
           updated_at = now()
     WHERE id = p_invoice_ids[v_index];
  END LOOP;

  RETURN v_scheduled_payment_id;
END;
$$;

-- Source: 20260624000013_programmatic_payouts_dwolla.sql
-- 4. RPC to securely release funds for an invoice
CREATE OR REPLACE FUNCTION public.release_invoice_funds(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_role TEXT;
  v_org_id UUID;
BEGIN
  -- Verify the invoice exists
  SELECT * INTO v_invoice 
  FROM public.invoices 
  WHERE id = p_invoice_id;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  -- Verify User Role (Must be location_manager, brand_manager, or org_owner equivalent)
  SELECT role INTO v_role
  FROM public.profiles
  WHERE id = auth.uid() AND organization_id = v_invoice.organization_id;

  IF v_role NOT IN ('location_manager', 'branch_manager', 'org_owner', 'owner', 'admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Unauthorized: Only Managers or Owners can release funds';
  END IF;

  IF v_invoice.status NOT IN ('scheduled') THEN
    RAISE EXCEPTION 'Invoice must be in scheduled status to release funds';
  END IF;

  -- Update invoice status to processing to prevent double-firing
  UPDATE public.invoices
  SET payment_status = 'processing',
      updated_at = now()
  WHERE id = p_invoice_id;

  -- Create a pending payment record that the Edge Function will update
  INSERT INTO public.payments (
    invoice_id,
    vendor_id,
    vendor_name,
    invoice_number,
    amount,
    payment_method,
    status,
    payout_status,
    payment_date,
    payment_account_id,
    organization_id,
    brand_id,
    location_id,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.vendor_id,
    v_invoice.vendor_name,
    v_invoice.invoice_number,
    COALESCE(v_invoice.total_amount, 0) - COALESCE(v_invoice.paid_amount, 0),
    'bank_transfer',
    'pending',
    'processing',
    CURRENT_DATE,
    v_invoice.payment_account_id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    auth.uid()
  );

  RETURN jsonb_build_object('status', 'success', 'invoice_id', p_invoice_id);
END;
$$;

