-- Source: 20260624000015_pay_now_support.sql
CREATE OR REPLACE FUNCTION public.release_invoice_funds(
  p_invoice_id UUID, 
  p_payout_method TEXT DEFAULT 'dwolla_ach',
  p_payment_account_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_role TEXT;
  v_payment_method TEXT;
  v_final_account_id UUID;
BEGIN
  -- Verify the invoice exists
  SELECT * INTO v_invoice 
  FROM public.invoices 
  WHERE id = p_invoice_id;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  -- Verify User Role
  SELECT role INTO v_role
  FROM public.profiles
  WHERE id = auth.uid() AND organization_id = v_invoice.organization_id;

  IF v_role NOT IN ('location_manager', 'branch_manager', 'org_owner', 'owner', 'admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Unauthorized: Only Managers or Owners can release funds';
  END IF;

  IF v_invoice.status NOT IN ('approved', 'scheduled') THEN
    RAISE EXCEPTION 'Invoice must be in approved or scheduled status to release funds';
  END IF;

  -- Determine the payment account
  v_final_account_id := COALESCE(p_payment_account_id, v_invoice.payment_account_id);
  
  IF v_final_account_id IS NULL THEN
    RAISE EXCEPTION 'A payment account is required to release funds.';
  END IF;

  -- Determine payment method based on argument
  IF p_payout_method = 'dwolla_ach' THEN
    v_payment_method := 'bank_transfer';
  ELSIF p_payout_method IN ('checkbook_digital', 'checkbook_physical') THEN
    v_payment_method := 'check';
  ELSE
    RAISE EXCEPTION 'Invalid payout method';
  END IF;

  -- Update invoice
  UPDATE public.invoices
  SET payment_status = 'processing',
      status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
      payment_account_id = v_final_account_id,
      updated_at = now()
  WHERE id = p_invoice_id;

  -- Create a pending payment record
  INSERT INTO public.payments (
    invoice_id,
    vendor_id,
    vendor_name,
    invoice_number,
    amount,
    payment_method,
    status,
    payout_status,
    payment_date,
    payment_account_id,
    organization_id,
    brand_id,
    location_id,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.vendor_id,
    v_invoice.vendor_name,
    v_invoice.invoice_number,
    COALESCE(v_invoice.total_amount, 0) - COALESCE(v_invoice.paid_amount, 0),
    v_payment_method,
    'pending',
    'processing',
    CURRENT_DATE,
    v_final_account_id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    auth.uid()
  );

  RETURN jsonb_build_object('status', 'success', 'invoice_id', p_invoice_id, 'payout_method', p_payout_method);
END;
$$;

-- Source: 20260624000016_freeze_schema_per_tenant_default.sql
DROP FUNCTION IF EXISTS public.auto_provision_new_tenant_schema();

CREATE OR REPLACE FUNCTION public.auto_register_new_tenant_shared_public()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  registry_record RECORD;
  generated_schema_name TEXT;
BEGIN
  generated_schema_name := public.generate_tenant_schema_name(NEW.id, NEW.slug, NEW.name);

  INSERT INTO public.tenant_registry (
    organization_id,
    schema_name,
    status,
    read_mode,
    write_mode,
    metadata
  )
  VALUES (
    NEW.id,
    generated_schema_name,
    'active',
    'public',
    'public',
    jsonb_build_object(
      'tenancy_model', 'shared_public',
      'registered_by', 'auto_register_new_tenant_shared_public',
      'schema_per_tenant_default_disabled_at', now()
    )
  )
  ON CONFLICT (organization_id) DO UPDATE
  SET status = CASE
        WHEN public.tenant_registry.status = 'archived' THEN public.tenant_registry.status
        ELSE 'active'
      END,
      read_mode = 'public',
      write_mode = 'public',
      metadata = public.tenant_registry.metadata || jsonb_build_object(
        'tenancy_model', 'shared_public',
        'registered_by', 'auto_register_new_tenant_shared_public',
        'schema_per_tenant_default_disabled_at', now(),
        'previous_read_mode', public.tenant_registry.read_mode,
        'previous_write_mode', public.tenant_registry.write_mode
      )
  RETURNING * INTO registry_record;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.auto_register_new_tenant_shared_public() IS
  'Registers new organizations as shared-public tenants. Does not create tenant schemas.';

-- Source: 20260624000017_shared_public_access_scope_hardening.sql
-- 3. Keep explicit organization scope aligned with parent records.
CREATE OR REPLACE FUNCTION public.set_brand_member_organization_id()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  parent_org_id UUID;
BEGIN
  SELECT b.organization_id
  INTO parent_org_id
  FROM public.brands b
  WHERE b.brand_id = NEW.brand_id;

  IF parent_org_id IS NULL THEN
    RAISE EXCEPTION 'Brand % does not exist', NEW.brand_id;
  END IF;

  IF NEW.organization_id IS NOT NULL AND NEW.organization_id IS DISTINCT FROM parent_org_id THEN
    RAISE EXCEPTION 'brand_members.organization_id must match parent brand organization_id';
  END IF;

  NEW.organization_id := parent_org_id;
  RETURN NEW;
END;
$$;

