-- Source: 20260625000017_architecture_inspection_rpc.sql
CREATE OR REPLACE FUNCTION public.inspect_database_architecture()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'generated_at', now(),
    'schemas', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema_name', n.nspname,
        'owner', pg_catalog.pg_get_userbyid(n.nspowner)
      ) ORDER BY n.nspname), '[]'::jsonb)
      FROM pg_catalog.pg_namespace n
      WHERE n.nspname NOT LIKE 'pg_%'
        AND n.nspname <> 'information_schema'
    ),
    'extensions', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'extension_name', e.extname,
        'schema_name', ns.nspname,
        'version', e.extversion
      ) ORDER BY e.extname), '[]'::jsonb)
      FROM pg_catalog.pg_extension e
      JOIN pg_catalog.pg_namespace ns ON ns.oid = e.extnamespace
    ),
    'tables', (
      SELECT COALESCE(jsonb_agg(table_payload ORDER BY table_payload->>'schema_name', table_payload->>'table_name'), '[]'::jsonb)
      FROM (
        SELECT jsonb_build_object(
          'schema_name', ns.nspname,
          'table_name', c.relname,
          'kind', CASE c.relkind
            WHEN 'r' THEN 'table'
            WHEN 'p' THEN 'partitioned_table'
            WHEN 'v' THEN 'view'
            WHEN 'm' THEN 'materialized_view'
            WHEN 'f' THEN 'foreign_table'
            ELSE c.relkind::TEXT
          END,
          'owner', pg_catalog.pg_get_userbyid(c.relowner),
          'rls_enabled', c.relrowsecurity,
          'rls_forced', c.relforcerowsecurity,
          'estimated_rows', c.reltuples::BIGINT,
          'columns', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
              'column_name', a.attname,
              'ordinal', a.attnum,
              'data_type', pg_catalog.format_type(a.atttypid, a.atttypmod),
              'not_null', a.attnotnull,
              'default', pg_catalog.pg_get_expr(ad.adbin, ad.adrelid),
              'identity', a.attidentity,
              'generated', a.attgenerated
            ) ORDER BY a.attnum), '[]'::jsonb)
            FROM pg_catalog.pg_attribute a
            LEFT JOIN pg_catalog.pg_attrdef ad
              ON ad.adrelid = a.attrelid
             AND ad.adnum = a.attnum
            WHERE a.attrelid = c.oid
              AND a.attnum > 0
              AND NOT a.attisdropped
          ),
          'policies', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
              'policy_name', p.polname,
              'command', CASE p.polcmd
                WHEN 'r' THEN 'select'
                WHEN 'a' THEN 'insert'
                WHEN 'w' THEN 'update'
                WHEN 'd' THEN 'delete'
                WHEN '*' THEN 'all'
                ELSE p.polcmd::TEXT
              END,
              'permissive', p.polpermissive,
              'roles', (
                SELECT COALESCE(jsonb_agg(r.rolname ORDER BY r.rolname), '[]'::jsonb)
                FROM unnest(p.polroles) AS role_oid
                JOIN pg_catalog.pg_roles r ON r.oid = role_oid
              ),
              'using_expression', pg_catalog.pg_get_expr(p.polqual, p.polrelid),
              'check_expression', pg_catalog.pg_get_expr(p.polwithcheck, p.polrelid)
            ) ORDER BY p.polname), '[]'::jsonb)
            FROM pg_catalog.pg_policy p
            WHERE p.polrelid = c.oid
          ),
          'triggers', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
              'trigger_name', t.tgname,
              'enabled', t.tgenabled,
              'is_internal', t.tgisinternal,
              'definition', pg_catalog.pg_get_triggerdef(t.oid, true)
            ) ORDER BY t.tgname), '[]'::jsonb)
            FROM pg_catalog.pg_trigger t
            WHERE t.tgrelid = c.oid
              AND NOT t.tgisinternal
          )
        ) AS table_payload
        FROM pg_catalog.pg_class c
        JOIN pg_catalog.pg_namespace ns ON ns.oid = c.relnamespace
        WHERE ns.nspname NOT LIKE 'pg_%'
          AND ns.nspname <> 'information_schema'
          AND c.relkind IN ('r', 'p', 'v', 'm', 'f')
      ) table_rows
    ),
    'indexes', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema_name', schemaname,
        'table_name', tablename,
        'index_name', indexname,
        'definition', indexdef
      ) ORDER BY schemaname, tablename, indexname), '[]'::jsonb)
      FROM pg_catalog.pg_indexes
      WHERE schemaname NOT LIKE 'pg_%'
        AND schemaname <> 'information_schema'
    ),
    'constraints', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema_name', ns.nspname,
        'table_name', c.relname,
        'constraint_name', con.conname,
        'constraint_type', con.contype,
        'definition', pg_catalog.pg_get_constraintdef(con.oid, true)
      ) ORDER BY ns.nspname, c.relname, con.conname), '[]'::jsonb)
      FROM pg_catalog.pg_constraint con
      JOIN pg_catalog.pg_class c ON c.oid = con.conrelid
      JOIN pg_catalog.pg_namespace ns ON ns.oid = c.relnamespace
      WHERE ns.nspname NOT LIKE 'pg_%'
        AND ns.nspname <> 'information_schema'
    ),
    'functions', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema_name', ns.nspname,
        'function_name', p.proname,
        'identity_arguments', pg_catalog.pg_get_function_identity_arguments(p.oid),
        'result_type', pg_catalog.pg_get_function_result(p.oid),
        'language', l.lanname,
        'security_definer', p.prosecdef,
        'volatility', p.provolatile,
        'parallel', p.proparallel,
        'owner', pg_catalog.pg_get_userbyid(p.proowner)
      ) ORDER BY ns.nspname, p.proname, pg_catalog.pg_get_function_identity_arguments(p.oid)), '[]'::jsonb)
      FROM pg_catalog.pg_proc p
      JOIN pg_catalog.pg_namespace ns ON ns.oid = p.pronamespace
      JOIN pg_catalog.pg_language l ON l.oid = p.prolang
      WHERE ns.nspname NOT LIKE 'pg_%'
        AND ns.nspname <> 'information_schema'
    )
  )
  INTO result;

  RETURN result;
END;
$$;

COMMENT ON FUNCTION public.inspect_database_architecture() IS
  'Service-role-only metadata inspection RPC for architecture audits. Returns schemas, tables, columns, RLS policies, triggers, functions, indexes, constraints, and extensions.';

-- Source: 20260625000018_shared_tenancy_rls_financial_hardening.sql
CREATE OR REPLACE FUNCTION public.assert_financial_actor(
  p_organization_id UUID,
  p_allowed_roles TEXT[] DEFAULT ARRAY['location_manager', 'branch_manager', 'org_owner', 'owner', 'admin', 'platform_admin']
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  v_role TEXT;
  v_profile_org UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, organization_id
    INTO v_role, v_profile_org
  FROM public.profiles
  WHERE id = auth.uid();

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role <> 'platform_admin' AND v_profile_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization financial access denied';
  END IF;

  IF NOT v_role = ANY(p_allowed_roles) THEN
    RAISE EXCEPTION 'Insufficient financial permissions';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.schedule_invoice_payment(
  p_invoice_id UUID,
  p_payment_account_id UUID,
  p_date DATE
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_account_org UUID;
BEGIN
  SELECT id, organization_id, status, payment_status, ap_status, ap_routing_destination
    INTO v_invoice
    FROM public.invoices
   WHERE id = p_invoice_id
   FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  SELECT organization_id
    INTO v_account_org
  FROM public.payment_accounts
  WHERE id = p_payment_account_id
    AND is_active IS DISTINCT FROM false;

  IF v_account_org IS NULL OR v_account_org IS DISTINCT FROM v_invoice.organization_id THEN
    RAISE EXCEPTION 'Payment account does not belong to the invoice organization';
  END IF;

  IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
    RAISE EXCEPTION 'Invoice is routed to %, not Payments', v_invoice.ap_routing_destination;
  END IF;

  IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
    RAISE EXCEPTION 'Paid invoices cannot be scheduled for payment';
  END IF;

  IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
    RAISE EXCEPTION 'Invoice must be approved before scheduling payment';
  END IF;

  UPDATE public.invoices
     SET payment_account_id = p_payment_account_id,
         scheduled_payment_date = p_date,
         status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
         ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('status', 'scheduled', 'scheduled_payment_date', p_date);
END;
$$;

CREATE OR REPLACE FUNCTION public.record_invoice_payment(
  p_invoice_id UUID,
  p_amount NUMERIC,
  p_reference TEXT,
  p_payment_method TEXT DEFAULT 'manual'
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_remaining NUMERIC;
  v_new_paid_amount NUMERIC;
  v_new_status TEXT;
  v_payment_id UUID;
BEGIN
  IF COALESCE(p_amount, 0) <= 0 THEN
    RAISE EXCEPTION 'Payment amount must be greater than zero';
  END IF;

  IF NULLIF(trim(COALESCE(p_reference, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Payment reference is required';
  END IF;

  SELECT * INTO v_invoice
    FROM public.invoices
   WHERE id = p_invoice_id
   FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
    RAISE EXCEPTION 'Invoice is routed to %, not Payments', v_invoice.ap_routing_destination;
  END IF;

  IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
    RAISE EXCEPTION 'Paid invoices cannot receive another payment';
  END IF;

  IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
    RAISE EXCEPTION 'Invoice must be approved before recording payment';
  END IF;

  v_remaining := GREATEST(0, COALESCE(v_invoice.total_amount, 0) - COALESCE(v_invoice.paid_amount, 0));
  IF p_amount > v_remaining THEN
    RAISE EXCEPTION 'Payment amount % exceeds remaining balance %', p_amount, v_remaining;
  END IF;

  v_new_paid_amount := COALESCE(v_invoice.paid_amount, 0) + p_amount;
  v_new_status := CASE
    WHEN v_new_paid_amount >= COALESCE(v_invoice.total_amount, 0) THEN 'paid'
    ELSE 'partially_paid'
  END;

  UPDATE public.invoices
     SET paid_amount = v_new_paid_amount,
         payment_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE 'partial' END,
         status = v_new_status,
         ap_status = CASE WHEN v_new_status = 'paid' THEN 'paid' ELSE ap_status END,
         payment_reference = p_reference,
         updated_at = now()
   WHERE id = p_invoice_id;

  INSERT INTO public.payments (
    invoice_id,
    vendor_id,
    vendor_name,
    invoice_number,
    amount,
    payment_method,
    status,
    transaction_id,
    payment_date,
    payment_account_id,
    organization_id,
    brand_id,
    location_id,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.vendor_id,
    v_invoice.vendor_name,
    v_invoice.invoice_number,
    p_amount,
    p_payment_method,
    'completed',
    p_reference,
    CURRENT_DATE,
    v_invoice.payment_account_id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    auth.uid()
  )
  RETURNING id INTO v_payment_id;

  PERFORM public.log_invoice_audit_event(
    v_invoice.id,
    'payment_recorded',
    'Payment recorded through tenant-safe financial RPC',
    to_jsonb(v_invoice),
    jsonb_build_object(
      'payment_id', v_payment_id,
      'amount', p_amount,
      'payment_method', p_payment_method,
      'reference', p_reference,
      'status', v_new_status
    )
  );

  RETURN jsonb_build_object(
    'status', v_new_status,
    'paid_amount', v_new_paid_amount,
    'payment_id', v_payment_id
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.schedule_payment_batch(
  p_vendor_id UUID,
  p_payment_account_id UUID,
  p_scheduled_date DATE,
  p_invoice_ids UUID[],
  p_amounts NUMERIC[]
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_scheduled_payment_id UUID;
  v_total NUMERIC := 0;
  v_invoice RECORD;
  v_index INTEGER;
  v_organization_id UUID;
  v_account_org UUID;
BEGIN
  IF array_length(p_invoice_ids, 1) IS NULL OR array_length(p_invoice_ids, 1) = 0 THEN
    RAISE EXCEPTION 'At least one invoice is required';
  END IF;

  IF array_length(p_invoice_ids, 1) <> array_length(p_amounts, 1) THEN
    RAISE EXCEPTION 'Invoice and amount arrays must have the same length';
  END IF;

  FOR v_index IN 1 .. array_length(p_invoice_ids, 1) LOOP
    SELECT id, organization_id, vendor_id, status, payment_status, ap_routing_destination
      INTO v_invoice
      FROM public.invoices
     WHERE id = p_invoice_ids[v_index]
     FOR UPDATE;

    IF v_invoice.id IS NULL THEN
      RAISE EXCEPTION 'Invoice % not found', p_invoice_ids[v_index];
    END IF;

    IF v_index = 1 THEN
      v_organization_id := v_invoice.organization_id;
      PERFORM public.assert_financial_actor(v_organization_id);

      SELECT organization_id
        INTO v_account_org
      FROM public.payment_accounts
      WHERE id = p_payment_account_id
        AND is_active IS DISTINCT FROM false;

      IF v_account_org IS NULL OR v_account_org IS DISTINCT FROM v_organization_id THEN
        RAISE EXCEPTION 'Payment account does not belong to the invoice organization';
      END IF;
    ELSIF v_invoice.organization_id IS DISTINCT FROM v_organization_id THEN
      RAISE EXCEPTION 'All selected invoices must belong to the same organization';
    END IF;

    IF v_invoice.vendor_id IS DISTINCT FROM p_vendor_id THEN
      RAISE EXCEPTION 'All selected invoices must belong to the selected vendor';
    END IF;

    IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
      RAISE EXCEPTION 'Invoice % is not routed to Payments', v_invoice.id;
    END IF;

    IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
      RAISE EXCEPTION 'Paid invoice % cannot be scheduled', v_invoice.id;
    END IF;

    IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
      RAISE EXCEPTION 'Invoice % must be approved before scheduling payment', v_invoice.id;
    END IF;

    IF COALESCE(p_amounts[v_index], 0) <= 0 THEN
      RAISE EXCEPTION 'Scheduled amount must be greater than zero';
    END IF;

    v_total := v_total + p_amounts[v_index];
  END LOOP;

  INSERT INTO public.scheduled_payments (
    organization_id,
    vendor_id,
    payment_account_id,
    total_amount,
    scheduled_date,
    status,
    created_by
  ) VALUES (
    v_organization_id,
    p_vendor_id,
    p_payment_account_id,
    v_total,
    p_scheduled_date,
    'scheduled',
    auth.uid()
  ) RETURNING id INTO v_scheduled_payment_id;

  FOR v_index IN 1 .. array_length(p_invoice_ids, 1) LOOP
    INSERT INTO public.scheduled_payment_invoices (
      scheduled_payment_id,
      invoice_id,
      amount_applied
    ) VALUES (
      v_scheduled_payment_id,
      p_invoice_ids[v_index],
      p_amounts[v_index]
    );

    UPDATE public.invoices
       SET scheduled_payment_date = p_scheduled_date,
           payment_account_id = p_payment_account_id,
           status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
           ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
           updated_at = now()
     WHERE id = p_invoice_ids[v_index];
  END LOOP;

  RETURN v_scheduled_payment_id;
END;
$$;

COMMENT ON FUNCTION public.assert_financial_actor(UUID, TEXT[]) IS
  'Shared guard for tenant-safe financial RPCs. Validates authenticated user role and organization scope before money-moving mutations.';

-- Source: 20260625000019_fix_schedule_payment_batch_lint.sql
CREATE OR REPLACE FUNCTION public.schedule_payment_batch(
  p_vendor_id UUID,
  p_payment_account_id UUID,
  p_scheduled_date DATE,
  p_invoice_ids UUID[],
  p_amounts NUMERIC[]
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_scheduled_payment_id UUID;
  v_total NUMERIC := 0;
  v_invoice RECORD;
  v_organization_id UUID;
  v_account_org UUID;
BEGIN
  IF array_length(p_invoice_ids, 1) IS NULL OR array_length(p_invoice_ids, 1) = 0 THEN
    RAISE EXCEPTION 'At least one invoice is required';
  END IF;

  IF array_length(p_invoice_ids, 1) <> array_length(p_amounts, 1) THEN
    RAISE EXCEPTION 'Invoice and amount arrays must have the same length';
  END IF;

  FOR v_index IN 1 .. array_length(p_invoice_ids, 1) LOOP
    SELECT id, organization_id, vendor_id, status, payment_status, ap_routing_destination
      INTO v_invoice
      FROM public.invoices
     WHERE id = p_invoice_ids[v_index]
     FOR UPDATE;

    IF v_invoice.id IS NULL THEN
      RAISE EXCEPTION 'Invoice % not found', p_invoice_ids[v_index];
    END IF;

    IF v_index = 1 THEN
      v_organization_id := v_invoice.organization_id;
      PERFORM public.assert_financial_actor(v_organization_id);

      SELECT organization_id
        INTO v_account_org
      FROM public.payment_accounts
      WHERE id = p_payment_account_id
        AND is_active IS DISTINCT FROM false;

      IF v_account_org IS NULL OR v_account_org IS DISTINCT FROM v_organization_id THEN
        RAISE EXCEPTION 'Payment account does not belong to the invoice organization';
      END IF;
    ELSIF v_invoice.organization_id IS DISTINCT FROM v_organization_id THEN
      RAISE EXCEPTION 'All selected invoices must belong to the same organization';
    END IF;

    IF v_invoice.vendor_id IS DISTINCT FROM p_vendor_id THEN
      RAISE EXCEPTION 'All selected invoices must belong to the selected vendor';
    END IF;

    IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
      RAISE EXCEPTION 'Invoice % is not routed to Payments', v_invoice.id;
    END IF;

    IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'auto_pay') OR v_invoice.status = 'paid' THEN
      RAISE EXCEPTION 'Paid invoice % cannot be scheduled', v_invoice.id;
    END IF;

    IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
      RAISE EXCEPTION 'Invoice % must be approved before scheduling payment', v_invoice.id;
    END IF;

    IF COALESCE(p_amounts[v_index], 0) <= 0 THEN
      RAISE EXCEPTION 'Scheduled amount must be greater than zero';
    END IF;

    v_total := v_total + p_amounts[v_index];
  END LOOP;

  INSERT INTO public.scheduled_payments (
    organization_id,
    vendor_id,
    payment_account_id,
    total_amount,
    scheduled_date,
    status,
    created_by
  ) VALUES (
    v_organization_id,
    p_vendor_id,
    p_payment_account_id,
    v_total,
    p_scheduled_date,
    'scheduled',
    auth.uid()
  ) RETURNING id INTO v_scheduled_payment_id;

  FOR v_index IN 1 .. array_length(p_invoice_ids, 1) LOOP
    INSERT INTO public.scheduled_payment_invoices (
      scheduled_payment_id,
      invoice_id,
      amount_applied
    ) VALUES (
      v_scheduled_payment_id,
      p_invoice_ids[v_index],
      p_amounts[v_index]
    );

    UPDATE public.invoices
       SET scheduled_payment_date = p_scheduled_date,
           payment_account_id = p_payment_account_id,
           status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
           ap_status = CASE WHEN ap_status = 'approved' THEN 'scheduled' ELSE ap_status END,
           updated_at = now()
     WHERE id = p_invoice_ids[v_index];
  END LOOP;

  RETURN v_scheduled_payment_id;
END;
$$;

-- Source: 20260625000020_financial_rpc_service_scope_returns.sql
CREATE OR REPLACE FUNCTION public.assert_financial_actor(
  p_organization_id UUID,
  p_allowed_roles TEXT[] DEFAULT ARRAY['location_manager', 'branch_manager', 'org_owner', 'owner', 'admin', 'platform_admin']
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  v_role TEXT;
  v_profile_org UUID;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, organization_id
    INTO v_role, v_profile_org
  FROM public.profiles
  WHERE id = auth.uid();

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role <> 'platform_admin' AND v_profile_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization financial access denied';
  END IF;

  IF NOT v_role = ANY(p_allowed_roles) THEN
    RAISE EXCEPTION 'Insufficient financial permissions';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.release_invoice_funds(
  p_invoice_id UUID,
  p_payout_method TEXT DEFAULT 'dwolla_ach',
  p_payment_account_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_payment_method TEXT;
  v_final_account_id UUID;
  v_payment_id UUID;
  v_account_org UUID;
BEGIN
  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  IF COALESCE(v_invoice.ap_routing_destination, 'payments') <> 'payments' THEN
    RAISE EXCEPTION 'Invoice is routed to %, not Payments', v_invoice.ap_routing_destination;
  END IF;

  IF COALESCE(v_invoice.payment_status, 'unpaid') IN ('paid', 'processing', 'auto_pay') OR v_invoice.status = 'paid' THEN
    RAISE EXCEPTION 'Invoice is already paid or processing';
  END IF;

  IF v_invoice.status NOT IN ('approved', 'scheduled', 'partially_paid') THEN
    RAISE EXCEPTION 'Invoice must be approved before releasing funds';
  END IF;

  v_final_account_id := COALESCE(p_payment_account_id, v_invoice.payment_account_id);

  IF v_final_account_id IS NULL THEN
    RAISE EXCEPTION 'A payment account is required to release funds';
  END IF;

  SELECT organization_id
    INTO v_account_org
  FROM public.payment_accounts
  WHERE id = v_final_account_id
    AND is_active IS DISTINCT FROM false;

  IF v_account_org IS NULL OR v_account_org IS DISTINCT FROM v_invoice.organization_id THEN
    RAISE EXCEPTION 'Payment account does not belong to the invoice organization';
  END IF;

  IF p_payout_method = 'dwolla_ach' THEN
    v_payment_method := 'bank_transfer';
  ELSIF p_payout_method IN ('checkbook_digital', 'checkbook_physical') THEN
    v_payment_method := 'check';
  ELSE
    RAISE EXCEPTION 'Invalid payout method';
  END IF;

  UPDATE public.invoices
     SET payment_status = 'processing',
         status = CASE WHEN status = 'approved' THEN 'scheduled' ELSE status END,
         payment_account_id = v_final_account_id,
         updated_at = now()
   WHERE id = p_invoice_id;

  INSERT INTO public.payments (
    invoice_id,
    vendor_id,
    vendor_name,
    invoice_number,
    amount,
    payment_method,
    status,
    payout_status,
    payment_date,
    payment_account_id,
    organization_id,
    brand_id,
    location_id,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.vendor_id,
    v_invoice.vendor_name,
    v_invoice.invoice_number,
    COALESCE(v_invoice.total_amount, 0) - COALESCE(v_invoice.paid_amount, 0),
    v_payment_method,
    'pending',
    'processing',
    CURRENT_DATE,
    v_final_account_id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    auth.uid()
  )
  RETURNING id INTO v_payment_id;

  RETURN jsonb_build_object(
    'status', 'success',
    'invoice_id', p_invoice_id,
    'organization_id', v_invoice.organization_id,
    'payment_id', v_payment_id,
    'payout_method', p_payout_method
  );
END;
$$;

