    organization_id,
    vendor_id,
    vendor_name,
    amount,
    status,
    payment_method,
    payment_date,
    notes,
    created_by
  ) VALUES (
    v_source_payment_id,
    v_vendor.organization_id,
    v_vendor.id,
    v_vendor.name,
    p_amount,
    'completed',
    COALESCE(NULLIF(p_payment_method, ''), 'manual'),
    CURRENT_DATE,
    p_memo,
    auth.uid()
  )
  ON CONFLICT (id) DO UPDATE
     SET updated_at = now()
  RETURNING id INTO v_source_payment_id;

  INSERT INTO public.ledger_bills (
    organization_id,
    vendor_id,
    invoice_id,
    subtotal,
    tax,
    total,
    due_date,
    status
  ) VALUES (
