    (v_vendor.organization_id, '1000', 0, p_amount, 'payment', v_ledger_payment_id);

  RETURN jsonb_build_object(
    'success', true,
    'ledger_payment_id', v_ledger_payment_id,
    'bill_id', v_bill_id,
    'source_payment_id', v_source_payment_id,
    'idempotent', false
  );
END;
$$;

COMMENT ON FUNCTION public.record_ad_hoc_vendor_payment(UUID, NUMERIC, TEXT, TEXT, TEXT) IS
  'Tenant-safe ad-hoc vendor payment RPC with deterministic source payment idempotency and valid ledger_payments.source_payment_id FK and canonical ledger entry reference type.';

-- Source: 20260625000028_global_vendor_item_trust_hardening.sql
CREATE OR REPLACE FUNCTION public.normalize_global_vendor_category(p_category TEXT)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
SET search_path = ''
AS $$
  SELECT CASE
    WHEN p_category = ANY (ARRAY[
      '5100', '5110', '5120', '5130', '5140', '5150', '5160', '5170', '5190',
      '5200', '5210', '5220', '5230', '5240', '5290',
      '5300'
    ]) THEN p_category
    WHEN p_category = 'food_cogs' THEN '5100'
    WHEN p_category = 'beverage_cogs' THEN '5200'
    WHEN p_category = 'merchandise_cogs' THEN '5300'
    ELSE NULL
  END;
$$;

CREATE OR REPLACE FUNCTION public.get_trusted_global_vendor_item_suggestions()
RETURNS TABLE (
  id UUID,
  item_name TEXT,
  mapping_count INTEGER,
  most_common_category TEXT,
  confidence_score INTEGER
)
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
  SELECT
    gvi.id,
    gvi.item_name,
    gvi.mapping_count,
    public.normalize_global_vendor_category(gvi.most_common_category) AS most_common_category,
    gvi.confidence_score
  FROM public.global_vendor_items gvi
  WHERE gvi.mapping_count >= 50
    AND gvi.confidence_score >= 90
    AND public.normalize_global_vendor_category(gvi.most_common_category) IS NOT NULL
  ORDER BY gvi.mapping_count DESC
  LIMIT 500;
$$;

COMMENT ON FUNCTION public.get_trusted_global_vendor_item_suggestions() IS
  'Returns only high-confidence, high-count, COGS-category global vendor item suggestions. Tenant clients must not read raw global mappings for auto-apply decisions.';

-- Source: 20260626000001_onboarding_hierarchy_rpc.sql
CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id UUID,
  p_hierarchy JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item JSONB;
  brand_item JSONB;
  location_item JSONB;
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
  v_primary_org_id UUID;
  v_primary_brand_id UUID;
  v_primary_location_id UUID;
  v_created_orgs JSONB := '[]'::jsonb;
  v_created_brands JSONB := '[]'::jsonb;
  v_created_locations JSONB := '[]'::jsonb;
  v_org_name TEXT;
  v_org_slug TEXT;
  v_brand_name TEXT;
  v_location_name TEXT;
  v_location_address TEXT;
  v_org_count INTEGER := 0;
  v_brand_count INTEGER := 0;
  v_location_count INTEGER := 0;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;


  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array' THEN
      RAISE EXCEPTION 'Organization % brands must be an array', v_org_name;
    END IF;

    IF jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (name, slug, owner_id)
    VALUES (v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(
      jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug)
    );

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'org_owner')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array' THEN
        RAISE EXCEPTION 'Brand % locations must be an array', v_brand_name;
      END IF;

      IF jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(
        jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name)
      );

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'org_owner')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(
          jsonb_build_object(
            'id', v_location_id,
            'organization_id', v_org_id,
            'brand_id', v_brand_id,
            'name', v_location_name,
            'address', v_location_address
          )
        );

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'org_owner')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (
      organization_id,
      current_step,
      completed_steps,
      is_completed
    )
    VALUES (
      v_org_id,
      'hierarchy_created',
      ARRAY['organizations', 'brands', 'locations'],
      false
    )
    ON CONFLICT DO NOTHING;
  END LOOP;

  UPDATE public.profiles
  SET organization_id = v_primary_org_id,
      brand_id        = v_primary_brand_id,
      location_id     = v_primary_location_id,
      role            = 'org_owner',
      access_level    = 'organization',
      updated_at      = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'org_owner',
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  BEGIN
    PERFORM public.emit_domain_event(
      'user.onboarding.hierarchy_created',
      'user',
      p_user_id,
      v_primary_org_id,
      jsonb_build_object(
        'organization_count', v_org_count,
        'brand_count', v_brand_count,
        'location_count', v_location_count,
        'organization_ids', (
          SELECT jsonb_agg(value->>'id') FROM jsonb_array_elements(v_created_orgs)
        )
      )
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Could not emit onboarding hierarchy event: %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object(
      'organizations', v_org_count,
      'brands', v_brand_count,
      'locations', v_location_count
    )
  );
END;
$$;

COMMENT ON FUNCTION public.setup_onboarding_hierarchy(UUID, JSONB) IS
  'Atomic hierarchy onboarding: creates all organizations, brands, locations, memberships, active profile context, auth metadata, progress rows, and a domain event.';

-- Source: 20260626000003_production_onboarding_workflow.sql
CREATE OR REPLACE FUNCTION public.touch_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_or_create_onboarding_run(p_user_id UUID DEFAULT auth.uid())
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_run_id UUID;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT id INTO v_run_id
  FROM public.onboarding_workflow_runs
  WHERE user_id = p_user_id
    AND status IN ('in_progress', 'pending_review', 'blocked')
  ORDER BY started_at DESC
  LIMIT 1;

  IF v_run_id IS NULL THEN
    INSERT INTO public.onboarding_workflow_runs (user_id)
    VALUES (p_user_id)
    RETURNING id INTO v_run_id;
  END IF;

  RETURN v_run_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.record_onboarding_event(
  p_run_id UUID,
  p_user_id UUID,
  p_step_key TEXT,
  p_event_type TEXT,
  p_status TEXT DEFAULT NULL,
  p_metadata JSONB DEFAULT '{}'::jsonb
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM public.profiles
  WHERE id = p_user_id;

  INSERT INTO public.onboarding_step_events (
    run_id,
    user_id,
    organization_id,
    step_key,
    event_type,
    status,
    metadata
  )
  VALUES (
    p_run_id,
    p_user_id,
    v_org_id,
    p_step_key,
    p_event_type,
    p_status,
    COALESCE(p_metadata, '{}'::jsonb)
  );

  UPDATE public.onboarding_workflow_runs
  SET current_step = p_step_key,
      organization_id = COALESCE(organization_id, v_org_id),
      last_activity_at = now(),
      metadata = metadata || jsonb_build_object('last_event', p_event_type)
  WHERE id = p_run_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.mask_tax_identifier(p_identifier TEXT)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT right(regexp_replace(COALESCE(p_identifier, ''), '\D', '', 'g'), 4);
$$;

CREATE OR REPLACE FUNCTION public.submit_business_verification(p_payload JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_legal_name TEXT;
  v_business_type TEXT;
  v_identifier_type TEXT;
  v_identifier_last4 TEXT;
  v_email TEXT;
  v_phone TEXT;
  v_website TEXT;
  v_provider TEXT;
  v_score INTEGER := 0;
  v_status TEXT;
  v_business_address JSONB;
  v_mailing_address JSONB;
  v_service_address JSONB;
  v_same_mailing BOOLEAN;
  v_verification_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  v_legal_name := NULLIF(btrim(p_payload->>'legalName'), '');
  v_business_type := COALESCE(NULLIF(btrim(p_payload->>'businessType'), ''), 'llc');
  v_identifier_type := COALESCE(NULLIF(btrim(p_payload->>'identifierType'), ''), 'ein');
  v_identifier_last4 := public.mask_tax_identifier(p_payload->>'taxIdentifier');
  v_email := NULLIF(btrim(p_payload->>'email'), '');
  v_phone := NULLIF(btrim(p_payload->>'phone'), '');
  v_website := NULLIF(btrim(p_payload->>'website'), '');
  v_business_address := COALESCE(p_payload->'businessAddress', '{}'::jsonb);
  v_same_mailing := COALESCE((p_payload->>'sameMailing')::boolean, true);
  v_mailing_address := CASE
    WHEN v_same_mailing THEN v_business_address
    ELSE COALESCE(p_payload->'mailingAddress', '{}'::jsonb)
  END;
  v_service_address := COALESCE(p_payload->'serviceAddress', '{}'::jsonb);

  IF v_legal_name IS NULL THEN
    RAISE EXCEPTION 'Legal business name is required';
  END IF;

  IF v_identifier_type NOT IN ('ein', 'ssn') THEN
    RAISE EXCEPTION 'Tax identifier type must be ein or ssn';
  END IF;

  IF length(v_identifier_last4) <> 4 THEN
    RAISE EXCEPTION 'Valid tax identifier is required';
  END IF;

  IF v_email IS NULL OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'A valid business email is required';
  END IF;

  IF length(regexp_replace(COALESCE(v_phone, ''), '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid business phone number is required';
  END IF;

  IF NULLIF(btrim(v_business_address->>'line1'), '') IS NULL
     OR NULLIF(btrim(v_business_address->>'city'), '') IS NULL
     OR NULLIF(btrim(v_business_address->>'state'), '') IS NULL
     OR length(regexp_replace(COALESCE(v_business_address->>'zip', ''), '\D', '', 'g')) < 5 THEN
    RAISE EXCEPTION 'Business address must include street, city, state, and ZIP';
  END IF;

  IF NULLIF(btrim(v_service_address->>'line1'), '') IS NULL
     OR NULLIF(btrim(v_service_address->>'city'), '') IS NULL
     OR NULLIF(btrim(v_service_address->>'state'), '') IS NULL
     OR length(regexp_replace(COALESCE(v_service_address->>'zip', ''), '\D', '', 'g')) < 5 THEN
    RAISE EXCEPTION 'Service address must include street, city, state, and ZIP';
  END IF;

  v_score := CASE WHEN v_identifier_type = 'ein' THEN 50 ELSE 45 END;
  IF v_email LIKE '%@%' THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(v_phone, '\D', '', 'g')) >= 10 THEN v_score := v_score + 10; END IF;
  IF v_website IS NOT NULL THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(COALESCE(v_business_address->>'zip', ''), '\D', '', 'g')) >= 5 THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(COALESCE(v_service_address->>'zip', ''), '\D', '', 'g')) >= 5 THEN v_score := v_score + 10; END IF;
  v_score := LEAST(v_score, 100);
  v_status := CASE WHEN v_score >= 80 THEN 'verified' WHEN v_score >= 50 THEN 'pending_review' ELSE 'failed' END;
  v_provider := CASE WHEN v_identifier_type = 'ein' THEN 'global_database_kyb' ELSE 'searchbug_ssn' END;

  INSERT INTO public.business_verifications (
    user_id,
    legal_business_name,
    business_type,
    identifier_type,
    identifier_last4,
    provider_name,
    provider_reference_id,
    verification_status,
    trust_score,
    metadata
  )
  VALUES (
    v_user_id,
    v_legal_name,
    v_business_type,
    v_identifier_type,
    v_identifier_last4,
    v_provider,
    'provider-ready-' || replace(gen_random_uuid()::text, '-', ''),
    v_status,
    v_score,
    jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'website', v_website,
      'provider_mode', 'simulation_until_provider_keys_configured'
    )
  )
  RETURNING id INTO v_verification_id;

  DELETE FROM public.organization_addresses
  WHERE user_id = v_user_id
    AND organization_id IS NULL;

  INSERT INTO public.organization_addresses (
    user_id,
    address_type,
    location_name,
    address_line_1,
    address_line_2,
    city,
    state,
    zip_code,
    country,
    usps_verified,
    usps_standardized,
    usps_validation_code
  )
  VALUES
    (
      v_user_id,
      'business',
      NULL,
      btrim(v_business_address->>'line1'),
      NULLIF(btrim(v_business_address->>'line2'), ''),
      btrim(v_business_address->>'city'),
      btrim(v_business_address->>'state'),
      btrim(v_business_address->>'zip'),
      'US',
      true,
      true,
      'PROVIDER_READY_USPS'
    ),
    (
      v_user_id,
      'mailing',
      NULL,
      btrim(v_mailing_address->>'line1'),
      NULLIF(btrim(v_mailing_address->>'line2'), ''),
      btrim(v_mailing_address->>'city'),
      btrim(v_mailing_address->>'state'),
      btrim(v_mailing_address->>'zip'),
      'US',
      true,
      true,
      CASE WHEN v_same_mailing THEN 'SAME_AS_BUSINESS' ELSE 'PROVIDER_READY_USPS' END
    ),
    (
      v_user_id,
      'service',
      NULLIF(btrim(p_payload->>'serviceLocationName'), ''),
      btrim(v_service_address->>'line1'),
      NULLIF(btrim(v_service_address->>'line2'), ''),
      btrim(v_service_address->>'city'),
      btrim(v_service_address->>'state'),
      btrim(v_service_address->>'zip'),
      'US',
      true,
      true,
      'PROVIDER_READY_USPS'
    );

  UPDATE public.profiles
  SET business_verification_status = v_status,
      business_verification_score = v_score,
      business_verification_provider = v_provider,
      business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
      business_type = v_business_type,
      tax_identifier_type = v_identifier_type,
      tax_identifier_last4 = v_identifier_last4,
      onboarding_status = CASE WHEN v_status = 'pending_review' THEN 'pending_review' ELSE 'in_progress' END,
      onboarding_current_step = CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'business_verification' END,
      updated_at = now()
  WHERE id = v_user_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'business_verification',
    CASE WHEN v_status = 'verified' THEN 'verified' WHEN v_status = 'failed' THEN 'failed' ELSE 'submitted' END,
    v_status,
    jsonb_build_object('verification_id', v_verification_id, 'trust_score', v_score)
  );

  RETURN jsonb_build_object(
    'success', true,
    'verification_id', v_verification_id,
    'status', v_status,
    'trust_score', v_score,
    'next_step', CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'manual_review' END
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.verify_onboarding_payment_method(
  p_method_type TEXT,
  p_provider TEXT DEFAULT 'stripe',
  p_provider_payment_method_id TEXT DEFAULT NULL,
  p_last4 TEXT DEFAULT NULL,
  p_brand TEXT DEFAULT NULL,
  p_bank_name TEXT DEFAULT NULL,
  p_metadata JSONB DEFAULT '{}'::jsonb
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_status TEXT;
  v_payment_method_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF p_method_type NOT IN ('card', 'ach') THEN
    RAISE EXCEPTION 'Payment method must be card or ach';
  END IF;

  SELECT business_verification_status INTO v_status
  FROM public.profiles
  WHERE id = v_user_id;

  IF COALESCE(v_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before payment setup';
  END IF;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);

  INSERT INTO public.onboarding_payment_methods (
    user_id,
    method_type,
    provider,
    provider_payment_method_id,
    status,
    last4,
    brand,
    bank_name,
    verified_at,
    metadata
  )
  VALUES (
    v_user_id,
    p_method_type,
    COALESCE(NULLIF(p_provider, ''), 'stripe'),
    NULLIF(p_provider_payment_method_id, ''),
    'verified',
    NULLIF(p_last4, ''),
    NULLIF(p_brand, ''),
    NULLIF(p_bank_name, ''),
    now(),
    COALESCE(p_metadata, '{}'::jsonb)
  )
  RETURNING id INTO v_payment_method_id;

  UPDATE public.profiles
  SET payment_verified = true,
      payment_method_type = p_method_type,
      payment_method_verified_at = now(),
      onboarding_status = 'in_progress',
      onboarding_current_step = 'plan_selection',
      updated_at = now()
  WHERE id = v_user_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'payment_method',
    'verified',
    'verified',
    jsonb_build_object('payment_method_id', v_payment_method_id, 'method_type', p_method_type)
  );

  RETURN jsonb_build_object(
    'success', true,
    'payment_method_id', v_payment_method_id,
    'method_type', p_method_type,
    'next_step', 'plan_selection'
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_onboarding_coupon(
  p_code TEXT,
  p_plan_id TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_coupon public.onboarding_coupons%ROWTYPE;
  v_redemption_id UUID;
  v_trial_ends_at TIMESTAMPTZ;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_coupon
  FROM public.onboarding_coupons
  WHERE lower(code) = lower(btrim(p_code))
    AND active = true
    AND (starts_at IS NULL OR starts_at <= now())
    AND (expires_at IS NULL OR expires_at > now())
  LIMIT 1;

  IF v_coupon.id IS NULL THEN
    RAISE EXCEPTION 'Coupon is invalid or expired';
  END IF;

  IF v_coupon.max_redemptions IS NOT NULL AND v_coupon.redeemed_count >= v_coupon.max_redemptions THEN
    RAISE EXCEPTION 'Coupon has reached its redemption limit';
  END IF;

  IF v_coupon.applies_to_plan_ids IS NOT NULL
     AND p_plan_id IS NOT NULL
     AND NOT (p_plan_id = ANY(v_coupon.applies_to_plan_ids)) THEN
    RAISE EXCEPTION 'Coupon does not apply to the selected plan';
  END IF;

  v_trial_ends_at := CASE
    WHEN v_coupon.discount_type = 'trial_days' AND v_coupon.trial_days > 0
    THEN now() + make_interval(days => v_coupon.trial_days)
    ELSE NULL
  END;

  INSERT INTO public.onboarding_coupon_redemptions (
    coupon_id,
    user_id,
    plan_id,
    discount_snapshot
  )
  VALUES (
    v_coupon.id,
    v_user_id,
    p_plan_id,
    jsonb_build_object(
      'code', v_coupon.code,
      'discount_type', v_coupon.discount_type,
      'discount_value', v_coupon.discount_value,
      'trial_days', v_coupon.trial_days,
      'trial_ends_at', v_trial_ends_at
    )
  )
  ON CONFLICT (coupon_id, user_id) DO UPDATE
  SET plan_id = EXCLUDED.plan_id,
      status = 'applied',
      discount_snapshot = EXCLUDED.discount_snapshot,
      redeemed_at = now()
  RETURNING id INTO v_redemption_id;

  UPDATE public.onboarding_coupons
  SET redeemed_count = (
    SELECT count(*) FROM public.onboarding_coupon_redemptions
    WHERE coupon_id = v_coupon.id AND status IN ('applied', 'consumed')
  )
  WHERE id = v_coupon.id;

  UPDATE public.profiles
  SET coupon_code = v_coupon.code,
      trial_ends_at = COALESCE(v_trial_ends_at, trial_ends_at),
      onboarding_current_step = 'hierarchy_setup',
      updated_at = now()
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'redemption_id', v_redemption_id,
    'coupon', jsonb_build_object(
      'code', v_coupon.code,
      'description', v_coupon.description,
      'discount_type', v_coupon.discount_type,
      'discount_value', v_coupon.discount_value,
      'trial_days', v_coupon.trial_days,
      'trial_ends_at', v_trial_ends_at
    )
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_my_onboarding_state()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_profile JSONB;
  v_verification JSONB;
  v_payment JSONB;
  v_coupon JSONB;
  v_run JSONB;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT to_jsonb(p) INTO v_profile
  FROM public.profiles p
  WHERE p.id = v_user_id;

  SELECT to_jsonb(bv) INTO v_verification
  FROM public.business_verifications bv
  WHERE bv.user_id = v_user_id
  ORDER BY bv.created_at DESC
  LIMIT 1;

  SELECT to_jsonb(pm) INTO v_payment
  FROM public.onboarding_payment_methods pm
  WHERE pm.user_id = v_user_id
  ORDER BY pm.created_at DESC
  LIMIT 1;

  SELECT to_jsonb(r) INTO v_coupon
  FROM public.onboarding_coupon_redemptions r
  WHERE r.user_id = v_user_id
    AND r.status = 'applied'
  ORDER BY r.redeemed_at DESC
  LIMIT 1;

  SELECT to_jsonb(w) INTO v_run
  FROM public.onboarding_workflow_runs w
  WHERE w.user_id = v_user_id
  ORDER BY w.started_at DESC
  LIMIT 1;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'workflow_run', v_run,
    'business_verification', v_verification,
    'payment_method', v_payment,
    'coupon_redemption', v_coupon
  );
END;
$$;

-- Source: 20260626000004_harden_onboarding_hierarchy_completion.sql
CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id UUID,
  p_hierarchy JSONB
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item JSONB;
  brand_item JSONB;
  location_item JSONB;
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
  v_primary_org_id UUID;
  v_primary_brand_id UUID;
  v_primary_location_id UUID;
  v_created_orgs JSONB := '[]'::jsonb;
  v_created_brands JSONB := '[]'::jsonb;
  v_created_locations JSONB := '[]'::jsonb;
  v_org_name TEXT;
  v_org_slug TEXT;
  v_brand_name TEXT;
  v_location_name TEXT;
  v_location_address TEXT;
  v_org_count INTEGER := 0;
  v_brand_count INTEGER := 0;
  v_location_count INTEGER := 0;
  v_business_status TEXT;
  v_payment_verified BOOLEAN;
  v_run_id UUID;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified
  INTO v_business_status, v_payment_verified
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  v_run_id := public.get_or_create_onboarding_run(p_user_id);


  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array' THEN
      RAISE EXCEPTION 'Organization % brands must be an array', v_org_name;
    END IF;

    IF jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (name, slug, owner_id)
    VALUES (v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(
      jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug)
    );

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'org_owner')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array' THEN
        RAISE EXCEPTION 'Brand % locations must be an array', v_brand_name;
      END IF;

      IF jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(
        jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name)
      );

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'org_owner')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(
          jsonb_build_object(
            'id', v_location_id,
            'organization_id', v_org_id,
            'brand_id', v_brand_id,
            'name', v_location_name,
            'address', v_location_address
          )
        );

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'org_owner')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (
      organization_id,
      current_step,
      completed_steps,
      is_completed
    )
    VALUES (
      v_org_id,
      'hierarchy_created',
      ARRAY['organizations', 'brands', 'locations'],
      false
    )
    ON CONFLICT DO NOTHING;
  END LOOP;

  UPDATE public.profiles
  SET organization_id = v_primary_org_id,
      brand_id        = v_primary_brand_id,
      location_id     = v_primary_location_id,
      role            = 'org_owner',
      access_level    = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at      = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'org_owner',
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  UPDATE public.business_verifications
  SET organization_id = v_primary_org_id,
      updated_at = now()
  WHERE user_id = p_user_id
    AND organization_id IS NULL;

  UPDATE public.organization_addresses
  SET organization_id = v_primary_org_id,
      updated_at = now()
  WHERE user_id = p_user_id
    AND organization_id IS NULL;

  UPDATE public.onboarding_payment_methods
  SET organization_id = v_primary_org_id,
      updated_at = now()
  WHERE user_id = p_user_id
    AND organization_id IS NULL;

  UPDATE public.onboarding_coupon_redemptions
  SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id
    AND organization_id IS NULL;

  UPDATE public.onboarding_workflow_runs
  SET organization_id = v_primary_org_id,
      status = 'completed',
      current_step = 'completed',
      completed_at = now(),
      last_activity_at = now()
  WHERE id = v_run_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    p_user_id,
    'hierarchy_setup',
    'completed',
    'completed',
    jsonb_build_object(
      'primary_org_id', v_primary_org_id,
      'organization_count', v_org_count,
      'brand_count', v_brand_count,
      'location_count', v_location_count
    )
  );
  BEGIN
    PERFORM public.emit_domain_event(
      'user.onboarding.hierarchy_created',
      'user',
      p_user_id,
      v_primary_org_id,
      jsonb_build_object(
        'organization_count', v_org_count,
        'brand_count', v_brand_count,
        'location_count', v_location_count,
        'organization_ids', (
          SELECT jsonb_agg(value->>'id') FROM jsonb_array_elements(v_created_orgs)
        )
      )
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Could not emit onboarding hierarchy event: %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'success', true,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object(
      'organizations', v_org_count,
      'brands', v_brand_count,
      'locations', v_location_count
    )
  );
END;
$$;

COMMENT ON FUNCTION public.setup_onboarding_hierarchy(UUID, JSONB) IS
  'Atomic production onboarding completion: requires verified business and payment, creates hierarchy, links verification/payment/coupon state, and completes the workflow run.';

-- Source: 20260626000005_onboarding_contact_otp.sql
CREATE OR REPLACE FUNCTION public.normalize_contact_target(p_channel TEXT, p_target TEXT)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  v_target TEXT;
  v_digits TEXT;
BEGIN
  IF p_channel = 'email' THEN
    v_target := lower(btrim(COALESCE(p_target, '')));
    RETURN v_target;
  ELSIF p_channel = 'phone' THEN
    v_digits := regexp_replace(COALESCE(p_target, ''), '\D', '', 'g');
    IF length(v_digits) = 10 THEN
      RETURN '+1' || v_digits;
    ELSIF length(v_digits) = 11 AND left(v_digits, 1) = '1' THEN
      RETURN '+' || v_digits;
    ELSE
      RETURN v_digits;
    END IF;
  END IF;

  RETURN btrim(COALESCE(p_target, ''));
END;
$$;

CREATE OR REPLACE FUNCTION public.request_onboarding_contact_otp(
  p_channel TEXT,
  p_target TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_channel TEXT := lower(btrim(COALESCE(p_channel, '')));
  v_target TEXT;
  v_code TEXT;
  v_otp_id UUID;
  v_recent_count INTEGER;
  v_run_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF v_channel NOT IN ('email', 'phone') THEN
    RAISE EXCEPTION 'OTP channel must be email or phone';
  END IF;

  v_target := public.normalize_contact_target(v_channel, p_target);

  IF v_channel = 'email' AND (v_target IS NULL OR position('@' in v_target) = 0) THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  IF v_channel = 'phone' AND length(regexp_replace(v_target, '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid phone number is required';
  END IF;

  SELECT count(*) INTO v_recent_count
  FROM public.onboarding_contact_otps
  WHERE user_id = v_user_id
    AND channel = v_channel
    AND created_at > now() - interval '15 minutes';

  IF v_recent_count >= 5 THEN
    RAISE EXCEPTION 'Too many OTP requests. Please wait before requesting another code';
  END IF;

  v_code := lpad(floor(random() * 1000000)::text, 6, '0');

  INSERT INTO public.onboarding_contact_otps (
    user_id,
    channel,
    target,
    code_hash,
    provider,
    metadata
  )
  VALUES (
    v_user_id,
    v_channel,
    v_target,
    crypt(v_code, gen_salt('bf')),
    CASE WHEN v_channel = 'email' THEN 'email_provider_ready' ELSE 'sms_provider_ready' END,
    jsonb_build_object('delivery_mode', 'development_echo_until_provider_configured')
  )
  RETURNING id INTO v_otp_id;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    CASE WHEN v_channel = 'email' THEN 'business_email_otp' ELSE 'business_phone_otp' END,
    'started',
    'pending',
    jsonb_build_object('otp_id', v_otp_id, 'target', v_target)
  );

  RETURN jsonb_build_object(
    'success', true,
    'otp_id', v_otp_id,
    'channel', v_channel,
    'target', v_target,
    'expires_at', now() + interval '10 minutes',
    'delivery_mode', 'development_echo_until_provider_configured',
    'dev_code', v_code
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.verify_onboarding_contact_otp(
  p_otp_id UUID,
  p_code TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_otp public.onboarding_contact_otps%ROWTYPE;
  v_run_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_otp
  FROM public.onboarding_contact_otps
  WHERE id = p_otp_id
    AND user_id = v_user_id
  FOR UPDATE;

  IF v_otp.id IS NULL THEN
    RAISE EXCEPTION 'OTP request not found';
  END IF;

  IF v_otp.status = 'verified' THEN
    RETURN jsonb_build_object('success', true, 'channel', v_otp.channel, 'target', v_otp.target, 'already_verified', true);
  END IF;

  IF v_otp.status <> 'pending' THEN
    RAISE EXCEPTION 'OTP request is no longer active';
  END IF;

  IF v_otp.expires_at < now() THEN
    UPDATE public.onboarding_contact_otps
    SET status = 'expired', updated_at = now()
    WHERE id = v_otp.id;
    RAISE EXCEPTION 'OTP code expired';
  END IF;

  IF v_otp.attempts >= v_otp.max_attempts THEN
    UPDATE public.onboarding_contact_otps
    SET status = 'failed', updated_at = now()
    WHERE id = v_otp.id;
    RAISE EXCEPTION 'Too many incorrect OTP attempts';
  END IF;

  IF v_otp.code_hash <> crypt(btrim(COALESCE(p_code, '')), v_otp.code_hash) THEN
    UPDATE public.onboarding_contact_otps
    SET attempts = attempts + 1,
        status = CASE WHEN attempts + 1 >= max_attempts THEN 'failed' ELSE status END,
        updated_at = now()
    WHERE id = v_otp.id;
    RAISE EXCEPTION 'Invalid OTP code';
  END IF;

  UPDATE public.onboarding_contact_otps
  SET status = 'verified',
      verified_at = now(),
      updated_at = now()
  WHERE id = v_otp.id;

  IF v_otp.channel = 'email' THEN
    UPDATE public.profiles
    SET business_email = v_otp.target,
        business_email_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  ELSE
    UPDATE public.profiles
    SET business_phone = v_otp.target,
        business_phone_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    CASE WHEN v_otp.channel = 'email' THEN 'business_email_otp' ELSE 'business_phone_otp' END,
    'verified',
    'verified',
    jsonb_build_object('otp_id', v_otp.id, 'target', v_otp.target)
  );

  RETURN jsonb_build_object(
    'success', true,
    'channel', v_otp.channel,
    'target', v_otp.target,
    'verified_at', now()
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.ensure_onboarding_contact_verified(p_email TEXT, p_phone TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_email TEXT := public.normalize_contact_target('email', p_email);
  v_phone TEXT := public.normalize_contact_target('phone', p_phone);
  v_profile RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT business_email, business_email_verified_at, business_phone, business_phone_verified_at
  INTO v_profile
  FROM public.profiles
  WHERE id = v_user_id;

  IF v_profile.business_email_verified_at IS NULL OR v_profile.business_email IS DISTINCT FROM v_email THEN
    RAISE EXCEPTION 'Business email must be verified by OTP before business verification';
  END IF;

  IF v_profile.business_phone_verified_at IS NULL OR v_profile.business_phone IS DISTINCT FROM v_phone THEN
    RAISE EXCEPTION 'Business phone must be verified by OTP before business verification';
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_business_verification_contact_otp()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_profile RECORD;
  v_email TEXT;
  v_phone TEXT;
BEGIN
  IF public.get_auth_role() = 'platform_admin' THEN
    RETURN NEW;
  END IF;

  v_email := public.normalize_contact_target('email', NEW.metadata->>'email');
  v_phone := public.normalize_contact_target('phone', NEW.metadata->>'phone');

  SELECT business_email, business_email_verified_at, business_phone, business_phone_verified_at
  INTO v_profile
  FROM public.profiles
  WHERE id = NEW.user_id;

  IF v_profile.business_email_verified_at IS NULL OR v_profile.business_email IS DISTINCT FROM v_email THEN
    RAISE EXCEPTION 'Business email must be verified by OTP before business verification';
  END IF;

  IF v_profile.business_phone_verified_at IS NULL OR v_profile.business_phone IS DISTINCT FROM v_phone THEN
    RAISE EXCEPTION 'Business phone must be verified by OTP before business verification';
  END IF;

  NEW.metadata := COALESCE(NEW.metadata, '{}'::jsonb) || jsonb_build_object(
    'email_verified', true,
    'email_verified_at', v_profile.business_email_verified_at,
    'phone_verified', true,
    'phone_verified_at', v_profile.business_phone_verified_at
  );

  RETURN NEW;
END;
$$;

-- Source: 20260626000006_enforce_tax_identifier_by_tenant_type.sql
CREATE OR REPLACE FUNCTION public.required_tax_identifier_type_for_business_type(p_business_type TEXT)
RETURNS TEXT
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE
    WHEN p_business_type IN ('sole_proprietor', 'independent_contractor') THEN 'ssn'
    ELSE 'ein'
  END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_business_verification_identifier_type()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_required_type TEXT;
BEGIN
  v_required_type := public.required_tax_identifier_type_for_business_type(NEW.business_type);

  IF NEW.identifier_type IS DISTINCT FROM v_required_type THEN
    RAISE EXCEPTION 'Tax identifier type % is not allowed for business type %. Required type is %', NEW.identifier_type, NEW.business_type, v_required_type;
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260626000007_start_invoice_extraction_workflow.sql
CREATE OR REPLACE FUNCTION public.start_invoice_extraction_workflow(p_invoice_id UUID)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_functions_url TEXT;
  v_service_role_key TEXT;
  v_url TEXT;
  v_headers JSONB;
  v_payload JSONB;
  v_request_id BIGINT;
BEGIN
  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % not found', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.assert_org_actor(v_invoice.organization_id);

  IF v_invoice.status NOT IN ('extracting', 'uploading', 'extract_failed') THEN
    RETURN jsonb_build_object(
      'success', true,
      'queued', false,
      'reason', 'invoice_not_extractable',
      'status', v_invoice.status
    );
  END IF;

  IF v_invoice.status = 'extracting'
     AND v_invoice.extraction_started_at IS NOT NULL
     AND v_invoice.extraction_started_at > now() - interval '5 minutes' THEN
    RETURN jsonb_build_object(
      'success', true,
      'queued', false,
      'reason', 'extraction_already_running',
      'status', v_invoice.status,
      'extraction_started_at', v_invoice.extraction_started_at
    );
  END IF;

  UPDATE public.invoices
     SET status = 'extracting',
         ap_status = 'processing',
         extraction_started_at = NULL,
         validation_results = COALESCE(validation_results, '{}'::jsonb) - 'error',
         updated_at = now()
   WHERE id = p_invoice_id
   RETURNING * INTO v_invoice;

  SELECT setting_value
    INTO v_functions_url
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'functions_url';

  SELECT setting_value
    INTO v_service_role_key
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'service_role_key';

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE EXCEPTION 'private.workflow_runtime_settings.service_role_key is required for invoice extraction dispatch';
  END IF;

  v_url := COALESCE(
    NULLIF(trim(v_functions_url), ''),
    'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1'
  ) || '/invoice-processing';

  v_headers := jsonb_build_object(
    'Content-Type', 'application/json',
    'Authorization', 'Bearer ' || v_service_role_key
  );

  v_payload := jsonb_build_object(
    'type', 'INSERT',
    'table', 'invoices',
    'schema', 'public',
    'record', row_to_json(v_invoice),
    'old_record', NULL
  );

  SELECT net.http_post(
    url := v_url,
    body := v_payload,
    headers := v_headers
  ) INTO v_request_id;

  RETURN jsonb_build_object(
    'success', true,
    'queued', true,
    'request_id', v_request_id,
    'invoice_id', v_invoice.id
  );
END;
$$;

COMMENT ON FUNCTION public.start_invoice_extraction_workflow(UUID) IS
  'Tenant-safe workflow entrypoint that enqueues invoice extraction through pg_net after validating invoice access.';

-- Source: 20260626000009_extend_invoice_processing_pg_net_timeout.sql
CREATE OR REPLACE FUNCTION public.invoke_edge_function()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  function_name text := TG_ARGV[0];
  v_url text;
  v_functions_url text;
  v_service_role_key text;
  v_headers jsonb;
  v_payload jsonb;
BEGIN
  SELECT setting_value
    INTO v_functions_url
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'functions_url';

  SELECT setting_value
    INTO v_service_role_key
    FROM private.workflow_runtime_settings
   WHERE setting_name = 'service_role_key';

  v_url := COALESCE(
    NULLIF(trim(v_functions_url), ''),
    'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1'
  ) || '/' || function_name;

  IF v_service_role_key IS NULL OR length(trim(v_service_role_key)) = 0 THEN
    RAISE EXCEPTION 'private.workflow_runtime_settings.service_role_key is required for invoke_edge_function';
  END IF;

  v_headers := jsonb_build_object(
    'Content-Type', 'application/json',
    'Authorization', 'Bearer ' || v_service_role_key
  );

  v_payload := jsonb_build_object(
    'type', TG_OP,
    'table', TG_TABLE_NAME,
    'schema', TG_TABLE_SCHEMA,
    'record', CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW) ELSE NULL END,
    'old_record', CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD) ELSE NULL END
  );

  PERFORM net.http_post(
    url := v_url,
    body := v_payload,
    headers := v_headers,
    timeout_milliseconds := CASE WHEN function_name = 'invoice-processing' THEN 180000 ELSE 30000 END
  );

  RETURN NULL;
END;
$$;

