-- Source: 20260628000022_vendor_banking_default.sql
CREATE OR REPLACE FUNCTION public.set_vendor_banking_default()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.is_default IS NOT TRUE THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.vendor_banking_details vbd
      WHERE vbd.vendor_id = NEW.vendor_id
        AND vbd.is_default = true
        AND vbd.deleted_at IS NULL
    ) THEN
      NEW.is_default := true;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_vendor_payment_account(p_vendor_id uuid)
RETURNS TABLE (
  id uuid,
  banking_secret_id uuid,
  account_last4 text,
  is_default boolean
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  -- Ponytail: fallback picks any active+verified alternate with no explicit
  -- ordering. If the business needs ranked fallback, add a priority column then.
  SELECT vbd.id,
         vbd.banking_secret_id,
         vbd.account_last4,
         vbd.is_default
  FROM public.vendor_banking_details vbd
  WHERE vbd.vendor_id = p_vendor_id
    AND vbd.is_active = true
    AND vbd.verification_state = 'verified'
    AND vbd.banking_secret_id IS NOT NULL
    AND vbd.deleted_at IS NULL
  ORDER BY vbd.is_default DESC, vbd.created_at ASC, vbd.id ASC
  LIMIT 1;
$$;

-- Source: 20260628000023_vendor_banking_link.sql
CREATE OR REPLACE FUNCTION public.set_vendor_banking_link_scope()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
BEGIN
  SELECT *
    INTO v_vendor
  FROM public.vendors
  WHERE id = NEW.vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor % does not exist', NEW.vendor_id;
  END IF;

  NEW.organization_id := v_vendor.organization_id;
  NEW.brand_id := v_vendor.brand_id;
  NEW.location_id := v_vendor.location_id;
  NEW.updated_at := now();
  NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := COALESCE(NEW.created_at, now());
    NEW.created_by := COALESCE(NEW.created_by, auth.uid());
  END IF;

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.issue_vendor_banking_link(p_vendor_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_token public.vendor_banking_link_tokens%ROWTYPE;
BEGIN
  SELECT *
    INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(
    v_vendor.organization_id,
    v_vendor.brand_id,
    v_vendor.location_id,
    NULL::timestamptz,
    'location_manager'
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendor_banking_link_tokens
     SET status = 'cancelled',
         updated_at = now(),
         updated_by = auth.uid()
   WHERE vendor_id = p_vendor_id
     AND status = 'pending'
     AND deleted_at IS NULL;

  INSERT INTO public.vendor_banking_link_tokens (vendor_id)
  VALUES (p_vendor_id)
  RETURNING * INTO v_token;

  RETURN jsonb_build_object(
    'id', v_token.id,
    'vendor_id', v_token.vendor_id,
    'organization_id', v_token.organization_id,
    'brand_id', v_token.brand_id,
    'location_id', v_token.location_id,
    'token', v_token.token,
    'status', v_token.status,
    'expires_at', v_token.expires_at
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.submit_vendor_banking_via_link(
  p_token text,
  p_account text,
  p_routing text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_token public.vendor_banking_link_tokens%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
  v_store_result jsonb;
BEGIN
  SELECT *
    INTO v_token
  FROM public.vendor_banking_link_tokens
  WHERE token = btrim(COALESCE(p_token, ''))
    AND status = 'pending'
    AND expires_at > now()
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_token.id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired banking link';
  END IF;

  INSERT INTO public.vendor_banking_details (
    vendor_id,
    organization_id,
    brand_id,
    location_id,
    verification_state,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_token.organization_id,
    v_token.brand_id,
    v_token.location_id,
    'pending',
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_bank;

  v_store_result := public.store_vendor_banking_secret(v_bank.id, p_account, p_routing);

  UPDATE public.vendor_banking_link_tokens
     SET status = 'submitted',
         submitted_at = now(),
         updated_at = now()
   WHERE id = v_token.id;

  IF v_token.created_by IS NOT NULL THEN
    INSERT INTO public.notifications (
      user_id,
      organization_id,
      brand_id,
      location_id,
      title,
      message,
      type,
      is_read,
      metadata
    ) VALUES (
      v_token.created_by,
      v_token.organization_id,
      v_token.brand_id,
      v_token.location_id,
      'Vendor submitted banking details',
      'A vendor submitted banking details through the secure link.',
      'system',
      false,
      jsonb_build_object(
        'vendor_id', v_token.vendor_id,
        'banking_row_id', v_bank.id,
        'token_id', v_token.id
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_token.vendor_id,
    'banking_row_id', v_bank.id,
    'banking_secret_id', v_store_result->>'banking_secret_id',
    'account_last4', v_store_result->>'account_last4'
  );
END;
$$;

-- Source: 20260628000024_vendor_banking_change_intent.sql
CREATE OR REPLACE FUNCTION public.enforce_vendor_banking_default_replacement()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Ponytail: replace deactivates the prior default at the single "becoming
  -- default" point, so link submit and manual promotion cannot diverge. Ceiling:
  -- a future "switch default but keep both active" flow needs an explicit flag.
  IF NEW.is_default IS TRUE
     AND (TG_OP = 'INSERT' OR OLD.is_default IS DISTINCT FROM TRUE) THEN
    UPDATE public.vendor_banking_details
       SET is_default = false,
           is_active = false,
           updated_at = now()
     WHERE vendor_id = NEW.vendor_id
       AND id IS DISTINCT FROM NEW.id
       AND is_default = true
       AND is_active = true
       AND deleted_at IS NULL;
  END IF;

  RETURN NEW;
END;
$$;

DROP FUNCTION IF EXISTS public.issue_vendor_banking_link(uuid);

CREATE OR REPLACE FUNCTION public.issue_vendor_banking_link(
  p_vendor_id uuid,
  p_intent text DEFAULT 'add'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_token public.vendor_banking_link_tokens%ROWTYPE;
  v_intent text := COALESCE(NULLIF(btrim(p_intent), ''), 'add');
BEGIN
  IF v_intent NOT IN ('add', 'replace') THEN
    RAISE EXCEPTION 'Invalid vendor banking link intent: %', p_intent;
  END IF;

  SELECT *
    INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(
    v_vendor.organization_id,
    v_vendor.brand_id,
    v_vendor.location_id,
    NULL::timestamptz,
    'location_manager'
  ) THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendor_banking_link_tokens
     SET status = 'cancelled',
         updated_at = now(),
         updated_by = auth.uid()
   WHERE vendor_id = p_vendor_id
     AND status = 'pending'
     AND deleted_at IS NULL;

  INSERT INTO public.vendor_banking_link_tokens (vendor_id, intent)
  VALUES (p_vendor_id, v_intent)
  RETURNING * INTO v_token;

  RETURN jsonb_build_object(
    'id', v_token.id,
    'vendor_id', v_token.vendor_id,
    'organization_id', v_token.organization_id,
    'brand_id', v_token.brand_id,
    'location_id', v_token.location_id,
    'token', v_token.token,
    'status', v_token.status,
    'intent', v_token.intent,
    'expires_at', v_token.expires_at
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.submit_vendor_banking_via_link(
  p_token text,
  p_account text,
  p_routing text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_token public.vendor_banking_link_tokens%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
  v_store_result jsonb;
BEGIN
  SELECT *
    INTO v_token
  FROM public.vendor_banking_link_tokens
  WHERE token = btrim(COALESCE(p_token, ''))
    AND status = 'pending'
    AND expires_at > now()
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_token.id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired banking link';
  END IF;

  INSERT INTO public.vendor_banking_details (
    vendor_id,
    organization_id,
    brand_id,
    location_id,
    verification_state,
    verified_at,
    is_default,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_token.organization_id,
    v_token.brand_id,
    v_token.location_id,
    'verified',
    now(),
    false,
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_bank;

  v_store_result := public.store_vendor_banking_secret(v_bank.id, p_account, p_routing);

  IF v_token.intent = 'replace' THEN
    UPDATE public.vendor_banking_details
       SET is_default = true,
           updated_at = now()
     WHERE id = v_bank.id
     RETURNING * INTO v_bank;
  END IF;

  UPDATE public.vendor_banking_link_tokens
     SET status = 'submitted',
         submitted_at = now(),
         updated_at = now()
   WHERE id = v_token.id;

  IF v_token.created_by IS NOT NULL THEN
    INSERT INTO public.notifications (
      user_id,
      organization_id,
      brand_id,
      location_id,
      title,
      message,
      type,
      is_read,
      metadata
    ) VALUES (
      v_token.created_by,
      v_token.organization_id,
      v_token.brand_id,
      v_token.location_id,
      'Vendor submitted banking details',
      'A vendor submitted banking details through the secure link.',
      'system',
      false,
      jsonb_build_object(
        'vendor_id', v_token.vendor_id,
        'banking_row_id', v_bank.id,
        'token_id', v_token.id,
        'intent', v_token.intent
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_token.vendor_id,
    'banking_row_id', v_bank.id,
    'banking_secret_id', v_store_result->>'banking_secret_id',
    'account_last4', v_store_result->>'account_last4',
    'intent', v_token.intent,
    'is_default', v_bank.is_default
  );
END;
$$;

-- Source: 20260628000025_provider_links_consolidation.sql
CREATE OR REPLACE FUNCTION public.get_vendor_provider_link(
  p_vendor_id uuid,
  p_provider text
)
RETURNS TABLE (
  id uuid,
  vendor_id uuid,
  organization_id uuid,
  brand_id uuid,
  location_id uuid,
  provider text,
  provider_customer_ref text,
  provider_funding_ref text,
  provider_status text,
  is_active boolean
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  -- Ponytail: provider-links hold vendor/destination keys only. Tenant/source
  -- funding refs stay on payment_accounts. Checkbook creates a row here only
  -- if a future adapter registers a reusable vendor token to store.
  SELECT vpl.id,
         vpl.vendor_id,
         vpl.organization_id,
         vpl.brand_id,
         vpl.location_id,
         vpl.provider,
         vpl.provider_customer_ref,
         vpl.provider_funding_ref,
         vpl.provider_status,
         vpl.is_active
  FROM public.vendor_payment_provider_links vpl
  WHERE vpl.vendor_id = p_vendor_id
    AND vpl.provider = lower(btrim(p_provider))
    AND vpl.is_active = true
    AND vpl.deleted_at IS NULL
  ORDER BY vpl.updated_at DESC, vpl.created_at DESC, vpl.id DESC
  LIMIT 1;
$$;

-- Source: 20260628000028_vendor_approval_containment.sql
CREATE OR REPLACE FUNCTION public.assert_can_approve_vendor_scope(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_auth_org uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_role := public.get_auth_role();
  v_auth_org := public.get_auth_org();

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF p_organization_id IS NULL OR v_auth_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization vendor approval denied';
  END IF;

  IF v_role = 'org_owner' THEN
    RETURN;
  END IF;

  IF v_role = 'branch_manager'
     AND p_brand_id IS NOT NULL
     AND public.reference_scope_writable(
       p_organization_id,
       p_brand_id,
       NULL,
       NULL,
       'branch_manager'
     ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Vendor approval denied for role % outside accessible brand scope', v_role;
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_vendor_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
    PERFORM public.assert_can_approve_vendor_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260628000029_vendor_approval_insert_containment.sql
CREATE OR REPLACE FUNCTION public.assert_can_approve_vendor_scope(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_auth_org uuid;
BEGIN
  -- ponytail: service_role bypass is safe here because auth.role() comes from the
  -- verified database request context, not user-supplied JWT metadata; authenticated
  -- callers cannot forge service_role without the service-role key.
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_role := public.get_auth_role();
  v_auth_org := public.get_auth_org();

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF p_organization_id IS NULL OR v_auth_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization vendor approval denied';
  END IF;

  IF v_role = 'org_owner' THEN
    RETURN;
  END IF;

  IF v_role = 'branch_manager'
     AND p_brand_id IS NOT NULL
     AND public.reference_scope_writable(
       p_organization_id,
       p_brand_id,
       NULL,
       NULL,
       'branch_manager'
     ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Vendor approval denied for role % outside accessible brand scope', v_role;
END;
$$;

CREATE OR REPLACE FUNCTION public.enforce_vendor_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.approval_status IN ('pending_approval', 'approved', 'suspended', 'rejected') THEN
      PERFORM public.assert_can_approve_vendor_scope(
        NEW.organization_id,
        NEW.brand_id,
        NEW.location_id
      );
    END IF;

    RETURN NEW;
  END IF;

  IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
    PERFORM public.assert_can_approve_vendor_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260628000030_vendor_approval_transition_rpc.sql
CREATE OR REPLACE FUNCTION public.transition_vendor_approval(
  p_vendor_id uuid,
  p_new_status text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_new_status text;
BEGIN

  v_new_status := lower(btrim(COALESCE(p_new_status, '')));

  SELECT *
    INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id
  FOR UPDATE;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  PERFORM public.assert_can_approve_vendor_scope(
    v_vendor.organization_id,
    v_vendor.brand_id,
    v_vendor.location_id
  );

  IF v_new_status = v_vendor.approval_status THEN
    RAISE EXCEPTION 'Vendor approval_status is already %', v_new_status;
  END IF;

  -- ponytail: transition edges are intentionally hard-coded for V2's tiny
  -- lifecycle. Ceiling: edges live in function code; upgrade path is a
  -- transition table if the lifecycle grows or becomes tenant-configurable.
  IF NOT (
    (v_vendor.approval_status = 'draft' AND v_new_status IN ('pending_approval', 'approved'))
    OR (v_vendor.approval_status = 'pending_approval' AND v_new_status IN ('approved', 'rejected'))
    OR (v_vendor.approval_status = 'approved' AND v_new_status = 'suspended')
    OR (v_vendor.approval_status = 'suspended' AND v_new_status IN ('approved', 'rejected'))
  ) THEN
    RAISE EXCEPTION 'Invalid vendor approval transition from % to %',
      v_vendor.approval_status,
      COALESCE(NULLIF(v_new_status, ''), '<empty>');
  END IF;

  UPDATE public.vendors
     SET approval_status = v_new_status,
         updated_at = now()
   WHERE id = p_vendor_id
   RETURNING * INTO v_vendor;

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_vendor.id,
    'approval_status', v_vendor.approval_status
  );
END;
$$;

-- Source: 20260628000031_find_duplicate_vendors.sql
CREATE OR REPLACE FUNCTION public.find_duplicate_vendors(
  p_organization_id uuid,
  p_name text,
  p_email text DEFAULT NULL,
  p_tax_id_last4 text DEFAULT NULL
)
RETURNS TABLE (
  vendor_id uuid,
  name text,
  approval_status text,
  status text,
  confidence text
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  -- ponytail: exact-match-after-normalize only. Ceiling: spelling variants
  -- like "Sysco" vs "Sysco Foods" are missed; upgrade path is pg_trgm
  -- similarity if duplicate review proves it is worth the index and tuning.
  WITH input AS (
    SELECT
      lower(btrim(COALESCE(p_name, ''))) AS normalized_name,
      lower(btrim(NULLIF(p_email, ''))) AS normalized_email,
      btrim(NULLIF(p_tax_id_last4, '')) AS normalized_tax_last4
  )
  SELECT
    v.id AS vendor_id,
    v.name,
    v.approval_status,
    v.status,
    CASE
      WHEN (
        i.normalized_email IS NOT NULL
        AND lower(btrim(COALESCE(v.email, ''))) = i.normalized_email
      ) OR (
        i.normalized_tax_last4 IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM public.vendor_tax_information vti
          WHERE vti.vendor_id = v.id
            AND vti.deleted_at IS NULL
            AND btrim(COALESCE(vti.tax_id_last4, '')) = i.normalized_tax_last4
        )
      ) THEN 'likely'
      ELSE 'possible'
    END AS confidence
  FROM public.vendors v
  CROSS JOIN input i
  WHERE p_organization_id IS NOT NULL
    AND i.normalized_name <> ''
    AND v.organization_id = p_organization_id
    AND lower(btrim(v.name)) = i.normalized_name
    AND public.reference_scope_visible(v.organization_id, v.brand_id, v.location_id, NULL)
  ORDER BY
    CASE
      WHEN (
        i.normalized_email IS NOT NULL
        AND lower(btrim(COALESCE(v.email, ''))) = i.normalized_email
      ) OR (
        i.normalized_tax_last4 IS NOT NULL
        AND EXISTS (
          SELECT 1
          FROM public.vendor_tax_information vti
          WHERE vti.vendor_id = v.id
            AND vti.deleted_at IS NULL
            AND btrim(COALESCE(vti.tax_id_last4, '')) = i.normalized_tax_last4
        )
      ) THEN 0
      ELSE 1
    END,
    v.name,
    v.id;
$$;

-- Source: 20260628000032_validate_invoice_reconciliation.sql
CREATE OR REPLACE FUNCTION public.validate_invoice(p_invoice_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_line_discrepancies jsonb := '[]'::jsonb;
  v_total_discrepancies jsonb := '[]'::jsonb;
  v_discrepancies jsonb := '[]'::jsonb;
  v_line record;
  v_expected_line_total numeric;
  v_line_sum numeric := 0;
  v_expected_total numeric;
  v_result jsonb;
BEGIN
  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND public.tenant_scope_visible(organization_id, brand_id, location_id, deleted_at);

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice % not found or not visible', p_invoice_id;
  END IF;

  FOR v_line IN
    SELECT id, quantity, unit_price, total_price
    FROM public.invoice_line_items
    WHERE invoice_id = p_invoice_id
  LOOP
    v_expected_line_total := COALESCE(v_line.quantity, 0) * COALESCE(v_line.unit_price, 0);
    v_line_sum := v_line_sum + COALESCE(v_line.total_price, 0);

    -- ponytail: fixed 0.01 epsilon assumes 2-decimal money and is not
    -- currency-aware. Upgrade path: derive epsilon from currency scale.
    IF abs(v_expected_line_total - COALESCE(v_line.total_price, 0)) >= 0.01 THEN
      v_line_discrepancies := v_line_discrepancies || jsonb_build_array(
        jsonb_build_object(
          'line_id', v_line.id,
          'field', 'total_price',
          'expected', v_expected_line_total,
          'got', COALESCE(v_line.total_price, 0)
        )
      );
    END IF;
  END LOOP;

  IF abs(v_line_sum - COALESCE(v_invoice.subtotal, 0)) >= 0.01 THEN
    v_total_discrepancies := v_total_discrepancies || jsonb_build_array(
      jsonb_build_object(
        'field', 'subtotal',
        'expected', v_line_sum,
        'got', COALESCE(v_invoice.subtotal, 0)
      )
    );
  END IF;

  v_expected_total :=
    COALESCE(v_invoice.subtotal, 0)
    + COALESCE(v_invoice.tax_amount, 0)
    + COALESCE(v_invoice.fuel_surcharge, 0)
    + COALESCE(v_invoice.delivery_fee, 0)
    + COALESCE(v_invoice.other_charges, 0);

  IF abs(v_expected_total - COALESCE(v_invoice.total_amount, 0)) >= 0.01 THEN
    v_total_discrepancies := v_total_discrepancies || jsonb_build_array(
      jsonb_build_object(
        'field', 'total_amount',
        'expected', v_expected_total,
        'got', COALESCE(v_invoice.total_amount, 0)
      )
    );
  END IF;

  v_discrepancies := v_line_discrepancies || v_total_discrepancies;

  v_result := jsonb_build_object(
    'line_math', CASE WHEN jsonb_array_length(v_line_discrepancies) = 0 THEN 'pass' ELSE 'fail' END,
    'total_math', CASE WHEN jsonb_array_length(v_total_discrepancies) = 0 THEN 'pass' ELSE 'fail' END,
    'discrepancies', v_discrepancies
  );

  UPDATE public.invoices
     SET validation_results = COALESCE(validation_results, '{}'::jsonb) || v_result,
         updated_at = now()
   WHERE id = p_invoice_id;

  RETURN v_result;
END;
$$;

