CREATE OR REPLACE FUNCTION public.can_access_dashboard_scope(
  p_org_id uuid,
  p_scope text,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND (
        p.role = 'platform_admin'
        OR (
          p.role = 'tenant_super_admin' 
          AND p.tenant_id = (SELECT tenant_id FROM public.organizations WHERE id = p_org_id)
        )
        OR (
          p.organization_id = p_org_id
          AND (
            p.role = 'org_manager'
            OR (p_scope = 'brand' AND p.role IN ('brand_manager', 'branch_manager') AND (p.brand_id IS NULL OR p.brand_id = p_brand_id))
            OR (p_scope IN ('location', 'staff') AND p.role IN ('location_manager', 'ground_staff') AND (p.location_id IS NULL OR p.location_id = p_location_id))
            OR (p_scope IN ('location', 'staff') AND p.role IN ('brand_manager', 'branch_manager') AND (p.brand_id IS NULL OR p.brand_id = p_brand_id))
          )
        )
      )
  );
$$;

CREATE OR REPLACE FUNCTION public.assert_can_approve_invoice_scope(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_role text;
  v_org_id uuid;
  v_tenant_id uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, organization_id, tenant_id
    INTO v_role, v_org_id, v_tenant_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;
  
  IF v_role = 'tenant_super_admin' THEN
    IF v_tenant_id = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Cross-tenant invoice approval denied';
  END IF;

  IF p_organization_id IS NULL OR v_org_id IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization invoice approval denied';
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN;
  END IF;

  IF p_brand_id IS NULL AND p_location_id IS NULL THEN
    RAISE EXCEPTION 'Org-level invoice approval requires org_manager or platform_admin';
  END IF;

  IF v_role = 'branch_manager' THEN
    IF p_brand_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public.get_my_accessible_brand_ids() b(id)
      WHERE b.id = p_brand_id
    ) THEN
      RETURN;
    END IF;

    IF p_location_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public.locations l
      JOIN public.get_my_accessible_brand_ids() b(id) ON b.id = l.brand_id
      WHERE l.id = p_location_id
    ) THEN
      RETURN;
    END IF;
  END IF;

  IF v_role = 'location_manager' THEN
    IF p_location_id IS NOT NULL AND EXISTS (
      SELECT 1
      FROM public.get_my_accessible_location_ids() l(id)
      WHERE l.id = p_location_id
    ) THEN
      RETURN;
    END IF;
  END IF;

  RAISE EXCEPTION 'Invoice approval denied for role % outside accessible scope', v_role;
END;
$$;

CREATE OR REPLACE FUNCTION public.assert_can_approve_vendor_scope(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_role text;
  v_auth_org uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  v_role := public.get_auth_role();
  v_auth_org := public.get_auth_org();

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;
  
  IF v_role = 'tenant_super_admin' THEN
    IF public.get_auth_tenant() = (SELECT tenant_id FROM public.organizations WHERE id = p_organization_id) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Cross-tenant vendor approval denied';
  END IF;

  IF p_organization_id IS NULL OR v_auth_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization vendor approval denied';
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN;
  END IF;

  IF v_role = 'branch_manager'
     AND p_brand_id IS NOT NULL
     AND public.reference_scope_writable(
       p_organization_id,
       p_brand_id,
       NULL,
       NULL,
       'branch_manager'
     ) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'Vendor approval denied for role % outside accessible brand scope', v_role;
END;
$$;

CREATE OR REPLACE FUNCTION public.update_user_approval_limit(
  target_user_id uuid,
  new_limit numeric
) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_actor_id uuid := auth.uid();
  v_actor record;
  v_target record;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF target_user_id IS NULL THEN
    RAISE EXCEPTION 'Target user is required';
  END IF;

  IF new_limit IS NULL OR new_limit < 0 THEN
    RAISE EXCEPTION 'Approval limit must be non-negative';
  END IF;

  IF target_user_id = v_actor_id THEN
    RAISE EXCEPTION 'Users cannot set their own approval limit';
  END IF;

  SELECT id, role, organization_id, tenant_id, brand_id, location_id,
         COALESCE(invoice_approval_limit, 0) AS invoice_approval_limit
    INTO v_actor
  FROM public.profiles
  WHERE id = v_actor_id
    AND deleted_at IS NULL;

  SELECT id, role, organization_id, tenant_id, brand_id, location_id
    INTO v_target
  FROM public.profiles
  WHERE id = target_user_id
    AND deleted_at IS NULL;

  IF v_actor.id IS NULL THEN
    RAISE EXCEPTION 'Actor profile not found';
  END IF;

  IF v_target.id IS NULL THEN
    RAISE EXCEPTION 'Target profile not found';
  END IF;

  IF v_actor.role <> 'platform_admin'
    AND v_actor.role <> 'tenant_super_admin'
    AND v_actor.organization_id IS DISTINCT FROM v_target.organization_id THEN
    RAISE EXCEPTION 'Cannot set approval limit outside your organization';
  END IF;
  
  IF v_actor.role = 'tenant_super_admin'
    AND v_actor.tenant_id IS DISTINCT FROM v_target.tenant_id THEN
    RAISE EXCEPTION 'Cannot set approval limit outside your tenant';
  END IF;

  IF v_actor.role NOT IN ('platform_admin', 'tenant_super_admin')
    AND new_limit > v_actor.invoice_approval_limit THEN
    RAISE EXCEPTION 'Cannot grant approval limit % above your own limit %',
      new_limit, v_actor.invoice_approval_limit;
  END IF;

  IF v_actor.role = 'platform_admin' THEN
    IF v_target.role = 'platform_admin' THEN
      RAISE EXCEPTION 'Platform admins cannot set peer platform admin limits';
    END IF;
  ELSIF v_actor.role = 'tenant_super_admin' THEN
    IF v_target.role = 'tenant_super_admin' THEN
      RAISE EXCEPTION 'Tenant super admins cannot set peer limits';
    END IF;
  ELSIF v_actor.role = 'org_manager' THEN
    IF v_target.role <> 'branch_manager' THEN
      RAISE EXCEPTION 'Org managers may only set branch manager approval limits';
    END IF;
  ELSIF v_actor.role = 'branch_manager' THEN
    IF v_target.role <> 'location_manager' THEN
      RAISE EXCEPTION 'Branch managers may only set location manager approval limits';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.get_my_accessible_brand_ids() b(id)
      WHERE b.id = COALESCE(
        v_target.brand_id,
        (SELECT l.brand_id FROM public.locations l WHERE l.id = v_target.location_id)
      )
    ) THEN
      RAISE EXCEPTION 'Target user is outside your brand scope';
    END IF;
  ELSE
    RAISE EXCEPTION 'Insufficient role to set approval limits';
  END IF;

  UPDATE public.profiles
     SET invoice_approval_limit = new_limit,
         updated_at = now()
   WHERE id = target_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.execute_approval_step(
  p_step_id uuid,
  p_status text,
  p_comments text DEFAULT NULL
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_instance_id uuid;
  v_invoice_id uuid;
  v_pending_count int;
  v_required_role text;
  v_actor_role text;
  v_invoice public.invoices%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_status NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Unsupported approval step status %', p_status;
  END IF;

  SELECT s.instance_id, s.required_role, ai.invoice_id
    INTO v_instance_id, v_required_role, v_invoice_id
  FROM public.approval_steps s
  JOIN public.approval_instances ai ON ai.id = s.instance_id
  WHERE s.id = p_step_id
    AND s.status = 'pending'
  FOR UPDATE OF s;

  IF v_instance_id IS NULL THEN
    RAISE EXCEPTION 'Pending approval step not found';
  END IF;

  SELECT *
    INTO v_invoice
  FROM public.invoices
  WHERE id = v_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_can_approve_invoice_scope(
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id
  );

  v_actor_role := public.get_auth_role();

  IF NOT (
    v_actor_role = v_required_role
    OR v_actor_role IN ('platform_admin', 'tenant_super_admin')
    OR (v_actor_role = 'org_manager'
        AND v_required_role IN ('location_manager', 'branch_manager', 'org_manager', 'org_admin'))
    OR (v_actor_role = 'branch_manager'
        AND v_required_role IN ('location_manager', 'branch_manager'))
  ) THEN
    RAISE EXCEPTION 'Role % cannot act on approval step requiring %',
      v_actor_role, v_required_role;
  END IF;

  UPDATE public.approval_steps
     SET status = p_status::approval_step_status,
         approver_id = auth.uid(),
         comments = p_comments,
         acted_at = now()
   WHERE id = p_step_id;

  IF p_status = 'rejected' THEN
    UPDATE public.approval_instances
       SET status = 'rejected',
           updated_at = now()
     WHERE id = v_instance_id;

    UPDATE public.invoices
       SET status = 'rejected',
           ap_status = 'rejected',
           updated_at = now()
     WHERE id = v_invoice_id;

    RETURN jsonb_build_object('status', 'rejected');
  END IF;

  SELECT count(*)
    INTO v_pending_count
  FROM public.approval_steps
  WHERE instance_id = v_instance_id
    AND status = 'pending';

  IF v_pending_count = 0 THEN
    UPDATE public.approval_instances
       SET status = 'approved',
           updated_at = now()
     WHERE id = v_instance_id;

    UPDATE public.invoices
       SET status = 'approved',
           ap_status = 'approved',
           approved_by = auth.uid(),
           approved_date = now(),
           updated_at = now()
     WHERE id = v_invoice_id;

    -- Sync products now that it is fully approved
    PERFORM public.sync_invoice_products(v_invoice_id);

    RETURN jsonb_build_object('status', 'fully_approved');
  END IF;

  RETURN jsonb_build_object('status', 'partially_approved', 'pending_steps', v_pending_count);
END;
$$;

CREATE OR REPLACE FUNCTION public.notify_expired_owner_invitations()
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_invitation RECORD;
  v_admin RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_invitation IN
    SELECT i.*
    FROM public.invitations i
    WHERE i.role IN ('org_manager', 'tenant_super_admin', 'owner', 'org_owner')
      AND i.accepted_at IS NULL
      AND i.closed_at IS NULL
      AND i.expires_at IS NOT NULL
      AND i.expires_at <= now()
      AND i.expired_notified_at IS NULL
  LOOP
    FOR v_admin IN SELECT id FROM public.profiles WHERE role = 'platform_admin'
    LOOP
      INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read)
      VALUES (
        v_admin.id,
        v_invitation.organization_id,
        'system',
        'Owner onboarding invitation expired',
        'The owner invitation for ' || v_invitation.email || ' expired and needs follow-up or reissue.',
        false
      );
    END LOOP;

    UPDATE public.invitations
    SET expired_notified_at = now()
    WHERE id = v_invitation.id;

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'expired_invitations_notified', v_count);
END;
$$;

CREATE OR REPLACE FUNCTION public.org_remove_member(
  target_user_id uuid,
  target_org_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  caller_role TEXT;
  caller_org  UUID;
BEGIN
  caller_role := public.get_auth_role();
  caller_org  := COALESCE(target_org_id, public.get_auth_org());

  IF caller_role NOT IN ('org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions: only org_manager, tenant_super_admin, or platform_admin can remove users';
  END IF;

  IF target_user_id = auth.uid() THEN
    RAISE EXCEPTION 'You cannot remove yourself. Transfer ownership first.';
  END IF;

  -- Remove from organization_members
  DELETE FROM public.organization_members 
  WHERE user_id = target_user_id AND organization_id = caller_org;
  
  -- Remove from brand_members for this org
  DELETE FROM public.brand_members 
  WHERE user_id = target_user_id 
    AND brand_id IN (SELECT id FROM public.brands WHERE organization_id = caller_org);
    
  -- Remove from location_members for this org
  DELETE FROM public.location_members 
  WHERE user_id = target_user_id 
    AND location_id IN (SELECT id FROM public.locations WHERE organization_id = caller_org);

  -- Update profiles if this was their active org
  UPDATE public.profiles 
  SET organization_id = NULL, brand_id = NULL, location_id = NULL, role = 'ground_staff'
  WHERE id = target_user_id AND organization_id = caller_org;

  -- Update app_metadata if this is their active context
  IF (SELECT raw_app_meta_data->>'organization_id' FROM auth.users WHERE id = target_user_id) = caller_org::text THEN
      UPDATE auth.users
      SET raw_app_meta_data = raw_app_meta_data - 'organization_id' - 'role' - 'brand_id' - 'location_id'
      WHERE id = target_user_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

CREATE OR REPLACE FUNCTION public.complete_onboarding(
  p_user_id uuid,
  p_org_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  caller_org_id uuid;
  org_owner uuid;
  v_current_role text;
BEGIN
  -- Verify caller is the user being updated
  IF auth.uid() != p_user_id THEN
    RAISE EXCEPTION 'Can only complete onboarding for yourself';
  END IF;

  -- Verify the user does NOT already have an org (prevents re-onboarding abuse)
  SELECT organization_id, role INTO caller_org_id, v_current_role FROM public.profiles WHERE id = p_user_id;
  IF caller_org_id IS NOT NULL THEN
    RAISE EXCEPTION 'User already belongs to an organization';
  END IF;

  -- Verify the org exists and the user is the owner
  SELECT owner_id INTO org_owner FROM public.organizations WHERE id = p_org_id;
  IF org_owner IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'Organization does not belong to this user';
  END IF;

  -- Update the profile with org hierarchy and preserve platform_admin
  UPDATE public.profiles SET
    organization_id = p_org_id,
    brand_id = p_brand_id,
    location_id = p_location_id,
    role = CASE WHEN v_current_role = 'platform_admin' THEN 'platform_admin' ELSE 'org_manager' END,
    access_level = CASE WHEN v_current_role = 'platform_admin' THEN 'platform' ELSE 'organization' END,
    updated_at = now()
  WHERE id = p_user_id;

  -- Sync JWT metadata
  UPDATE auth.users SET
    raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb) || jsonb_build_object(
      'role', CASE WHEN v_current_role = 'platform_admin' THEN 'platform_admin' ELSE 'org_manager' END,
      'access_level', CASE WHEN v_current_role = 'platform_admin' THEN 'platform' ELSE 'organization' END,
      'organization_id', p_org_id,
      'brand_id', p_brand_id,
      'location_id', p_location_id
    )
  WHERE id = p_user_id;

  -- Audit log
  INSERT INTO public.audit_logs (organization_id, user_id, action, table_name, record_id, new_data)
  VALUES (p_org_id, p_user_id, 'ONBOARDING_COMPLETE', 'profiles', p_user_id,
          jsonb_build_object('org_id', p_org_id, 'brand_id', p_brand_id, 'location_id', p_location_id));
END;
$$;

-- Source: 20260709000003_invite_business_verification_toggle.sql
CREATE OR REPLACE FUNCTION public.accept_invitation(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite record;
  v_user_id uuid;
  v_user_email text;
  v_role text;
  v_tenant_id uuid;
  v_business_verification_required boolean := true;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND closed_at IS NULL
    AND lower(email) = lower(v_user_email)
    AND (expires_at IS NULL OR expires_at > now());

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  v_role := public.normalize_app_role(v_invite.role);
  v_tenant_id := v_invite.tenant_id;
  v_business_verification_required := COALESCE((v_invite.metadata->>'business_verification_required')::boolean, true);

  IF v_tenant_id IS NULL AND v_invite.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = v_invite.organization_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (name, owner_id, metadata)
    VALUES (
      COALESCE(v_invite.metadata->>'tenant_name', split_part(v_user_email, '@', 1), 'Tenant'),
      v_user_id,
      jsonb_build_object(
        'source', 'accept_invitation',
        'invitation_id', v_invite.id,
        'invited_email', v_invite.email,
        'business_verification_required', v_business_verification_required
      )
    )
    RETURNING id INTO v_tenant_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (v_tenant_id, v_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    UPDATE public.tenants
    SET owner_id = COALESCE(owner_id, v_user_id),
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('business_verification_required', v_business_verification_required),
        updated_at = now()
    WHERE id = v_tenant_id;
  END IF;

  IF v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_invite.organization_id, v_user_id, v_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET tenant_id = COALESCE(v_tenant_id, tenant_id),
      role = v_role,
      organization_id = COALESCE(v_invite.organization_id, organization_id),
      brand_id = COALESCE(v_invite.brand_id, brand_id),
      location_id = COALESCE(v_invite.location_id, location_id),
      business_verification_status = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
        ELSE business_verification_status
      END,
      onboarding_current_step = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
        ELSE onboarding_current_step
      END,
      updated_at = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id,
      role = v_role,
      tenant_id = COALESCE(tenant_id, v_tenant_id),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('business_verification_required', v_business_verification_required)
  WHERE id = v_invite.id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_role,
    'tenant_id', COALESCE(v_tenant_id::text, ''),
    'organization_id', COALESCE(v_invite.organization_id::text, ''),
    'business_verification_required', v_business_verification_required
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'role', v_role,
    'tenant_id', v_tenant_id,
    'organization_id', v_invite.organization_id,
    'business_verification_required', v_business_verification_required
  );
END;
$$;

-- Source: 20260709000004_persist_onboarding_hierarchy_addresses.sql
CREATE OR REPLACE FUNCTION public.insert_onboarding_address(
  p_user_id uuid,
  p_organization_id uuid,
  p_brand_id uuid,
  p_location_id uuid,
  p_address_type text,
  p_location_name text,
  p_address jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_address_id uuid;
  v_zip_code text;
  v_country text;
BEGIN
  IF p_address IS NULL OR COALESCE(jsonb_typeof(p_address), 'null') <> 'object' THEN
    RETURN NULL;
  END IF;

  v_zip_code := COALESCE(
    NULLIF(btrim(p_address->>'postalCode'), ''),
    NULLIF(btrim(p_address->>'zipCode'), ''),
    NULLIF(btrim(p_address->>'zip'), '')
  );

  IF NULLIF(btrim(p_address->>'line1'), '') IS NULL
     OR NULLIF(btrim(p_address->>'city'), '') IS NULL
     OR NULLIF(btrim(p_address->>'state'), '') IS NULL
     OR v_zip_code IS NULL THEN
    RAISE EXCEPTION 'Address is incomplete';
  END IF;

  v_country := COALESCE(NULLIF(btrim(p_address->>'country'), ''), 'US');
  IF lower(v_country) IN ('us', 'usa', 'united states', 'united states of america') THEN
    v_country := 'US';
  END IF;

  INSERT INTO public.organization_addresses (
    user_id,
    organization_id,
    brand_id,
    location_id,
    address_type,
    location_name,
    address_line_1,
    address_line_2,
    city,
    state,
    zip_code,
    country,
    usps_verified,
    usps_standardized,
    usps_validation_code
  )
  VALUES (
    p_user_id,
    p_organization_id,
    p_brand_id,
    p_location_id,
    p_address_type,
    NULLIF(btrim(p_location_name), ''),
    btrim(p_address->>'line1'),
    NULLIF(btrim(p_address->>'line2'), ''),
    btrim(p_address->>'city'),
    btrim(p_address->>'state'),
    v_zip_code,
    v_country,
    false,
    false,
    'ONBOARDING_CAPTURED'
  )
  RETURNING id INTO v_address_id;

  RETURN v_address_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := org_item#>'{metadata,organization_address}';

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NOT NULL AND COALESCE(jsonb_typeof(v_org_address), 'null') = 'object' THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
      );
    END IF;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := brand_item#>'{metadata,brand_address}';

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NOT NULL AND COALESCE(jsonb_typeof(v_mailing_address), 'null') = 'object' THEN
          PERFORM public.insert_onboarding_address(
            p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
          );
        END IF;

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

-- Source: 20260709000007_normalize_invitation_roles_before_constraint.sql
-- Normalize invitation role aliases before CHECK constraints run.
-- This protects onboarding from stale deployed/cached clients that may still send
-- legacy values like owner/org_owner while keeping canonical stored roles.

CREATE OR REPLACE FUNCTION public.normalize_invitation_role_before_check()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
BEGIN
  v_role := lower(trim(COALESCE(NEW.role, '')));
  v_role := replace(replace(v_role, '-', '_'), ' ', '_');

  NEW.role := CASE
    WHEN v_role IN ('tenant', 'tenant_admin', 'tenant_superadmin', 'tenant_super_admin') THEN
      'tenant_super_admin'
    WHEN v_role IN ('owner', 'org_owner', 'organization_owner') AND NEW.organization_id IS NULL THEN
      'tenant_super_admin'
    WHEN v_role IN ('owner', 'org_owner', 'organization_owner', 'org_manager', 'organization_manager') THEN
      'org_manager'
    WHEN v_role IN ('brand_manager') THEN
      'brand_manager'
    WHEN v_role IN ('branch_manager') THEN
      'branch_manager'
    WHEN v_role IN ('manager', 'location_manager') THEN
      'location_manager'
    WHEN v_role IN ('ground_staff', 'staff') THEN
      'ground_staff'
    WHEN v_role IN ('admin', 'platform_admin') THEN
      'platform_admin'
    ELSE
      v_role
  END;

  RETURN NEW;
END;
$$;

-- Source: 20260709000008_invite_coupon_email_lock.sql
-- Invite-generated coupons are bound to the invited email and copied into the
-- tenant super admin profile when the invite is accepted.

CREATE OR REPLACE FUNCTION public.apply_onboarding_coupon(
  p_code TEXT,
  p_plan_id TEXT DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_user_email TEXT;
  v_coupon public.onboarding_coupons%ROWTYPE;
  v_invited_email TEXT;
  v_redemption_id UUID;
  v_trial_ends_at TIMESTAMPTZ;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_coupon
  FROM public.onboarding_coupons
  WHERE lower(code) = lower(btrim(p_code))
    AND active = true
    AND (starts_at IS NULL OR starts_at <= now())
    AND (expires_at IS NULL OR expires_at > now())
  LIMIT 1;

  IF v_coupon.id IS NULL THEN
    RAISE EXCEPTION 'Coupon is invalid or expired';
  END IF;

  v_invited_email := lower(NULLIF(v_coupon.metadata->>'invited_email', ''));
  IF v_invited_email IS NOT NULL AND v_invited_email <> lower(COALESCE(v_user_email, '')) THEN
    RAISE EXCEPTION 'Coupon is assigned to a different invited email';
  END IF;

  IF v_coupon.max_redemptions IS NOT NULL AND v_coupon.redeemed_count >= v_coupon.max_redemptions THEN
    RAISE EXCEPTION 'Coupon has reached its redemption limit';
  END IF;

  IF v_coupon.applies_to_plan_ids IS NOT NULL
     AND p_plan_id IS NOT NULL
     AND NOT (p_plan_id = ANY(v_coupon.applies_to_plan_ids)) THEN
    RAISE EXCEPTION 'Coupon does not apply to the selected plan';
  END IF;

  v_trial_ends_at := CASE
    WHEN v_coupon.discount_type = 'trial_days' AND v_coupon.trial_days > 0
    THEN now() + make_interval(days => v_coupon.trial_days)
    ELSE NULL
  END;

  INSERT INTO public.onboarding_coupon_redemptions (
    coupon_id,
    user_id,
    plan_id,
    discount_snapshot
  )
  VALUES (
    v_coupon.id,
    v_user_id,
    p_plan_id,
    jsonb_build_object(
      'code', v_coupon.code,
      'discount_type', v_coupon.discount_type,
      'discount_value', v_coupon.discount_value,
      'trial_days', v_coupon.trial_days,
      'trial_ends_at', v_trial_ends_at,
      'invited_email', v_invited_email
    )
  )
  ON CONFLICT (coupon_id, user_id) DO UPDATE
  SET plan_id = EXCLUDED.plan_id,
      status = 'applied',
      discount_snapshot = EXCLUDED.discount_snapshot,
      redeemed_at = now()
  RETURNING id INTO v_redemption_id;

  UPDATE public.onboarding_coupons
  SET redeemed_count = (
    SELECT count(*) FROM public.onboarding_coupon_redemptions
    WHERE coupon_id = v_coupon.id AND status IN ('applied', 'consumed')
  )
  WHERE id = v_coupon.id;

  UPDATE public.profiles
  SET coupon_code = v_coupon.code,
      trial_ends_at = COALESCE(v_trial_ends_at, trial_ends_at),
      onboarding_current_step = 'hierarchy_setup',
      updated_at = now()
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'redemption_id', v_redemption_id,
    'coupon', jsonb_build_object(
      'code', v_coupon.code,
      'description', v_coupon.description,
      'discount_type', v_coupon.discount_type,
      'discount_value', v_coupon.discount_value,
      'trial_days', v_coupon.trial_days,
      'trial_ends_at', v_trial_ends_at
    )
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invite record;
  v_user_id uuid;
  v_user_email text;
  v_role text;
  v_tenant_id uuid;
  v_business_verification_required boolean := true;
  v_coupon_code text;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT email INTO v_user_email FROM auth.users WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND closed_at IS NULL
    AND lower(email) = lower(v_user_email)
    AND (expires_at IS NULL OR expires_at > now());

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  v_role := public.normalize_app_role(v_invite.role);
  v_tenant_id := v_invite.tenant_id;
  v_business_verification_required := COALESCE((v_invite.metadata->>'business_verification_required')::boolean, true);
  v_coupon_code := COALESCE(v_invite.metadata->>'coupon_code', v_invite.metadata#>>'{coupon,code}');

  IF v_tenant_id IS NULL AND v_invite.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = v_invite.organization_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (name, owner_id, metadata)
    VALUES (
      COALESCE(v_invite.metadata->>'tenant_name', split_part(v_user_email, '@', 1), 'Tenant'),
      v_user_id,
      jsonb_build_object(
        'source', 'accept_invitation',
        'invitation_id', v_invite.id,
        'invited_email', v_invite.email,
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
    )
    RETURNING id INTO v_tenant_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (v_tenant_id, v_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    UPDATE public.tenants
    SET owner_id = COALESCE(owner_id, v_user_id),
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'business_verification_required', v_business_verification_required,
          'coupon_code', v_coupon_code
        ),
        updated_at = now()
    WHERE id = v_tenant_id;
  END IF;

  IF v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_invite.organization_id, v_user_id, v_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  UPDATE public.profiles
  SET tenant_id = COALESCE(v_tenant_id, tenant_id),
      role = v_role,
      organization_id = COALESCE(v_invite.organization_id, organization_id),
      brand_id = COALESCE(v_invite.brand_id, brand_id),
      location_id = COALESCE(v_invite.location_id, location_id),
      coupon_code = COALESCE(v_coupon_code, coupon_code),
      business_verification_status = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
        ELSE business_verification_status
      END,
      onboarding_current_step = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
        ELSE onboarding_current_step
      END,
      updated_at = now()
  WHERE id = v_user_id;

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id,
      role = v_role,
      tenant_id = COALESCE(tenant_id, v_tenant_id),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
  WHERE id = v_invite.id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', v_role,
    'tenant_id', COALESCE(v_tenant_id::text, ''),
    'organization_id', COALESCE(v_invite.organization_id::text, ''),
    'business_verification_required', v_business_verification_required,
    'coupon_code', COALESCE(v_coupon_code, '')
  )
  WHERE id = v_user_id;

  RETURN jsonb_build_object(
    'success', true,
    'role', v_role,
    'tenant_id', v_tenant_id,
    'organization_id', v_invite.organization_id,
    'business_verification_required', v_business_verification_required,
    'coupon_code', v_coupon_code
  );
END;
$$;

-- Source: 20260710000002_fix_onboarding_contact_otp_hashing.sql
-- Fix onboarding contact OTP hashing for environments where gen_salt/crypt are
-- not available on the function search path. Uses a per-OTP UUID salt with md5
-- for the current development echo OTP flow.

CREATE OR REPLACE FUNCTION public.request_onboarding_contact_otp(
  p_channel TEXT,
  p_target TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_channel TEXT := lower(btrim(COALESCE(p_channel, '')));
  v_target TEXT;
  v_code TEXT;
  v_otp_id UUID := gen_random_uuid();
  v_recent_count INTEGER;
  v_run_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF v_channel NOT IN ('email', 'phone') THEN
    RAISE EXCEPTION 'OTP channel must be email or phone';
  END IF;

  v_target := public.normalize_contact_target(v_channel, p_target);

  IF v_channel = 'email' AND (v_target IS NULL OR position('@' in v_target) = 0) THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  IF v_channel = 'phone' AND length(regexp_replace(v_target, '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid phone number is required';
  END IF;

  SELECT count(*) INTO v_recent_count
  FROM public.onboarding_contact_otps
  WHERE user_id = v_user_id
    AND channel = v_channel
    AND created_at > now() - interval '15 minutes';

  IF v_recent_count >= 5 THEN
    RAISE EXCEPTION 'Too many OTP requests. Please wait before requesting another code';
  END IF;

  v_code := lpad(floor(random() * 1000000)::text, 6, '0');

  INSERT INTO public.onboarding_contact_otps (
    id,
    user_id,
    channel,
    target,
    code_hash,
    provider,
    metadata
  )
  VALUES (
    v_otp_id,
    v_user_id,
    v_channel,
    v_target,
    md5(v_code || ':' || v_otp_id::text),
    CASE WHEN v_channel = 'email' THEN 'email_provider_ready' ELSE 'sms_provider_ready' END,
    jsonb_build_object('delivery_mode', 'development_echo_until_provider_configured', 'hash_version', 'md5_uuid_salt')
  );

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    CASE WHEN v_channel = 'email' THEN 'business_email_otp' ELSE 'business_phone_otp' END,
    'started',
    'pending',
    jsonb_build_object('otp_id', v_otp_id, 'target', v_target)
  );

  RETURN jsonb_build_object(
    'success', true,
    'otp_id', v_otp_id,
    'channel', v_channel,
    'target', v_target,
    'expires_at', now() + interval '10 minutes',
    'delivery_mode', 'development_echo_until_provider_configured',
    'dev_code', v_code
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.verify_onboarding_contact_otp(
  p_otp_id UUID,
  p_code TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_otp public.onboarding_contact_otps%ROWTYPE;
  v_run_id UUID;
  v_code TEXT := btrim(COALESCE(p_code, ''));
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_otp
  FROM public.onboarding_contact_otps
  WHERE id = p_otp_id
    AND user_id = v_user_id
  FOR UPDATE;

  IF v_otp.id IS NULL THEN
    RAISE EXCEPTION 'OTP request not found';
  END IF;

  IF v_otp.status = 'verified' THEN
    RETURN jsonb_build_object('success', true, 'channel', v_otp.channel, 'target', v_otp.target, 'already_verified', true);
  END IF;

  IF v_otp.status <> 'pending' THEN
    RAISE EXCEPTION 'OTP request is no longer active';
  END IF;

  IF v_otp.expires_at < now() THEN
    UPDATE public.onboarding_contact_otps
    SET status = 'expired', updated_at = now()
    WHERE id = v_otp.id;
    RAISE EXCEPTION 'OTP code expired';
  END IF;

  IF v_otp.attempts >= v_otp.max_attempts THEN
    UPDATE public.onboarding_contact_otps
    SET status = 'failed', updated_at = now()
    WHERE id = v_otp.id;
    RAISE EXCEPTION 'Too many incorrect OTP attempts';
  END IF;

  IF v_otp.code_hash <> md5(v_code || ':' || v_otp.id::text) THEN
    UPDATE public.onboarding_contact_otps
    SET attempts = attempts + 1,
        status = CASE WHEN attempts + 1 >= max_attempts THEN 'failed' ELSE status END,
        updated_at = now()
    WHERE id = v_otp.id;
    RAISE EXCEPTION 'Invalid OTP code';
  END IF;

  UPDATE public.onboarding_contact_otps
  SET status = 'verified',
      verified_at = now(),
      updated_at = now()
  WHERE id = v_otp.id;

  IF v_otp.channel = 'email' THEN
    UPDATE public.profiles
    SET business_email = v_otp.target,
        business_email_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  ELSE
    UPDATE public.profiles
    SET business_phone = v_otp.target,
        business_phone_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    CASE WHEN v_otp.channel = 'email' THEN 'business_email_otp' ELSE 'business_phone_otp' END,
    'verified',
    'verified',
    jsonb_build_object('otp_id', v_otp.id, 'target', v_otp.target)
  );

  RETURN jsonb_build_object(
    'success', true,
    'channel', v_otp.channel,
    'target', v_otp.target,
    'verified_at', now()
  );
END;
$$;

-- Source: 20260710000003_remove_onboarding_otp_dev_echo.sql
-- Remove browser-visible onboarding OTP development echo.
-- OTP codes must be delivered by a secure server-side email/SMS provider, not
-- returned to the client. Until that provider is configured, fail closed.

CREATE OR REPLACE FUNCTION public.request_onboarding_contact_otp(
  p_channel TEXT,
  p_target TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_channel TEXT := lower(btrim(COALESCE(p_channel, '')));
  v_target TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF v_channel NOT IN ('email', 'phone') THEN
    RAISE EXCEPTION 'OTP channel must be email or phone';
  END IF;

  v_target := public.normalize_contact_target(v_channel, p_target);

  IF v_channel = 'email' AND (v_target IS NULL OR position('@' in v_target) = 0) THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  IF v_channel = 'phone' AND length(regexp_replace(v_target, '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid phone number is required';
  END IF;

  RAISE EXCEPTION 'Secure OTP delivery provider is not configured yet. Configure server-side email/SMS delivery before enabling onboarding contact OTP.';
END;
$$;

-- Source: 20260710000004_supabase_auth_onboarding_contact_verification.sql
-- Mark onboarding contact verification after Supabase Auth OTP succeeds.
-- OTP delivery and token verification are handled by Supabase Auth; this RPC only
-- persists the verified contact on the onboarding profile for workflow gates.

CREATE OR REPLACE FUNCTION public.mark_onboarding_contact_verified(
  p_channel TEXT,
  p_target TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_channel TEXT := lower(btrim(COALESCE(p_channel, '')));
  v_target TEXT;
  v_run_id UUID;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF v_channel NOT IN ('email', 'phone') THEN
    RAISE EXCEPTION 'OTP channel must be email or phone';
  END IF;

  v_target := public.normalize_contact_target(v_channel, p_target);

  IF v_channel = 'email' AND (v_target IS NULL OR position('@' in v_target) = 0) THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  IF v_channel = 'phone' AND length(regexp_replace(v_target, '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid phone number is required';
  END IF;

  IF v_channel = 'email' THEN
    UPDATE public.profiles
    SET business_email = v_target,
        business_email_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  ELSE
    UPDATE public.profiles
    SET business_phone = v_target,
        business_phone_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    CASE WHEN v_channel = 'email' THEN 'business_email_otp' ELSE 'business_phone_otp' END,
    'verified',
    'verified',
    jsonb_build_object('target', v_target, 'provider', 'supabase_auth')
  );

  RETURN jsonb_build_object(
    'success', true,
    'channel', v_channel,
    'target', v_target,
    'verified_at', now(),
    'provider', 'supabase_auth'
  );
END;
$$;

-- Source: 20260710000005_temporary_dev_onboarding_contact_otp.sql
-- Temporary onboarding contact OTP bypass for development/testing only.
-- Remove this migration/function override after Supabase email templates and Twilio SMS are fully configured.

CREATE OR REPLACE FUNCTION public.request_onboarding_contact_dev_otp(
  p_channel TEXT,
  p_target TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_channel TEXT := lower(btrim(COALESCE(p_channel, '')));
  v_target TEXT;
  v_expires_at TIMESTAMPTZ := TIMESTAMPTZ '2026-07-25 00:00:00+00';
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF now() >= v_expires_at THEN
    RAISE EXCEPTION 'Temporary development OTP bypass has expired';
  END IF;

  IF v_channel NOT IN ('email', 'phone') THEN
    RAISE EXCEPTION 'OTP channel must be email or phone';
  END IF;

  v_target := public.normalize_contact_target(v_channel, p_target);

  IF v_channel = 'email' AND (v_target IS NULL OR position('@' in v_target) = 0) THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  IF v_channel = 'phone' AND length(regexp_replace(v_target, '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid phone number is required';
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'otp_id', 'dev_contact_' || v_channel,
    'channel', v_channel,
    'target', v_target,
    'provider', 'temporary_dev_bypass',
    'expires_at', v_expires_at
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.verify_onboarding_contact_dev_otp(
  p_channel TEXT,
  p_target TEXT,
  p_code TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_channel TEXT := lower(btrim(COALESCE(p_channel, '')));
  v_target TEXT;
  v_code TEXT := btrim(COALESCE(p_code, ''));
  v_expected_code TEXT;
  v_run_id UUID;
  v_expires_at TIMESTAMPTZ := TIMESTAMPTZ '2026-07-25 00:00:00+00';
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF now() >= v_expires_at THEN
    RAISE EXCEPTION 'Temporary development OTP bypass has expired';
  END IF;

  IF v_channel NOT IN ('email', 'phone') THEN
    RAISE EXCEPTION 'OTP channel must be email or phone';
  END IF;

  v_expected_code := CASE v_channel
    WHEN 'email' THEN '724913'
    WHEN 'phone' THEN '381602'
  END;

  IF v_code IS DISTINCT FROM v_expected_code THEN
    RAISE EXCEPTION 'Invalid OTP code';
  END IF;

  v_target := public.normalize_contact_target(v_channel, p_target);

  IF v_channel = 'email' AND (v_target IS NULL OR position('@' in v_target) = 0) THEN
    RAISE EXCEPTION 'A valid email address is required';
  END IF;

  IF v_channel = 'phone' AND length(regexp_replace(v_target, '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid phone number is required';
  END IF;

  IF v_channel = 'email' THEN
    UPDATE public.profiles
    SET business_email = v_target,
        business_email_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  ELSE
    UPDATE public.profiles
    SET business_phone = v_target,
        business_phone_verified_at = now(),
        updated_at = now()
    WHERE id = v_user_id;
  END IF;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    CASE WHEN v_channel = 'email' THEN 'business_email_otp' ELSE 'business_phone_otp' END,
    'verified',
    'verified',
    jsonb_build_object(
      'target', v_target,
      'provider', 'temporary_dev_bypass',
      'expires_at', v_expires_at
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'channel', v_channel,
    'target', v_target,
    'verified_at', now(),
    'provider', 'temporary_dev_bypass',
    'expires_at', v_expires_at
  );
END;
$$;

-- Source: 20260710000006_business_verification_tenant_addresses_only.sql
-- Business verification should not collect or require hierarchy/location service addresses.
-- Location business/service and mailing addresses are collected later in the hierarchy step.
CREATE OR REPLACE FUNCTION public.submit_business_verification(p_payload JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_legal_name TEXT;
  v_business_type TEXT;
  v_identifier_type TEXT;
  v_identifier_required BOOLEAN;
  v_identifier_last4 TEXT;
  v_email TEXT;
  v_phone TEXT;
  v_website TEXT;
  v_provider TEXT;
  v_score INTEGER := 0;
  v_status TEXT;
  v_business_address JSONB;
  v_mailing_address JSONB;
  v_same_mailing BOOLEAN;
  v_verification_id UUID;
  v_settings RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT ein_verification_enabled, ssn_verification_enabled
  INTO v_settings
  FROM public.platform_onboarding_settings
  WHERE id = true;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  v_legal_name := NULLIF(btrim(p_payload->>'legalName'), '');
  v_business_type := COALESCE(NULLIF(btrim(p_payload->>'businessType'), ''), 'llc');
  v_identifier_type := COALESCE(NULLIF(btrim(p_payload->>'identifierType'), ''), public.required_tax_identifier_type_for_business_type(v_business_type));
  v_identifier_required := CASE
    WHEN v_identifier_type = 'ein' THEN COALESCE(v_settings.ein_verification_enabled, true)
    WHEN v_identifier_type = 'ssn' THEN COALESCE(v_settings.ssn_verification_enabled, true)
    ELSE true
  END;
  v_identifier_last4 := CASE WHEN v_identifier_required THEN public.mask_tax_identifier(p_payload->>'taxIdentifier') ELSE NULL END;
  v_email := NULLIF(btrim(p_payload->>'email'), '');
  v_phone := NULLIF(btrim(p_payload->>'phone'), '');
  v_website := NULLIF(btrim(p_payload->>'website'), '');
  v_business_address := COALESCE(p_payload->'businessAddress', '{}'::jsonb);
  v_same_mailing := COALESCE((p_payload->>'sameMailing')::boolean, true);
  v_mailing_address := CASE
    WHEN v_same_mailing THEN v_business_address
    ELSE COALESCE(p_payload->'mailingAddress', '{}'::jsonb)
  END;

  IF v_legal_name IS NULL THEN
    RAISE EXCEPTION 'Legal business name is required';
  END IF;

  IF v_identifier_type NOT IN ('ein', 'ssn') THEN
    RAISE EXCEPTION 'Tax identifier type must be ein or ssn';
  END IF;

  IF v_identifier_type IS DISTINCT FROM public.required_tax_identifier_type_for_business_type(v_business_type) THEN
    RAISE EXCEPTION 'Tax identifier type % is not allowed for business type %', v_identifier_type, v_business_type;
  END IF;

  IF v_identifier_required AND length(COALESCE(v_identifier_last4, '')) <> 4 THEN
    RAISE EXCEPTION 'Valid tax identifier is required';
  END IF;

  IF v_email IS NULL OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'A valid business email is required';
  END IF;

  IF length(regexp_replace(COALESCE(v_phone, ''), '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid business phone number is required';
  END IF;

  IF NULLIF(btrim(v_business_address->>'line1'), '') IS NULL
     OR NULLIF(btrim(v_business_address->>'city'), '') IS NULL
     OR NULLIF(btrim(v_business_address->>'state'), '') IS NULL
     OR length(regexp_replace(COALESCE(v_business_address->>'zip', ''), '\D', '', 'g')) < 5 THEN
    RAISE EXCEPTION 'Business address must include street, city, state, and ZIP';
  END IF;


  v_score := CASE
    WHEN NOT v_identifier_required THEN 60
    WHEN v_identifier_type = 'ein' THEN 50
    ELSE 45
  END;
  IF v_email LIKE '%@%' THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(v_phone, '\D', '', 'g')) >= 10 THEN v_score := v_score + 10; END IF;
  IF v_website IS NOT NULL THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(COALESCE(v_business_address->>'zip', ''), '\D', '', 'g')) >= 5 THEN v_score := v_score + 10; END IF;
  v_score := LEAST(v_score, 100);
  v_status := CASE WHEN v_score >= 80 THEN 'verified' WHEN v_score >= 50 THEN 'pending_review' ELSE 'failed' END;
  v_provider := CASE
    WHEN NOT v_identifier_required THEN v_identifier_type || '_verification_disabled_by_platform'
    WHEN v_identifier_type = 'ein' THEN 'global_database_kyb'
    ELSE 'searchbug_ssn'
  END;

  INSERT INTO public.business_verifications (
    user_id,
    legal_business_name,
    business_type,
    identifier_type,
    identifier_last4,
    provider_name,
    provider_reference_id,
    verification_status,
    trust_score,
    metadata
  )
  VALUES (
    v_user_id,
    v_legal_name,
    v_business_type,
    v_identifier_type,
    v_identifier_last4,
    v_provider,
    CASE WHEN v_identifier_required THEN 'provider-ready-' || replace(gen_random_uuid()::text, '-', '') ELSE 'verification-disabled' END,
    v_status,
    v_score,
    jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'website', v_website,
      'tax_identifier_required', v_identifier_required,
      'ein_verification_enabled', COALESCE(v_settings.ein_verification_enabled, true),
      'ssn_verification_enabled', COALESCE(v_settings.ssn_verification_enabled, true),
      'provider_mode', CASE WHEN v_identifier_required THEN 'simulation_until_provider_keys_configured' ELSE 'disabled_by_platform_admin' END
    )
  )
  RETURNING id INTO v_verification_id;

  DELETE FROM public.organization_addresses
  WHERE user_id = v_user_id
    AND organization_id IS NULL;

  INSERT INTO public.organization_addresses (
    user_id,
    address_type,
    location_name,
    address_line_1,
    address_line_2,
    city,
    state,
    zip_code,
    country,
    usps_verified,
    usps_standardized,
    usps_validation_code
  )
  VALUES
    (v_user_id, 'business', NULL, btrim(v_business_address->>'line1'), NULLIF(btrim(v_business_address->>'line2'), ''), btrim(v_business_address->>'city'), btrim(v_business_address->>'state'), btrim(v_business_address->>'zip'), 'US', true, true, 'PROVIDER_READY_USPS'),
    (v_user_id, 'mailing', NULL, btrim(v_mailing_address->>'line1'), NULLIF(btrim(v_mailing_address->>'line2'), ''), btrim(v_mailing_address->>'city'), btrim(v_mailing_address->>'state'), btrim(v_mailing_address->>'zip'), 'US', true, true, CASE WHEN v_same_mailing THEN 'SAME_AS_BUSINESS' ELSE 'PROVIDER_READY_USPS' END);

  UPDATE public.profiles
  SET business_verification_status = v_status,
      business_verification_score = v_score,
      business_verification_provider = v_provider,
      business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
      business_type = v_business_type,
      tax_identifier_type = v_identifier_type,
      tax_identifier_last4 = v_identifier_last4,
      onboarding_draft = '{}'::jsonb,
      onboarding_status = CASE WHEN v_status = 'pending_review' THEN 'pending_review' ELSE 'in_progress' END,
      onboarding_current_step = CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'business_verification' END,
      updated_at = now()
  WHERE id = v_user_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'business_verification',
    CASE WHEN v_status = 'verified' THEN 'verified' WHEN v_status = 'failed' THEN 'failed' ELSE 'submitted' END,
    v_status,
    jsonb_build_object('verification_id', v_verification_id, 'trust_score', v_score, 'tax_identifier_required', v_identifier_required)
  );

  RETURN jsonb_build_object(
    'success', true,
    'verification_id', v_verification_id,
    'status', v_status,
    'trust_score', v_score,
    'tax_identifier_required', v_identifier_required,
    'next_step', CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'manual_review' END
  );
END;
$$;

-- Source: 20260710000007_hierarchy_required_org_location_addresses.sql
-- Align hierarchy onboarding with organization/location address capture.
-- Business identity remains identity-only; addresses are captured with the hierarchy.

CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}');
    v_mailing_address := CASE
      WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
      ELSE org_item#>'{metadata,organization_mailing_address}'
    END;

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NULL OR COALESCE(jsonb_typeof(v_org_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % requires a business/service address', v_org_name;
    END IF;

    IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % requires a mailing address', v_org_name;
    END IF;

    PERFORM public.insert_onboarding_address(
      p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
    );

    PERFORM public.insert_onboarding_address(
      p_user_id, v_org_id, NULL, NULL, 'mailing', v_org_name, v_mailing_address
    );

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := brand_item#>'{metadata,brand_address}';

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a mailing address', v_brand_name;
        END IF;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
        );

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

-- Source: 20260710000008_business_verification_without_addresses.sql
-- Business verification should not collect or require hierarchy addresses.
-- Organization/location business and mailing addresses are collected later in the hierarchy step.
CREATE OR REPLACE FUNCTION public.submit_business_verification(p_payload JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_run_id UUID;
  v_legal_name TEXT;
  v_business_type TEXT;
  v_identifier_type TEXT;
  v_identifier_required BOOLEAN;
  v_identifier_last4 TEXT;
  v_email TEXT;
  v_phone TEXT;
  v_website TEXT;
  v_provider TEXT;
  v_score INTEGER := 0;
  v_status TEXT;
  v_verification_id UUID;
  v_settings RECORD;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT ein_verification_enabled, ssn_verification_enabled
  INTO v_settings
  FROM public.platform_onboarding_settings
  WHERE id = true;

  v_run_id := public.get_or_create_onboarding_run(v_user_id);
  v_legal_name := NULLIF(btrim(p_payload->>'legalName'), '');
  v_business_type := COALESCE(NULLIF(btrim(p_payload->>'businessType'), ''), 'llc');
  v_identifier_type := COALESCE(NULLIF(btrim(p_payload->>'identifierType'), ''), public.required_tax_identifier_type_for_business_type(v_business_type));
  v_identifier_required := CASE
    WHEN v_identifier_type = 'ein' THEN COALESCE(v_settings.ein_verification_enabled, true)
    WHEN v_identifier_type = 'ssn' THEN COALESCE(v_settings.ssn_verification_enabled, true)
    ELSE true
  END;
  v_identifier_last4 := CASE WHEN v_identifier_required THEN public.mask_tax_identifier(p_payload->>'taxIdentifier') ELSE NULL END;
  v_email := NULLIF(btrim(p_payload->>'email'), '');
  v_phone := NULLIF(btrim(p_payload->>'phone'), '');
  v_website := NULLIF(btrim(p_payload->>'website'), '');
  IF v_legal_name IS NULL THEN
    RAISE EXCEPTION 'Legal business name is required';
  END IF;

  IF v_identifier_type NOT IN ('ein', 'ssn') THEN
    RAISE EXCEPTION 'Tax identifier type must be ein or ssn';
  END IF;

  IF v_identifier_type IS DISTINCT FROM public.required_tax_identifier_type_for_business_type(v_business_type) THEN
    RAISE EXCEPTION 'Tax identifier type % is not allowed for business type %', v_identifier_type, v_business_type;
  END IF;

  IF v_identifier_required AND length(COALESCE(v_identifier_last4, '')) <> 4 THEN
    RAISE EXCEPTION 'Valid tax identifier is required';
  END IF;

  IF v_email IS NULL OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'A valid business email is required';
  END IF;

  IF length(regexp_replace(COALESCE(v_phone, ''), '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid business phone number is required';
  END IF;


  v_score := CASE
    WHEN NOT v_identifier_required THEN 60
    WHEN v_identifier_type = 'ein' THEN 50
    ELSE 45
  END;
  IF v_email LIKE '%@%' THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(v_phone, '\D', '', 'g')) >= 10 THEN v_score := v_score + 10; END IF;
  IF v_website IS NOT NULL THEN v_score := v_score + 10; END IF;
  v_score := LEAST(v_score, 100);
  v_status := CASE WHEN v_score >= 80 THEN 'verified' WHEN v_score >= 50 THEN 'pending_review' ELSE 'failed' END;
  v_provider := CASE
    WHEN NOT v_identifier_required THEN v_identifier_type || '_verification_disabled_by_platform'
    WHEN v_identifier_type = 'ein' THEN 'global_database_kyb'
    ELSE 'searchbug_ssn'
  END;

  INSERT INTO public.business_verifications (
    user_id,
    legal_business_name,
    business_type,
    identifier_type,
    identifier_last4,
    provider_name,
    provider_reference_id,
    verification_status,
    trust_score,
    metadata
  )
  VALUES (
    v_user_id,
    v_legal_name,
    v_business_type,
    v_identifier_type,
    v_identifier_last4,
    v_provider,
    CASE WHEN v_identifier_required THEN 'provider-ready-' || replace(gen_random_uuid()::text, '-', '') ELSE 'verification-disabled' END,
    v_status,
    v_score,
    jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'website', v_website,
      'tax_identifier_required', v_identifier_required,
      'ein_verification_enabled', COALESCE(v_settings.ein_verification_enabled, true),
      'ssn_verification_enabled', COALESCE(v_settings.ssn_verification_enabled, true),
      'provider_mode', CASE WHEN v_identifier_required THEN 'simulation_until_provider_keys_configured' ELSE 'disabled_by_platform_admin' END
    )
  )
  RETURNING id INTO v_verification_id;

  UPDATE public.profiles
  SET business_verification_status = v_status,
      business_verification_score = v_score,
      business_verification_provider = v_provider,
      business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
      business_type = v_business_type,
      tax_identifier_type = v_identifier_type,
      tax_identifier_last4 = v_identifier_last4,
      onboarding_draft = '{}'::jsonb,
      onboarding_status = CASE WHEN v_status = 'pending_review' THEN 'pending_review' ELSE 'in_progress' END,
      onboarding_current_step = CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'business_verification' END,
      updated_at = now()
  WHERE id = v_user_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'business_verification',
    CASE WHEN v_status = 'verified' THEN 'verified' WHEN v_status = 'failed' THEN 'failed' ELSE 'submitted' END,
    v_status,
    jsonb_build_object('verification_id', v_verification_id, 'trust_score', v_score, 'tax_identifier_required', v_identifier_required)
  );

  RETURN jsonb_build_object(
    'success', true,
    'verification_id', v_verification_id,
    'status', v_status,
    'trust_score', v_score,
    'tax_identifier_required', v_identifier_required,
    'next_step', CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'manual_review' END
  );
END;
$$;

-- Source: 20260710000012_business_review_notification_metadata.sql
CREATE OR REPLACE FUNCTION public.notify_business_verification_review_state()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_admin RECORD;
  v_title TEXT;
  v_message TEXT;
  v_run_id UUID;
BEGIN
  IF NEW.verification_status NOT IN ('pending_review', 'failed') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND COALESCE(OLD.verification_status, '') = NEW.verification_status THEN
    RETURN NEW;
  END IF;

  v_title := CASE
    WHEN NEW.verification_status = 'failed' THEN 'Business verification failed'
    ELSE 'Business verification pending review'
  END;
  v_message := CASE
    WHEN NEW.verification_status = 'failed' THEN COALESCE(NULLIF(NEW.rejection_reason, ''), 'Your business verification could not be approved. Please review and resubmit.')
    ELSE 'Your business verification is pending platform admin review.'
  END;

  INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read, metadata)
  VALUES (
    NEW.user_id,
    NEW.organization_id,
    'system',
    v_title,
    v_message,
    false,
    jsonb_build_object(
      'review_type', 'business_verification',
      'verification_id', NEW.id,
      'tenant_user_id', NEW.user_id,
      'status', NEW.verification_status
    )
  );

  FOR v_admin IN SELECT id FROM public.profiles WHERE role = 'platform_admin'
  LOOP
    INSERT INTO public.notifications(user_id, organization_id, type, title, message, is_read, metadata)
    VALUES (
      v_admin.id,
      NEW.organization_id,
      'system',
      v_title,
      COALESCE(NEW.legal_business_name, 'Tenant') || ' requires onboarding follow-up: ' || NEW.verification_status,
      false,
      jsonb_build_object(
        'action', 'business_verification_review',
        'review_type', 'business_verification',
        'verification_id', NEW.id,
        'tenant_user_id', NEW.user_id,
        'status', NEW.verification_status,
        'target_path', '/PlatformOrganizations?review=business'
      )
    );
  END LOOP;

  v_run_id := public.get_or_create_onboarding_run(NEW.user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    NEW.user_id,
    'business_verification',
    CASE WHEN NEW.verification_status = 'failed' THEN 'failed_notification_queued' ELSE 'pending_review_notification_queued' END,
    NEW.verification_status,
    jsonb_build_object('verification_id', NEW.id)
  );

  RETURN NEW;
END;
$$;

-- Source: 20260710000013_platform_business_review_queue_rpc.sql
-- Platform admins need a reliable review queue even before tenant hierarchy rows exist.
-- This bypasses table RLS only after verifying the caller is a platform_admin.

CREATE OR REPLACE FUNCTION public.platform_business_verification_reviews()
RETURNS SETOF public.business_verifications
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.role = 'platform_admin'
  ) THEN
    RAISE EXCEPTION 'platform_admin role required'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT bv.*
  FROM public.business_verifications bv
  WHERE bv.verification_status IN ('pending_review', 'failed', 'verified')
  ORDER BY bv.created_at DESC
  LIMIT 200;
END;
$$;

-- Source: 20260710000014_dedupe_business_verifications_per_user.sql
CREATE OR REPLACE FUNCTION public.merge_business_verification_per_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_existing_id UUID;
BEGIN
  SELECT id
  INTO v_existing_id
  FROM public.business_verifications
  WHERE user_id = NEW.user_id
  ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST, id DESC
  LIMIT 1;

  IF v_existing_id IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.business_verifications
  SET organization_id = COALESCE(NEW.organization_id, organization_id),
      legal_business_name = NEW.legal_business_name,
      business_type = NEW.business_type,
      identifier_type = NEW.identifier_type,
      identifier_last4 = NEW.identifier_last4,
      provider_name = NEW.provider_name,
      provider_reference_id = NEW.provider_reference_id,
      verification_status = NEW.verification_status,
      trust_score = NEW.trust_score,
      metadata = COALESCE(NEW.metadata, '{}'::jsonb),
      reviewed_by = NULL,
      reviewed_at = NULL,
      rejection_reason = NULL,
      updated_at = now()
  WHERE id = v_existing_id;

  NEW.id := v_existing_id;
  RETURN NULL;
END;
$$;

-- Source: 20260710000015_idempotent_submit_business_verification_rpc.sql
DROP FUNCTION IF EXISTS public.merge_business_verification_per_user();

CREATE OR REPLACE FUNCTION public.submit_business_verification(p_payload JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
