  END IF;

  IF v_identifier_type IS DISTINCT FROM public.required_tax_identifier_type_for_business_type(v_business_type) THEN
    RAISE EXCEPTION 'Tax identifier type % is not allowed for business type %', v_identifier_type, v_business_type;
  END IF;

  IF v_identifier_required AND length(COALESCE(v_identifier_last4, '')) <> 4 THEN
    RAISE EXCEPTION 'Valid tax identifier is required';
  END IF;

  IF v_email IS NULL OR position('@' in v_email) = 0 THEN
    RAISE EXCEPTION 'A valid business email is required';
  END IF;

  IF length(regexp_replace(COALESCE(v_phone, ''), '\D', '', 'g')) < 10 THEN
    RAISE EXCEPTION 'A valid business phone number is required';
  END IF;

  v_score := CASE
    WHEN NOT v_identifier_required THEN 60
    WHEN v_identifier_type = 'ein' THEN 50
    ELSE 45
  END;
  IF v_email LIKE '%@%' THEN v_score := v_score + 10; END IF;
  IF length(regexp_replace(v_phone, '\D', '', 'g')) >= 10 THEN v_score := v_score + 10; END IF;
  IF v_website IS NOT NULL THEN v_score := v_score + 10; END IF;
  v_score := LEAST(v_score, 100);
  v_status := CASE WHEN v_score >= 80 THEN 'verified' WHEN v_score >= 50 THEN 'pending_review' ELSE 'failed' END;
  v_provider := CASE
    WHEN NOT v_identifier_required THEN v_identifier_type || '_verification_disabled_by_platform'
    WHEN v_identifier_type = 'ein' THEN 'global_database_kyb'
    ELSE 'searchbug_ssn'
  END;

  INSERT INTO public.business_verifications (
    user_id,
    legal_business_name,
    business_type,
    identifier_type,
    identifier_last4,
    provider_name,
    provider_reference_id,
    verification_status,
    trust_score,
    metadata,
    reviewed_by,
    reviewed_at,
    rejection_reason,
    updated_at
  )
  VALUES (
    v_user_id,
    v_legal_name,
    v_business_type,
    v_identifier_type,
    v_identifier_last4,
    v_provider,
    CASE WHEN v_identifier_required THEN 'provider-ready-' || replace(gen_random_uuid()::text, '-', '') ELSE 'verification-disabled' END,
    v_status,
    v_score,
    jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'website', v_website,
      'tax_identifier_required', v_identifier_required,
      'ein_verification_enabled', COALESCE(v_settings.ein_verification_enabled, true),
      'ssn_verification_enabled', COALESCE(v_settings.ssn_verification_enabled, true),
      'provider_mode', CASE WHEN v_identifier_required THEN 'simulation_until_provider_keys_configured' ELSE 'disabled_by_platform_admin' END
    ),
    NULL,
    NULL,
    NULL,
    now()
  )
  ON CONFLICT (user_id) WHERE user_id IS NOT NULL DO UPDATE
  SET legal_business_name = EXCLUDED.legal_business_name,
      business_type = EXCLUDED.business_type,
      identifier_type = EXCLUDED.identifier_type,
      identifier_last4 = EXCLUDED.identifier_last4,
      provider_name = EXCLUDED.provider_name,
      provider_reference_id = EXCLUDED.provider_reference_id,
      verification_status = EXCLUDED.verification_status,
      trust_score = EXCLUDED.trust_score,
      metadata = EXCLUDED.metadata,
      reviewed_by = NULL,
      reviewed_at = NULL,
      rejection_reason = NULL,
      updated_at = now()
  RETURNING id INTO v_verification_id;

  UPDATE public.profiles
  SET business_verification_status = v_status,
      business_verification_score = v_score,
      business_verification_provider = v_provider,
      business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
      business_type = v_business_type,
      tax_identifier_type = v_identifier_type,
      tax_identifier_last4 = v_identifier_last4,
      onboarding_draft = '{}'::jsonb,
      onboarding_status = CASE WHEN v_status = 'pending_review' THEN 'pending_review' ELSE 'in_progress' END,
      onboarding_current_step = CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'business_verification' END,
      updated_at = now()
  WHERE id = v_user_id;

  PERFORM public.record_onboarding_event(
    v_run_id,
    v_user_id,
    'business_verification',
    CASE WHEN v_status = 'verified' THEN 'verified' WHEN v_status = 'failed' THEN 'failed' ELSE 'submitted' END,
    v_status,
    jsonb_build_object('verification_id', v_verification_id, 'trust_score', v_score, 'tax_identifier_required', v_identifier_required)
  );

  RETURN jsonb_build_object(
    'success', true,
    'verification_id', v_verification_id,
    'status', v_status,
    'trust_score', v_score,
    'tax_identifier_required', v_identifier_required,
    'next_step', CASE WHEN v_status = 'verified' THEN 'payment_method' ELSE 'manual_review' END
  );
END;
$$;

-- Source: 20260710000016_fix_approve_business_verification_columns.sql
CREATE OR REPLACE FUNCTION public.approve_business_verification(p_user_id UUID, p_note TEXT DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_run_id UUID;
  v_verification_id UUID;
BEGIN
  IF public.get_auth_role() <> 'platform_admin' THEN
    RAISE EXCEPTION 'Platform admin access required';
  END IF;

  SELECT id
  INTO v_verification_id
  FROM public.business_verifications
  WHERE user_id = p_user_id
  ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST, id DESC
  LIMIT 1;

  IF v_verification_id IS NULL THEN
    RAISE EXCEPTION 'Business verification row not found for user %', p_user_id;
  END IF;

  UPDATE public.business_verifications
  SET verification_status = 'verified',
      reviewed_by = v_actor,
      reviewed_at = now(),
      rejection_reason = NULL,
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object('admin_note', p_note),
      updated_at = now()
  WHERE id = v_verification_id;

  UPDATE public.profiles
  SET business_verification_status = 'verified',
      business_verified_at = now(),
      onboarding_status = 'in_progress',
      onboarding_current_step = 'payment_method',
      updated_at = now()
  WHERE id = p_user_id;

  INSERT INTO public.onboarding_admin_actions(actor_user_id, target_user_id, action, reason)
  VALUES (v_actor, p_user_id, 'approve_business_verification', p_note);

  INSERT INTO public.notifications(user_id, type, title, message, is_read)
  VALUES (p_user_id, 'system', 'Business verification approved', 'Your business verification was approved. You can continue onboarding.', false);

  v_run_id := public.get_or_create_onboarding_run(p_user_id);
  PERFORM public.record_onboarding_event(
    v_run_id,
    p_user_id,
    'business_verification',
    'admin_approved',
    'verified',
    jsonb_build_object('actor_user_id', v_actor, 'verification_id', v_verification_id)
  );

  RETURN jsonb_build_object('success', true, 'status', 'verified', 'next_step', 'payment_method', 'verification_id', v_verification_id);
END;
$$;

-- Source: 20260710000018_optional_org_address_required_location_address.sql
-- Align hierarchy onboarding with organization/location address capture.
-- Business identity remains identity-only; addresses are captured with the hierarchy.

CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}');
    v_mailing_address := CASE
      WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
      ELSE org_item#>'{metadata,organization_mailing_address}'
    END;

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NOT NULL AND COALESCE(jsonb_typeof(v_org_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % business/service address must be an object when provided', v_org_name;
    END IF;

    IF v_org_address IS NOT NULL THEN
      IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
        RAISE EXCEPTION 'Organization % mailing address must be an object when organization address is provided', v_org_name;
      END IF;

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
      );

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'mailing', v_org_name, v_mailing_address
      );
    END IF;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := brand_item#>'{metadata,brand_address}';

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a mailing address', v_brand_name;
        END IF;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
        );

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

-- Source: 20260711000001_allow_trial_coupon_before_hierarchy_creation.sql
CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE
     AND COALESCE(v_pending_payment_metadata->>'provider', '') NOT IN ('trial_coupon', 'free_plan', 'mock_subscription', 'stripe')
     AND NOT EXISTS (
       SELECT 1
       FROM public.onboarding_coupon_redemptions r
       JOIN public.onboarding_coupons c ON c.id = r.coupon_id
       WHERE r.user_id = p_user_id
         AND r.status IN ('applied', 'consumed')
         AND COALESCE(c.trial_days, 0) > 0
     ) THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}');
    v_mailing_address := CASE
      WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
      ELSE org_item#>'{metadata,organization_mailing_address}'
    END;

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NOT NULL AND COALESCE(jsonb_typeof(v_org_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % business/service address must be an object when provided', v_org_name;
    END IF;

    IF v_org_address IS NOT NULL THEN
      IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
        RAISE EXCEPTION 'Organization % mailing address must be an object when organization address is provided', v_org_name;
      END IF;

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
      );

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'mailing', v_org_name, v_mailing_address
      );
    END IF;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := brand_item#>'{metadata,brand_address}';

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a mailing address', v_brand_name;
        END IF;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
        );

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

-- Source: 20260711000002_treat_optional_hierarchy_address_json_null_as_absent.sql
-- Treat optional hierarchy address JSON null values as absent.

CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE
     AND COALESCE(v_pending_payment_metadata->>'provider', '') NOT IN ('trial_coupon', 'free_plan', 'mock_subscription', 'stripe')
     AND NOT EXISTS (
       SELECT 1
       FROM public.onboarding_coupon_redemptions r
       JOIN public.onboarding_coupons c ON c.id = r.coupon_id
       WHERE r.user_id = p_user_id
         AND r.status IN ('applied', 'consumed')
         AND COALESCE(c.trial_days, 0) > 0
     ) THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := NULLIF(COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}'), 'null'::jsonb);
    v_mailing_address := CASE
      WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
      ELSE NULLIF(org_item#>'{metadata,organization_mailing_address}', 'null'::jsonb)
    END;

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NOT NULL AND COALESCE(jsonb_typeof(v_org_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % business/service address must be an object when provided', v_org_name;
    END IF;

    IF v_org_address IS NOT NULL THEN
      IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
        RAISE EXCEPTION 'Organization % mailing address must be an object when organization address is provided', v_org_name;
      END IF;

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
      );

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'mailing', v_org_name, v_mailing_address
      );
    END IF;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := NULLIF(brand_item#>'{metadata,brand_address}', 'null'::jsonb);

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a mailing address', v_brand_name;
        END IF;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
        );

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

-- Source: 20260711000004_vendor_onboarding_flow.sql
CREATE OR REPLACE FUNCTION public.set_vendor_onboarding_event_scope()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
BEGIN
  SELECT * INTO v_vendor
  FROM public.vendors
  WHERE id = NEW.vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor % does not exist', NEW.vendor_id;
  END IF;

  NEW.organization_id := v_vendor.organization_id;
  NEW.brand_id := v_vendor.brand_id;
  NEW.location_id := v_vendor.location_id;
  NEW.created_at := COALESCE(NEW.created_at, now());
  NEW.actor_id := COALESCE(NEW.actor_id, auth.uid());

  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.is_valid_vendor_document_upload_token(p_storage_name text)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.vendor_link_tokens vlt
    WHERE vlt.token = split_part(split_part(p_storage_name, '/', 2), '_', 1)
      AND vlt.link_type = 'tax'
      AND vlt.status = 'pending'
      AND vlt.expires_at > now()
      AND vlt.deleted_at IS NULL
  );
$$;

CREATE OR REPLACE FUNCTION public.vendor_has_required_onboarding_documents(p_vendor_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.vendor_documents vd
    WHERE vd.vendor_id = p_vendor_id
      AND vd.document_type = 'w9'
      AND vd.status = 'on_file'
      AND vd.deleted_at IS NULL
  );
$$;

CREATE OR REPLACE FUNCTION public.issue_vendor_link_token(
  p_vendor_id uuid,
  p_link_type text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_link_type text := lower(btrim(COALESCE(p_link_type, '')));
  v_token public.vendor_link_tokens%ROWTYPE;
BEGIN
  IF v_link_type NOT IN ('tax', 'documents') THEN
    RAISE EXCEPTION 'Invalid vendor link type: %', p_link_type;
  END IF;

  SELECT * INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, NULL, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF COALESCE(v_vendor.onboarding_status, 'invited') NOT IN (
    'otp_verified',
    'pending_tax',
    'tax_submitted',
    'business_verified',
    'verification_failed',
    'documents_on_file',
    'pending_bank',
    'banking_submitted',
    'banking_verified',
    'method_selected',
    'pending_approval',
    'active',
    'completed'
  ) THEN
    RAISE EXCEPTION 'Vendor OTP must be verified before issuing magic links';
  END IF;

  UPDATE public.vendor_link_tokens
     SET status = 'cancelled',
         updated_at = now(),
         updated_by = auth.uid()
   WHERE vendor_id = p_vendor_id
     AND link_type = v_link_type
     AND status = 'pending'
     AND deleted_at IS NULL;

  INSERT INTO public.vendor_link_tokens (vendor_id, link_type)
  VALUES (p_vendor_id, v_link_type)
  RETURNING * INTO v_token;

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, actor_type, metadata
  ) VALUES (
    p_vendor_id,
    v_link_type || '_link_issued',
    'admin',
    jsonb_build_object('token_id', v_token.id)
  );

  RETURN jsonb_build_object(
    'id', v_token.id,
    'vendor_id', v_token.vendor_id,
    'organization_id', v_token.organization_id,
    'brand_id', v_token.brand_id,
    'location_id', v_token.location_id,
    'link_type', v_token.link_type,
    'token', v_token.token,
    'status', v_token.status,
    'expires_at', v_token.expires_at
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.issue_vendor_banking_link(
  p_vendor_id uuid,
  p_intent text DEFAULT 'add'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_token public.vendor_banking_link_tokens%ROWTYPE;
  v_intent text := COALESCE(NULLIF(btrim(p_intent), ''), 'add');
BEGIN
  IF v_intent NOT IN ('add', 'replace') THEN
    RAISE EXCEPTION 'Invalid vendor banking link intent: %', p_intent;
  END IF;

  SELECT * INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, NULL::timestamptz, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF COALESCE(v_vendor.onboarding_status, 'invited') NOT IN (
    'otp_verified',
    'tax_submitted',
    'business_verified',
    'documents_on_file',
    'pending_bank',
    'banking_submitted',
    'banking_verified',
    'method_selected',
    'pending_approval',
    'active',
    'completed'
  ) THEN
    RAISE EXCEPTION 'Vendor OTP must be verified before issuing banking links';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.vendor_tax_information vti
    WHERE vti.vendor_id = p_vendor_id
      AND vti.verification_status = 'verified'
      AND vti.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Business is not verified';
  END IF;

  IF NOT public.vendor_has_required_onboarding_documents(p_vendor_id) THEN
    RAISE EXCEPTION 'Required vendor documents are not on file';
  END IF;

  UPDATE public.vendor_banking_link_tokens
     SET status = 'cancelled',
         updated_at = now(),
         updated_by = auth.uid()
   WHERE vendor_id = p_vendor_id
     AND status = 'pending'
     AND deleted_at IS NULL;

  INSERT INTO public.vendor_banking_link_tokens (vendor_id, intent)
  VALUES (p_vendor_id, v_intent)
  RETURNING * INTO v_token;

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, actor_type, metadata
  ) VALUES (
    p_vendor_id,
    'banking_link_issued',
    'admin',
    jsonb_build_object('token_id', v_token.id, 'intent', v_intent)
  );

  RETURN jsonb_build_object(
    'id', v_token.id,
    'vendor_id', v_token.vendor_id,
    'organization_id', v_token.organization_id,
    'brand_id', v_token.brand_id,
    'location_id', v_token.location_id,
    'token', v_token.token,
    'status', v_token.status,
    'intent', v_token.intent,
    'expires_at', v_token.expires_at
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.submit_vendor_banking_via_link(
  p_token text,
  p_account text,
  p_routing text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_token public.vendor_banking_link_tokens%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_store_result jsonb;
  v_reason text;
BEGIN
  SELECT * INTO v_token
  FROM public.vendor_banking_link_tokens
  WHERE token = btrim(COALESCE(p_token, ''))
    AND status = 'pending'
    AND expires_at > now()
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_token.id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired banking link';
  END IF;

  IF v_token.intent = 'replace' THEN
    v_reason := 'vendor_requested_update';
  ELSIF EXISTS (
    SELECT 1
    FROM public.vendor_banking_details existing
    WHERE existing.vendor_id = v_token.vendor_id
      AND existing.is_default = true
      AND existing.is_active = true
      AND existing.deleted_at IS NULL
  ) THEN
    v_reason := 'admin_correction';
  ELSE
    v_reason := 'onboarding';
  END IF;

  INSERT INTO public.vendor_banking_details (
    vendor_id,
    organization_id,
    brand_id,
    location_id,
    verification_state,
    callback_status,
    is_default,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_token.organization_id,
    v_token.brand_id,
    v_token.location_id,
    'pending',
    'pending',
    false,
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_bank;

  v_store_result := public.store_vendor_banking_secret(v_bank.id, p_account, p_routing);

  INSERT INTO public.vendor_banking_change_requests (
    vendor_id,
    banking_detail_id,
    request_reason,
    requested_by,
    callback_phone_source,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_bank.id,
    v_reason,
    v_token.created_by,
    'on_file_contact',
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_request;

  UPDATE public.vendor_banking_link_tokens
     SET status = 'submitted',
         submitted_at = now(),
         updated_at = now()
   WHERE id = v_token.id;

  UPDATE public.vendors
     SET onboarding_status = 'banking_submitted',
         updated_at = now()
   WHERE id = v_token.vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, from_status, to_status, actor_type, metadata
  ) VALUES (
    v_token.vendor_id,
    'banking_submitted',
    NULL,
    'banking_submitted',
    'vendor',
    jsonb_build_object(
      'banking_row_id', v_bank.id,
      'change_request_id', v_request.id,
      'token_id', v_token.id,
      'intent', v_token.intent
    )
  );

  IF v_token.created_by IS NOT NULL THEN
    INSERT INTO public.notifications (
      user_id,
      organization_id,
      brand_id,
      location_id,
      title,
      message,
      type,
      is_read,
      metadata
    ) VALUES (
      v_token.created_by,
      v_token.organization_id,
      v_token.brand_id,
      v_token.location_id,
      'Vendor banking callback required',
      'A vendor submitted banking details. Call the phone number already on file before paying this account.',
      'system',
      false,
      jsonb_build_object(
        'vendor_id', v_token.vendor_id,
        'banking_row_id', v_bank.id,
        'change_request_id', v_request.id,
        'token_id', v_token.id,
        'intent', v_token.intent
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_token.vendor_id,
    'banking_row_id', v_bank.id,
    'banking_change_request_id', v_request.id,
    'banking_secret_id', v_store_result->>'banking_secret_id',
    'account_last4', v_store_result->>'account_last4',
    'intent', v_token.intent,
    'is_default', v_bank.is_default,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.confirm_vendor_banking_callback(
  p_request_id uuid,
  p_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
BEGIN
  SELECT * INTO v_request
  FROM public.vendor_banking_change_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'Banking change request not found';
  END IF;

  IF NOT public.reference_scope_writable(v_request.organization_id, v_request.brand_id, v_request.location_id, NULL, 'branch_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendor_banking_change_requests
     SET callback_status = 'confirmed',
         confirmed_by = auth.uid(),
         confirmed_at = now(),
         notes = COALESCE(p_notes, notes),
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = p_request_id
   RETURNING * INTO v_request;

  UPDATE public.vendor_banking_details
     SET callback_status = 'confirmed',
         verification_state = 'verified',
         verified_at = COALESCE(verified_at, now()),
         is_default = CASE
           WHEN v_request.request_reason IN ('onboarding', 'vendor_requested_update')
             OR NOT EXISTS (
               SELECT 1
               FROM public.vendor_banking_details existing
               WHERE existing.vendor_id = v_request.vendor_id
                 AND existing.is_default = true
                 AND existing.is_active = true
                 AND existing.deleted_at IS NULL
                 AND existing.id IS DISTINCT FROM v_request.banking_detail_id
             )
           THEN true
           ELSE is_default
         END,
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = v_request.banking_detail_id
   RETURNING * INTO v_bank;

  UPDATE public.vendors
     SET onboarding_status = 'banking_verified',
         updated_at = now()
   WHERE id = v_request.vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, to_status, actor_type, metadata
  ) VALUES (
    v_request.vendor_id,
    'callback_confirmed',
    'banking_verified',
    'admin',
    jsonb_build_object('banking_row_id', v_bank.id, 'change_request_id', v_request.id)
  );

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_request.vendor_id,
    'banking_row_id', v_bank.id,
    'change_request_id', v_request.id,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status,
    'is_default', v_bank.is_default
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.override_vendor_banking_callback(
  p_request_id uuid,
  p_override_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
BEGIN
  IF NULLIF(btrim(COALESCE(p_override_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Override reason is required';
  END IF;

  SELECT * INTO v_request
  FROM public.vendor_banking_change_requests
  WHERE id = p_request_id
  FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'Banking change request not found';
  END IF;

  IF NOT public.reference_scope_writable(v_request.organization_id, v_request.brand_id, v_request.location_id, NULL, 'branch_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendor_banking_change_requests
     SET callback_status = 'skipped_override',
         override_by = auth.uid(),
         override_reason = p_override_reason,
         override_at = now(),
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = p_request_id
   RETURNING * INTO v_request;

  UPDATE public.vendor_banking_details
     SET callback_status = 'confirmed',
         verification_state = 'verified',
         verified_at = COALESCE(verified_at, now()),
         is_default = CASE
           WHEN v_request.request_reason IN ('onboarding', 'vendor_requested_update')
             OR NOT EXISTS (
               SELECT 1
               FROM public.vendor_banking_details existing
               WHERE existing.vendor_id = v_request.vendor_id
                 AND existing.is_default = true
                 AND existing.is_active = true
                 AND existing.deleted_at IS NULL
                 AND existing.id IS DISTINCT FROM v_request.banking_detail_id
             )
           THEN true
           ELSE is_default
         END,
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = v_request.banking_detail_id
   RETURNING * INTO v_bank;

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, to_status, actor_type, metadata
  ) VALUES (
    v_request.vendor_id,
    'callback_override',
    'banking_verified',
    'admin',
    jsonb_build_object(
      'banking_row_id', v_bank.id,
      'change_request_id', v_request.id,
      'override_reason', p_override_reason
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_request.vendor_id,
    'banking_row_id', v_bank.id,
    'change_request_id', v_request.id,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status,
    'is_default', v_bank.is_default
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.review_vendor_tax_information(
  p_tax_row_id uuid,
  p_verification_status text,
  p_verification_method text DEFAULT 'manual_review',
  p_failure_reason text DEFAULT NULL,
  p_review_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tax public.vendor_tax_information%ROWTYPE;
  v_status text := lower(btrim(COALESCE(p_verification_status, '')));
  v_method text := lower(btrim(COALESCE(p_verification_method, 'manual_review')));
BEGIN
  IF v_status NOT IN ('verified', 'failed', 'mismatch') THEN
    RAISE EXCEPTION 'Invalid tax verification status: %', p_verification_status;
  END IF;

  IF v_method NOT IN ('irs_tin_match', 'business_registry_lookup', 'manual_review') THEN
    RAISE EXCEPTION 'Invalid tax verification method: %', p_verification_method;
  END IF;

  SELECT * INTO v_tax
  FROM public.vendor_tax_information
  WHERE id = p_tax_row_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_tax.id IS NULL THEN
    RAISE EXCEPTION 'Vendor tax information not found';
  END IF;

  IF NOT public.reference_scope_writable(v_tax.organization_id, v_tax.brand_id, v_tax.location_id, v_tax.deleted_at, 'branch_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendor_tax_information
     SET verification_status = v_status,
         verification_method = v_method,
         verification_checked_at = now(),
         verification_failure_reason = CASE WHEN v_status = 'verified' THEN NULL ELSE p_failure_reason END,
         w9_status = CASE WHEN v_status = 'verified' THEN 'verified' ELSE 'rejected' END,
         updated_by = auth.uid(),
         updated_at = now()
   WHERE id = p_tax_row_id
   RETURNING * INTO v_tax;

  IF v_tax.w9_document_id IS NOT NULL THEN
    UPDATE public.vendor_documents
       SET status = CASE WHEN v_status = 'verified' THEN 'on_file' ELSE 'rejected' END,
           reviewed_by = auth.uid(),
           reviewed_at = now(),
           review_notes = p_review_notes,
           updated_by = auth.uid(),
           updated_at = now()
     WHERE id = v_tax.w9_document_id;
  END IF;

  UPDATE public.vendors
     SET business_verified_at = CASE WHEN v_status = 'verified' THEN now() ELSE NULL END,
         onboarding_status = CASE WHEN v_status = 'verified' THEN 'business_verified' ELSE 'verification_failed' END,
         updated_at = now()
   WHERE id = v_tax.vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, to_status, actor_type, metadata
  ) VALUES (
    v_tax.vendor_id,
    CASE WHEN v_status = 'verified' THEN 'business_verified' ELSE 'verification_failed' END,
    CASE WHEN v_status = 'verified' THEN 'business_verified' ELSE 'verification_failed' END,
    'admin',
    jsonb_build_object('tax_row_id', v_tax.id, 'verification_method', v_method)
  );

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_tax.vendor_id,
    'tax_row_id', v_tax.id,
    'verification_status', v_tax.verification_status,
    'w9_status', v_tax.w9_status
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_vendor_payment_account(p_vendor_id uuid)
RETURNS TABLE (
  id uuid,
  banking_secret_id uuid,
  account_last4 text,
  is_default boolean
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT vbd.id,
         vbd.banking_secret_id,
         vbd.account_last4,
         vbd.is_default
  FROM public.vendor_banking_details vbd
  WHERE vbd.vendor_id = p_vendor_id
    AND vbd.is_active = true
    AND vbd.verification_state = 'verified'
    AND vbd.callback_status = 'confirmed'
    AND vbd.banking_secret_id IS NOT NULL
    AND vbd.deleted_at IS NULL
  ORDER BY vbd.is_default DESC, vbd.created_at ASC, vbd.id ASC
  LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION public.transition_vendor_approval(
  p_vendor_id uuid,
  p_new_status text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_new_status text;
BEGIN
  v_new_status := lower(btrim(COALESCE(p_new_status, '')));

  SELECT * INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id
  FOR UPDATE;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  PERFORM public.assert_can_approve_vendor_scope(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id);

  IF v_new_status = v_vendor.approval_status THEN
    RAISE EXCEPTION 'Vendor approval_status is already %', v_new_status;
  END IF;

  IF NOT (
    (v_vendor.approval_status = 'draft' AND v_new_status IN ('pending_approval', 'approved'))
    OR (v_vendor.approval_status = 'pending_approval' AND v_new_status IN ('approved', 'rejected'))
    OR (v_vendor.approval_status = 'approved' AND v_new_status = 'suspended')
    OR (v_vendor.approval_status = 'suspended' AND v_new_status IN ('approved', 'rejected'))
  ) THEN
    RAISE EXCEPTION 'Invalid vendor approval transition from % to %',
      v_vendor.approval_status,
      COALESCE(NULLIF(v_new_status, ''), '<empty>');
  END IF;

  IF v_new_status = 'approved' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.vendor_tax_information vti
      WHERE vti.vendor_id = p_vendor_id
        AND vti.verification_status = 'verified'
        AND vti.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Business is not verified';
    END IF;

    IF NOT public.vendor_has_required_onboarding_documents(p_vendor_id) THEN
      RAISE EXCEPTION 'W9 is not on file';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.vendor_banking_details vbd
      WHERE vbd.vendor_id = p_vendor_id
        AND vbd.is_default = true
        AND vbd.is_active = true
        AND vbd.verification_state = 'verified'
        AND vbd.callback_status = 'confirmed'
        AND vbd.banking_secret_id IS NOT NULL
        AND vbd.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Banking is not callback-confirmed';
    END IF;
  END IF;

  UPDATE public.vendors
     SET approval_status = v_new_status,
         onboarding_status = CASE
           WHEN v_new_status = 'approved' THEN 'active'
           WHEN v_new_status = 'pending_approval' THEN 'pending_approval'
           WHEN v_new_status = 'rejected' THEN 'rejected'
           ELSE onboarding_status
         END,
         updated_at = now()
   WHERE id = p_vendor_id
   RETURNING * INTO v_vendor;

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, from_status, to_status, actor_type
  ) VALUES (
    p_vendor_id,
    'approval_transition',
    NULL,
    v_new_status,
    'admin'
  );

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_vendor.id,
    'approval_status', v_vendor.approval_status
  );
END;
$$;

-- Source: 20260713000001_require_stripe_payment_method_for_trial_coupons.sql
-- Require Stripe payment-method collection for trial coupons before hierarchy setup.

CREATE OR REPLACE FUNCTION public.setup_onboarding_hierarchy(
  p_user_id uuid,
  p_hierarchy jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  org_item jsonb;
  brand_item jsonb;
  location_item jsonb;
  v_tenant_id uuid;
  v_org_id uuid;
  v_brand_id uuid;
  v_location_id uuid;
  v_primary_org_id uuid;
  v_primary_brand_id uuid;
  v_primary_location_id uuid;
  v_created_orgs jsonb := '[]'::jsonb;
  v_created_brands jsonb := '[]'::jsonb;
  v_created_locations jsonb := '[]'::jsonb;
  v_org_name text;
  v_org_slug text;
  v_brand_name text;
  v_location_name text;
  v_location_address text;
  v_org_count integer := 0;
  v_brand_count integer := 0;
  v_location_count integer := 0;
  v_business_status text;
  v_payment_verified boolean;
  v_pending_plan_id text;
  v_pending_stripe_customer_id text;
  v_pending_stripe_subscription_id text;
  v_pending_checkout_session_id text;
  v_pending_payment_metadata jsonb;
  v_run_id uuid;
  v_org_address jsonb;
  v_brand_address jsonb;
  v_business_address jsonb;
  v_mailing_address jsonb;
  v_tenant_identity jsonb;
BEGIN
  IF auth.uid() != p_user_id AND public.get_auth_role() != 'platform_admin' THEN
    RAISE EXCEPTION 'Not authorized to onboard another user';
  END IF;

  SELECT business_verification_status, payment_verified, pending_onboarding_plan_id, pending_stripe_customer_id, pending_stripe_subscription_id, pending_checkout_session_id, pending_payment_metadata
  INTO v_business_status, v_payment_verified, v_pending_plan_id, v_pending_stripe_customer_id, v_pending_stripe_subscription_id, v_pending_checkout_session_id, v_pending_payment_metadata
  FROM public.profiles
  WHERE id = p_user_id;

  IF COALESCE(v_business_status, 'not_started') <> 'verified' THEN
    RAISE EXCEPTION 'Business verification must be completed before hierarchy setup';
  END IF;

  IF COALESCE(v_payment_verified, false) IS NOT TRUE
     AND COALESCE(v_pending_payment_metadata->>'provider', '') NOT IN ('free_plan', 'stripe') THEN
    RAISE EXCEPTION 'Payment method verification must be completed before hierarchy setup';
  END IF;

  IF p_hierarchy IS NULL OR COALESCE(jsonb_typeof(p_hierarchy), 'null') <> 'array' THEN
    RAISE EXCEPTION 'Onboarding hierarchy must be an array';
  END IF;

  IF jsonb_array_length(p_hierarchy) = 0 THEN
    RAISE EXCEPTION 'Onboarding hierarchy must include at least one organization';
  END IF;

  v_org_name := NULLIF(btrim((p_hierarchy->0)->>'name'), '');
  v_org_slug := NULLIF(btrim((p_hierarchy->0)->>'slug'), '');

  INSERT INTO public.tenants (name, slug, owner_id, metadata)
  VALUES (
    COALESCE(v_org_name, 'Tenant'),
    left('tenant_' || regexp_replace(lower(COALESCE(v_org_slug, gen_random_uuid()::text)), '[^a-z0-9]+', '_', 'g'), 63),
    p_user_id,
    jsonb_build_object(
      'source', 'setup_onboarding_hierarchy',
      'business_identity', (p_hierarchy->0)#>'{metadata,tenant_business_identity}'
    )
  )
  ON CONFLICT (slug) DO UPDATE
    SET owner_id = EXCLUDED.owner_id,
        metadata = COALESCE(public.tenants.metadata, '{}'::jsonb) || EXCLUDED.metadata
  RETURNING id INTO v_tenant_id;

  BEGIN
    v_run_id := public.get_or_create_onboarding_run(p_user_id);
  EXCEPTION WHEN undefined_function THEN
    v_run_id := NULL;
  END;

  FOR org_item IN SELECT value FROM jsonb_array_elements(p_hierarchy)
  LOOP
    v_org_name := NULLIF(btrim(org_item->>'name'), '');
    v_org_slug := NULLIF(btrim(org_item->>'slug'), '');
    v_org_address := NULLIF(COALESCE(org_item#>'{metadata,organization_business_address}', org_item#>'{metadata,organization_address}'), 'null'::jsonb);
    v_mailing_address := CASE
      WHEN COALESCE((org_item#>>'{metadata,organization_mailing_same_as_business}')::boolean, true) THEN v_org_address
      ELSE NULLIF(org_item#>'{metadata,organization_mailing_address}', 'null'::jsonb)
    END;

    IF v_org_name IS NULL OR v_org_slug IS NULL THEN
      RAISE EXCEPTION 'Each organization requires a name and slug';
    END IF;

    IF COALESCE(jsonb_typeof(org_item->'brands'), 'null') <> 'array'
       OR jsonb_array_length(org_item->'brands') = 0 THEN
      RAISE EXCEPTION 'Organization % requires at least one brand', v_org_name;
    END IF;

    INSERT INTO public.organizations (tenant_id, name, slug, owner_id)
    VALUES (v_tenant_id, v_org_name, v_org_slug, p_user_id)
    RETURNING id INTO v_org_id;

    IF v_org_address IS NOT NULL AND COALESCE(jsonb_typeof(v_org_address), 'null') <> 'object' THEN
      RAISE EXCEPTION 'Organization % business/service address must be an object when provided', v_org_name;
    END IF;

    IF v_org_address IS NOT NULL THEN
      IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
        RAISE EXCEPTION 'Organization % mailing address must be an object when organization address is provided', v_org_name;
      END IF;

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'service', v_org_name, v_org_address
      );

      PERFORM public.insert_onboarding_address(
        p_user_id, v_org_id, NULL, NULL, 'mailing', v_org_name, v_mailing_address
      );
    END IF;

    v_org_count := v_org_count + 1;
    v_created_orgs := v_created_orgs || jsonb_build_array(jsonb_build_object('id', v_org_id, 'name', v_org_name, 'slug', v_org_slug));

    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_org_id, p_user_id, 'tenant_super_admin')
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    IF v_primary_org_id IS NULL THEN
      v_primary_org_id := v_org_id;
    END IF;

    FOR brand_item IN SELECT value FROM jsonb_array_elements(org_item->'brands')
    LOOP
      v_brand_name := NULLIF(btrim(brand_item->>'name'), '');
      v_brand_address := NULLIF(brand_item#>'{metadata,brand_address}', 'null'::jsonb);

      IF v_brand_name IS NULL THEN
        RAISE EXCEPTION 'Every brand in organization % requires a name', v_org_name;
      END IF;

      IF COALESCE(jsonb_typeof(brand_item->'locations'), 'null') <> 'array'
         OR jsonb_array_length(brand_item->'locations') = 0 THEN
        RAISE EXCEPTION 'Brand % requires at least one location', v_brand_name;
      END IF;

      INSERT INTO public.brands (organization_id, name)
      VALUES (v_org_id, v_brand_name)
      RETURNING brand_id INTO v_brand_id;

      IF v_brand_address IS NOT NULL AND COALESCE(jsonb_typeof(v_brand_address), 'null') = 'object' THEN
        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, NULL, 'service', v_brand_name, v_brand_address
        );
      END IF;

      v_brand_count := v_brand_count + 1;
      v_created_brands := v_created_brands || jsonb_build_array(jsonb_build_object('id', v_brand_id, 'organization_id', v_org_id, 'name', v_brand_name));

      INSERT INTO public.brand_members (brand_id, user_id, role)
      VALUES (v_brand_id, p_user_id, 'tenant_super_admin')
      ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;

      IF v_primary_brand_id IS NULL THEN
        v_primary_brand_id := v_brand_id;
      END IF;

      FOR location_item IN SELECT value FROM jsonb_array_elements(brand_item->'locations')
      LOOP
        v_location_name := NULLIF(btrim(location_item->>'name'), '');
        v_location_address := COALESCE(NULLIF(btrim(location_item->>'address'), ''), 'Address pending');
        v_business_address := location_item->'business_address';
        v_mailing_address := location_item->'mailing_address';

        IF v_location_name IS NULL THEN
          RAISE EXCEPTION 'Every location in brand % requires a name', v_brand_name;
        END IF;

        IF v_business_address IS NULL OR COALESCE(jsonb_typeof(v_business_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a business/service address', v_brand_name;
        END IF;

        INSERT INTO public.locations (organization_id, brand_id, name, address)
        VALUES (v_org_id, v_brand_id, v_location_name, v_location_address)
        RETURNING id INTO v_location_id;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'service', v_location_name, v_business_address
        );

        IF v_mailing_address IS NULL OR COALESCE(jsonb_typeof(v_mailing_address), 'null') <> 'object' THEN
          RAISE EXCEPTION 'Every location in brand % requires a mailing address', v_brand_name;
        END IF;

        PERFORM public.insert_onboarding_address(
          p_user_id, v_org_id, v_brand_id, v_location_id, 'mailing', v_location_name, v_mailing_address
        );

        v_location_count := v_location_count + 1;
        v_created_locations := v_created_locations || jsonb_build_array(jsonb_build_object(
          'id', v_location_id,
          'organization_id', v_org_id,
          'brand_id', v_brand_id,
          'name', v_location_name,
          'address', v_location_address
        ));

        INSERT INTO public.location_members (location_id, user_id, role)
        VALUES (v_location_id, p_user_id, 'tenant_super_admin')
        ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;

        IF v_primary_location_id IS NULL THEN
          v_primary_location_id := v_location_id;
        END IF;
      END LOOP;
    END LOOP;

    INSERT INTO public.onboarding_progress (organization_id, current_step, completed_steps, is_completed)
    VALUES (v_org_id, 'hierarchy_created', ARRAY['organizations', 'brands', 'locations'], false)
    ON CONFLICT DO NOTHING;
  END LOOP;

  INSERT INTO public.tenant_members (tenant_id, user_id, role)
  VALUES (v_tenant_id, p_user_id, 'tenant_super_admin')
  ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

  UPDATE public.profiles
  SET tenant_id = v_tenant_id,
      organization_id = v_primary_org_id,
      brand_id = v_primary_brand_id,
      location_id = v_primary_location_id,
      role = 'tenant_super_admin',
      access_level = 'organization',
      onboarding_status = 'completed',
      onboarding_current_step = 'completed',
      onboarding_completed_at = now(),
      updated_at = now()
  WHERE id = p_user_id;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', 'tenant_super_admin',
    'tenant_id', v_tenant_id::text,
    'organization_id', v_primary_org_id::text,
    'brand_id', v_primary_brand_id::text,
    'location_id', v_primary_location_id::text
  )
  WHERE id = p_user_id;

  IF v_primary_org_id IS NOT NULL THEN
    UPDATE public.organizations
    SET plan_id = COALESCE(v_pending_plan_id, plan_id),
        stripe_customer_id = COALESCE(v_pending_stripe_customer_id, stripe_customer_id),
        stripe_subscription_id = COALESCE(v_pending_stripe_subscription_id, stripe_subscription_id)
    WHERE id = v_primary_org_id;
  END IF;

  UPDATE public.business_verifications SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.organization_addresses SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_payment_methods SET organization_id = v_primary_org_id, updated_at = now()
  WHERE user_id = p_user_id AND organization_id IS NULL;
  UPDATE public.onboarding_coupon_redemptions SET organization_id = v_primary_org_id
  WHERE user_id = p_user_id AND organization_id IS NULL;

  v_tenant_identity := (p_hierarchy->0)#>'{metadata,tenant_business_identity}';
  IF v_tenant_identity IS NOT NULL AND COALESCE(jsonb_typeof(v_tenant_identity), 'null') = 'object' THEN
    v_business_address := v_tenant_identity->'businessAddress';
    v_mailing_address := CASE
      WHEN COALESCE((v_tenant_identity->>'mailingSameAsBusiness')::boolean, true) THEN v_business_address
      ELSE v_tenant_identity->'mailingAddress'
    END;

    IF v_business_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'business'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'business', 'Tenant business identity', v_business_address
      );
    END IF;

    IF v_mailing_address IS NOT NULL
       AND NOT EXISTS (
         SELECT 1
         FROM public.organization_addresses
         WHERE user_id = p_user_id
           AND organization_id = v_primary_org_id
           AND brand_id IS NULL
           AND location_id IS NULL
           AND address_type = 'mailing'
       ) THEN
      PERFORM public.insert_onboarding_address(
        p_user_id, v_primary_org_id, NULL, NULL, 'mailing', 'Tenant business identity', v_mailing_address
      );
    END IF;
  END IF;

  IF v_run_id IS NOT NULL THEN
    UPDATE public.onboarding_workflow_runs
    SET organization_id = v_primary_org_id,
        status = 'completed',
        current_step = 'completed',
        completed_at = now(),
        last_activity_at = now()
    WHERE id = v_run_id;

    PERFORM public.record_onboarding_event(
      v_run_id,
      p_user_id,
      'hierarchy_setup',
      'completed',
      'completed',
      jsonb_build_object('tenant_id', v_tenant_id, 'primary_org_id', v_primary_org_id, 'plan_id', v_pending_plan_id, 'checkout_session_id', v_pending_checkout_session_id)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'tenant_id', v_tenant_id,
    'primary_org_id', v_primary_org_id,
    'primary_brand_id', v_primary_brand_id,
    'primary_location_id', v_primary_location_id,
    'organizations', v_created_orgs,
    'brands', v_created_brands,
    'locations', v_created_locations,
    'counts', jsonb_build_object('organizations', v_org_count, 'brands', v_brand_count, 'locations', v_location_count),
    'plan_id', v_pending_plan_id,
    'stripe_customer_id', v_pending_stripe_customer_id,
    'stripe_subscription_id', v_pending_stripe_subscription_id
  );
END;
$$;

-- Source: 20260714000002_recipe_library_release_1.sql
CREATE OR REPLACE FUNCTION public.sync_primary_recipe_yield()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF COALESCE(NEW.yield_quantity, 0) <= 0 OR COALESCE(trim(NEW.yield_unit), '') = '' THEN
    RETURN NEW;
  END IF;

  UPDATE public.recipe_yields SET is_primary = false
  WHERE recipe_id = NEW.id AND lower(unit) <> lower(NEW.yield_unit) AND is_primary;

  INSERT INTO public.recipe_yields (organization_id, recipe_id, quantity, unit, is_primary, cost_per_unit)
  VALUES (NEW.organization_id, NEW.id, NEW.yield_quantity, NEW.yield_unit, true, NEW.cost_per_serving)
  ON CONFLICT (recipe_id, lower(unit)) DO UPDATE SET
    quantity = EXCLUDED.quantity,
    is_primary = true,
    cost_per_unit = EXCLUDED.cost_per_unit,
    updated_at = now();
  RETURN NEW;
END;
$$;

-- Source: 20260715000001_vendor_module_hardening.sql
-- update_vendor_metrics_on_invoice (127_vendor_command_center.sql) only ever added to
-- vendors.total_spent/unpaid_ap when an invoice entered approved/paid. It never reversed
-- either figure when an invoice left those states (rejected/flagged/reverted) or was
-- soft-deleted while approved, so total_spent/unpaid_ap drift permanently out of sync
-- with reality over time.
CREATE OR REPLACE FUNCTION public.update_vendor_metrics_on_invoice()
RETURNS TRIGGER AS $$
BEGIN
  -- Entering approved: add to total spend and outstanding AP.
  IF NEW.status = 'approved' AND (OLD.status IS NULL OR OLD.status != 'approved') THEN
    UPDATE public.vendors
    SET total_spent = total_spent + NEW.total_amount,
        unpaid_ap = unpaid_ap + NEW.total_amount
    WHERE id = NEW.vendor_id;
  END IF;

  -- Leaving approved (rejected/flagged/reverted) while not soft-deleted: back out total spend,
  -- and back out unpaid_ap too if it hadn't already been paid off.
  IF OLD.status = 'approved' AND NEW.status IS DISTINCT FROM 'approved' AND NEW.deleted_at IS NULL THEN
    UPDATE public.vendors
    SET total_spent = GREATEST(total_spent - OLD.total_amount, 0),
        unpaid_ap = CASE WHEN OLD.payment_status IS DISTINCT FROM 'paid'
                          THEN GREATEST(unpaid_ap - OLD.total_amount, 0)
                          ELSE unpaid_ap END
    WHERE id = OLD.vendor_id;
  END IF;

  -- Entering paid: remove from outstanding AP.
  IF NEW.payment_status = 'paid' AND (OLD.payment_status IS NULL OR OLD.payment_status != 'paid') THEN
    UPDATE public.vendors
    SET unpaid_ap = GREATEST(unpaid_ap - NEW.total_amount, 0)
    WHERE id = NEW.vendor_id;
  END IF;

  -- Payment reversed on a still-approved invoice: it's outstanding again.
  IF OLD.payment_status = 'paid' AND NEW.payment_status IS DISTINCT FROM 'paid'
     AND NEW.status = 'approved' AND NEW.deleted_at IS NULL THEN
    UPDATE public.vendors
    SET unpaid_ap = unpaid_ap + NEW.total_amount
    WHERE id = NEW.vendor_id;
  END IF;

  -- Soft-deleting an approved invoice: back out the same as leaving approved.
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL AND OLD.status = 'approved' THEN
    UPDATE public.vendors
    SET total_spent = GREATEST(total_spent - OLD.total_amount, 0),
        unpaid_ap = CASE WHEN OLD.payment_status IS DISTINCT FROM 'paid'
                          THEN GREATEST(unpaid_ap - OLD.total_amount, 0)
                          ELSE unpaid_ap END
    WHERE id = OLD.vendor_id;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 20260715010001_recipe_margin_alert_lifecycle.sql
create or replace function public.sync_recipe_margin_alert_lifecycle()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if tg_op = 'UPDATE' and new.margin_alert_status is distinct from old.margin_alert_status then
    new.margin_alert_enabled := new.margin_alert_status = 'active';
  elsif tg_op = 'UPDATE' and new.margin_alert_enabled is distinct from old.margin_alert_enabled then
    new.margin_alert_status := case when new.margin_alert_enabled then 'active' else 'none' end;
  else
    new.margin_alert_status := coalesce(
      new.margin_alert_status,
      case when coalesce(new.margin_alert_enabled, false) then 'active' else 'none' end
    );
    new.margin_alert_enabled := new.margin_alert_status = 'active';
  end if;
  return new;
end;
$$;

-- Source: 20260715010003_recipe_margin_alert_events.sql
create or replace function public.record_recipe_margin_alert_events()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  old_cost numeric := coalesce(old.cost_per_serving, 0);
  new_cost numeric := coalesce(new.cost_per_serving, 0);
  old_price numeric := coalesce(old.selling_price, 0);
  new_price numeric := coalesce(new.selling_price, 0);
  old_target numeric := 100 - coalesce(old.target_margin_percent, 70);
  new_target numeric := 100 - coalesce(new.target_margin_percent, 70);
  old_plate numeric := case when old_price > 0 then old_cost / old_price * 100 else null end;
  new_plate numeric := case when new_price > 0 then new_cost / new_price * 100 else null end;
  old_alert text := coalesce(old.margin_alert_status, case when coalesce(old.margin_alert_enabled, false) then 'active' else 'none' end);
  new_alert text := coalesce(new.margin_alert_status, case when coalesce(new.margin_alert_enabled, false) then 'active' else 'none' end);
  actor uuid := auth.uid();
begin
  if new_cost is distinct from old_cost then
    insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
    values (new.organization_id, new.id, 'cost_changed', 'Unit cost changed', jsonb_build_object('cost', old_cost), jsonb_build_object('cost', new_cost), new_plate, new_target, actor);
  end if;

  if new_price is distinct from old_price then
    insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
    values (new.organization_id, new.id, 'price_changed', 'Menu price changed', jsonb_build_object('price', old_price), jsonb_build_object('price', new_price), new_plate, new_target, actor);
  end if;

  if new_target is distinct from old_target then
    insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
    values (new.organization_id, new.id, 'target_changed', 'Plate-cost target changed', jsonb_build_object('target_percent', old_target), jsonb_build_object('target_percent', new_target), new_plate, new_target, actor);
  end if;

  if new_alert is distinct from old_alert then
    insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
    values (new.organization_id, new.id, 'monitoring_changed', 'Cost monitoring changed', jsonb_build_object('status', old_alert), jsonb_build_object('status', new_alert), new_plate, new_target, actor);
  end if;

  if new_alert = 'active' and new_plate is not null then
    if (old_alert <> 'active' or old_plate is null or old_plate <= old_target) and new_plate > new_target then
      insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
      values (new.organization_id, new.id, 'threshold_exceeded', 'Plate cost exceeded its configured target', jsonb_build_object('plate_cost_percent', old_plate, 'target_percent', old_target), jsonb_build_object('plate_cost_percent', new_plate, 'target_percent', new_target), new_plate, new_target, actor);
    elsif old_alert = 'active' and old_plate > old_target and new_plate <= new_target then
      insert into public.recipe_margin_alert_events (organization_id, recipe_id, event_type, message, previous_value, current_value, plate_cost_percent, target_plate_cost_percent, actor_user_id)
      values (new.organization_id, new.id, 'threshold_recovered', 'Plate cost returned within its configured target', jsonb_build_object('plate_cost_percent', old_plate, 'target_percent', old_target), jsonb_build_object('plate_cost_percent', new_plate, 'target_percent', new_target), new_plate, new_target, actor);
    end if;
  end if;

  return new;
end;
$$;

-- Source: 20260715010004_menu_item_authoring_phase1.sql
create or replace function public.sync_recipe_ingredients_from_jsonb()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  ing record;
  v_product_id uuid;
  v_sub_recipe_id uuid;
begin
  delete from public.recipe_ingredients where recipe_id = new.id;
  if new.ingredients is not null and jsonb_typeof(new.ingredients) = 'array' then
    for ing in select value, ordinality from jsonb_array_elements(new.ingredients) with ordinality
    loop
      v_product_id := nullif(ing.value->>'product_id', '')::uuid;
      v_sub_recipe_id := nullif(ing.value->>'sub_recipe_id', '')::uuid;
      if v_product_id is not null or v_sub_recipe_id is not null then
        insert into public.recipe_ingredients (
          organization_id, recipe_id, product_id, sub_recipe_id, quantity, unit,
          yield_percentage, cost_unit, unit_cost_snapshot, notes, sort_order
        ) values (
          new.organization_id, new.id, v_product_id, v_sub_recipe_id,
          coalesce(nullif(ing.value->>'quantity', '')::numeric, 0), ing.value->>'unit',
          coalesce(nullif(ing.value->>'yield_percentage', '')::numeric, 100),
          ing.value->>'cost_unit', coalesce(nullif(ing.value->>'unit_cost', '')::numeric, 0),
          nullif(ing.value->>'notes', ''), ing.ordinality - 1
        );
      end if;
    end loop;
  end if;
  return new;
end;
$$;

create or replace function public.save_menu_item_phase1(
  p_recipe jsonb,
  p_yields jsonb,
  p_visibility jsonb,
  p_equipment_names jsonb,
  p_steps jsonb,
  p_location_prices jsonb
)
returns public.recipes
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_org uuid := nullif(p_recipe->>'organization_id', '')::uuid;
  v_recipe public.recipes;
  v_row jsonb;
  v_equipment_id uuid;
begin
  if auth.uid() is null or v_org is null or v_org <> public.get_my_org() or not public.is_manager_or_above() then
    raise exception 'Not authorized to save menu items';
  end if;
  if coalesce(trim(p_recipe->>'name'), '') = '' then raise exception 'Name is required'; end if;
  if jsonb_typeof(p_yields) <> 'array' or jsonb_array_length(p_yields) = 0 then raise exception 'At least one yield is required'; end if;

  insert into public.recipes (
    organization_id, brand_id, location_id, name, description, category, status,
    recipe_type_id, yield_quantity, yield_unit, yield_percentage, ingredients,
    instructions, selling_price, target_margin_percent, margin_alert_enabled,
    total_ingredient_cost, total_packaging_cost, labor_cost, total_cost,
    cost_per_serving, is_batch, shelf_life_quantity, shelf_life_unit, created_by
  ) values (
    v_org, nullif(p_recipe->>'brand_id', '')::uuid, nullif(p_recipe->>'location_id', '')::uuid,
    trim(p_recipe->>'name'), nullif(p_recipe->>'description', ''), coalesce(nullif(p_recipe->>'category', ''), 'other'),
    coalesce(nullif(p_recipe->>'status', ''), 'active'), nullif(p_recipe->>'recipe_type_id', '')::uuid,
    (p_yields->0->>'quantity')::numeric, p_yields->0->>'unit', 100,
    coalesce(p_recipe->'ingredients', '[]'::jsonb), coalesce(p_recipe->>'instructions', ''),
    coalesce(nullif(p_recipe->>'selling_price', '')::numeric, 0),
    coalesce(nullif(p_recipe->>'target_margin_percent', '')::numeric, 70),
    coalesce((p_recipe->>'margin_alert_enabled')::boolean, true),
    coalesce(nullif(p_recipe->>'total_ingredient_cost', '')::numeric, 0), 0, 0,
    coalesce(nullif(p_recipe->>'total_cost', '')::numeric, 0),
    coalesce(nullif(p_recipe->>'cost_per_serving', '')::numeric, 0), false,
    nullif(p_recipe->>'shelf_life_quantity', '')::numeric, nullif(p_recipe->>'shelf_life_unit', ''), auth.uid()
  ) returning * into v_recipe;

  delete from public.recipe_yields where recipe_id = v_recipe.id;
  for v_row in select value from jsonb_array_elements(p_yields)
  loop
    insert into public.recipe_yields (organization_id, recipe_id, quantity, unit, is_primary, cost_per_unit)
    values (v_org, v_recipe.id, (v_row->>'quantity')::numeric, trim(v_row->>'unit'), coalesce((v_row->>'is_primary')::boolean, false), nullif(v_row->>'cost_per_unit', '')::numeric);
  end loop;

  if coalesce(p_visibility->>'mode', 'all') = 'selected' then
    for v_row in select value from jsonb_array_elements(coalesce(p_visibility->'location_ids', '[]'::jsonb))
    loop
      insert into public.recipe_location_visibility (organization_id, recipe_id, location_id, is_visible)
      select v_org, v_recipe.id, trim(both '"' from v_row::text)::uuid, true
      from public.locations l
      where l.id = trim(both '"' from v_row::text)::uuid and l.organization_id = v_org;
    end loop;
  end if;

  for v_row in select value from jsonb_array_elements(coalesce(p_equipment_names, '[]'::jsonb))
  loop
    insert into public.recipe_equipment_catalog (organization_id, name)
    values (v_org, trim(both '"' from v_row::text))
    on conflict (organization_id, lower(name)) do update set is_active = true, updated_at = now()
    returning id into v_equipment_id;
    insert into public.recipe_equipment_assignments (organization_id, recipe_id, equipment_id)
    values (v_org, v_recipe.id, v_equipment_id) on conflict do nothing;
  end loop;

  for v_row in select value from jsonb_array_elements(coalesce(p_steps, '[]'::jsonb))
  loop
    insert into public.recipe_preparation_steps (organization_id, recipe_id, step_number, instruction, notes)
    values (v_org, v_recipe.id, (v_row->>'step_number')::integer, trim(v_row->>'instruction'), nullif(v_row->>'notes', ''));
  end loop;

  for v_row in select value from jsonb_array_elements(coalesce(p_location_prices, '[]'::jsonb))
  loop
    insert into public.recipe_location_prices (organization_id, recipe_id, location_id, price)
    select v_org, v_recipe.id, (v_row->>'location_id')::uuid, (v_row->>'price')::numeric
    from public.locations l
    where l.id = (v_row->>'location_id')::uuid and l.organization_id = v_org;
  end loop;

  return v_recipe;
end;
$$;

comment on function public.save_menu_item_phase1(jsonb, jsonb, jsonb, jsonb, jsonb, jsonb) is
  'Atomically creates a tenant-scoped Menu Item and its Phase 1 Recipe-owned child records.';

-- Source: 20260715010005_prepared_items_release1.sql
create or replace function public.recipe_dependency_would_cycle(p_recipe_id uuid, p_candidate_child_id uuid)
returns boolean language sql stable security definer set search_path = public, pg_temp as $$
  with recursive descendants(id) as (
    select p_candidate_child_id
    union
    select ri.sub_recipe_id
    from public.recipe_ingredients ri join descendants d on ri.recipe_id = d.id
    where ri.sub_recipe_id is not null
      and ri.organization_id = public.get_my_org()
  )
  select p_recipe_id = p_candidate_child_id or exists(select 1 from descendants where id = p_recipe_id);
$$;

create or replace function public.get_prepared_item_dependencies(p_recipe_id uuid)
returns table (
  recipe_id uuid, recipe_name text, recipe_status text, quantity numeric, unit text,
  yield_percentage numeric, cost_contribution numeric, is_prepared_item boolean
) language sql stable security invoker set search_path = public, pg_temp as $$
  select r.id, r.name, r.status, ri.quantity, ri.unit, ri.yield_percentage,
         coalesce(ri.quantity * ri.unit_cost_snapshot / nullif(ri.yield_percentage / 100.0, 0), 0),
         coalesce(r.is_batch, false)
  from public.recipe_ingredients ri
  join public.recipes r on r.id = ri.recipe_id and r.organization_id = ri.organization_id
  where ri.sub_recipe_id = p_recipe_id
    and ri.organization_id = public.get_my_org()
  order by r.name;
$$;

create or replace function public.recalculate_recipe_cost_tree(p_recipe_id uuid)
returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid;
  v_total numeric := 0;
  v_yield numeric := 1;
  v_unit text := 'each';
  v_version integer;
  v_parent record;
begin
  select organization_id into v_org from public.recipes where id = p_recipe_id;
  if v_org is null or v_org <> public.get_my_org() then raise exception 'Recipe is outside the active organization'; end if;

  select coalesce(sum(coalesce(unit_cost_snapshot,0) * quantity / nullif(yield_percentage / 100.0,0)),0)
    into v_total from public.recipe_ingredients where recipe_id = p_recipe_id;
  select quantity, unit into v_yield, v_unit from public.recipe_yields
    where recipe_id = p_recipe_id and is_primary order by created_at limit 1;
  v_yield := coalesce(nullif(v_yield,0),1);

  update public.recipes set total_ingredient_cost=v_total, total_cost=v_total,
    cost_per_serving=v_total/v_yield, costing_version=costing_version+1, last_costed_at=now(), updated_at=now()
    where id=p_recipe_id returning costing_version into v_version;
  update public.recipe_yields set cost_per_unit=v_total/nullif(quantity,0), updated_at=now()
    where recipe_id=p_recipe_id;
  insert into public.recipe_cost_snapshots(organization_id,recipe_id,costing_version,total_cost,primary_yield_quantity,primary_yield_unit,cost_per_yield_unit,ingredient_snapshot)
    select v_org,p_recipe_id,v_version,v_total,v_yield,v_unit,v_total/v_yield,
      coalesce((select jsonb_agg(to_jsonb(ri) order by sort_order) from public.recipe_ingredients ri where ri.recipe_id=p_recipe_id),'[]'::jsonb);

  for v_parent in select distinct recipe_id from public.recipe_ingredients where sub_recipe_id=p_recipe_id loop
    update public.recipe_ingredients ri set unit_cost_snapshot=r.cost_per_serving, updated_at=now()
      from public.recipes r where ri.recipe_id=v_parent.recipe_id and ri.sub_recipe_id=r.id;
    perform public.recalculate_recipe_cost_tree(v_parent.recipe_id);
  end loop;
end;
$$;

create or replace function public.save_prepared_item_release1(
  p_recipe jsonb, p_yields jsonb, p_visibility jsonb, p_equipment_names jsonb,
  p_steps jsonb, p_ingredients jsonb
) returns public.recipes language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_org uuid := nullif(p_recipe->>'organization_id','')::uuid;
  v_id uuid := nullif(p_recipe->>'id','')::uuid;
  v_recipe public.recipes;
  v_row jsonb;
  v_equipment_id uuid;
  v_child uuid;
begin
  if auth.uid() is null or v_org is null or v_org <> public.get_my_org() or not public.is_manager_or_above() then
    raise exception 'Not authorized to save Prepared Items';
  end if;
  if coalesce(trim(p_recipe->>'name'),'')='' then raise exception 'Name is required'; end if;
  if jsonb_typeof(p_yields)<>'array' or jsonb_array_length(p_yields)=0 then raise exception 'At least one yield is required'; end if;
  if not exists(select 1 from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false)) then raise exception 'A primary yield is required'; end if;

  for v_row in select value from jsonb_array_elements(coalesce(p_ingredients,'[]'::jsonb)) loop
    v_child := nullif(v_row->>'sub_recipe_id','')::uuid;
    if v_child is not null and v_id is not null and public.recipe_dependency_would_cycle(v_id,v_child) then
      raise exception 'Circular Prepared Item dependency detected';
    end if;
    if coalesce((v_row->>'missing_conversion')::boolean,false) then raise exception 'A required unit conversion is missing'; end if;
  end loop;

  if v_id is null then
    insert into public.recipes(organization_id,brand_id,location_id,name,description,category,status,recipe_type_id,
      yield_quantity,yield_unit,yield_percentage,ingredients,instructions,total_ingredient_cost,total_cost,cost_per_serving,is_batch,shelf_life_quantity,shelf_life_unit,created_by)
    values(v_org,nullif(p_recipe->>'brand_id','')::uuid,nullif(p_recipe->>'location_id','')::uuid,trim(p_recipe->>'name'),nullif(p_recipe->>'description',''),
      'other',coalesce(nullif(p_recipe->>'status',''),'active'),nullif(p_recipe->>'recipe_type_id','')::uuid,
      (select (x->>'quantity')::numeric from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) limit 1),
      (select x->>'unit' from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) limit 1),100,p_ingredients,
      coalesce(p_recipe->>'instructions',''),0,0,0,true,nullif(p_recipe->>'shelf_life_quantity','')::numeric,nullif(p_recipe->>'shelf_life_unit',''),auth.uid()) returning * into v_recipe;
    v_id := v_recipe.id;
  else
    update public.recipes set name=trim(p_recipe->>'name'),description=nullif(p_recipe->>'description',''),status=coalesce(nullif(p_recipe->>'status',''),'active'),
      recipe_type_id=nullif(p_recipe->>'recipe_type_id','')::uuid,ingredients=p_ingredients,instructions=coalesce(p_recipe->>'instructions',''),is_batch=true,
      shelf_life_quantity=nullif(p_recipe->>'shelf_life_quantity','')::numeric,shelf_life_unit=nullif(p_recipe->>'shelf_life_unit',''),updated_at=now()
      where id=v_id and organization_id=v_org returning * into v_recipe;
    if v_recipe.id is null then raise exception 'Prepared Item not found'; end if;
  end if;

  for v_row in select value from jsonb_array_elements(coalesce(p_ingredients,'[]'::jsonb)) loop
    v_child := nullif(v_row->>'sub_recipe_id','')::uuid;
    if v_child is not null and public.recipe_dependency_would_cycle(v_id,v_child) then raise exception 'Circular Prepared Item dependency detected'; end if;
  end loop;

  delete from public.recipe_yields where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(p_yields) loop
    insert into public.recipe_yields(organization_id,recipe_id,quantity,unit,is_primary,cost_per_unit)
    values(v_org,v_id,(v_row->>'quantity')::numeric,trim(v_row->>'unit'),coalesce((v_row->>'is_primary')::boolean,false),null);
  end loop;
  delete from public.recipe_location_visibility where recipe_id=v_id;
  if coalesce(p_visibility->>'mode','all')='selected' then
    for v_row in select value from jsonb_array_elements(coalesce(p_visibility->'location_ids','[]'::jsonb)) loop
      insert into public.recipe_location_visibility(organization_id,recipe_id,location_id,is_visible)
      select v_org,v_id,trim(both '"' from v_row::text)::uuid,true from public.locations l
      where l.id=trim(both '"' from v_row::text)::uuid and l.organization_id=v_org;
    end loop;
  end if;
  delete from public.recipe_equipment_assignments where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_equipment_names,'[]'::jsonb)) loop
    insert into public.recipe_equipment_catalog(organization_id,name) values(v_org,trim(both '"' from v_row::text))
      on conflict(organization_id,lower(name)) do update set is_active=true,updated_at=now() returning id into v_equipment_id;
    insert into public.recipe_equipment_assignments(organization_id,recipe_id,equipment_id) values(v_org,v_id,v_equipment_id) on conflict do nothing;
  end loop;
  delete from public.recipe_preparation_steps where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_steps,'[]'::jsonb)) loop
    insert into public.recipe_preparation_steps(organization_id,recipe_id,step_number,instruction,notes)
    values(v_org,v_id,(v_row->>'step_number')::integer,trim(v_row->>'instruction'),nullif(v_row->>'notes',''));
  end loop;

  perform public.recalculate_recipe_cost_tree(v_id);
  select * into v_recipe from public.recipes where id=v_id;
  return v_recipe;
end;
$$;

create or replace function public.deactivate_prepared_item(p_recipe_id uuid)
returns public.recipes language plpgsql security definer set search_path=public,pg_temp as $$
declare v_recipe public.recipes; begin
  if not public.is_manager_or_above() then raise exception 'Not authorized'; end if;
  update public.recipes set status='inactive',updated_at=now() where id=p_recipe_id and organization_id=public.get_my_org() and is_batch=true returning * into v_recipe;
  return v_recipe;
end; $$;

create or replace function public.delete_prepared_item(p_recipe_id uuid)
returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if not public.is_manager_or_above() then raise exception 'Not authorized'; end if;
  if exists(select 1 from public.recipe_ingredients where sub_recipe_id=p_recipe_id and organization_id=public.get_my_org()) then
    raise exception 'Prepared Item is in use and cannot be deleted';
  end if;
  delete from public.recipes where id=p_recipe_id and organization_id=public.get_my_org() and is_batch=true;
end; $$;

comment on function public.delete_prepared_item(uuid) is 'Deletes only unused tenant-scoped Prepared Items; referenced components are blocked.';

-- Source: 20260716000001_payment_workflow_hardening.sql
CREATE OR REPLACE FUNCTION public.store_payment_account_banking_secret(
  p_account_id uuid,
  p_account text,
  p_routing text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_secret_name text := 'pabank_' || p_account_id::text;
  v_secret_id uuid;
  v_row public.payment_accounts%ROWTYPE;
  v_payload text;
  v_last4 text;
BEGIN
  SELECT *
    INTO v_row
  FROM public.payment_accounts
  WHERE id = p_account_id
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Payment account % not found', p_account_id;
  END IF;

  IF NULLIF(regexp_replace(COALESCE(p_account, ''), '\D', '', 'g'), '') IS NULL THEN
    RAISE EXCEPTION 'Account number is required';
  END IF;

  IF NULLIF(regexp_replace(COALESCE(p_routing, ''), '\D', '', 'g'), '') IS NULL THEN
    RAISE EXCEPTION 'Routing number is required';
  END IF;

  v_last4 := right(regexp_replace(p_account, '\D', '', 'g'), 4);
  v_payload := jsonb_build_object('account', p_account, 'routing', p_routing)::text;

  -- Same convention as store_vendor_banking_secret: Vault name keyed on the account row id.
  SELECT id
    INTO v_secret_id
  FROM vault.secrets
  WHERE name = v_secret_name;

  IF v_secret_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;

  SELECT *
    INTO v_secret_id
  FROM vault.create_secret(v_payload, v_secret_name, 'payment account banking');

  UPDATE public.payment_accounts
     SET banking_secret_id = v_secret_id,
         last_four = v_last4,
         updated_at = now()
   WHERE id = p_account_id;

  RETURN jsonb_build_object(
    'account_id', p_account_id,
    'banking_secret_id', v_secret_id,
    'last_four', v_last4
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_payment_account_banking_for_audit(
  p_account_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_secret_id uuid;
  v_secret text;
BEGIN
  -- service-role only, same as get_vendor_banking_for_audit: used exclusively by
  -- create-dwolla-funding-source to retrieve the org's real bank details for the Dwolla API call.
  SELECT banking_secret_id
    INTO v_secret_id
  FROM public.payment_accounts
  WHERE id = p_account_id;

  IF v_secret_id IS NULL THEN
    RAISE EXCEPTION 'Payment account banking secret for % not found', p_account_id;
  END IF;

  SELECT decrypted_secret
    INTO v_secret
  FROM vault.decrypted_secrets
  WHERE id = v_secret_id;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'Vault secret % not found', v_secret_id;
  END IF;

  RETURN v_secret::jsonb;
END;
$$;

-- Source: 20260716010001_bar_items_release1.sql
create or replace function public.save_bar_item_release1(
  p_recipe jsonb, p_yields jsonb, p_visibility jsonb, p_equipment_names jsonb,
  p_steps jsonb, p_location_prices jsonb
) returns public.recipes language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_org uuid := nullif(p_recipe->>'organization_id','')::uuid;
  v_id uuid := nullif(p_recipe->>'id','')::uuid;
  v_recipe public.recipes; v_row jsonb; v_equipment_id uuid; v_child uuid; v_type uuid := nullif(p_recipe->>'recipe_type_id','')::uuid;
begin
  if auth.uid() is null or v_org is null or v_org <> public.get_my_org() or not public.is_manager_or_above() then raise exception 'Not authorized to save Bar Items'; end if;
  if coalesce(trim(p_recipe->>'name'),'')='' then raise exception 'Name is required'; end if;
  if jsonb_typeof(p_yields)<>'array' or jsonb_array_length(p_yields)=0 then raise exception 'At least one yield is required'; end if;
  if (select count(*) from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) and coalesce((x->>'quantity')::numeric,0)>0) <> 1 then raise exception 'Exactly one positive primary yield is required'; end if;
  if v_type is not null and not exists(select 1 from public.recipe_types where id=v_type and organization_id=v_org and kind='beverage') then raise exception 'Bar Item type must be a beverage Recipe type'; end if;
  for v_row in select value from jsonb_array_elements(coalesce(p_recipe->'ingredients','[]'::jsonb)) loop
    v_child := nullif(v_row->>'sub_recipe_id','')::uuid;
    if coalesce((v_row->>'missing_conversion')::boolean,false) then raise exception 'A required unit conversion is missing'; end if;
    if v_child is not null and v_id is not null and public.recipe_dependency_would_cycle(v_id,v_child) then raise exception 'Circular Recipe dependency detected'; end if;
  end loop;

  if v_id is null then
    insert into public.recipes(organization_id,brand_id,location_id,name,description,category,status,recipe_type_id,yield_quantity,yield_unit,yield_percentage,ingredients,instructions,selling_price,target_margin_percent,margin_alert_enabled,total_ingredient_cost,total_cost,cost_per_serving,is_batch,shelf_life_quantity,shelf_life_unit,created_by)
    values(v_org,nullif(p_recipe->>'brand_id','')::uuid,nullif(p_recipe->>'location_id','')::uuid,trim(p_recipe->>'name'),nullif(p_recipe->>'description',''),'beverage',coalesce(nullif(p_recipe->>'status',''),'active'),v_type,
      (select (x->>'quantity')::numeric from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) limit 1),(select x->>'unit' from jsonb_array_elements(p_yields) x where coalesce((x->>'is_primary')::boolean,false) limit 1),100,coalesce(p_recipe->'ingredients','[]'::jsonb),coalesce(p_recipe->>'instructions',''),coalesce(nullif(p_recipe->>'selling_price','')::numeric,0),coalesce(nullif(p_recipe->>'target_margin_percent','')::numeric,70),coalesce((p_recipe->>'margin_alert_enabled')::boolean,true),0,0,0,false,nullif(p_recipe->>'shelf_life_quantity','')::numeric,nullif(p_recipe->>'shelf_life_unit',''),auth.uid()) returning * into v_recipe;
    v_id := v_recipe.id;
  else
    update public.recipes set name=trim(p_recipe->>'name'),description=nullif(p_recipe->>'description',''),category='beverage',status=coalesce(nullif(p_recipe->>'status',''),'active'),recipe_type_id=v_type,
      ingredients=coalesce(p_recipe->'ingredients','[]'::jsonb),instructions=coalesce(p_recipe->>'instructions',''),selling_price=coalesce(nullif(p_recipe->>'selling_price','')::numeric,0),target_margin_percent=coalesce(nullif(p_recipe->>'target_margin_percent','')::numeric,70),margin_alert_enabled=coalesce((p_recipe->>'margin_alert_enabled')::boolean,true),is_batch=false,shelf_life_quantity=nullif(p_recipe->>'shelf_life_quantity','')::numeric,shelf_life_unit=nullif(p_recipe->>'shelf_life_unit',''),updated_at=now()
      where id=v_id and organization_id=v_org and category='beverage' and not coalesce(is_batch,false) returning * into v_recipe;
    if v_recipe.id is null then raise exception 'Bar Item not found'; end if;
  end if;

  delete from public.recipe_yields where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(p_yields) loop insert into public.recipe_yields(organization_id,recipe_id,quantity,unit,is_primary,cost_per_unit) values(v_org,v_id,(v_row->>'quantity')::numeric,trim(v_row->>'unit'),coalesce((v_row->>'is_primary')::boolean,false),nullif(v_row->>'cost_per_unit','')::numeric); end loop;
  delete from public.recipe_location_visibility where recipe_id=v_id;
  if coalesce(p_visibility->>'mode','all')='selected' then for v_row in select value from jsonb_array_elements(coalesce(p_visibility->'location_ids','[]'::jsonb)) loop insert into public.recipe_location_visibility(organization_id,recipe_id,location_id,is_visible) select v_org,v_id,trim(both '"' from v_row::text)::uuid,true from public.locations l where l.id=trim(both '"' from v_row::text)::uuid and l.organization_id=v_org; end loop; end if;
  delete from public.recipe_equipment_assignments where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_equipment_names,'[]'::jsonb)) loop insert into public.recipe_equipment_catalog(organization_id,name) values(v_org,trim(both '"' from v_row::text)) on conflict(organization_id,lower(name)) do update set is_active=true,updated_at=now() returning id into v_equipment_id; insert into public.recipe_equipment_assignments(organization_id,recipe_id,equipment_id) values(v_org,v_id,v_equipment_id) on conflict do nothing; end loop;
  delete from public.recipe_preparation_steps where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_steps,'[]'::jsonb)) loop insert into public.recipe_preparation_steps(organization_id,recipe_id,step_number,instruction,notes) values(v_org,v_id,(v_row->>'step_number')::integer,trim(v_row->>'instruction'),nullif(v_row->>'notes','')); end loop;
  delete from public.recipe_location_prices where recipe_id=v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_location_prices,'[]'::jsonb)) loop insert into public.recipe_location_prices(organization_id,recipe_id,location_id,price) select v_org,v_id,(v_row->>'location_id')::uuid,(v_row->>'price')::numeric from public.locations l where l.id=(v_row->>'location_id')::uuid and l.organization_id=v_org; end loop;
  perform public.recalculate_recipe_cost_tree(v_id);
  select * into v_recipe from public.recipes where id=v_id;
  return v_recipe;
end; $$;

create or replace function public.set_bar_item_status(p_recipe_id uuid,p_status text) returns public.recipes language plpgsql security definer set search_path=public,pg_temp as $$ declare v_recipe public.recipes; begin
  if not public.is_manager_or_above() or p_status not in ('active','inactive') then raise exception 'Not authorized or invalid status'; end if;
  update public.recipes set status=p_status,updated_at=now() where id=p_recipe_id and organization_id=public.get_my_org() and category='beverage' and not coalesce(is_batch,false) returning * into v_recipe; return v_recipe;
end; $$;

create or replace function public.delete_bar_item(p_recipe_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin
  if not public.is_manager_or_above() then raise exception 'Not authorized'; end if;
  if exists(select 1 from public.recipe_ingredients where sub_recipe_id=p_recipe_id and organization_id=public.get_my_org()) then raise exception 'Bar Item is in use and cannot be deleted'; end if;
  delete from public.recipes where id=p_recipe_id and organization_id=public.get_my_org() and category='beverage' and not coalesce(is_batch,false);
end; $$;

comment on function public.save_bar_item_release1(jsonb,jsonb,jsonb,jsonb,jsonb,jsonb) is 'Atomically saves tenant-scoped beverage Recipes and shared Recipe child records.';

-- Source: 20260716015500_add_get_product_catalog_rpc.sql
-- Product catalog RPC used by the Products page.
-- Keeps pagination/search/sort in Postgres and returns a couple of computed
-- fields the UI expects: item_count/vendor_item_count and last_purchased_at.

DROP FUNCTION IF EXISTS public.get_product_catalog(uuid, uuid, uuid, text, text, integer, integer);

CREATE OR REPLACE FUNCTION public.get_product_catalog(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_search text DEFAULT NULL,
  p_sort_by text DEFAULT 'name',
  p_page integer DEFAULT 0,
  p_page_size integer DEFAULT 50
)
RETURNS TABLE (
  id uuid,
  product_id text,
  name text,
  description text,
  category text,
  accounting_category text,
  is_inventoried boolean,
  is_tax_exempt boolean,
  report_by_unit text,
  base_unit text,
  latest_price numeric,
  average_price numeric,
  price_history jsonb,
  preferred_vendor_id uuid,
  par_level numeric,
  reorder_point numeric,
  location_specific boolean,
  locations jsonb,
  status text,
  created_from_invoice_id uuid,
  created_by uuid,
  created_at timestamptz,
  updated_at timestamptz,
  organization_id uuid,
  location_id uuid,
  brand_id uuid,
  item_count bigint,
  vendor_item_count bigint,
  last_purchased_at date,
  total_count bigint
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_page, 0), 0) * LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_sort text := COALESCE(NULLIF(p_sort_by, ''), 'name');
BEGIN
  RETURN QUERY
  WITH base AS (
    SELECT
      p.*,
      COUNT(*) OVER () AS total_count,
      COUNT(vim.id) AS item_count,
      MAX(vi.last_purchased_at) AS last_purchased_at
    FROM public.products p
    LEFT JOIN public.vendor_item_mappings vim
      ON vim.internal_product_id = p.id
      AND vim.organization_id = p.organization_id
    LEFT JOIN public.vendor_items vi
      ON vi.id = vim.vendor_item_id
      AND vi.organization_id = p.organization_id
    WHERE p.organization_id = p_organization_id
      AND p.deleted_at IS NULL
      AND (p_brand_id IS NULL OR p.brand_id IS NULL OR p.brand_id = p_brand_id)
      AND (p_location_id IS NULL OR p.location_id IS NULL OR p.location_id = p_location_id)
      AND (
        COALESCE(NULLIF(p_search, ''), NULL) IS NULL
        OR p.name ILIKE '%' || p_search || '%'
        OR p.description ILIKE '%' || p_search || '%'
        OR p.product_id ILIKE '%' || p_search || '%'
        OR p.category ILIKE '%' || p_search || '%'
        OR p.accounting_category ILIKE '%' || p_search || '%'
      )
    GROUP BY p.id
  )
  SELECT
    b.id,
    b.product_id,
    b.name,
    b.description,
    b.category,
    b.accounting_category,
    b.is_inventoried,
    b.is_tax_exempt,
    b.report_by_unit,
    b.base_unit,
    b.latest_price,
    b.average_price,
    b.price_history,
    b.preferred_vendor_id,
    b.par_level,
    b.reorder_point,
    b.location_specific,
    b.locations,
    b.status,
    b.created_from_invoice_id,
    b.created_by,
    b.created_at,
    b.updated_at,
    b.organization_id,
    b.location_id,
    b.brand_id,
    GREATEST(b.item_count, 1)::bigint AS item_count,
    GREATEST(b.item_count, 1)::bigint AS vendor_item_count,
    b.last_purchased_at,
    b.total_count
  FROM base b
  ORDER BY
    CASE WHEN v_sort = 'name' THEN b.name END ASC NULLS LAST,
    CASE WHEN v_sort = '-name' THEN b.name END DESC NULLS LAST,
    CASE WHEN v_sort = 'category' THEN b.category END ASC NULLS LAST,
    CASE WHEN v_sort = '-category' THEN b.category END DESC NULLS LAST,
    CASE WHEN v_sort = 'accounting_category' THEN b.accounting_category END ASC NULLS LAST,
    CASE WHEN v_sort = '-accounting_category' THEN b.accounting_category END DESC NULLS LAST,
    CASE WHEN v_sort = 'is_inventoried' THEN b.is_inventoried END ASC NULLS LAST,
    CASE WHEN v_sort = '-is_inventoried' THEN b.is_inventoried END DESC NULLS LAST,
    CASE WHEN v_sort = 'is_tax_exempt' THEN b.is_tax_exempt END ASC NULLS LAST,
    CASE WHEN v_sort = '-is_tax_exempt' THEN b.is_tax_exempt END DESC NULLS LAST,
    CASE WHEN v_sort = 'report_by_unit' THEN b.report_by_unit END ASC NULLS LAST,
    CASE WHEN v_sort = '-report_by_unit' THEN b.report_by_unit END DESC NULLS LAST,
    CASE WHEN v_sort = 'latest_price' THEN b.latest_price END ASC NULLS LAST,
    CASE WHEN v_sort = '-latest_price' THEN b.latest_price END DESC NULLS LAST,
    b.name ASC NULLS LAST,
    b.created_at DESC
  LIMIT v_limit OFFSET v_offset;
END;
$function$;

-- Source: 20260716020000_add_product_page_workflow_rpcs.sql
-- Minimal Products page RPCs for product catalog workflows.

DROP FUNCTION IF EXISTS public.get_product_dashboard_summary(uuid, uuid, uuid);

DROP FUNCTION IF EXISTS public.get_product_purchase_report(uuid, uuid, uuid, date, date, text, text, text);

DROP FUNCTION IF EXISTS public.get_product_verification_queue(uuid, uuid, uuid, text, text);

DROP FUNCTION IF EXISTS public.create_product_details(text, text, text, text, text, boolean, boolean, text, text, numeric, boolean, uuid, uuid, uuid);

DROP FUNCTION IF EXISTS public.update_product_details(uuid, text, text, text, text, text, boolean, boolean, text, text, numeric, boolean);

DROP FUNCTION IF EXISTS public.set_product_inventory_tracking(uuid, boolean);

DROP FUNCTION IF EXISTS public.soft_delete_product_safe(uuid);

