CREATE OR REPLACE FUNCTION public.get_product_dashboard_summary(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS TABLE (
  total_products bigint,
  inventoried_count bigint,
  tax_exempt_count bigint,
  category_count bigint,
  missing_product_id_count bigint,
  uncategorized_count bigint,
  unmapped_vendor_item_count bigint,
  price_variance_count bigint
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  WITH scoped AS (
    SELECT *
    FROM public.products p
    WHERE p.organization_id = p_organization_id
      AND p.deleted_at IS NULL
      AND (p_brand_id IS NULL OR p.brand_id IS NULL OR p.brand_id = p_brand_id)
      AND (p_location_id IS NULL OR p.location_id IS NULL OR p.location_id = p_location_id)
  )
  SELECT
    COUNT(*)::bigint,
    COUNT(*) FILTER (WHERE is_inventoried IS TRUE)::bigint,
    COUNT(*) FILTER (WHERE is_tax_exempt IS TRUE)::bigint,
    COUNT(DISTINCT NULLIF(accounting_category, ''))::bigint,
    COUNT(*) FILTER (WHERE COALESCE(product_id, '') = '')::bigint,
    COUNT(*) FILTER (WHERE COALESCE(category, '') = '' OR category = 'Uncategorized')::bigint,
    COUNT(*) FILTER (
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.vendor_item_mappings vim
        WHERE vim.internal_product_id = scoped.id
          AND vim.organization_id = scoped.organization_id
      )
    )::bigint,
    0::bigint
  FROM scoped;
$$;

CREATE OR REPLACE FUNCTION public.get_product_purchase_report(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_start_date date DEFAULT NULL,
  p_end_date date DEFAULT NULL,
  p_category_type text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_search text DEFAULT NULL
)
RETURNS TABLE (
  product_id uuid,
  restops_product_id text,
  name text,
  description text,
  category text,
  accounting_category text,
  purchased_units numeric,
  purchased_amount numeric,
  latest_cost numeric,
  avg_cost numeric,
  last_purchased_at date
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT
    p.id,
    p.product_id,
    p.name,
    p.description,
    p.category,
    p.accounting_category,
    COALESCE(SUM(ili.quantity), 0)::numeric,
    COALESCE(SUM(ili.total_price), 0)::numeric,
    COALESCE(MAX(ili.unit_price), p.latest_price, 0)::numeric,
    COALESCE(AVG(NULLIF(ili.unit_price, 0)), p.average_price, p.latest_price, 0)::numeric,
    MAX(i.invoice_date)::date
  FROM public.products p
  LEFT JOIN public.invoice_line_items ili
    ON ili.internal_product_id = p.id
    AND ili.organization_id = p.organization_id
  LEFT JOIN public.invoices i
    ON i.id = ili.invoice_id
    AND i.organization_id = p.organization_id
    AND i.deleted_at IS NULL
    AND (p_start_date IS NULL OR i.invoice_date >= p_start_date)
    AND (p_end_date IS NULL OR i.invoice_date <= p_end_date)
  WHERE p.organization_id = p_organization_id
    AND p.deleted_at IS NULL
    AND (p_brand_id IS NULL OR p.brand_id IS NULL OR p.brand_id = p_brand_id)
    AND (p_location_id IS NULL OR p.location_id IS NULL OR p.location_id = p_location_id)
    AND (p_category IS NULL OR p.category = p_category)
    AND (
      COALESCE(NULLIF(p_search, ''), NULL) IS NULL
      OR p.name ILIKE '%' || p_search || '%'
      OR p.description ILIKE '%' || p_search || '%'
      OR p.product_id ILIKE '%' || p_search || '%'
    )
  GROUP BY p.id
  ORDER BY COALESCE(SUM(ili.total_price), 0) DESC, p.name ASC;
$$;

CREATE OR REPLACE FUNCTION public.get_product_verification_queue(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_status text DEFAULT NULL,
  p_search text DEFAULT NULL
)
RETURNS TABLE (
  internal_product_id uuid,
  product_id text,
  name text,
  description text,
  category text,
  accounting_category text,
  suggested_category text,
  suggested_accounting_category text,
  category_confidence numeric,
  category_review_status text,
  latest_price numeric
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT
    p.id,
    p.product_id,
    p.name,
    p.description,
    p.category,
    p.accounting_category,
    NULL::text,
    NULL::text,
    NULL::numeric,
    'verified'::text,
    p.latest_price
  FROM public.products p
  WHERE p.organization_id = p_organization_id
    AND p.deleted_at IS NULL
    AND (p_brand_id IS NULL OR p.brand_id IS NULL OR p.brand_id = p_brand_id)
    AND (p_location_id IS NULL OR p.location_id IS NULL OR p.location_id = p_location_id)
    AND (
      COALESCE(NULLIF(p_search, ''), NULL) IS NULL
      OR p.name ILIKE '%' || p_search || '%'
      OR p.description ILIKE '%' || p_search || '%'
      OR p.product_id ILIKE '%' || p_search || '%'
    )
  ORDER BY p.updated_at DESC
  LIMIT 100;
$$;

CREATE OR REPLACE FUNCTION public.create_product_details(
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT true,
  p_is_tax_exempt boolean DEFAULT false,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT 0,
  p_location_specific boolean DEFAULT false,
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_product public.products;
BEGIN
  INSERT INTO public.products (
    organization_id, brand_id, location_id, product_id, name, description,
    category, accounting_category, is_inventoried, is_tax_exempt,
    report_by_unit, base_unit, latest_price, location_specific, status,
    created_by
  )
  VALUES (
    p_organization_id, p_brand_id, p_location_id, p_restops_product_id, p_name, p_description,
    p_category, p_accounting_category, COALESCE(p_is_inventoried, true), COALESCE(p_is_tax_exempt, false),
    p_report_by_unit, p_base_unit, COALESCE(p_latest_price, 0), COALESCE(p_location_specific, false), 'active',
    auth.uid()
  )
  RETURNING * INTO v_product;

  RETURN to_jsonb(v_product);
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_product_details(
  p_product_id uuid,
  p_name text DEFAULT NULL,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT NULL,
  p_is_tax_exempt boolean DEFAULT NULL,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT NULL,
  p_location_specific boolean DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_product public.products;
BEGIN
  UPDATE public.products
  SET
    product_id = p_restops_product_id,
    name = COALESCE(p_name, name),
    description = p_description,
    category = p_category,
    accounting_category = p_accounting_category,
    is_inventoried = COALESCE(p_is_inventoried, is_inventoried),
    is_tax_exempt = COALESCE(p_is_tax_exempt, is_tax_exempt),
    report_by_unit = p_report_by_unit,
    base_unit = p_base_unit,
    latest_price = COALESCE(p_latest_price, latest_price),
    location_specific = COALESCE(p_location_specific, location_specific),
    updated_at = now()
  WHERE id = p_product_id
    AND deleted_at IS NULL
  RETURNING * INTO v_product;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  RETURN to_jsonb(v_product);
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_product_inventory_tracking(
  p_product_id uuid,
  p_is_inventoried boolean
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_product public.products;
BEGIN
  UPDATE public.products
  SET is_inventoried = COALESCE(p_is_inventoried, false),
      updated_at = now()
  WHERE id = p_product_id
    AND deleted_at IS NULL
  RETURNING * INTO v_product;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  RETURN to_jsonb(v_product);
END;
$function$;

CREATE OR REPLACE FUNCTION public.soft_delete_product_safe(p_product_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.products
  SET deleted_at = now(),
      deleted_by = auth.uid(),
      updated_at = now()
  WHERE id = p_product_id
    AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  RETURN true;
END;
$function$;

CREATE OR REPLACE FUNCTION public.apply_product_category_suggestion(p_product_id uuid)
RETURNS jsonb
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT to_jsonb(p) FROM public.products p WHERE p.id = p_product_id;
$$;

CREATE OR REPLACE FUNCTION public.reject_product_category_suggestion(p_product_id uuid)
RETURNS jsonb
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT to_jsonb(p) FROM public.products p WHERE p.id = p_product_id;
$$;

-- Source: 20260717000001_inventory_count_session_persistence.sql
DROP FUNCTION IF EXISTS public.save_inventory_count_session(uuid, uuid, uuid, text, text, date, jsonb, uuid, uuid);

CREATE OR REPLACE FUNCTION public.save_inventory_count_session(
  p_organization_id uuid,
  p_location_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_count_sheet_id uuid DEFAULT NULL,
  p_scope_key text DEFAULT 'all',
  p_type text DEFAULT 'Inventory',
  p_count_date date DEFAULT CURRENT_DATE,
  p_items jsonb DEFAULT '[]'::jsonb,
  p_user_id uuid DEFAULT NULL,
  p_session_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.count_sessions;
  v_items jsonb := COALESCE(p_items, '[]'::jsonb);
  v_total numeric := 0;
  v_item_count integer := 0;
BEGIN
  SELECT
    COALESCE(SUM(COALESCE((item->>'value')::numeric, 0)), 0),
    COUNT(*)
  INTO v_total, v_item_count
  FROM jsonb_array_elements(v_items) AS item;

  IF p_session_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.count_sessions
    WHERE id = p_session_id
      AND organization_id = p_organization_id
      AND deleted_at IS NULL
      AND status <> 'closed'
  ) THEN
    UPDATE public.count_sessions
    SET
      location_id = p_location_id,
      brand_id = p_brand_id,
      count_sheet_id = p_count_sheet_id,
      scope_key = COALESCE(NULLIF(p_scope_key, ''), 'all'),
      type = COALESCE(NULLIF(p_type, ''), 'Inventory'),
      count_date = COALESCE(p_count_date, CURRENT_DATE),
      items = v_items,
      counted_data = v_items,
      total_value = v_total,
      item_count = v_item_count,
      status = 'saved',
      saved_at = COALESCE(saved_at, now()),
      updated_at = now(),
      counted_by = COALESCE(p_user_id, counted_by),
      created_by = COALESCE(created_by, p_user_id)
    WHERE id = p_session_id
      AND organization_id = p_organization_id
    RETURNING * INTO v_row;
  ELSE
    INSERT INTO public.count_sessions (
      organization_id,
      location_id,
      brand_id,
      count_sheet_id,
      scope_key,
      type,
      count_date,
      items,
      counted_data,
      total_value,
      item_count,
      status,
      saved_at,
      updated_at,
      counted_by,
      created_by
    )
    VALUES (
      p_organization_id,
      p_location_id,
      p_brand_id,
      p_count_sheet_id,
      COALESCE(NULLIF(p_scope_key, ''), 'all'),
      COALESCE(NULLIF(p_type, ''), 'Inventory'),
      COALESCE(p_count_date, CURRENT_DATE),
      v_items,
      v_items,
      v_total,
      v_item_count,
      'saved',
      now(),
      now(),
      p_user_id,
      p_user_id
    )
    RETURNING * INTO v_row;
  END IF;

  RETURN to_jsonb(v_row);
END;
$function$;

CREATE OR REPLACE FUNCTION public.close_inventory_count_session(
  p_organization_id uuid,
  p_session_id uuid,
  p_user_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.count_sessions;
BEGIN
  UPDATE public.count_sessions
  SET
    status = 'closed',
    completed_at = COALESCE(completed_at, now()),
    closed_at = COALESCE(closed_at, now()),
    updated_at = now(),
    counted_by = COALESCE(counted_by, p_user_id)
  WHERE id = p_session_id
    AND organization_id = p_organization_id
    AND deleted_at IS NULL
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Inventory count session not found';
  END IF;

  RETURN to_jsonb(v_row);
END;
$function$;

CREATE OR REPLACE FUNCTION public.delete_inventory_count_session(
  p_organization_id uuid,
  p_session_id uuid,
  p_user_id uuid DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.count_sessions
  SET deleted_at = now(), updated_at = now()
  WHERE id = p_session_id
    AND organization_id = p_organization_id
    AND deleted_at IS NULL;

  RETURN FOUND;
END;
$function$;

-- Source: 20260717000003_payment_reminders_and_failure_notify.sql
-- Reimplements the org_owner/branch_manager/location_manager/ground_staff visibility rule
-- from financial_scope_visible(), but against an EXPLICIT target user's profile instead of
-- auth.uid() -- financial_scope_visible only ever checks the calling session's own access,
-- which is meaningless inside a cron job that has to evaluate many different users' access.
CREATE OR REPLACE FUNCTION public.send_due_date_reminders()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_setting RECORD;
  v_profile RECORD;
  v_invoice RECORD;
BEGIN
  FOR v_setting IN
    SELECT user_id, organization_id, reminder_days
    FROM public.invoice_reminder_settings
    WHERE enabled = true
  LOOP
    SELECT role, organization_id, brand_id, location_id
      INTO v_profile
    FROM public.profiles
    WHERE id = v_setting.user_id
      AND deleted_at IS NULL;

    IF v_profile.role IS NULL THEN
      CONTINUE;
    END IF;

    FOR v_invoice IN
      SELECT i.id, i.due_date, (i.due_date - CURRENT_DATE) AS days_out
      FROM public.invoices i
      WHERE i.deleted_at IS NULL
        AND i.organization_id = v_setting.organization_id
        AND COALESCE(i.payment_status, 'unpaid') NOT IN ('paid', 'auto_pay')
        AND i.due_date IS NOT NULL
        AND (i.due_date - CURRENT_DATE) = ANY(v_setting.reminder_days)
        AND (
          v_profile.role IN ('org_owner', 'platform_admin')
          OR (
            v_profile.role = 'branch_manager'
            AND (
              i.brand_id = v_profile.brand_id
              OR i.location_id IN (SELECT l.id FROM public.locations l WHERE l.brand_id = v_profile.brand_id)
            )
          )
          OR (
            v_profile.role IN ('location_manager', 'ground_staff')
            AND i.location_id = v_profile.location_id
          )
        )
    LOOP
      INSERT INTO public.invoice_reminder_log (invoice_id, user_id, reminder_day)
      VALUES (v_invoice.id, v_setting.user_id, v_invoice.days_out)
      ON CONFLICT (invoice_id, user_id, reminder_day) DO NOTHING;

      IF FOUND THEN
        INSERT INTO public.notifications (user_id, organization_id, type, title, message, is_read, metadata)
        VALUES (
          v_setting.user_id,
          v_setting.organization_id,
          'invoice',
          CASE WHEN v_invoice.days_out <= 0 THEN 'Invoice overdue' ELSE 'Invoice due soon' END,
          CASE WHEN v_invoice.days_out <= 0
            THEN format('An invoice was due on %s and is still unpaid.', to_char(v_invoice.due_date, 'Mon DD, YYYY'))
            ELSE format('An invoice is due in %s day%s (%s).', v_invoice.days_out, CASE WHEN v_invoice.days_out = 1 THEN '' ELSE 's' END, to_char(v_invoice.due_date, 'Mon DD, YYYY'))
          END,
          false,
          jsonb_build_object('invoice_id', v_invoice.id, 'due_in_days', v_invoice.days_out)
        );
      END IF;
    END LOOP;
  END LOOP;

  -- Trigger the email side (plain SQL can't call Resend). Same secure-dispatch pattern as
  -- dispatch_webhook_queue(): read the functions URL/service key from
  -- private.workflow_runtime_settings rather than hardcoding credentials in this function.
  DECLARE
    v_functions_url text;
    v_service_role_key text;
    v_url text;
  BEGIN
    SELECT setting_value INTO v_functions_url FROM private.workflow_runtime_settings WHERE setting_name = 'functions_url';
    SELECT setting_value INTO v_service_role_key FROM private.workflow_runtime_settings WHERE setting_name = 'service_role_key';

    IF v_service_role_key IS NOT NULL AND length(trim(v_service_role_key)) > 0 THEN
      v_url := COALESCE(NULLIF(trim(v_functions_url), ''), 'https://gsupqfmwlsmwoybphimx.supabase.co/functions/v1') || '/send-due-date-reminder-emails';

      PERFORM net.http_post(
        url := v_url,
        body := '{}'::jsonb,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_service_role_key
        )
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- Notifications already landed above; a failure to trigger the email side is non-fatal.
    NULL;
  END;
END;
$$;

