-- Source: 20260719000014_product_approval_workflow.sql
-- ===== org-level toggle, reusing operational_settings (already RLS-protected, already the
-- established home for exactly this kind of per-org preference) =====

CREATE OR REPLACE FUNCTION public.get_product_approval_setting(p_organization_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT COALESCE(
    (SELECT (settings->>'require_location_manager_approval')::boolean
     FROM public.operational_settings
     WHERE organization_id = p_organization_id
       AND scope = 'organization'
       AND brand_id IS NULL
       AND location_id IS NULL
       AND category = 'product_approval'),
    false
  );
$$;

CREATE OR REPLACE FUNCTION public.set_product_approval_setting(p_organization_id uuid, p_enabled boolean)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF public.get_auth_role() NOT IN ('org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Only an org manager or above can change the product approval setting';
  END IF;

  IF NOT public.is_platform_admin() AND p_organization_id IS DISTINCT FROM public.get_auth_org() THEN
    RAISE EXCEPTION 'Cross-organization access denied';
  END IF;

  -- NB: operational_settings' unique constraint includes nullable brand_id/location_id, and
  -- Postgres never treats NULL = NULL as a conflict for constraint/ON CONFLICT purposes --
  -- an ON CONFLICT (organization_id, brand_id, location_id, category) target would silently
  -- never match an org-level (brand/location NULL) row and just insert a duplicate every call.
  -- Explicit check-then-write instead, scoped to this function rather than touching the
  -- shared table's constraint (used by other settings categories too).
  IF EXISTS (
    SELECT 1 FROM public.operational_settings
    WHERE organization_id = p_organization_id AND scope = 'organization'
      AND brand_id IS NULL AND location_id IS NULL AND category = 'product_approval'
  ) THEN
    UPDATE public.operational_settings
    SET settings = jsonb_build_object('require_location_manager_approval', p_enabled),
        updated_by = auth.uid(),
        updated_at = now()
    WHERE organization_id = p_organization_id AND scope = 'organization'
      AND brand_id IS NULL AND location_id IS NULL AND category = 'product_approval';
  ELSE
    INSERT INTO public.operational_settings (organization_id, scope, category, settings, created_by, updated_by)
    VALUES (p_organization_id, 'organization', 'product_approval',
            jsonb_build_object('require_location_manager_approval', p_enabled), auth.uid(), auth.uid());
  END IF;

  RETURN jsonb_build_object('success', true, 'require_location_manager_approval', p_enabled);
END;
$$;

-- ===== create_product_details: location_manager's create still inserts a live row, but
-- flagged pending when the org has opted in =====

CREATE OR REPLACE FUNCTION public.create_product_details(
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT true,
  p_is_tax_exempt boolean DEFAULT false,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT 0,
  p_location_specific boolean DEFAULT false,
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_my_org());
  v_brand_id uuid;
  v_location_id uuid;
  v_product public.products%ROWTYPE;
  v_needs_approval boolean;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF p_location_specific THEN
    v_location_id := COALESCE(p_location_id, (SELECT location_id FROM public.profiles WHERE id = auth.uid()));
    v_brand_id := COALESCE(p_brand_id, (SELECT brand_id FROM public.locations WHERE id = v_location_id));
  ELSE
    v_location_id := NULL;
    v_brand_id := p_brand_id;
  END IF;

  IF NOT public.reference_scope_writable(v_org_id, v_brand_id, v_location_id, NULL, 'location_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to create this product';
  END IF;

  v_needs_approval := public.get_auth_role() = 'location_manager'
    AND public.get_product_approval_setting(v_org_id);

  BEGIN
    INSERT INTO public.products (
      name, product_id, description, category, accounting_category,
      is_inventoried, is_tax_exempt, report_by_unit, base_unit, latest_price,
      location_specific, organization_id, brand_id, location_id, created_by,
      pending_approval, pending_action, submitted_by, submitted_at
    ) VALUES (
      btrim(p_name), p_restops_product_id, p_description, p_category, p_accounting_category,
      p_is_inventoried, p_is_tax_exempt, p_report_by_unit, p_base_unit, p_latest_price,
      p_location_specific, v_org_id, v_brand_id, v_location_id, auth.uid(),
      v_needs_approval, CASE WHEN v_needs_approval THEN 'create' ELSE NULL END,
      CASE WHEN v_needs_approval THEN auth.uid() ELSE NULL END,
      CASE WHEN v_needs_approval THEN now() ELSE NULL END
    )
    RETURNING * INTO v_product;
  EXCEPTION WHEN unique_violation THEN
    IF SQLERRM ILIKE '%products_product_id_key%' THEN
      RAISE EXCEPTION 'Product ID "%" is already in use. Choose a different one.', p_restops_product_id;
    END IF;
    RAISE;
  END;

  RETURN to_jsonb(v_product);
END;
$$;

-- ===== update_product_details: same pattern -- the update applies for real, snapshot of the
-- prior row is kept so a reject can revert it =====

CREATE OR REPLACE FUNCTION public.update_product_details(
  p_product_id uuid,
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT true,
  p_is_tax_exempt boolean DEFAULT false,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT 0,
  p_location_specific boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_existing public.products%ROWTYPE;
  v_product public.products%ROWTYPE;
  v_needs_approval boolean;
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  SELECT * INTO v_existing FROM public.products WHERE id = p_product_id AND deleted_at IS NULL;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.reference_scope_writable(v_existing.organization_id, v_existing.brand_id, v_existing.location_id, v_existing.deleted_at, 'location_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to update this product';
  END IF;

  v_needs_approval := public.get_auth_role() = 'location_manager'
    AND public.get_product_approval_setting(v_existing.organization_id)
    AND NOT v_existing.pending_approval;

  BEGIN
    UPDATE public.products SET
      name = btrim(p_name),
      product_id = COALESCE(p_restops_product_id, product_id),
      description = p_description,
      category = p_category,
      accounting_category = COALESCE(p_accounting_category, accounting_category),
      is_inventoried = p_is_inventoried,
      is_tax_exempt = p_is_tax_exempt,
      report_by_unit = p_report_by_unit,
      base_unit = p_base_unit,
      latest_price = p_latest_price,
      location_specific = p_location_specific,
      pending_approval = CASE WHEN v_needs_approval THEN true ELSE pending_approval END,
      pending_action = CASE WHEN v_needs_approval THEN 'update' ELSE pending_action END,
      pending_snapshot = CASE WHEN v_needs_approval THEN to_jsonb(v_existing) ELSE pending_snapshot END,
      submitted_by = CASE WHEN v_needs_approval THEN auth.uid() ELSE submitted_by END,
      submitted_at = CASE WHEN v_needs_approval THEN now() ELSE submitted_at END,
      updated_at = now()
    WHERE id = p_product_id
    RETURNING * INTO v_product;
  EXCEPTION WHEN unique_violation THEN
    IF SQLERRM ILIKE '%products_product_id_key%' THEN
      RAISE EXCEPTION 'Product ID "%" is already in use. Choose a different one.', p_restops_product_id;
    END IF;
    RAISE;
  END;

  RETURN to_jsonb(v_product);
END;
$$;

-- ===== soft_delete_product_safe: for a gated location_manager delete, the product is NOT
-- soft-deleted yet -- it stays live and usable, just flagged pending_action='delete' until a
-- manager approves it =====

CREATE OR REPLACE FUNCTION public.soft_delete_product_safe(
  p_product_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_existing public.products%ROWTYPE;
  v_needs_approval boolean;
BEGIN
  SELECT * INTO v_existing FROM public.products WHERE id = p_product_id AND deleted_at IS NULL;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.reference_scope_writable(v_existing.organization_id, v_existing.brand_id, v_existing.location_id, v_existing.deleted_at, 'location_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to delete this product';
  END IF;

  v_needs_approval := public.get_auth_role() = 'location_manager'
    AND public.get_product_approval_setting(v_existing.organization_id)
    AND NOT v_existing.pending_approval;

  IF v_needs_approval THEN
    UPDATE public.products SET
      pending_approval = true,
      pending_action = 'delete',
      pending_snapshot = to_jsonb(v_existing),
      submitted_by = auth.uid(),
      submitted_at = now()
    WHERE id = p_product_id;

    RETURN jsonb_build_object('success', true, 'pending_approval', true);
  END IF;

  UPDATE public.products SET deleted_at = now(), deleted_by = auth.uid() WHERE id = p_product_id;

  RETURN jsonb_build_object('success', true, 'pending_approval', false);
END;
$$;

-- ===== approve / reject =====

CREATE OR REPLACE FUNCTION public.approve_product_change(p_product_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_existing public.products%ROWTYPE;
BEGIN
  SELECT * INTO v_existing FROM public.products WHERE id = p_product_id;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT v_existing.pending_approval THEN
    RAISE EXCEPTION 'This product has no pending change to approve';
  END IF;

  IF public.get_auth_role() NOT IN ('branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions to approve product changes';
  END IF;

  IF NOT public.reference_scope_writable(v_existing.organization_id, v_existing.brand_id, v_existing.location_id, NULL, 'branch_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to approve this product change';
  END IF;

  IF v_existing.pending_action = 'delete' THEN
    UPDATE public.products SET
      deleted_at = now(), deleted_by = auth.uid(),
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  ELSE
    UPDATE public.products SET
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

CREATE OR REPLACE FUNCTION public.reject_product_change(p_product_id uuid, p_reason text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_existing public.products%ROWTYPE;
BEGIN
  SELECT * INTO v_existing FROM public.products WHERE id = p_product_id;
  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT v_existing.pending_approval THEN
    RAISE EXCEPTION 'This product has no pending change to reject';
  END IF;

  IF public.get_auth_role() NOT IN ('branch_manager', 'org_manager', 'tenant_super_admin', 'platform_admin') THEN
    RAISE EXCEPTION 'Insufficient permissions to reject product changes';
  END IF;

  IF NOT public.reference_scope_writable(v_existing.organization_id, v_existing.brand_id, v_existing.location_id, NULL, 'branch_manager') THEN
    RAISE EXCEPTION 'Insufficient permissions to reject this product change';
  END IF;

  IF v_existing.pending_action = 'create' THEN
    -- Undo the creation: soft-delete it, there's no prior state to revert to.
    UPDATE public.products SET
      deleted_at = now(), deleted_by = auth.uid(),
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  ELSIF v_existing.pending_action = 'update' THEN
    -- Revert every column back to the pre-change snapshot.
    UPDATE public.products SET
      name = (v_existing.pending_snapshot->>'name'),
      product_id = (v_existing.pending_snapshot->>'product_id'),
      description = (v_existing.pending_snapshot->>'description'),
      category = (v_existing.pending_snapshot->>'category'),
      accounting_category = (v_existing.pending_snapshot->>'accounting_category'),
      is_inventoried = (v_existing.pending_snapshot->>'is_inventoried')::boolean,
      is_tax_exempt = (v_existing.pending_snapshot->>'is_tax_exempt')::boolean,
      report_by_unit = (v_existing.pending_snapshot->>'report_by_unit'),
      base_unit = (v_existing.pending_snapshot->>'base_unit'),
      latest_price = (v_existing.pending_snapshot->>'latest_price')::numeric,
      location_specific = (v_existing.pending_snapshot->>'location_specific')::boolean,
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  ELSE
    -- pending delete rejected: cancel the delete request, product stays as-is.
    UPDATE public.products SET
      pending_approval = false, pending_action = NULL, pending_snapshot = NULL,
      submitted_by = NULL, submitted_at = NULL
    WHERE id = p_product_id;
  END IF;

  IF p_reason IS NOT NULL THEN
    PERFORM public.log_audit_event(jsonb_build_object(
      'organization_id', v_existing.organization_id,
      'user_id', auth.uid(),
      'action', 'product_change_rejected',
      'table_name', 'products',
      'record_id', p_product_id::text,
      'entity_type', 'product',
      'entity_id', p_product_id::text,
      'details', jsonb_build_object('reason', p_reason, 'rejected_action', v_existing.pending_action)
    ));
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;

-- Source: 20260719000015_invoice_audit_common_path_and_webhook_dispatch.sql
-- 9.9: route invoice audit events through the common log_audit_event path (in addition to
-- the existing invoice_audit_events insert, which stays for InvoiceAuditLog.jsx).
-- 9.10: dispatch audit_logs inserts through the existing webhook-trigger pattern
-- (queue_webhook_event -> webhook_events_queue -> notify_webhook_dispatcher pg_net call),
-- reusing 066_webhook_triggers.sql / 120_native_workflow_triggers.sql infrastructure as-is.

CREATE OR REPLACE FUNCTION public.log_invoice_audit_event(p_invoice_id uuid, p_action text, p_description text DEFAULT NULL::text, p_old_value jsonb DEFAULT NULL::jsonb, p_new_value jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id UUID;
BEGIN
  SELECT organization_id INTO v_org_id FROM public.invoices WHERE id = p_invoice_id;

  IF v_org_id IS NOT NULL THEN
    INSERT INTO public.invoice_audit_events (
      invoice_id, organization_id, user_id, action, description, old_value, new_value
    ) VALUES (
      p_invoice_id, v_org_id, auth.uid(), p_action, p_description, p_old_value, p_new_value
    );

    -- Best-effort mirror into the common audit_logs ledger. Must never block the invoice
    -- write itself: log_audit_event requires an authenticated/service-role actor context
    -- (assert_org_actor), which isn't present for direct-SQL/cron-driven invoice updates.
    BEGIN
      PERFORM public.log_audit_event(jsonb_build_object(
        'organization_id', v_org_id,
        'action', p_action,
        'table_name', 'invoices',
        'record_id', p_invoice_id::text,
        'entity_type', 'invoice',
        'entity_id', p_invoice_id::text,
        'old_data', p_old_value,
        'new_data', p_new_value,
        'details', p_description
      ));
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;
END;
$function$;

-- Fix a latent bug in queue_webhook_event() (066_webhook_triggers.sql): on a partitioned
-- table, a row-level trigger cloned onto a partition fires with TG_TABLE_NAME set to the
-- PARTITION's name (e.g. 'audit_logs_y2026'), not the parent's ('audit_logs'), so event_type
-- never matched an exact subscription. Never surfaced before because none of the previously
-- wired tables (profiles, employees, inventory) are partitioned; audit_logs is. Resolve via
-- the partition root, which is a no-op for non-partitioned tables (falls back to TG_RELID).
CREATE OR REPLACE FUNCTION public.queue_webhook_event()
RETURNS TRIGGER AS $$
DECLARE
    v_event_type TEXT;
    v_org_id UUID;
    v_payload JSONB;
    v_table_name TEXT;
BEGIN
    SELECT relname INTO v_table_name FROM pg_class WHERE oid = pg_partition_root(TG_RELID);
    v_event_type := COALESCE(v_table_name, TG_TABLE_NAME) || '.' || lower(TG_OP);

    IF TG_OP = 'DELETE' THEN
        v_payload := row_to_json(OLD)::jsonb;
    ELSE
        v_payload := row_to_json(NEW)::jsonb;
    END IF;

    -- Try to get organization_id from the record
    BEGIN
        v_org_id := (v_payload->>'organization_id')::UUID;
    EXCEPTION WHEN OTHERS THEN
        RETURN COALESCE(NEW, OLD); -- Skip if no organization_id
    END;

    IF v_org_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    -- Find endpoints subscribed to this event or '*'
    INSERT INTO public.webhook_events_queue (organization_id, endpoint_id, event_type, payload)
    SELECT we.organization_id, we.id, v_event_type, v_payload
    FROM public.webhook_endpoints we
    JOIN public.webhook_subscriptions ws ON we.id = ws.endpoint_id
    WHERE we.organization_id = v_org_id
      AND we.status = 'active'
      AND (ws.event_type = v_event_type OR ws.event_type = '*');

    RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Source: 20260719000016_org_document_storage_stats.sql
-- 5.3: file-count/total-bytes tracking per org, aggregated off invoice_documents
-- (populated since the register_invoice_document RPC landed). SECURITY INVOKER so it
-- naturally respects the caller's existing RLS on invoice_documents (financial_scope
-- visibility) rather than duplicating scope logic -- an org_manager sees their org's full
-- totals, a location_manager sees only what they can already see.

CREATE OR REPLACE FUNCTION public.get_org_document_stats()
RETURNS TABLE (
  organization_id uuid,
  file_count bigint,
  total_bytes bigint
)
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public'
AS $function$
  SELECT
    organization_id,
    count(*) AS file_count,
    COALESCE(sum(file_size), 0) AS total_bytes
  FROM public.invoice_documents
  GROUP BY organization_id;
$function$;

-- Source: 20260720000001_product_module_phase1_safe_rpcs.sql
-- Product module Phase 1: safe reporting and workflow RPCs.
-- This migration is intentionally additive: it reuses existing product,
-- invoice, vendor item, and mapping tables.

CREATE OR REPLACE FUNCTION public.normalize_product_report_unit(p_unit text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN NULLIF(trim(COALESCE(p_unit, '')), '') IS NULL THEN 'Each'
    WHEN lower(trim(p_unit)) IN ('ea', 'each', 'unit', 'units') THEN 'Each'
    WHEN lower(trim(p_unit)) IN ('cs', 'case', 'cases') THEN 'Case'
    WHEN lower(trim(p_unit)) IN ('lb', 'lbs', 'pound', 'pounds') THEN 'Pound'
    WHEN lower(trim(p_unit)) IN ('oz', 'ounce', 'ounces') THEN 'Ounce'
    WHEN lower(trim(p_unit)) IN ('gal', 'gallon', 'gallons') THEN 'Gallon'
    WHEN lower(trim(p_unit)) IN ('qt', 'quart', 'quarts') THEN 'Quart'
    WHEN lower(trim(p_unit)) IN ('pt', 'pint', 'pints') THEN 'Pint'
    WHEN lower(trim(p_unit)) IN ('floz', 'fl oz', 'fluid ounce', 'fluid ounces') THEN 'Fluid Ounce'
    WHEN lower(trim(p_unit)) IN ('kg', 'kilogram', 'kilograms') THEN 'Kilogram'
    WHEN lower(trim(p_unit)) IN ('g', 'gram', 'grams') THEN 'Gram'
    WHEN lower(trim(p_unit)) IN ('box', 'boxes') THEN 'Box'
    WHEN lower(trim(p_unit)) IN ('bag', 'bags') THEN 'Bag'
    WHEN lower(trim(p_unit)) IN ('btl', 'bottle', 'bottles') THEN 'Bottle'
    WHEN lower(trim(p_unit)) IN ('can', 'cans') THEN 'Can'
    ELSE initcap(trim(p_unit))
  END;
$$;

CREATE OR REPLACE FUNCTION public.derive_product_category_type(
  p_accounting_category text,
  p_category text DEFAULT NULL,
  p_name text DEFAULT NULL
)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN lower(COALESCE(p_accounting_category, '')) LIKE '52%'
      OR lower(COALESCE(p_accounting_category, '')) LIKE '%beverage%'
      OR lower(COALESCE(p_category, '')) IN ('beer', 'wine', 'liquor', 'beverage', 'beverages')
      OR lower(COALESCE(p_name, '')) ~ '(beer|wine|liquor|vodka|gin|rum|tequila|whiskey|syrup, fontn|soda)'
      THEN 'Beverage'
    WHEN lower(COALESCE(p_accounting_category, '')) LIKE '51%'
      OR lower(COALESCE(p_accounting_category, '')) LIKE '%food%'
      OR lower(COALESCE(p_accounting_category, '')) IN ('food', 'food_cogs', '5100')
      THEN 'Food'
    ELSE 'Other'
  END;
$$;

CREATE OR REPLACE FUNCTION public.derive_product_category(p_category text, p_name text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN NULLIF(trim(COALESCE(p_category, '')), '') IS NOT NULL
      AND lower(trim(p_category)) <> 'uncategorized'
      THEN trim(p_category)
    WHEN lower(COALESCE(p_name, '')) ~ '(lettuce|tomato|potato|onion|pepper|celery|carrot|cucumber|lemon|okra|coleslaw|produce)'
      THEN 'Produce'
    WHEN lower(COALESCE(p_name, '')) ~ '(cheese|milk|cream|butter|buttermilk|dairy)'
      THEN 'Dairy'
    WHEN lower(COALESCE(p_name, '')) ~ '(chicken|wing|breast|tender|poultry)'
      THEN 'Poultry'
    WHEN lower(COALESCE(p_name, '')) ~ '(beef|bacon|pork|meat|patty)'
      THEN 'Meat'
    WHEN lower(COALESCE(p_name, '')) ~ '(beer|ale|lager)'
      THEN 'Beer'
    WHEN lower(COALESCE(p_name, '')) ~ '(wine|pinot|cabernet|chardonnay)'
      THEN 'Wine'
    WHEN lower(COALESCE(p_name, '')) ~ '(vodka|gin|rum|tequila|whiskey|liquor)'
      THEN 'Liquor'
    WHEN lower(COALESCE(p_name, '')) ~ '(container|towel|scrubber|glove|kit, ctly|napkin|paper|bleach)'
      THEN 'Restaurant Supplies'
    WHEN lower(COALESCE(p_name, '')) ~ '(flour|bread|roll|macaroni|ketchup|mayonnaise|sauce|shortening|tortilla|breade?r|syrup)'
      THEN 'Grocery and Dry Goods'
    ELSE 'Uncategorized'
  END;
$$;

CREATE OR REPLACE FUNCTION public.generate_restops_product_id()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_next bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('public.products.product_id'));

  SELECT COALESCE(MAX(((regexp_match(product_id, '^PRD-([0-9]+)$'))[1])::bigint), 0) + 1
    INTO v_next
  FROM public.products
  WHERE product_id ~ '^PRD-[0-9]+$';

  RETURN 'PRD-' || lpad(v_next::text, 6, '0');
END;
$$;

CREATE OR REPLACE FUNCTION public.soft_delete_product_safe(p_product_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Product not found');
  END IF;

  IF NOT public.reference_scope_writable(
    v_product.organization_id,
    v_product.brand_id,
    v_product.location_id,
    NULL,
    'location_manager'
  ) THEN
    RAISE EXCEPTION 'Not authorized to delete this product';
  END IF;

  UPDATE public.products
     SET deleted_at = now(),
         deleted_by = auth.uid(),
         updated_at = now()
   WHERE id = p_product_id;

  RETURN jsonb_build_object('success', true, 'product_id', p_product_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.get_product_dashboard_summary(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS TABLE (
  total_products bigint,
  inventoried_count bigint,
  tax_exempt_count bigint,
  category_count bigint,
  missing_product_id_count bigint,
  uncategorized_count bigint,
  unmapped_vendor_item_count bigint,
  price_variance_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH product_scope AS (
    SELECT p.*
    FROM public.products p
    WHERE p.organization_id = v_org_id
      AND p.deleted_at IS NULL
      AND (p_brand_id IS NULL OR p.brand_id IS NOT DISTINCT FROM p_brand_id)
      AND (p_location_id IS NULL OR p.location_id IS NOT DISTINCT FROM p_location_id)
      AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
  ),
  vendor_scope AS (
    SELECT vi.*
    FROM public.vendor_items vi
    WHERE vi.organization_id = v_org_id
  )
  SELECT
    (SELECT count(*) FROM product_scope),
    (SELECT count(*) FROM product_scope WHERE COALESCE(is_inventoried, false)),
    (SELECT count(*) FROM product_scope WHERE COALESCE(is_tax_exempt, false)),
    (SELECT count(DISTINCT public.derive_product_category(category, name)) FROM product_scope),
    (SELECT count(*) FROM product_scope WHERE NULLIF(trim(COALESCE(product_id, '')), '') IS NULL),
    (SELECT count(*) FROM product_scope WHERE public.derive_product_category(category, name) = 'Uncategorized'),
    (
      SELECT count(*)
      FROM vendor_scope vi
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.vendor_item_mappings vim
        WHERE vim.vendor_item_id = vi.id
      )
    ),
    (SELECT count(*) FROM vendor_scope WHERE COALESCE(price_variance_flag, false));
END;
$$;

CREATE OR REPLACE FUNCTION public.get_product_purchase_report(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_start_date date DEFAULT NULL,
  p_end_date date DEFAULT NULL,
  p_category_type text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_search text DEFAULT NULL
)
RETURNS TABLE (
  restaurant text,
  product_id uuid,
  restops_product_id text,
  product_name text,
  category_type text,
  category text,
  report_by text,
  invoice_count bigint,
  line_count bigint,
  purchased_units numeric,
  purchased_amount numeric,
  latest_cost numeric,
  avg_cost numeric,
  last_purchased_at date
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH approved_lines AS (
    SELECT
      i.id AS invoice_id,
      i.invoice_date,
      i.organization_id,
      i.brand_id,
      i.location_id,
      i.vendor_id,
      ili.id AS line_id,
      ili.item_name,
      ili.quantity,
      ili.unit_price,
      ili.total_price,
      ili.vendor_unit,
      ili.internal_product_id,
      ili.inventory_item_id
    FROM public.invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    WHERE i.organization_id = v_org_id
      AND i.deleted_at IS NULL
      AND (i.status = 'approved' OR i.ap_status = 'approved')
      AND (p_brand_id IS NULL OR i.brand_id IS NOT DISTINCT FROM p_brand_id)
      AND (p_location_id IS NULL OR i.location_id IS NOT DISTINCT FROM p_location_id)
      AND (p_start_date IS NULL OR i.invoice_date >= p_start_date)
      AND (p_end_date IS NULL OR i.invoice_date <= p_end_date)
      AND public.tenant_scope_visible(i.organization_id, i.brand_id, i.location_id, i.deleted_at)
      AND public.tenant_scope_visible(ili.organization_id, i.brand_id, i.location_id, NULL)
  ),
  enriched AS (
    SELECT
      COALESCE(l.name, 'Current Store') AS restaurant,
      p.id AS product_id,
      p.product_id AS restops_product_id,
      COALESCE(p.name, al.item_name) AS product_name,
      public.derive_product_category_type(p.accounting_category, p.category, COALESCE(p.name, al.item_name)) AS category_type,
      public.derive_product_category(p.category, COALESCE(p.name, al.item_name)) AS category,
      public.normalize_product_report_unit(COALESCE(p.report_by_unit, al.vendor_unit)) AS report_by,
      al.invoice_id,
      al.line_id,
      COALESCE(al.quantity, 0) AS quantity,
      COALESCE(al.total_price, COALESCE(al.quantity, 0) * COALESCE(al.unit_price, 0)) AS total_price,
      COALESCE(al.unit_price, 0) AS unit_price,
      al.invoice_date
    FROM approved_lines al
    LEFT JOIN public.products p
      ON p.id = al.internal_product_id
      OR (al.inventory_item_id IS NOT NULL AND p.product_id = al.inventory_item_id)
    LEFT JOIN public.locations l ON l.id = al.location_id
    WHERE (p_search IS NULL OR COALESCE(p.name, al.item_name, '') ILIKE '%' || p_search || '%')
  )
  SELECT
    e.restaurant,
    e.product_id,
    e.restops_product_id,
    e.product_name,
    e.category_type,
    e.category,
    e.report_by,
    count(DISTINCT e.invoice_id) AS invoice_count,
    count(e.line_id) AS line_count,
    round(sum(e.quantity), 4) AS purchased_units,
    round(sum(e.total_price), 2) AS purchased_amount,
    (array_agg(e.unit_price ORDER BY e.invoice_date DESC NULLS LAST, e.line_id DESC))[1] AS latest_cost,
    round(sum(e.total_price) / NULLIF(sum(e.quantity), 0), 4) AS avg_cost,
    max(e.invoice_date) AS last_purchased_at
  FROM enriched e
  WHERE (p_category_type IS NULL OR p_category_type = 'all' OR e.category_type = p_category_type)
    AND (p_category IS NULL OR p_category = 'all' OR e.category = p_category)
  GROUP BY
    e.restaurant,
    e.product_id,
    e.restops_product_id,
    e.product_name,
    e.category_type,
    e.category,
    e.report_by
  ORDER BY e.product_name;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_product_verification_queue(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_status text DEFAULT NULL,
  p_search text DEFAULT NULL
)
RETURNS TABLE (
  vendor_item_id uuid,
  vendor_item_code text,
  vendor_item_name text,
  vendor_name text,
  vendor_unit text,
  last_price numeric,
  last_purchased_at date,
  mapping_id uuid,
  internal_product_id uuid,
  restops_product_id text,
  product_name text,
  category_type text,
  category text,
  match_confidence numeric,
  mapping_status text,
  needs_verification boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH queue AS (
    SELECT
      vi.id AS vendor_item_id,
      vi.vendor_item_code,
      vi.vendor_item_name,
      v.name AS vendor_name,
      vi.vendor_unit,
      vi.last_price,
      vi.last_purchased_at,
      vim.id AS mapping_id,
      vim.internal_product_id,
      p.product_id AS restops_product_id,
      p.name AS product_name,
      public.derive_product_category_type(p.accounting_category, p.category, COALESCE(p.name, vi.vendor_item_name)) AS category_type,
      public.derive_product_category(p.category, COALESCE(p.name, vi.vendor_item_name)) AS category,
      COALESCE(vi.match_confidence, CASE WHEN vim.is_verified THEN 100 ELSE 0 END) AS match_confidence,
      COALESCE(vi.mapping_status, CASE WHEN vim.id IS NULL THEN 'unmapped' WHEN vim.is_verified THEN 'verified' ELSE 'suggested' END) AS mapping_status,
      (vim.id IS NULL OR COALESCE(vim.is_verified, false) = false OR COALESCE(vi.match_confidence, 0) < 90) AS needs_verification
    FROM public.vendor_items vi
    LEFT JOIN public.vendors v ON v.id = vi.vendor_id
    LEFT JOIN public.vendor_item_mappings vim ON vim.vendor_item_id = vi.id
    LEFT JOIN public.products p ON p.id = vim.internal_product_id AND p.deleted_at IS NULL
    WHERE vi.organization_id = v_org_id
      AND (p_search IS NULL OR vi.vendor_item_name ILIKE '%' || p_search || '%' OR COALESCE(p.name, '') ILIKE '%' || p_search || '%')
      AND (
        p_brand_id IS NULL
        OR p.brand_id IS NOT DISTINCT FROM p_brand_id
        OR p.id IS NULL
      )
      AND (
        p_location_id IS NULL
        OR p.location_id IS NOT DISTINCT FROM p_location_id
        OR p.id IS NULL
      )
  )
  SELECT *
  FROM queue q
  WHERE q.needs_verification
    AND (p_status IS NULL OR p_status = 'all' OR q.mapping_status = p_status)
  ORDER BY q.last_purchased_at DESC NULLS LAST, q.vendor_item_name;
END;
$$;

-- Preserve the current invoice approval behavior while ensuring invoice-created
-- products receive a user-facing Restops Product ID.
CREATE OR REPLACE FUNCTION public.sync_invoice_products(p_invoice_id UUID, p_user_id UUID DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_item RECORD;
  v_product_id UUID;
  v_vendor_item_id UUID;
  v_mapping_id UUID;
  v_previous_price NUMERIC;
  v_threshold NUMERIC := 10;
  v_price_variance_flag BOOLEAN;
  v_price_variance_percent NUMERIC;
  v_line_hash TEXT;
  v_existing_hash TEXT;
  v_updates_count INT := 0;
BEGIN
  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_invoice IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Invoice not found');
  END IF;

  SELECT md5(COALESCE(jsonb_agg(jsonb_build_object(
      'id', ili.id,
      'item_name', ili.item_name,
      'quantity', ili.quantity,
      'unit_price', ili.unit_price,
      'total_price', ili.total_price,
      'vendor_item_code', ili.vendor_item_code,
      'vendor_unit', ili.vendor_unit
    ) ORDER BY ili.id)::TEXT, '[]'))
    INTO v_line_hash
  FROM public.invoice_line_items ili
  WHERE ili.invoice_id = p_invoice_id;

  SELECT hash INTO v_existing_hash
  FROM public.invoice_sync_log
  WHERE invoice_id = p_invoice_id
    AND operation = 'sync_invoice_products'
  ORDER BY processed_at DESC
  LIMIT 1;

  IF v_existing_hash IS NOT NULL AND v_existing_hash = v_line_hash THEN
    RETURN jsonb_build_object('status', 'success', 'updates_count', 0, 'idempotent', true);
  END IF;

  FOR v_item IN
    SELECT *
    FROM public.invoice_line_items
    WHERE invoice_id = p_invoice_id
      AND NULLIF(trim(COALESCE(item_name, '')), '') IS NOT NULL
  LOOP
    v_product_id := v_item.internal_product_id;
    v_vendor_item_id := NULL;
    v_mapping_id := NULL;
    v_price_variance_flag := false;
    v_price_variance_percent := 0;

    IF v_product_id IS NULL THEN
      SELECT id INTO v_product_id
      FROM public.products
      WHERE organization_id = v_invoice.organization_id
        AND lower(name) = lower(v_item.item_name)
        AND deleted_at IS NULL
        AND (
          brand_id IS NOT DISTINCT FROM v_invoice.brand_id
          OR brand_id IS NULL
        )
      ORDER BY CASE WHEN brand_id IS NOT DISTINCT FROM v_invoice.brand_id THEN 0 ELSE 1 END
      LIMIT 1;

      IF v_product_id IS NULL THEN
        INSERT INTO public.products (
          organization_id,
          brand_id,
          location_id,
          product_id,
          name,
          category,
          accounting_category,
          report_by_unit,
          base_unit,
          latest_price,
          is_inventoried,
          created_from_invoice_id
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.brand_id,
          v_invoice.location_id,
          public.generate_restops_product_id(),
          v_item.item_name,
          public.derive_product_category(NULL, v_item.item_name),
          CASE
            WHEN public.derive_product_category_type(NULL, NULL, v_item.item_name) = 'Beverage' THEN '5200'
            ELSE '5100'
          END,
          COALESCE(NULLIF(v_item.vendor_unit, ''), 'ea'),
          COALESCE(NULLIF(v_item.vendor_unit, ''), 'ea'),
          COALESCE(v_item.unit_price, 0),
          false,
          p_invoice_id
        )
        RETURNING id INTO v_product_id;
      ELSE
        UPDATE public.products
           SET product_id = COALESCE(NULLIF(product_id, ''), public.generate_restops_product_id()),
               latest_price = CASE
                 WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price
                 ELSE latest_price
               END,
               category = CASE
                 WHEN NULLIF(trim(COALESCE(category, '')), '') IS NULL OR lower(category) = 'uncategorized'
                   THEN public.derive_product_category(category, v_item.item_name)
                 ELSE category
               END,
               brand_id = COALESCE(brand_id, v_invoice.brand_id),
               location_id = COALESCE(location_id, v_invoice.location_id),
               updated_at = now()
         WHERE id = v_product_id;
      END IF;
    END IF;

    IF v_invoice.vendor_id IS NOT NULL THEN
      SELECT id, last_price, price_variance_threshold_percent
        INTO v_vendor_item_id, v_previous_price, v_threshold
      FROM public.vendor_items
      WHERE organization_id = v_invoice.organization_id
        AND vendor_id = v_invoice.vendor_id
        AND lower(vendor_item_name) = lower(v_item.item_name)
        AND COALESCE(vendor_item_code, '') = COALESCE(v_item.vendor_item_code, '')
      LIMIT 1;

      v_threshold := COALESCE(v_threshold, 10);

      IF v_vendor_item_id IS NOT NULL THEN
        IF COALESCE(v_previous_price, 0) > 0 AND COALESCE(v_item.unit_price, 0) > 0 THEN
          v_price_variance_percent := ((v_item.unit_price - v_previous_price) / v_previous_price) * 100;
          v_price_variance_flag := abs(v_price_variance_percent) >= v_threshold;
        END IF;

        UPDATE public.vendor_items
           SET vendor_unit = COALESCE(NULLIF(v_item.vendor_unit, ''), vendor_unit),
               previous_price = last_price,
               last_price = COALESCE(v_item.unit_price, last_price),
               last_invoice_id = p_invoice_id,
               last_invoice_line_id = v_item.id,
               last_purchased_at = COALESCE(v_invoice.invoice_date, CURRENT_DATE),
               last_price_change_percent = v_price_variance_percent,
               price_variance_flag = v_price_variance_flag,
               updated_at = now()
         WHERE id = v_vendor_item_id;
      ELSE
        INSERT INTO public.vendor_items (
          organization_id,
          vendor_id,
          vendor_item_code,
          vendor_item_name,
          vendor_unit,
          default_price,
          last_price,
          last_invoice_id,
          last_invoice_line_id,
          last_purchased_at,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.vendor_id,
          NULLIF(v_item.vendor_item_code, ''),
          v_item.item_name,
          NULLIF(v_item.vendor_unit, ''),
          v_item.unit_price,
          v_item.unit_price,
          p_invoice_id,
          v_item.id,
          COALESCE(v_invoice.invoice_date, CURRENT_DATE),
          now()
        )
        RETURNING id INTO v_vendor_item_id;
      END IF;

      IF v_product_id IS NOT NULL AND v_vendor_item_id IS NOT NULL THEN
        INSERT INTO public.vendor_item_mappings (
          organization_id,
          vendor_item_id,
          internal_product_id,
          conversion_multiplier,
          is_verified,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_vendor_item_id,
          v_product_id,
          1,
          false,
          now()
        )
        ON CONFLICT (vendor_item_id, internal_product_id)
        DO UPDATE SET updated_at = now()
        RETURNING id INTO v_mapping_id;
      END IF;
    END IF;

    UPDATE public.invoice_line_items
       SET vendor_id = v_invoice.vendor_id,
           vendor_item_id = v_vendor_item_id,
           internal_product_id = v_product_id,
           price_variance_flag = v_price_variance_flag,
           price_variance_percent = v_price_variance_percent
     WHERE id = v_item.id;

    v_updates_count := v_updates_count + 1;
  END LOOP;

  INSERT INTO public.invoice_event_log (invoice_id, event_type, new_value, actor_id)
  VALUES (
    p_invoice_id,
    'product_catalog_synced',
    jsonb_build_object('updates_count', v_updates_count),
    COALESCE(p_user_id, auth.uid())
  );

  INSERT INTO public.invoice_sync_log (invoice_id, operation, hash)
  VALUES (p_invoice_id, 'sync_invoice_products', v_line_hash);

  RETURN jsonb_build_object('status', 'success', 'updates_count', v_updates_count);
END;
$$;

-- Source: 20260720000002_margin_edge_product_category_types.sql
-- Align product category type labels with MarginEdge-style reporting.
-- This intentionally separates category type from accounting/COA labels.

CREATE OR REPLACE FUNCTION public.derive_product_category_type(
  p_accounting_category text,
  p_category text DEFAULT NULL,
  p_name text DEFAULT NULL
)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  WITH normalized AS (
    SELECT
      lower(COALESCE(p_accounting_category, '')) AS accounting,
      lower(COALESCE(p_category, '')) AS category,
      lower(COALESCE(p_name, '')) AS name
  ),
  combined AS (
    SELECT accounting, category, name, accounting || ' ' || category || ' ' || name AS text
    FROM normalized
  )
  SELECT CASE
    WHEN text ~ '(beer|ale|lager|ipa|stout|porter|pilsner|cider|seltzer|blue moon|modelo|corona|budweiser|bud light|coors|miller|heineken)'
      THEN 'Beer'
    WHEN text ~ '(wine|pinot|chardonnay|cabernet|merlot|sauvignon|riesling|prosecco|champagne|moscato|malbec|zinfandel|rose\b)'
      THEN 'Wine'
    WHEN text ~ '(liquor|spirit|vodka|gin|rum|tequila|whiskey|whisky|bourbon|scotch|brandy|cognac|mezcal|liqueur|triple sec)'
      THEN 'Liquor'
    WHEN text ~ '(n/a bev|na beverage|non[- ]?alcohol|beverage|soda|juice|tea|coffee|lemonade|energy drink|water|syrup, fontn|fountain|bib)'
      OR accounting LIKE '52%'
      OR accounting LIKE '%beverage%'
      THEN 'N/A Bev'
    WHEN text ~ '(retail|merchandise|gift card|giftcard|apparel|shirt|hat|merch)'
      THEN 'Retail'
    WHEN accounting LIKE '51%'
      OR accounting LIKE '%food%'
      OR accounting IN ('food', 'food_cogs', '5100')
      OR category ~ '(dairy|produce|poultry|grocery|meat|seafood|bakery|bread|frozen|dry goods)'
      THEN 'Food'
    ELSE 'Other'
  END
  FROM combined;
$$;

COMMENT ON FUNCTION public.derive_product_category_type(text, text, text)
IS 'Returns MarginEdge-style product category types: Food, Beer, Wine, Liquor, N/A Bev, Retail, Other.';

-- Source: 20260720000003_product_ai_category_suggestions.sql
CREATE OR REPLACE FUNCTION public.derive_product_category(p_category text, p_name text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  WITH normalized AS (
    SELECT
      lower(trim(COALESCE(p_category, ''))) AS category,
      lower(trim(COALESCE(p_name, ''))) AS name
  ),
  cleaned AS (
    SELECT
      category,
      regexp_replace(name, '[^a-z0-9]+', ' ', 'g') AS name
    FROM normalized
  )
  SELECT CASE
    WHEN NULLIF(category, '') IS NOT NULL
      AND category <> 'uncategorized'
      THEN initcap(category)

    WHEN name ~ '(arugula|asparagus|avocado|basil|bean sprouts?|beet|broccoli|cabbage|carrot|cauliflower|celery|cilantro|corn|cucumber|eggplant|garlic|ginger|greens?|herbs?|jalapeno|kale|lettuce|lime|lemon|mushroom|okra|onion|pepper|potato|produce|romaine|scallion|spinach|squash|tomato|zucchini)'
      THEN 'Produce'
    WHEN name ~ '(cheese|cream|creamer|dairy|egg|eggs|half half|milk|mozzarella|parmesan|provolone|sour cream|yogurt|butter|buttermilk)'
      THEN 'Dairy'
    WHEN name ~ '(chicken|breast|drumstick|tender|thigh|wing|wings|poultry|turkey)'
      THEN 'Poultry'
    WHEN name ~ '(beef|burger|bacon|brisket|chorizo|ham|hot dog|meat|patty|pepperoni|pork|ribeye|sausage|steak|veal)'
      THEN 'Meat'
    WHEN name ~ '(anchovy|catfish|clam|cod|crab|fish|haddock|lobster|mussel|oyster|salmon|scallop|seafood|shrimp|tilapia|tuna)'
      THEN 'Seafood'
    WHEN name ~ '(bagel|bakery|biscuit|bread|bun|cake|croissant|dough|muffin|pastry|pita|roll|tortilla)'
      THEN 'Bakery'
    WHEN name ~ '(appetizer|batter|bean|beans|breadcrumb|cereal|chip|chips|cornstarch|crouton|dry goods|flour|grocery|ketchup|macaroni|mayo|mayonnaise|mustard|oil|olive|pasta|pickle|rice|salt|sauce|seasoning|shortening|spice|sugar|syrup|vinegar)'
      THEN 'Grocery and Dry Goods'
    WHEN name ~ '(frozen|fries|fry|ice cream|iqf|nugget)'
      THEN 'Frozen'
    WHEN name ~ '(beer|ale|lager|ipa|stout|porter|pilsner|cider|seltzer|modelo|corona|budweiser|bud light|coors|miller|heineken)'
      THEN 'Beer'
    WHEN name ~ '(wine|pinot|chardonnay|cabernet|merlot|sauvignon|riesling|prosecco|champagne|moscato|malbec|zinfandel|rose)'
      THEN 'Wine'
    WHEN name ~ '(liquor|spirit|vodka|gin|rum|tequila|whiskey|whisky|bourbon|scotch|brandy|cognac|mezcal|liqueur|triple sec)'
      THEN 'Liquor'
    WHEN name ~ '(beverage|bib|coffee|fountain|juice|lemonade|non alcohol|nonalcohol|soda|tea|water)'
      THEN 'N/A Beverage'
    WHEN name ~ '(bleach|cleaner|cleaning|detergent|dish|sanitizer|soap|scrubber|sponge)'
      THEN 'Cleaning Supplies'
    WHEN name ~ '(bag|bags|box|container|cup|film|foil|lid|napkin|packaging|paper|plate|straw|takeout|towel|wrap)'
      THEN 'Paper and Packaging'
    WHEN name ~ '(apron|candle|equipment|glove|gloves|kit|label|lighter|pan|smallware|thermometer|utensil)'
      THEN 'Restaurant Supplies'
    WHEN name ~ '(apparel|gift card|giftcard|hat|merch|merchandise|retail|shirt)'
      THEN 'Retail'
    ELSE 'Uncategorized'
  END
  FROM cleaned;
$$;

CREATE OR REPLACE FUNCTION public.derive_product_category_type(
  p_accounting_category text,
  p_category text DEFAULT NULL,
  p_name text DEFAULT NULL
)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  WITH normalized AS (
    SELECT
      lower(COALESCE(p_accounting_category, '')) AS accounting,
      lower(COALESCE(p_category, '')) AS category,
      lower(COALESCE(p_name, '')) AS name
  ),
  combined AS (
    SELECT accounting, category, name, accounting || ' ' || category || ' ' || name AS text
    FROM normalized
  )
  SELECT CASE
    WHEN text ~ '(beer|ale|lager|ipa|stout|porter|pilsner|cider|seltzer|modelo|corona|budweiser|bud light|coors|miller|heineken)'
      THEN 'Beer'
    WHEN text ~ '(wine|pinot|chardonnay|cabernet|merlot|sauvignon|riesling|prosecco|champagne|moscato|malbec|zinfandel|rose)'
      THEN 'Wine'
    WHEN text ~ '(liquor|spirit|vodka|gin|rum|tequila|whiskey|whisky|bourbon|scotch|brandy|cognac|mezcal|liqueur|triple sec)'
      THEN 'Liquor'
    WHEN text ~ '(n/a bev|na beverage|non[- ]?alcohol|beverage|bib|coffee|fountain|juice|lemonade|soda|tea|water)'
      OR accounting LIKE '52%'
      OR accounting LIKE '%beverage%'
      THEN 'N/A Bev'
    WHEN text ~ '(retail|merchandise|gift card|giftcard|apparel|shirt|hat|merch)'
      THEN 'Retail'
    WHEN accounting LIKE '51%'
      OR accounting LIKE '%food%'
      OR accounting IN ('food', 'food_cogs', '5100')
      OR category ~ '(bakery|dairy|dry goods|frozen|grocery|meat|paper and packaging|poultry|produce|restaurant supplies|seafood)'
      THEN 'Food'
    ELSE 'Other'
  END
  FROM combined;
$$;

CREATE OR REPLACE FUNCTION public.apply_product_category_suggestion(p_product_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Product not found');
  END IF;

  IF NOT public.reference_scope_writable(
    v_product.organization_id,
    v_product.brand_id,
    v_product.location_id,
    NULL,
    'location_manager'
  ) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  IF NULLIF(trim(COALESCE(v_product.suggested_category, '')), '') IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'No category suggestion is available');
  END IF;

  UPDATE public.products
     SET category = v_product.suggested_category,
         accounting_category = COALESCE(NULLIF(v_product.suggested_accounting_category, ''), accounting_category),
         category_confidence = v_product.category_confidence,
         category_source = 'approved',
         category_review_status = 'approved',
         category_reviewed_at = now(),
         category_reviewed_by = auth.uid(),
         updated_at = now()
   WHERE id = p_product_id;

  RETURN jsonb_build_object('success', true, 'product_id', p_product_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.reject_product_category_suggestion(p_product_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Product not found');
  END IF;

  IF NOT public.reference_scope_writable(
    v_product.organization_id,
    v_product.brand_id,
    v_product.location_id,
    NULL,
    'location_manager'
  ) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  UPDATE public.products
     SET category_review_status = 'rejected',
         category_reviewed_at = now(),
         category_reviewed_by = auth.uid(),
         updated_at = now()
   WHERE id = p_product_id;

  RETURN jsonb_build_object('success', true, 'product_id', p_product_id);
END;
$$;

CREATE OR REPLACE FUNCTION public.get_product_verification_queue(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_status text DEFAULT NULL,
  p_search text DEFAULT NULL
)
RETURNS TABLE (
  vendor_item_id uuid,
  vendor_item_code text,
  vendor_item_name text,
  vendor_name text,
  vendor_unit text,
  last_price numeric,
  last_purchased_at date,
  mapping_id uuid,
  internal_product_id uuid,
  restops_product_id text,
  product_name text,
  category_type text,
  category text,
  match_confidence numeric,
  mapping_status text,
  needs_verification boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH vendor_queue AS (
    SELECT
      vi.id AS vendor_item_id,
      vi.vendor_item_code,
      vi.vendor_item_name,
      v.name AS vendor_name,
      vi.vendor_unit,
      vi.last_price,
      vi.last_purchased_at,
      vim.id AS mapping_id,
      vim.internal_product_id,
      p.product_id AS restops_product_id,
      p.name AS product_name,
      public.derive_product_category_type(p.accounting_category, p.category, COALESCE(p.name, vi.vendor_item_name)) AS category_type,
      COALESCE(NULLIF(p.suggested_category, ''), public.derive_product_category(p.category, COALESCE(p.name, vi.vendor_item_name))) AS category,
      COALESCE(p.category_confidence, vi.match_confidence, CASE WHEN vim.is_verified THEN 100 ELSE 0 END) AS match_confidence,
      COALESCE(vi.mapping_status, CASE WHEN vim.id IS NULL THEN 'unmapped' WHEN vim.is_verified THEN 'verified' ELSE 'suggested' END) AS mapping_status,
      (vim.id IS NULL OR COALESCE(vim.is_verified, false) = false OR COALESCE(vi.match_confidence, 0) < 90) AS needs_verification
    FROM public.vendor_items vi
    LEFT JOIN public.vendors v ON v.id = vi.vendor_id
    LEFT JOIN public.vendor_item_mappings vim ON vim.vendor_item_id = vi.id
    LEFT JOIN public.products p ON p.id = vim.internal_product_id AND p.deleted_at IS NULL
    WHERE vi.organization_id = v_org_id
      AND (p_search IS NULL OR vi.vendor_item_name ILIKE '%' || p_search || '%' OR COALESCE(p.name, '') ILIKE '%' || p_search || '%')
      AND (
        p_brand_id IS NULL
        OR p.brand_id IS NOT DISTINCT FROM p_brand_id
        OR p.id IS NULL
      )
      AND (
        p_location_id IS NULL
        OR p.location_id IS NOT DISTINCT FROM p_location_id
        OR p.id IS NULL
      )
  ),
  product_category_queue AS (
    SELECT
      NULL::uuid AS vendor_item_id,
      NULL::text AS vendor_item_code,
      p.name AS vendor_item_name,
      'Product Catalog'::text AS vendor_name,
      p.report_by_unit AS vendor_unit,
      p.latest_price AS last_price,
      p.updated_at::date AS last_purchased_at,
      NULL::uuid AS mapping_id,
      p.id AS internal_product_id,
      p.product_id AS restops_product_id,
      p.name AS product_name,
      COALESCE(p.suggested_category_type, public.derive_product_category_type(p.accounting_category, COALESCE(p.suggested_category, p.category), p.name)) AS category_type,
      COALESCE(NULLIF(p.suggested_category, ''), public.derive_product_category(p.category, p.name)) AS category,
      COALESCE(p.category_confidence, 0) AS match_confidence,
      CASE
        WHEN p.category_review_status = 'pending' THEN 'suggested'
        WHEN p.category_review_status = 'rejected' THEN 'rejected'
        ELSE 'unmapped'
      END AS mapping_status,
      true AS needs_verification
    FROM public.products p
    WHERE p.organization_id = v_org_id
      AND p.deleted_at IS NULL
      AND (p_brand_id IS NULL OR p.brand_id IS NOT DISTINCT FROM p_brand_id)
      AND (p_location_id IS NULL OR p.location_id IS NOT DISTINCT FROM p_location_id)
      AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
      AND (
        p.category_review_status = 'pending'
        OR NULLIF(trim(COALESCE(p.category, '')), '') IS NULL
        OR lower(trim(p.category)) = 'uncategorized'
      )
      AND (p_search IS NULL OR p.name ILIKE '%' || p_search || '%' OR COALESCE(p.suggested_category, '') ILIKE '%' || p_search || '%')
  ),
  queue AS (
    SELECT * FROM vendor_queue vq WHERE vq.needs_verification
    UNION ALL
    SELECT * FROM product_category_queue
  )
  SELECT *
  FROM queue q
  WHERE (p_status IS NULL OR p_status = 'all' OR q.mapping_status = p_status)
  ORDER BY q.last_purchased_at DESC NULLS LAST, q.vendor_item_name;
END;
$$;

CREATE OR REPLACE FUNCTION public.product_accounting_category_for_type(p_category_type text, p_category text DEFAULT NULL)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT CASE
    WHEN p_category_type = 'Beer' THEN '5230'
    WHEN p_category_type = 'Wine' THEN '5240'
    WHEN p_category_type = 'Liquor' THEN '5220'
    WHEN p_category_type = 'N/A Bev' THEN '5210'
    WHEN p_category_type = 'Retail' THEN '5300'
    WHEN lower(COALESCE(p_category, '')) LIKE '%produce%' THEN '5150'
    WHEN lower(COALESCE(p_category, '')) LIKE '%dairy%' THEN '5140'
    WHEN lower(COALESCE(p_category, '')) LIKE '%poultry%' THEN '5120'
    WHEN lower(COALESCE(p_category, '')) LIKE '%seafood%' THEN '5130'
    WHEN lower(COALESCE(p_category, '')) LIKE '%frozen%' THEN '5160'
    WHEN lower(COALESCE(p_category, '')) LIKE '%grocery%' THEN '5170'
    WHEN lower(COALESCE(p_category, '')) LIKE '%dry goods%' THEN '5170'
    ELSE '5110'
  END;
$$;

CREATE OR REPLACE FUNCTION public.normalize_product_category_fields()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_category_type text;
  v_accounting_category text;
  v_should_set_accounting boolean := false;
BEGIN
  IF NULLIF(trim(COALESCE(NEW.category, '')), '') IS NULL
    OR lower(trim(NEW.category)) = 'uncategorized' THEN
    NEW.category := public.derive_product_category(NULL, NEW.name);
    IF NEW.category <> 'Uncategorized' THEN
      NEW.category_source := COALESCE(NULLIF(NEW.category_source, ''), 'rules');
      NEW.category_confidence := COALESCE(NEW.category_confidence, 75);
      NEW.category_review_status := COALESCE(NULLIF(NEW.category_review_status, ''), 'approved');
    END IF;
  END IF;

  v_category_type := public.derive_product_category_type(NEW.accounting_category, NEW.category, NEW.name);
  v_accounting_category := public.product_accounting_category_for_type(v_category_type, NEW.category);

  v_should_set_accounting :=
    TG_OP = 'INSERT'
    OR NULLIF(trim(COALESCE(NEW.accounting_category, '')), '') IS NULL
    OR (NEW.accounting_category = '5100' AND v_accounting_category <> '5110');

  IF TG_OP = 'UPDATE' THEN
    v_should_set_accounting := v_should_set_accounting
      OR (
        COALESCE(OLD.category, '') IS DISTINCT FROM COALESCE(NEW.category, '')
        AND COALESCE(OLD.accounting_category, '') = COALESCE(NEW.accounting_category, '')
      );
  END IF;

  IF v_should_set_accounting THEN
    NEW.accounting_category := v_accounting_category;
  END IF;

  IF NULLIF(trim(COALESCE(NEW.category, '')), '') IS NULL
    OR lower(trim(NEW.category)) = 'uncategorized' THEN
    NEW.category_review_status := 'pending';
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260720000004_fix_product_verification_queue_ambiguity.sql
CREATE OR REPLACE FUNCTION public.get_product_verification_queue(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_status text DEFAULT NULL,
  p_search text DEFAULT NULL
)
RETURNS TABLE (
  vendor_item_id uuid,
  vendor_item_code text,
  vendor_item_name text,
  vendor_name text,
  vendor_unit text,
  last_price numeric,
  last_purchased_at date,
  mapping_id uuid,
  internal_product_id uuid,
  restops_product_id text,
  product_name text,
  category_type text,
  category text,
  match_confidence numeric,
  mapping_status text,
  needs_verification boolean
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH vendor_queue AS (
    SELECT
      vi.id AS vendor_item_id,
      vi.vendor_item_code,
      vi.vendor_item_name,
      v.name AS vendor_name,
      vi.vendor_unit,
      vi.last_price,
      vi.last_purchased_at,
      vim.id AS mapping_id,
      vim.internal_product_id,
      p.product_id AS restops_product_id,
      p.name AS product_name,
      public.derive_product_category_type(p.accounting_category, p.category, COALESCE(p.name, vi.vendor_item_name)) AS category_type,
      COALESCE(NULLIF(p.suggested_category, ''), public.derive_product_category(p.category, COALESCE(p.name, vi.vendor_item_name))) AS category,
      COALESCE(p.category_confidence, vi.match_confidence, CASE WHEN vim.is_verified THEN 100 ELSE 0 END) AS match_confidence,
      COALESCE(vi.mapping_status, CASE WHEN vim.id IS NULL THEN 'unmapped' WHEN vim.is_verified THEN 'verified' ELSE 'suggested' END) AS mapping_status,
      (vim.id IS NULL OR COALESCE(vim.is_verified, false) = false OR COALESCE(vi.match_confidence, 0) < 90) AS needs_verification
    FROM public.vendor_items vi
    LEFT JOIN public.vendors v ON v.id = vi.vendor_id
    LEFT JOIN public.vendor_item_mappings vim ON vim.vendor_item_id = vi.id
    LEFT JOIN public.products p ON p.id = vim.internal_product_id AND p.deleted_at IS NULL
    WHERE vi.organization_id = v_org_id
      AND (p_search IS NULL OR vi.vendor_item_name ILIKE '%' || p_search || '%' OR COALESCE(p.name, '') ILIKE '%' || p_search || '%')
      AND (
        p_brand_id IS NULL
        OR p.brand_id IS NOT DISTINCT FROM p_brand_id
        OR p.id IS NULL
      )
      AND (
        p_location_id IS NULL
        OR p.location_id IS NOT DISTINCT FROM p_location_id
        OR p.id IS NULL
      )
  ),
  product_category_queue AS (
    SELECT
      NULL::uuid AS vendor_item_id,
      NULL::text AS vendor_item_code,
      p.name AS vendor_item_name,
      'Product Catalog'::text AS vendor_name,
      p.report_by_unit AS vendor_unit,
      p.latest_price AS last_price,
      p.updated_at::date AS last_purchased_at,
      NULL::uuid AS mapping_id,
      p.id AS internal_product_id,
      p.product_id AS restops_product_id,
      p.name AS product_name,
      COALESCE(p.suggested_category_type, public.derive_product_category_type(p.accounting_category, COALESCE(p.suggested_category, p.category), p.name)) AS category_type,
      COALESCE(NULLIF(p.suggested_category, ''), public.derive_product_category(p.category, p.name)) AS category,
      COALESCE(p.category_confidence, 0) AS match_confidence,
      CASE
        WHEN p.category_review_status = 'pending' THEN 'suggested'
        WHEN p.category_review_status = 'rejected' THEN 'rejected'
        ELSE 'unmapped'
      END AS mapping_status,
      true AS needs_verification
    FROM public.products p
    WHERE p.organization_id = v_org_id
      AND p.deleted_at IS NULL
      AND (p_brand_id IS NULL OR p.brand_id IS NOT DISTINCT FROM p_brand_id)
      AND (p_location_id IS NULL OR p.location_id IS NOT DISTINCT FROM p_location_id)
      AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
      AND (
        p.category_review_status = 'pending'
        OR NULLIF(trim(COALESCE(p.category, '')), '') IS NULL
        OR lower(trim(p.category)) = 'uncategorized'
      )
      AND (p_search IS NULL OR p.name ILIKE '%' || p_search || '%' OR COALESCE(p.suggested_category, '') ILIKE '%' || p_search || '%')
  ),
  queue AS (
    SELECT * FROM vendor_queue vq WHERE vq.needs_verification
    UNION ALL
    SELECT * FROM product_category_queue
  )
  SELECT *
  FROM queue q
  WHERE (p_status IS NULL OR p_status = 'all' OR q.mapping_status = p_status)
  ORDER BY q.last_purchased_at DESC NULLS LAST, q.vendor_item_name;
END;
$$;

-- Source: 20260720000005_product_catalog_counts_and_inventory_toggle.sql
CREATE OR REPLACE FUNCTION public.get_product_catalog(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_search text DEFAULT NULL,
  p_sort_by text DEFAULT 'name',
  p_page integer DEFAULT 0,
  p_page_size integer DEFAULT 50
)
RETURNS TABLE (
  id uuid,
  product_id text,
  name text,
  description text,
  category text,
  accounting_category text,
  category_confidence numeric,
  category_source text,
  category_review_status text,
  suggested_category text,
  suggested_category_type text,
  suggested_accounting_category text,
  category_reason text,
  is_inventoried boolean,
  is_tax_exempt boolean,
  report_by_unit text,
  base_unit text,
  latest_price numeric,
  location_specific boolean,
  organization_id uuid,
  brand_id uuid,
  location_id uuid,
  created_at timestamptz,
  item_count bigint,
  vendor_item_count bigint,
  inventory_item_id uuid
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_page integer := GREATEST(COALESCE(p_page, 0), 0);
  v_page_size integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 100);
  v_sort_by text := COALESCE(NULLIF(p_sort_by, ''), 'name');
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH product_scope AS (
    SELECT p.*
    FROM public.products p
    WHERE p.organization_id = v_org_id
      AND p.deleted_at IS NULL
      AND (p_brand_id IS NULL OR p.brand_id IS NOT DISTINCT FROM p_brand_id)
      AND (p_location_id IS NULL OR p.location_id IS NOT DISTINCT FROM p_location_id)
      AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
      AND (
        p_search IS NULL
        OR p.name ILIKE '%' || p_search || '%'
        OR COALESCE(p.description, '') ILIKE '%' || p_search || '%'
        OR COALESCE(p.product_id, '') ILIKE '%' || p_search || '%'
      )
  )
  SELECT
    p.id,
    p.product_id,
    p.name,
    p.description,
    p.category,
    p.accounting_category,
    p.category_confidence,
    p.category_source,
    p.category_review_status,
    p.suggested_category,
    p.suggested_category_type,
    p.suggested_accounting_category,
    p.category_reason,
    p.is_inventoried,
    p.is_tax_exempt,
    p.report_by_unit,
    p.base_unit,
    p.latest_price,
    p.location_specific,
    p.organization_id,
    p.brand_id,
    p.location_id,
    p.created_at,
    COALESCE(vic.vendor_item_count, 0) AS item_count,
    COALESCE(vic.vendor_item_count, 0) AS vendor_item_count,
    inv.id AS inventory_item_id
  FROM product_scope p
  LEFT JOIN LATERAL (
    SELECT count(DISTINCT vim.vendor_item_id)::bigint AS vendor_item_count
    FROM public.vendor_item_mappings vim
    JOIN public.vendor_items vi ON vi.id = vim.vendor_item_id
    WHERE vim.internal_product_id = p.id
      AND vi.organization_id = p.organization_id
  ) vic ON true
  LEFT JOIN LATERAL (
    SELECT i.id
    FROM public.inventory i
    WHERE i.organization_id = p.organization_id
      AND i.deleted_at IS NULL
      AND (
        i.internal_product_id = p.id
        OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = p.product_id)
      )
      AND (p.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM p.location_id)
    ORDER BY
      CASE WHEN i.internal_product_id = p.id THEN 0 ELSE 1 END,
      i.updated_at DESC NULLS LAST,
      i.created_at DESC NULLS LAST
    LIMIT 1
  ) inv ON true
  ORDER BY
    CASE WHEN v_sort_by = 'name' THEN p.name END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-name' THEN p.name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'category' THEN p.category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-category' THEN p.category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'accounting_category' THEN p.accounting_category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-accounting_category' THEN p.accounting_category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'is_inventoried' THEN p.is_inventoried END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-is_inventoried' THEN p.is_inventoried END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'latest_price' THEN p.latest_price END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-latest_price' THEN p.latest_price END DESC NULLS LAST,
    p.name ASC NULLS LAST,
    p.created_at DESC NULLS LAST
  LIMIT v_page_size
  OFFSET v_page * v_page_size;
END;
$$;

CREATE OR REPLACE FUNCTION public.set_product_inventory_tracking(
  p_product_id uuid,
  p_is_inventoried boolean
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_inventory_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Product not found');
  END IF;

  IF NOT public.reference_scope_writable(
    v_product.organization_id,
    v_product.brand_id,
    v_product.location_id,
    v_product.deleted_at,
    'location_manager'
  ) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  UPDATE public.products
     SET is_inventoried = COALESCE(p_is_inventoried, false),
         updated_at = now()
   WHERE id = p_product_id;

  IF COALESCE(p_is_inventoried, false) THEN
    SELECT i.id
      INTO v_inventory_id
    FROM public.inventory i
    WHERE i.organization_id = v_product.organization_id
      AND (
        i.internal_product_id = v_product.id
        OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = v_product.product_id)
      )
      AND (v_product.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM v_product.location_id)
    ORDER BY
      CASE WHEN i.deleted_at IS NULL THEN 0 ELSE 1 END,
      CASE WHEN i.internal_product_id = v_product.id THEN 0 ELSE 1 END,
      i.updated_at DESC NULLS LAST,
      i.created_at DESC NULLS LAST
    LIMIT 1;

    IF v_inventory_id IS NULL THEN
      INSERT INTO public.inventory (
        organization_id,
        brand_id,
        location_id,
        internal_product_id,
        product_id,
        product_name,
        category,
        accounting_category,
        current_quantity,
        current_unit,
        current_value,
        unit_cost,
        par_level,
        reorder_point,
        report_by,
        deleted_at,
        updated_at
      ) VALUES (
        v_product.organization_id,
        v_product.brand_id,
        v_product.location_id,
        v_product.id,
        v_product.product_id,
        v_product.name,
        v_product.category,
        v_product.accounting_category,
        0,
        COALESCE(NULLIF(v_product.report_by_unit, ''), NULLIF(v_product.base_unit, ''), 'Each'),
        0,
        COALESCE(v_product.latest_price, 0),
        v_product.par_level,
        v_product.reorder_point,
        COALESCE(NULLIF(v_product.report_by_unit, ''), NULLIF(v_product.base_unit, ''), 'Each'),
        NULL,
        now()
      )
      RETURNING id INTO v_inventory_id;
    ELSE
      UPDATE public.inventory
         SET internal_product_id = COALESCE(internal_product_id, v_product.id),
             product_id = COALESCE(NULLIF(product_id, ''), v_product.product_id),
             product_name = COALESCE(NULLIF(product_name, ''), v_product.name),
             category = COALESCE(NULLIF(category, ''), v_product.category),
             accounting_category = COALESCE(NULLIF(accounting_category, ''), v_product.accounting_category),
             current_unit = COALESCE(NULLIF(current_unit, ''), NULLIF(v_product.report_by_unit, ''), NULLIF(v_product.base_unit, ''), 'Each'),
             unit_cost = COALESCE(unit_cost, v_product.latest_price, 0),
             report_by = COALESCE(NULLIF(report_by, ''), NULLIF(v_product.report_by_unit, ''), NULLIF(v_product.base_unit, ''), 'Each'),
             deleted_at = NULL,
             deleted_by = NULL,
             updated_at = now()
       WHERE id = v_inventory_id;
    END IF;
  ELSE
    UPDATE public.inventory i
       SET deleted_at = COALESCE(i.deleted_at, now()),
           deleted_by = COALESCE(i.deleted_by, auth.uid()),
           updated_at = now()
     WHERE i.organization_id = v_product.organization_id
       AND i.deleted_at IS NULL
       AND (
         i.internal_product_id = v_product.id
         OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = v_product.product_id)
       )
       AND (v_product.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM v_product.location_id);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'product_id', p_product_id,
    'is_inventoried', COALESCE(p_is_inventoried, false),
    'inventory_item_id', v_inventory_id
  );
END;
$$;

-- Source: 20260720000007_fix_inventory_toggle_tenant_roles.sql
CREATE OR REPLACE FUNCTION public.set_product_inventory_tracking(
  p_product_id uuid,
  p_is_inventoried boolean
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_inventory_id uuid;
  v_role text;
  v_user_org_id uuid;
  v_user_tenant_id uuid;
  v_user_brand_id uuid;
  v_user_location_id uuid;
  v_product_tenant_id uuid;
  v_can_write boolean := false;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Product not found');
  END IF;

  SELECT
    public.normalize_app_role(p.role),
    p.organization_id,
    p.tenant_id,
    p.brand_id,
    p.location_id
    INTO v_role, v_user_org_id, v_user_tenant_id, v_user_brand_id, v_user_location_id
  FROM public.profiles p
  WHERE p.id = auth.uid()
    AND p.deleted_at IS NULL;

  IF v_user_tenant_id IS NULL AND v_user_org_id IS NOT NULL THEN
    SELECT o.tenant_id INTO v_user_tenant_id
    FROM public.organizations o
    WHERE o.id = v_user_org_id;
  END IF;

  SELECT o.tenant_id INTO v_product_tenant_id
  FROM public.organizations o
  WHERE o.id = v_product.organization_id;

  v_can_write := CASE
    WHEN v_role = 'platform_admin' THEN true
    WHEN v_role = 'tenant_super_admin' THEN v_user_tenant_id IS NOT NULL AND v_product_tenant_id = v_user_tenant_id
    WHEN v_role = 'org_manager' THEN v_user_org_id = v_product.organization_id
    WHEN v_role = 'branch_manager' THEN v_user_org_id = v_product.organization_id AND (v_product.brand_id IS NULL OR v_product.brand_id = v_user_brand_id)
    WHEN v_role = 'location_manager' THEN v_user_org_id = v_product.organization_id AND (v_product.location_id IS NULL OR v_product.location_id = v_user_location_id)
    ELSE false
  END;

  IF NOT v_can_write THEN
    RAISE EXCEPTION 'Not authorized to update inventory tracking for this product';
  END IF;

  UPDATE public.products
     SET is_inventoried = COALESCE(p_is_inventoried, false),
         updated_at = now()
   WHERE id = p_product_id;

  IF COALESCE(p_is_inventoried, false) THEN
    SELECT i.id
      INTO v_inventory_id
    FROM public.inventory i
    WHERE i.organization_id = v_product.organization_id
      AND (
        i.internal_product_id = v_product.id
        OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = v_product.product_id)
      )
      AND (v_product.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM v_product.location_id)
    ORDER BY
      CASE WHEN i.deleted_at IS NULL THEN 0 ELSE 1 END,
      CASE WHEN i.internal_product_id = v_product.id THEN 0 ELSE 1 END,
      i.updated_at DESC NULLS LAST,
      i.created_at DESC NULLS LAST
    LIMIT 1;

    IF v_inventory_id IS NULL THEN
      INSERT INTO public.inventory (
        organization_id,
        brand_id,
        location_id,
        internal_product_id,
        product_id,
        product_name,
        category,
        accounting_category,
        current_quantity,
        current_unit,
        current_value,
        unit_cost,
        par_level,
        reorder_point,
        report_by,
        deleted_at,
        updated_at
      ) VALUES (
        v_product.organization_id,
        v_product.brand_id,
        v_product.location_id,
        v_product.id,
        v_product.product_id,
        v_product.name,
        v_product.category,
        v_product.accounting_category,
        0,
        COALESCE(NULLIF(v_product.report_by_unit, ''), NULLIF(v_product.base_unit, ''), 'Each'),
        0,
        COALESCE(v_product.latest_price, 0),
        v_product.par_level,
        v_product.reorder_point,
        COALESCE(NULLIF(v_product.report_by_unit, ''), NULLIF(v_product.base_unit, ''), 'Each'),
        NULL,
        now()
      )
      RETURNING id INTO v_inventory_id;
    ELSE
      UPDATE public.inventory
         SET internal_product_id = COALESCE(internal_product_id, v_product.id),
             product_id = COALESCE(NULLIF(product_id, ''), v_product.product_id),
             product_name = COALESCE(NULLIF(product_name, ''), v_product.name),
             category = COALESCE(NULLIF(category, ''), v_product.category),
             accounting_category = COALESCE(NULLIF(accounting_category, ''), v_product.accounting_category),
             current_unit = COALESCE(NULLIF(current_unit, ''), NULLIF(v_product.report_by_unit, ''), NULLIF(v_product.base_unit, ''), 'Each'),
             unit_cost = COALESCE(unit_cost, v_product.latest_price, 0),
             report_by = COALESCE(NULLIF(report_by, ''), NULLIF(v_product.report_by_unit, ''), NULLIF(v_product.base_unit, ''), 'Each'),
             deleted_at = NULL,
             deleted_by = NULL,
             updated_at = now()
       WHERE id = v_inventory_id;
    END IF;
  ELSE
    UPDATE public.inventory i
       SET deleted_at = COALESCE(i.deleted_at, now()),
           deleted_by = COALESCE(i.deleted_by, auth.uid()),
           updated_at = now()
     WHERE i.organization_id = v_product.organization_id
       AND i.deleted_at IS NULL
       AND (
         i.internal_product_id = v_product.id
         OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = v_product.product_id)
       )
       AND (v_product.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM v_product.location_id);
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'product_id', p_product_id,
    'is_inventoried', COALESCE(p_is_inventoried, false),
    'inventory_item_id', v_inventory_id
  );
END;
$$;

-- Source: 20260720000008_product_edit_rpc.sql
CREATE OR REPLACE FUNCTION public.product_write_allowed(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_user_org_id uuid;
  v_user_tenant_id uuid;
  v_user_brand_id uuid;
  v_user_location_id uuid;
  v_target_tenant_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT
    public.normalize_app_role(p.role),
    p.organization_id,
    p.tenant_id,
    p.brand_id,
    p.location_id
    INTO v_role, v_user_org_id, v_user_tenant_id, v_user_brand_id, v_user_location_id
  FROM public.profiles p
  WHERE p.id = auth.uid()
    AND p.deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  IF v_user_tenant_id IS NULL AND v_user_org_id IS NOT NULL THEN
    SELECT o.tenant_id INTO v_user_tenant_id
    FROM public.organizations o
    WHERE o.id = v_user_org_id;
  END IF;

  SELECT o.tenant_id INTO v_target_tenant_id
  FROM public.organizations o
  WHERE o.id = p_organization_id;

  IF v_role = 'tenant_super_admin' THEN
    RETURN v_user_tenant_id IS NOT NULL AND v_target_tenant_id = v_user_tenant_id;
  END IF;

  IF v_user_org_id IS DISTINCT FROM p_organization_id THEN
    RETURN false;
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN true;
  END IF;

  IF v_role = 'branch_manager' THEN
    RETURN p_brand_id IS NULL OR v_user_brand_id = p_brand_id;
  END IF;

  IF v_role = 'location_manager' THEN
    RETURN p_location_id IS NULL OR v_user_location_id = p_location_id;
  END IF;

  RETURN false;
END;
$$;

DROP FUNCTION IF EXISTS public.update_product_details;

CREATE OR REPLACE FUNCTION public.update_product_details(
  p_product_id uuid,
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT NULL,
  p_is_tax_exempt boolean DEFAULT NULL,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT NULL,
  p_location_specific boolean DEFAULT NULL
)
RETURNS public.products
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_updated public.products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  IF NULLIF(trim(p_name), '') IS NULL THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  UPDATE public.products
     SET name = NULLIF(trim(p_name), ''),
         product_id = NULLIF(trim(COALESCE(p_restops_product_id, '')), ''),
         description = NULLIF(trim(COALESCE(p_description, '')), ''),
         category = NULLIF(trim(COALESCE(p_category, '')), ''),
         accounting_category = NULLIF(trim(COALESCE(p_accounting_category, '')), ''),
         is_tax_exempt = COALESCE(p_is_tax_exempt, false),
         report_by_unit = NULLIF(trim(COALESCE(p_report_by_unit, '')), ''),
         base_unit = NULLIF(trim(COALESCE(p_base_unit, '')), ''),
         latest_price = COALESCE(p_latest_price, 0),
         location_specific = COALESCE(p_location_specific, false),
         updated_at = now()
   WHERE id = p_product_id
   RETURNING * INTO v_updated;

  IF p_is_inventoried IS NOT NULL AND p_is_inventoried IS DISTINCT FROM v_product.is_inventoried THEN
    PERFORM public.set_product_inventory_tracking(p_product_id, p_is_inventoried);

    SELECT *
      INTO v_updated
    FROM public.products
    WHERE id = p_product_id;
  ELSIF p_is_inventoried IS NOT NULL THEN
    UPDATE public.products
       SET is_inventoried = p_is_inventoried,
           updated_at = now()
     WHERE id = p_product_id
     RETURNING * INTO v_updated;
  END IF;

  RETURN v_updated;
END;
$$;

-- Source: 20260720000009_product_create_rpc_and_uppercase_names.sql
DROP FUNCTION IF EXISTS public.create_product_details;

CREATE OR REPLACE FUNCTION public.create_product_details(
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT true,
  p_is_tax_exempt boolean DEFAULT false,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT NULL,
  p_location_specific boolean DEFAULT false,
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS public.products
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_brand_id uuid := p_brand_id;
  v_location_id uuid := p_location_id;
  v_product_id text := NULLIF(trim(COALESCE(p_restops_product_id, '')), '');
  v_created public.products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NULLIF(trim(COALESCE(p_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  IF v_brand_id IS NULL THEN
    SELECT p.brand_id INTO v_brand_id
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.organization_id = v_org_id
      AND p.deleted_at IS NULL;
  END IF;

  IF v_location_id IS NULL THEN
    SELECT p.location_id INTO v_location_id
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.organization_id = v_org_id
      AND p.deleted_at IS NULL;
  END IF;

  IF NOT public.product_write_allowed(v_org_id, v_brand_id, v_location_id) THEN
    RAISE EXCEPTION 'Not authorized to create products for this scope';
  END IF;

  IF v_product_id IS NULL THEN
    v_product_id := public.generate_restops_product_id();
  END IF;

  INSERT INTO public.products (
    organization_id,
    brand_id,
    location_id,
    product_id,
    name,
    description,
    category,
    accounting_category,
    is_inventoried,
    is_tax_exempt,
    report_by_unit,
    base_unit,
    latest_price,
    location_specific,
    updated_at
  ) VALUES (
    v_org_id,
    v_brand_id,
    v_location_id,
    v_product_id,
    upper(trim(p_name)),
    NULLIF(trim(COALESCE(p_description, '')), ''),
    NULLIF(trim(COALESCE(p_category, '')), ''),
    NULLIF(trim(COALESCE(p_accounting_category, '')), ''),
    COALESCE(p_is_inventoried, false),
    COALESCE(p_is_tax_exempt, false),
    NULLIF(trim(COALESCE(p_report_by_unit, '')), ''),
    NULLIF(trim(COALESCE(p_base_unit, '')), ''),
    COALESCE(p_latest_price, 0),
    COALESCE(p_location_specific, false),
    now()
  )
  RETURNING * INTO v_created;

  IF COALESCE(p_is_inventoried, false) THEN
    PERFORM public.set_product_inventory_tracking(v_created.id, true);

    SELECT *
      INTO v_created
    FROM public.products
    WHERE id = v_created.id;
  END IF;

  RETURN v_created;
END;
$$;

