-- Source: 20260722000007_preserve_invoice_extraction_state_for_paid_uploads.sql
CREATE OR REPLACE FUNCTION public.normalize_invoice_ap_state()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.status = 'approved' THEN
    NEW.ap_status := 'approved';
  ELSIF NEW.status = 'scheduled' THEN
    NEW.ap_status := 'scheduled';
  ELSIF NEW.status = 'paid' THEN
    NEW.ap_status := 'paid';
    NEW.payment_status := 'paid';
  ELSIF NEW.status = 'rejected' THEN
    IF COALESCE(NEW.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing')
      OR COALESCE(NEW.paid_amount, 0) > 0 THEN
      RAISE EXCEPTION 'Rejected invoices cannot carry paid or in-flight payment state';
    END IF;
    NEW.ap_status := 'rejected';
  END IF;

  IF NEW.payment_status = 'paid'
     AND COALESCE(NEW.status, '') NOT IN ('extracting', 'extract_failed') THEN
    NEW.status := 'paid';
    NEW.ap_status := 'paid';
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260722000009_allow_extraction_updates_for_paid_uploads.sql
CREATE OR REPLACE FUNCTION public.guard_locked_invoice_financial_fields()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF COALESCE(OLD.status, '') NOT IN ('extracting', 'extract_failed')
    AND (
      OLD.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
      OR OLD.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
      OR COALESCE(OLD.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
      OR COALESCE(OLD.paid_amount, 0) > 0
    ) THEN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id
      OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
      OR NEW.brand_id IS DISTINCT FROM OLD.brand_id
      OR NEW.location_id IS DISTINCT FROM OLD.location_id
      OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id
      OR NEW.vendor_name IS DISTINCT FROM OLD.vendor_name
      OR NEW.invoice_number IS DISTINCT FROM OLD.invoice_number
      OR NEW.invoice_date IS DISTINCT FROM OLD.invoice_date
      OR NEW.due_date IS DISTINCT FROM OLD.due_date
      OR NEW.total_amount IS DISTINCT FROM OLD.total_amount
      OR NEW.subtotal IS DISTINCT FROM OLD.subtotal
      OR NEW.tax_amount IS DISTINCT FROM OLD.tax_amount
      OR NEW.delivery_fee IS DISTINCT FROM OLD.delivery_fee
      OR NEW.fuel_surcharge IS DISTINCT FROM OLD.fuel_surcharge
      OR NEW.other_charges IS DISTINCT FROM OLD.other_charges
      OR NEW.currency IS DISTINCT FROM OLD.currency
      OR NEW.account_number IS DISTINCT FROM OLD.account_number
      OR NEW.purchase_order_id IS DISTINCT FROM OLD.purchase_order_id
      OR NEW.line_items IS DISTINCT FROM OLD.line_items THEN
      RAISE EXCEPTION 'Approved, scheduled, partially paid, or paid invoice financial fields are immutable';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260722000010_configurable_payment_approval_controls.sql
CREATE OR REPLACE FUNCTION public.get_payment_approval_settings(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE((
    SELECT os.settings
    FROM public.operational_settings os
    WHERE os.organization_id = p_organization_id
      AND os.category = 'payments'
      AND (
        (p_location_id IS NOT NULL AND os.location_id = p_location_id)
        OR (p_brand_id IS NOT NULL AND os.brand_id = p_brand_id AND os.location_id IS NULL)
        OR (os.brand_id IS NULL AND os.location_id IS NULL)
      )
    ORDER BY
      CASE
        WHEN p_location_id IS NOT NULL AND os.location_id = p_location_id THEN 1
        WHEN p_brand_id IS NOT NULL AND os.brand_id = p_brand_id AND os.location_id IS NULL THEN 2
        ELSE 3
      END,
      os.updated_at DESC NULLS LAST
    LIMIT 1
  ), '{}'::jsonb);
$$;

CREATE OR REPLACE FUNCTION public.enforce_invoice_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor_autopay boolean;
  v_settings jsonb;
  v_require_separate_approver boolean;
  v_enforce_approval_limits boolean;
  v_user_limit numeric;
  v_has_unlimited boolean;
  v_amount numeric;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'approved' OR NEW.ap_status = 'approved' THEN
      v_settings := public.get_payment_approval_settings(NEW.organization_id, NEW.brand_id, NEW.location_id);
      v_require_separate_approver := COALESCE((v_settings->>'requireSeparateApprover')::boolean, false);
      v_enforce_approval_limits := COALESCE((v_settings->>'enforceApprovalLimits')::boolean, false);

      IF v_require_separate_approver
        AND NEW.created_by IS NOT NULL
        AND NEW.created_by = auth.uid() THEN
        RAISE EXCEPTION 'Invoice submitters cannot approve their own invoices';
      END IF;

      PERFORM public.assert_can_approve_invoice_scope(
        NEW.organization_id,
        NEW.brand_id,
        NEW.location_id
      );

      IF v_enforce_approval_limits THEN
        SELECT invoice_approval_limit, COALESCE(has_unlimited_approval, false)
          INTO v_user_limit, v_has_unlimited
        FROM public.profiles
        WHERE id = auth.uid()
          AND deleted_at IS NULL;

        v_amount := COALESCE(NEW.total_amount, 0);
        IF NOT COALESCE(v_has_unlimited, false)
          AND (v_user_limit IS NULL OR v_amount > v_user_limit) THEN
          RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.',
            COALESCE(v_user_limit, 0), v_amount;
        END IF;
      END IF;

      SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
      IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
        RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF (NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved')
    OR (NEW.ap_status = 'approved' AND OLD.ap_status IS DISTINCT FROM 'approved') THEN
    v_settings := public.get_payment_approval_settings(NEW.organization_id, NEW.brand_id, NEW.location_id);
    v_require_separate_approver := COALESCE((v_settings->>'requireSeparateApprover')::boolean, false);
    v_enforce_approval_limits := COALESCE((v_settings->>'enforceApprovalLimits')::boolean, false);

    IF v_require_separate_approver
      AND COALESCE(OLD.created_by, NEW.created_by) IS NOT NULL
      AND COALESCE(OLD.created_by, NEW.created_by) = auth.uid() THEN
      RAISE EXCEPTION 'Invoice submitters cannot approve their own invoices';
    END IF;

    PERFORM public.assert_can_approve_invoice_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );

    IF v_enforce_approval_limits THEN
      SELECT invoice_approval_limit, COALESCE(has_unlimited_approval, false)
        INTO v_user_limit, v_has_unlimited
      FROM public.profiles
      WHERE id = auth.uid()
        AND deleted_at IS NULL;

      v_amount := COALESCE(NEW.total_amount, OLD.total_amount, 0);
      IF NOT COALESCE(v_has_unlimited, false)
        AND (v_user_limit IS NULL OR v_amount > v_user_limit) THEN
        RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.',
          COALESCE(v_user_limit, 0), v_amount;
      END IF;
    END IF;

    SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
    IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
      RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260722000011_allow_internal_product_sync_after_invoice_approval.sql
CREATE OR REPLACE FUNCTION public.guard_locked_invoice_line_items()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invoice record;
  v_invoice_id uuid;
BEGIN
  IF current_setting('app.invoice_product_sync', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);

  SELECT status, ap_status, payment_status, paid_amount
    INTO v_invoice
  FROM public.invoices
  WHERE id = v_invoice_id;

  IF v_invoice.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
    OR v_invoice.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
    OR COALESCE(v_invoice.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
    OR COALESCE(v_invoice.paid_amount, 0) > 0 THEN
    RAISE EXCEPTION 'Invoice line items are immutable after approval or payment activity';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE OR REPLACE FUNCTION public.trigger_sync_invoice_products()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF (TG_OP = 'UPDATE' AND NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved') THEN
    PERFORM set_config('app.invoice_product_sync', 'on', true);
    PERFORM public.sync_invoice_products(NEW.id);
    PERFORM set_config('app.invoice_product_sync', '', true);
  END IF;

  IF (TG_OP = 'INSERT' AND NEW.status = 'approved') THEN
    PERFORM set_config('app.invoice_product_sync', 'on', true);
    PERFORM public.sync_invoice_products(NEW.id);
    PERFORM set_config('app.invoice_product_sync', '', true);
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.invoice_product_sync', '', true);
  RAISE;
END;
$$;

-- Source: 20260722000012_sync_approved_invoice_products_to_inventory.sql
CREATE OR REPLACE FUNCTION public.ensure_inventory_for_invoiced_products(p_invoice_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_created_count integer := 0;
  v_marked_count integer := 0;
BEGIN
  WITH invoice_products AS (
    SELECT DISTINCT
      i.organization_id,
      i.brand_id,
      i.location_id,
      l.name AS location_name,
      p.id AS internal_product_id,
      p.product_id,
      p.name AS product_name,
      p.category,
      p.accounting_category,
      COALESCE(p.report_by_unit, p.base_unit, 'Each') AS unit,
      COALESCE(p.latest_price, 0) AS unit_cost
    FROM public.invoices i
    JOIN public.invoice_line_items ili ON ili.invoice_id = i.id
    JOIN public.products p ON p.id = ili.internal_product_id
    LEFT JOIN public.locations l ON l.id = i.location_id
    WHERE i.id = p_invoice_id
      AND i.deleted_at IS NULL
      AND p.deleted_at IS NULL
      AND ili.internal_product_id IS NOT NULL
  ), marked AS (
    UPDATE public.products p
       SET is_inventoried = true,
           updated_at = now()
      FROM invoice_products ip
     WHERE p.id = ip.internal_product_id
       AND COALESCE(p.is_inventoried, false) IS DISTINCT FROM true
    RETURNING p.id
  ), inserted AS (
    INSERT INTO public.inventory (
      organization_id,
      brand_id,
      location_id,
      internal_product_id,
      product_id,
      product_name,
      category,
      accounting_category,
      location,
      current_quantity,
      current_unit,
      current_value,
      previous_quantity,
      previous_value,
      unit_cost,
      report_by,
      conversion_rates,
      created_at,
      updated_at
    )
    SELECT
      ip.organization_id,
      ip.brand_id,
      ip.location_id,
      ip.internal_product_id,
      ip.product_id,
      ip.product_name,
      ip.category,
      ip.accounting_category,
      ip.location_name,
      0,
      ip.unit,
      0,
      0,
      0,
      ip.unit_cost,
      ip.unit,
      '{}'::jsonb,
      now(),
      now()
    FROM invoice_products ip
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.inventory inv
      WHERE inv.organization_id = ip.organization_id
        AND inv.location_id IS NOT DISTINCT FROM ip.location_id
        AND inv.internal_product_id = ip.internal_product_id
        AND inv.deleted_at IS NULL
    )
    RETURNING id
  )
  SELECT
    (SELECT count(*) FROM marked),
    (SELECT count(*) FROM inserted)
  INTO v_marked_count, v_created_count;

  RETURN jsonb_build_object(
    'status', 'success',
    'marked_products_count', v_marked_count,
    'created_inventory_count', v_created_count
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.trigger_sync_invoice_products()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF (TG_OP = 'UPDATE' AND NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved') THEN
    PERFORM set_config('app.invoice_product_sync', 'on', true);
