    PERFORM set_config('app.invoice_product_sync', 'on', true);
    PERFORM public.sync_invoice_products(NEW.id);
    PERFORM public.ensure_inventory_for_invoiced_products(NEW.id);
    PERFORM set_config('app.invoice_product_sync', '', true);
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.invoice_product_sync', '', true);
  RAISE;
END;
$$;

-- Source: 20260722000013_allow_tenant_super_admin_invoice_org_guard.sql
-- Invoice intake/document RPCs still depend on assert_org_actor(), which only
-- allowed profile.organization_id unless the caller was platform_admin. Tenant
-- super admins can switch into sibling organizations in the same tenant, so the
-- org guard must honor tenant ownership instead of treating that as cross-org.
CREATE OR REPLACE FUNCTION public.assert_org_actor(p_organization_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = ''
AS $$
DECLARE
  v_role TEXT;
  v_profile_org UUID;
  v_profile_tenant UUID;
  v_org_tenant UUID;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  SELECT public.normalize_app_role(p.role), p.organization_id, p.tenant_id
    INTO v_role, v_profile_org, v_profile_tenant
  FROM public.profiles p
  WHERE p.id = auth.uid()
    AND p.deleted_at IS NULL;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    SELECT o.tenant_id
      INTO v_org_tenant
    FROM public.organizations o
    WHERE o.id = p_organization_id;

    IF COALESCE(v_profile_tenant, public.get_auth_tenant()) IS NOT DISTINCT FROM v_org_tenant THEN
      RETURN;
    END IF;

    RAISE EXCEPTION 'Cross-tenant access denied';
  END IF;

  IF v_profile_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization access denied';
  END IF;
END;
$$;

-- Source: 20260722000014_org_level_reference_scope_visible.sql
-- Organization-level reference rows (brand_id IS NULL AND location_id IS NULL) are the
-- default product shape for many tenants. 20260721191500 made every reference row require
-- an active location and then returned false for this org-level tier, so Products /
-- get_product_catalog could hide an entire org catalog even though rows exist.
--
-- After this change:
--   * Same organization only (tenant/org isolation unchanged via organization_id match)
--   * Org-level rows are visible to callers in that organization (no location required)
--   * Brand-shared / location-specific rows still require an active location and match
--     the previous exact brand / location rules
--
-- Also widen get_product_catalog's optional brand/location filters so passing the active
-- brand/location (Products page + Recipe Unit Conversion) still includes ancestor scopes:
-- org-level and brand-shared rows remain in the catalog alongside exact location matches.

CREATE OR REPLACE FUNCTION public.reference_scope_visible(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_deleted_at timestamp with time zone DEFAULT NULL
)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_role text;
  v_org_id uuid;
  v_location_id uuid;
  v_active_location_brand_id uuid;
BEGIN
  IF p_deleted_at IS NOT NULL THEN
    RETURN false;
  END IF;

  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id, location_id
    INTO v_role, v_org_id, v_location_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  -- Tenant / organization isolation: never leak across organizations.
  IF p_organization_id IS NULL OR p_organization_id IS DISTINCT FROM v_org_id THEN
    RETURN false;
  END IF;

  -- Organization-level reference row (shared across the org catalog).
  IF p_brand_id IS NULL AND p_location_id IS NULL THEN
    RETURN true;
  END IF;

  -- Brand-shared and location-specific rows still require an active location.
  IF v_location_id IS NULL THEN
    RETURN false;
  END IF;

  -- Location-specific reference row: exact match.
  IF p_location_id IS NOT NULL THEN
    RETURN p_location_id = v_location_id;
  END IF;

  -- Brand-shared reference row (location intentionally NULL): visible when it matches the
  -- brand of the caller's currently active location.
  IF p_brand_id IS NOT NULL THEN
    SELECT l.brand_id INTO v_active_location_brand_id
    FROM public.locations l
    WHERE l.id = v_location_id;

    RETURN p_brand_id IS NOT NULL AND p_brand_id = v_active_location_brand_id;
  END IF;

  RETURN false;
END;
$$;

-- Keep Products and Recipe Unit Conversion on the same inclusive catalog when the UI
-- passes the active brand/location context.
DROP FUNCTION IF EXISTS public.get_product_catalog(uuid, uuid, uuid, text, text, integer, integer);

CREATE OR REPLACE FUNCTION public.get_product_catalog(
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_search text DEFAULT NULL,
  p_sort_by text DEFAULT 'name',
  p_page integer DEFAULT 0,
  p_page_size integer DEFAULT 50
)
RETURNS TABLE (
  id uuid,
  product_id text,
  name text,
  description text,
  category text,
  accounting_category text,
  category_confidence numeric,
  category_source text,
  category_review_status text,
  suggested_category text,
  suggested_category_type text,
  suggested_accounting_category text,
  category_reason text,
  is_inventoried boolean,
  is_tax_exempt boolean,
  report_by_unit text,
  base_unit text,
  latest_price numeric,
  location_specific boolean,
  organization_id uuid,
  brand_id uuid,
  location_id uuid,
  created_at timestamptz,
  item_count bigint,
  vendor_item_count bigint,
  inventory_item_id uuid,
  vendor_name text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_page integer := GREATEST(COALESCE(p_page, 0), 0);
  v_page_size integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 100);
  v_sort_by text := COALESCE(NULLIF(p_sort_by, ''), 'name');
BEGIN
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  RETURN QUERY
  WITH product_scope AS (
    SELECT p.*
    FROM public.products p
    WHERE p.organization_id = v_org_id
      AND p.deleted_at IS NULL
      -- Inclusive hierarchy filter: org-level + matching brand-shared + exact location.
      AND (
        p_brand_id IS NULL
        OR p.brand_id IS NULL
        OR p.brand_id IS NOT DISTINCT FROM p_brand_id
      )
      AND (
        p_location_id IS NULL
        OR p.location_id IS NULL
        OR p.location_id IS NOT DISTINCT FROM p_location_id
      )
      AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
      AND (
        p_search IS NULL
        OR p.name ILIKE '%' || p_search || '%'
        OR COALESCE(p.description, '') ILIKE '%' || p_search || '%'
        OR COALESCE(p.product_id, '') ILIKE '%' || p_search || '%'
      )
  )
  SELECT
    p.id,
    p.product_id,
    p.name,
    p.description,
    p.category,
    p.accounting_category,
    p.category_confidence,
    p.category_source,
    p.category_review_status,
    p.suggested_category,
    p.suggested_category_type,
    p.suggested_accounting_category,
    p.category_reason,
    p.is_inventoried,
    p.is_tax_exempt,
    p.report_by_unit,
    p.base_unit,
    p.latest_price,
    p.location_specific,
    p.organization_id,
    p.brand_id,
    p.location_id,
    p.created_at,
    COALESCE(vendor_info.vendor_item_count, 0) AS item_count,
    COALESCE(vendor_info.vendor_item_count, 0) AS vendor_item_count,
    inv.id AS inventory_item_id,
    vendor_info.vendor_name
  FROM product_scope p
  LEFT JOIN LATERAL (
    SELECT
      count(DISTINCT vim.vendor_item_id)::bigint AS vendor_item_count,
      string_agg(DISTINCT v.name, ', ' ORDER BY v.name) AS vendor_name
    FROM public.vendor_item_mappings vim
    JOIN public.vendor_items vi ON vi.id = vim.vendor_item_id
    LEFT JOIN public.vendors v ON v.id = vi.vendor_id
    WHERE vim.internal_product_id = p.id
      AND vim.organization_id = p.organization_id
      AND vi.organization_id = p.organization_id
  ) vendor_info ON true
  LEFT JOIN LATERAL (
    SELECT i.id
    FROM public.inventory i
    WHERE i.organization_id = p.organization_id
      AND i.deleted_at IS NULL
      AND (
        i.internal_product_id = p.id
        OR (NULLIF(i.product_id, '') IS NOT NULL AND i.product_id = p.product_id)
      )
      AND (p.location_id IS NULL OR i.location_id IS NULL OR i.location_id IS NOT DISTINCT FROM p.location_id)
    ORDER BY
      CASE WHEN i.internal_product_id = p.id THEN 0 ELSE 1 END,
      i.updated_at DESC NULLS LAST,
      i.created_at DESC NULLS LAST
    LIMIT 1
  ) inv ON true
  ORDER BY
    CASE WHEN v_sort_by = 'name' THEN p.name END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-name' THEN p.name END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'category' THEN p.category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-category' THEN p.category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'accounting_category' THEN p.accounting_category END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-accounting_category' THEN p.accounting_category END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'is_inventoried' THEN p.is_inventoried END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-is_inventoried' THEN p.is_inventoried END DESC NULLS LAST,
    CASE WHEN v_sort_by = 'latest_price' THEN p.latest_price END ASC NULLS LAST,
    CASE WHEN v_sort_by = '-latest_price' THEN p.latest_price END DESC NULLS LAST,
    p.name ASC NULLS LAST,
    p.created_at DESC NULLS LAST
  LIMIT v_page_size
  OFFSET v_page * v_page_size;
END;
$$;

-- Source: 20260722000015_audit_logs_hierarchy_visibility.sql
-- 2. New hierarchy predicate. Structured like tenant_scope_visible()/reference_scope_visible()
--    (one profile lookup up front) but each role gets its own real rule rather than collapsing
--    to one -- so the NULL-tier (org-level, brand+location both NULL) behavior falls out for
--    free: org_manager/tenant_super_admin never look at brand/location at all (see it),
--    branch_manager/location_manager/ground_staff all hard-require their column non-null
--    (don't see it) -- no special-cased carve-out needed, unlike tenant_scope_visible().
--
--    ground_staff note: get_my_accessible_location_ids() has no ground_staff branch (it's
--    manager-tier only, matching is_manager_or_above() excluding ground_staff elsewhere on
--    purpose) -- composing it alone would silently give ground_staff zero visibility. Fixed
--    with a local OR-fallback against the caller's own profiles.location_id (already fetched
--    above for the org-match guard, so this is free) instead of touching the shared helper,
--    which has unrelated callers across many other migrations.
CREATE OR REPLACE FUNCTION public.audit_log_scope_visible(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL::uuid,
  p_location_id uuid DEFAULT NULL::uuid
)
RETURNS boolean
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_role text;
  v_org_id uuid;
  v_location_id uuid;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN true;
  END IF;

  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  SELECT role, organization_id, location_id
    INTO v_role, v_org_id, v_location_id
  FROM public.profiles
  WHERE id = auth.uid()
    AND deleted_at IS NULL;

  IF v_role IS NULL THEN
    RETURN false;
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN true;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    RETURN p_organization_id IS NOT NULL
       AND p_organization_id IN (
         SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()
       );
  END IF;

  IF v_role = 'org_manager' THEN
    RETURN p_organization_id IS NOT NULL AND p_organization_id = v_org_id;
  END IF;

  IF v_role IN ('branch_manager', 'brand_manager') THEN
    RETURN p_organization_id IS NOT NULL AND p_organization_id = v_org_id
       AND p_brand_id IS NOT NULL
       AND p_brand_id IN (SELECT id FROM public.get_my_accessible_brand_ids() id);
  END IF;

  IF v_role IN ('location_manager', 'ground_staff') THEN
    RETURN p_organization_id IS NOT NULL AND p_organization_id = v_org_id
       AND p_location_id IS NOT NULL
       AND (
         p_location_id IN (SELECT id FROM public.get_my_accessible_location_ids() id)
         OR p_location_id = v_location_id
       );
  END IF;

  RETURN false;
END;
$function$;

-- 4. Trigger fix: remove JWT user_metadata fallback (the exact JWT-vs-profiles anti-pattern
--    this repo's hardening eliminated elsewhere -- profiles/the row itself wins), capture
--    brand_id/location_id. Attached only to invoices/payments/inventory/auto_orders -- all 4
--    confirmed to have their own brand_id/location_id columns. process_onboarding_audit_log()
--    needs NO changes -- it's attached only to pre-org/org-level tables with no brand/location
--    of their own, so those rows correctly land in the NULL tier already.
CREATE OR REPLACE FUNCTION public.process_audit_log()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID;
BEGIN
    v_user_id := auth.uid();
    IF (TG_OP = 'DELETE') THEN
        INSERT INTO public.audit_logs (organization_id, brand_id, location_id, user_id, action, table_name, record_id, old_data)
        VALUES (OLD.organization_id, OLD.brand_id, OLD.location_id, v_user_id, 'DELETE', TG_TABLE_NAME, OLD.id, row_to_json(OLD)::jsonb);
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        INSERT INTO public.audit_logs (organization_id, brand_id, location_id, user_id, action, table_name, record_id, old_data, new_data)
        VALUES (NEW.organization_id, NEW.brand_id, NEW.location_id, v_user_id, 'UPDATE', TG_TABLE_NAME, NEW.id, row_to_json(OLD)::jsonb, row_to_json(NEW)::jsonb);
        RETURN NEW;
    ELSIF (TG_OP = 'INSERT') THEN
        INSERT INTO public.audit_logs (organization_id, brand_id, location_id, user_id, action, table_name, record_id, new_data)
        VALUES (NEW.organization_id, NEW.brand_id, NEW.location_id, v_user_id, 'INSERT', TG_TABLE_NAME, NEW.id, row_to_json(NEW)::jsonb);
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$function$;

-- 5. RPC fix: log_audit_event() accepts brand_id/location_id, same COALESCE pattern as every
--    other field. Everything else in the body is unchanged. log_audit_events() needs no edit
--    -- it just loops calling this per array element.
CREATE OR REPLACE FUNCTION public.log_audit_event(p_entry JSONB)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_org_id UUID;
  v_brand_id UUID;
  v_location_id UUID;
  v_record_id UUID;
  v_row public.audit_logs%ROWTYPE;
  v_details TEXT;
BEGIN
  IF p_entry IS NULL OR jsonb_typeof(p_entry) <> 'object' THEN
    RAISE EXCEPTION 'Audit entry must be a JSON object';
  END IF;

  v_org_id := NULLIF(COALESCE(p_entry->>'organization_id', p_entry->>'org_id', p_entry->>'orgId'), '')::UUID;
  v_brand_id := NULLIF(COALESCE(p_entry->>'brand_id', p_entry->>'brandId'), '')::UUID;
  v_location_id := NULLIF(COALESCE(p_entry->>'location_id', p_entry->>'locationId'), '')::UUID;

  IF v_org_id IS NOT NULL THEN
    PERFORM public.assert_org_actor(v_org_id);
  ELSIF auth.role() <> 'service_role' AND NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'organization_id is required for non-platform audit events';
  END IF;

  v_record_id := CASE
    WHEN COALESCE(p_entry->>'record_id', p_entry->>'recordId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN COALESCE(p_entry->>'record_id', p_entry->>'recordId')::UUID
    ELSE NULL
  END;

  v_details := CASE
    WHEN p_entry ? 'details' AND jsonb_typeof(p_entry->'details') IN ('object', 'array') THEN (p_entry->'details')::TEXT
    WHEN p_entry ? 'details' THEN p_entry->>'details'
    ELSE NULL
  END;

  INSERT INTO public.audit_logs (
    organization_id,
    brand_id,
    location_id,
    user_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data,
    ip_address,
    user_agent,
    entity_type,
    entity_id,
    module,
    field_changed,
    old_value,
    new_value,
    user_email,
    details
  ) VALUES (
    v_org_id,
    v_brand_id,
    v_location_id,
    COALESCE(NULLIF(p_entry->>'user_id', '')::UUID, auth.uid()),
    COALESCE(NULLIF(p_entry->>'action', ''), 'audit'),
    COALESCE(NULLIF(p_entry->>'table_name', ''), NULLIF(p_entry->>'tableName', ''), NULLIF(p_entry->>'entity_type', ''), NULLIF(p_entry->>'entityType', ''), NULLIF(p_entry->>'module', ''), 'system'),
    v_record_id,
    CASE WHEN p_entry ? 'old_data' THEN p_entry->'old_data' WHEN p_entry ? 'oldData' THEN p_entry->'oldData' ELSE NULL END,
    CASE WHEN p_entry ? 'new_data' THEN p_entry->'new_data' WHEN p_entry ? 'newData' THEN p_entry->'newData' ELSE NULL END,
    NULLIF(p_entry->>'ip_address', ''),
    NULLIF(p_entry->>'user_agent', ''),
    COALESCE(NULLIF(p_entry->>'entity_type', ''), NULLIF(p_entry->>'entityType', ''), NULLIF(p_entry->>'action', ''), 'unknown'),
    COALESCE(NULLIF(p_entry->>'entity_id', ''), NULLIF(p_entry->>'entityId', ''), NULLIF(p_entry->>'target_user_id', ''), NULLIF(p_entry->>'record_id', ''), NULLIF(p_entry->>'recordId', '')),
    NULLIF(p_entry->>'module', ''),
    COALESCE(NULLIF(p_entry->>'field_changed', ''), NULLIF(p_entry->>'fieldChanged', '')),
    COALESCE(NULLIF(p_entry->>'old_value', ''), NULLIF(p_entry->>'oldValue', '')),
    COALESCE(NULLIF(p_entry->>'new_value', ''), NULLIF(p_entry->>'newValue', '')),
    COALESCE(NULLIF(p_entry->>'user_email', ''), NULLIF(p_entry->>'userEmail', '')),
    v_details
  )
  RETURNING * INTO v_row;

  RETURN to_jsonb(v_row);
END;
$$;

-- 6. assert_org_actor() recognizes tenant_super_admin's tenant-wide scope, not just an exact
--    own-org match -- needed now that log_audit_event() can be called for any org within a
--    tenant_super_admin's tenant. Everything else unchanged.
CREATE OR REPLACE FUNCTION public.assert_org_actor(p_organization_id UUID)
RETURNS void
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_role TEXT;
  v_profile_org UUID;
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT role, organization_id
    INTO v_role, v_profile_org
  FROM public.profiles
  WHERE id = auth.uid();

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF v_role = 'platform_admin' THEN
    RETURN;
  END IF;

  IF v_role = 'tenant_super_admin' THEN
    IF p_organization_id IN (SELECT o.id FROM public.organizations o WHERE o.tenant_id = public.get_auth_tenant()) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'Cross-organization access denied';
  END IF;

  IF v_profile_org IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'Cross-organization access denied';
  END IF;
END;
$function$;

-- Source: 20260722000017_product_count_unit_rpcs.sql
CREATE OR REPLACE FUNCTION public.upsert_product_count_unit(
  p_product_id uuid,
  p_name text,
  p_quantity numeric,
  p_unit text,
  p_unit_price numeric,
  p_source_quantity numeric,
  p_source_unit text,
  p_source_price numeric
)
RETURNS public.product_count_units
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_normalized_name text;
  v_existing_id uuid;
  v_count_unit public.product_count_units%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  v_normalized_name := lower(trim(COALESCE(p_name, '')));

  IF v_normalized_name = '' THEN
    RAISE EXCEPTION 'Count unit name is required';
  END IF;

  IF COALESCE(p_quantity, 0) <= 0 THEN
    RAISE EXCEPTION 'Count unit quantity must be greater than zero';
  END IF;

  IF COALESCE(p_source_quantity, 0) <= 0 THEN
    RAISE EXCEPTION 'Source package quantity must be greater than zero';
  END IF;

  SELECT id
    INTO v_existing_id
  FROM public.product_count_units
  WHERE organization_id = v_product.organization_id
    AND product_id = v_product.id
    AND normalized_name = v_normalized_name
    AND deleted_at IS NULL
  LIMIT 1;

  IF v_existing_id IS NOT NULL THEN
    UPDATE public.product_count_units
       SET brand_id = v_product.brand_id,
           location_id = v_product.location_id,
           name = trim(p_name),
           quantity = p_quantity,
           unit = trim(p_unit),
           unit_price = COALESCE(p_unit_price, 0),
           source_quantity = p_source_quantity,
           source_unit = trim(p_source_unit),
           source_price = COALESCE(p_source_price, 0),
           is_active = true,
           updated_at = now()
     WHERE id = v_existing_id
     RETURNING * INTO v_count_unit;
  ELSE
    INSERT INTO public.product_count_units (
      organization_id,
      brand_id,
      location_id,
      product_id,
      name,
      normalized_name,
      quantity,
      unit,
      unit_price,
      source_quantity,
      source_unit,
      source_price,
      is_active,
      created_by
    )
    VALUES (
      v_product.organization_id,
      v_product.brand_id,
      v_product.location_id,
      v_product.id,
      trim(p_name),
      v_normalized_name,
      p_quantity,
      trim(p_unit),
      COALESCE(p_unit_price, 0),
      p_source_quantity,
      trim(p_source_unit),
      COALESCE(p_source_price, 0),
      true,
      auth.uid()
    )
    RETURNING * INTO v_count_unit;
  END IF;

  RETURN v_count_unit;
END;
$$;

CREATE OR REPLACE FUNCTION public.remove_product_count_unit(
  p_count_unit_id uuid
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count_unit public.product_count_units%ROWTYPE;
  v_product public.products%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT *
    INTO v_count_unit
  FROM public.product_count_units
  WHERE id = p_count_unit_id
    AND deleted_at IS NULL;

  IF v_count_unit.id IS NULL THEN
    RETURN true;
  END IF;

  SELECT *
    INTO v_product
  FROM public.products
  WHERE id = v_count_unit.product_id
    AND deleted_at IS NULL;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;

  UPDATE public.product_count_units
     SET deleted_at = now(),
         is_active = false,
         updated_at = now()
   WHERE id = p_count_unit_id;

  RETURN true;
END;
$$;

-- Source: 20260722000018_apply_invite_modules_to_onboarded_orgs.sql
CREATE OR REPLACE FUNCTION public.get_invited_enabled_modules(p_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_modules jsonb;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  WITH latest_invite AS (
    SELECT i.metadata->'modules' AS modules
    FROM public.invitations i
    WHERE i.accepted_by = p_user_id
      AND i.accepted_at IS NOT NULL
      AND jsonb_typeof(i.metadata->'modules') = 'array'
    ORDER BY i.accepted_at DESC, i.created_at DESC
    LIMIT 1
  ), allowed_modules(module_key) AS (
    VALUES
      ('dashboard'),
      ('performance'),
      ('executive_bi'),
      ('custom_reports'),
      ('invoices'),
      ('payments'),
      ('billing'),
      ('products'),
      ('inventory'),
      ('orders'),
      ('smartprep'),
      ('commissary'),
      ('recipes'),
      ('vendors'),
      ('labor'),
      ('accounting'),
      ('admin'),
      ('setup'),
      ('food_safety'),
      ('kitchen_displays'),
      ('integrations'),
      ('crm_marketing'),
      ('ai_insights')
  ), normalized AS (
    SELECT DISTINCT lower(btrim(invited_module.module_key)) AS module_key
    FROM latest_invite,
      jsonb_array_elements_text(latest_invite.modules) AS invited_module(module_key)
    WHERE NULLIF(btrim(invited_module.module_key), '') IS NOT NULL
  )
  SELECT COALESCE(jsonb_agg(normalized.module_key ORDER BY normalized.module_key), '[]'::jsonb)
  INTO v_modules
  FROM normalized
  JOIN allowed_modules USING (module_key);

  IF v_modules IS NULL OR jsonb_array_length(v_modules) = 0 THEN
    RETURN NULL;
  END IF;

  RETURN v_modules;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_tenant_enabled_modules(p_tenant_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_modules jsonb;
BEGIN
  IF p_tenant_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT metadata->'enabled_modules'
  INTO v_modules
  FROM public.tenants
  WHERE id = p_tenant_id
    AND jsonb_typeof(metadata->'enabled_modules') = 'array';

  IF v_modules IS NULL OR jsonb_array_length(v_modules) = 0 THEN
    RETURN NULL;
  END IF;

  RETURN v_modules;
END;
$$;

CREATE OR REPLACE FUNCTION public.sync_invited_modules_to_tenant(p_user_id uuid, p_tenant_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_modules jsonb;
BEGIN
  IF p_user_id IS NULL OR p_tenant_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_modules := public.get_tenant_enabled_modules(p_tenant_id);
  IF v_modules IS NOT NULL THEN
    RETURN v_modules;
  END IF;

  v_modules := public.get_invited_enabled_modules(p_user_id);
  IF v_modules IS NULL THEN
    RETURN NULL;
  END IF;

  UPDATE public.tenants
  SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'enabled_modules', v_modules,
        'invite_modules', v_modules,
        'module_source', 'platform_invitation'
      ),
      updated_at = now()
  WHERE id = p_tenant_id
    AND COALESCE(jsonb_array_length(
          CASE
            WHEN jsonb_typeof(metadata->'enabled_modules') = 'array' THEN metadata->'enabled_modules'
            ELSE '[]'::jsonb
          END
        ), 0) = 0;

  RETURN v_modules;
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_invited_modules_to_organization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_modules jsonb;
BEGIN
  IF NEW.owner_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.tenant_id IS NOT NULL THEN
    v_modules := public.sync_invited_modules_to_tenant(NEW.owner_id, NEW.tenant_id);
  ELSE
    v_modules := public.get_invited_enabled_modules(NEW.owner_id);
  END IF;

  IF v_modules IS NOT NULL
     AND COALESCE(jsonb_array_length(
       CASE
         WHEN jsonb_typeof(NEW.enabled_modules) = 'array' THEN NEW.enabled_modules
         ELSE '[]'::jsonb
       END
     ), 0) = 0 THEN
    NEW.enabled_modules := v_modules;
  END IF;

  RETURN NEW;
END;
$$;

