CREATE OR REPLACE FUNCTION public.resolve_payment_provider_config(
  p_tenant_id uuid DEFAULT NULL,
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE((
    SELECT jsonb_build_object(
      'id', ppc.id,
      'tenant_id', ppc.tenant_id,
      'organization_id', ppc.organization_id,
      'brand_id', ppc.brand_id,
      'location_id', ppc.location_id,
      'collection_provider', ppc.collection_provider,
      'payout_provider', ppc.payout_provider,
      'check_provider', ppc.check_provider,
      'enabled', ppc.enabled,
      'settings', ppc.settings
    )
    FROM public.payment_provider_configs ppc
    WHERE ppc.enabled = true
      AND ppc.deleted_at IS NULL
      AND (ppc.tenant_id IS NULL OR ppc.tenant_id = p_tenant_id)
      AND (ppc.organization_id IS NULL OR ppc.organization_id = p_organization_id)
      AND (ppc.brand_id IS NULL OR ppc.brand_id = p_brand_id)
      AND (ppc.location_id IS NULL OR ppc.location_id = p_location_id)
    ORDER BY
      CASE WHEN ppc.location_id IS NOT NULL THEN 1 ELSE 0 END DESC,
      CASE WHEN ppc.brand_id IS NOT NULL THEN 1 ELSE 0 END DESC,
      CASE WHEN ppc.organization_id IS NOT NULL THEN 1 ELSE 0 END DESC,
      CASE WHEN ppc.tenant_id IS NOT NULL THEN 1 ELSE 0 END DESC,
      ppc.updated_at DESC
    LIMIT 1
  ), jsonb_build_object(
    'collection_provider', 'not_configured',
    'payout_provider', 'not_configured',
    'check_provider', 'checkbook',
    'enabled', false,
    'settings', '{}'::jsonb
  ));
$$;

CREATE OR REPLACE FUNCTION public.store_bank_account_secret(
  p_bank_account_id uuid,
  p_account_number text,
  p_routing_number text,
  p_fingerprint_hash text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_secret_name text := 'bank_' || p_bank_account_id::text;
  v_secret_id uuid;
  v_row public.bank_accounts%ROWTYPE;
  v_account text;
  v_routing text;
  v_payload text;
BEGIN
  SELECT *
    INTO v_row
  FROM public.bank_accounts
  WHERE id = p_bank_account_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_row.id IS NULL THEN
    RAISE EXCEPTION 'Bank account row % not found', p_bank_account_id;
  END IF;

  v_account := regexp_replace(COALESCE(p_account_number, ''), '\D', '', 'g');
  v_routing := regexp_replace(COALESCE(p_routing_number, ''), '\D', '', 'g');

  IF v_account !~ '^\d{4,17}$' THEN
    RAISE EXCEPTION 'A valid bank account number is required';
  END IF;

  IF v_routing !~ '^\d{9}$' THEN
    RAISE EXCEPTION 'A valid 9-digit routing number is required';
  END IF;

  IF NULLIF(btrim(COALESCE(p_fingerprint_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'A backend-generated fingerprint hash is required';
  END IF;

  v_payload := jsonb_build_object(
    'account_number', v_account,
    'routing_number', v_routing,
    'account_holder_name', v_row.account_holder_name,
    'account_type', v_row.account_type
  )::text;

  SELECT id INTO v_secret_id
  FROM vault.secrets
  WHERE name = v_secret_name;

  IF v_secret_id IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret_id;
  END IF;

  SELECT * INTO v_secret_id
  FROM vault.create_secret(v_payload, v_secret_name, 'provider-neutral bank account');

  UPDATE public.bank_accounts
     SET secret_id = v_secret_id,
         account_last4 = right(v_account, 4),
         routing_last4 = right(v_routing, 4),
         fingerprint_hash = p_fingerprint_hash,
         updated_at = now()
   WHERE id = p_bank_account_id;

  RETURN jsonb_build_object(
    'bank_account_id', p_bank_account_id,
    'secret_id', v_secret_id,
    'account_last4', right(v_account, 4),
    'routing_last4', right(v_routing, 4)
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_bank_account_secret_for_provider(
  p_bank_account_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_secret_id uuid;
  v_secret text;
BEGIN
  SELECT secret_id INTO v_secret_id
  FROM public.bank_accounts
  WHERE id = p_bank_account_id
    AND is_active = true
    AND deleted_at IS NULL;

  IF v_secret_id IS NULL THEN
    RAISE EXCEPTION 'Bank account secret for row % not found', p_bank_account_id;
  END IF;

  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE id = v_secret_id;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'Vault secret % not found', v_secret_id;
  END IF;

  INSERT INTO public.payment_provider_events (
    tenant_id,
    organization_id,
    brand_id,
    location_id,
    provider,
    provider_event_type,
    owner_type,
    owner_id,
    bank_account_id,
    status,
    payload
  )
  SELECT
    tenant_id,
    organization_id,
    brand_id,
    location_id,
    'internal',
    'bank_secret_retrieved_for_provider',
    owner_type,
    owner_id,
    id,
    'processed',
    jsonb_build_object('bank_account_id', id, 'retrieved_at', now())
  FROM public.bank_accounts
  WHERE id = p_bank_account_id;

  RETURN v_secret::jsonb;
END;
$$;

CREATE OR REPLACE FUNCTION public.record_payment_provider_event(
  p_payload jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.payment_provider_events (
    tenant_id,
    organization_id,
    brand_id,
    location_id,
    provider,
    provider_event_type,
    provider_event_ref,
    owner_type,
    owner_id,
    bank_account_id,
    payment_id,
    invoice_id,
    status,
    payload
  )
  VALUES (
    NULLIF(p_payload->>'tenant_id', '')::uuid,
    NULLIF(p_payload->>'organization_id', '')::uuid,
    NULLIF(p_payload->>'brand_id', '')::uuid,
    NULLIF(p_payload->>'location_id', '')::uuid,
    COALESCE(NULLIF(p_payload->>'provider', ''), 'internal'),
    COALESCE(NULLIF(p_payload->>'provider_event_type', ''), 'generic_event'),
    NULLIF(p_payload->>'provider_event_ref', ''),
    NULLIF(p_payload->>'owner_type', ''),
    NULLIF(p_payload->>'owner_id', '')::uuid,
    NULLIF(p_payload->>'bank_account_id', '')::uuid,
    NULLIF(p_payload->>'payment_id', '')::uuid,
    NULLIF(p_payload->>'invoice_id', '')::uuid,
    COALESCE(NULLIF(p_payload->>'status', ''), 'received'),
    COALESCE(p_payload->'payload', '{}'::jsonb)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

-- Source: 20260723000002_repair_invoice_anomaly_review_contract.sql
CREATE OR REPLACE FUNCTION public.record_invoice_anomaly_review(
  p_invoice_id uuid,
  p_anomaly_type text,
  p_decision text,
  p_notes text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invoice public.invoices%ROWTYPE;
  v_review_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_decision NOT IN ('opened_for_review', 'accepted_historical', 'finance_cleanup_requested') THEN
    RAISE EXCEPTION 'Unsupported invoice anomaly decision %', p_decision;
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  INSERT INTO public.invoice_anomaly_reviews (
    invoice_id,
    organization_id,
    brand_id,
    location_id,
    anomaly_type,
    decision,
    notes,
    created_by
  ) VALUES (
    v_invoice.id,
    v_invoice.organization_id,
    v_invoice.brand_id,
    v_invoice.location_id,
    COALESCE(NULLIF(p_anomaly_type, ''), 'unknown'),
    p_decision,
    p_notes,
    auth.uid()
  )
  RETURNING id INTO v_review_id;

  UPDATE public.invoices
     SET validation_results = COALESCE(validation_results, '{}'::jsonb)
       || jsonb_build_object(
            'invoice_anomaly_review',
            jsonb_build_object(
              'decision', p_decision,
              'anomaly_type', COALESCE(NULLIF(p_anomaly_type, ''), 'unknown'),
              'reviewed_by', auth.uid(),
              'reviewed_at', now(),
              'notes', p_notes
            )
          ),
         updated_at = now()
   WHERE id = v_invoice.id;

  RETURN jsonb_build_object(
    'success', true,
    'review_id', v_review_id,
    'decision', p_decision
  );
END;
$$;

-- Source: 20260723000003_sync_approved_ap_status_to_invoice_status.sql
CREATE OR REPLACE FUNCTION public.normalize_invoice_ap_state()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.ap_status = 'approved'
    AND COALESCE(NEW.status, 'processing') IN ('processing', 'pending_review', 'validated', 'pending_approval', 'flagged') THEN
    NEW.status := 'approved';
  ELSIF NEW.ap_status = 'scheduled'
    AND COALESCE(NEW.status, 'processing') IN ('processing', 'pending_review', 'validated', 'pending_approval', 'approved') THEN
    NEW.status := 'scheduled';
  END IF;

  IF NEW.status = 'approved' THEN
    NEW.ap_status := 'approved';
  ELSIF NEW.status = 'scheduled' THEN
    NEW.ap_status := 'scheduled';
  ELSIF NEW.status = 'paid' THEN
    NEW.ap_status := 'paid';
    NEW.payment_status := 'paid';
  ELSIF NEW.status = 'rejected' THEN
    IF COALESCE(NEW.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay', 'processing')
      OR COALESCE(NEW.paid_amount, 0) > 0 THEN
      RAISE EXCEPTION 'Rejected invoices cannot carry paid or in-flight payment state';
    END IF;
    NEW.ap_status := 'rejected';
  END IF;

  IF NEW.payment_status = 'paid'
    AND NEW.status <> 'extracting' THEN
    NEW.status := 'paid';
    NEW.ap_status := 'paid';
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260723000004_repair_configurable_self_approval_setting.sql
CREATE OR REPLACE FUNCTION public.get_payment_approval_settings(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE((
    SELECT os.settings
    FROM public.operational_settings os
    WHERE os.organization_id = p_organization_id
      AND os.category = 'payments'
      AND (
        (p_location_id IS NOT NULL AND os.location_id = p_location_id)
        OR (p_brand_id IS NOT NULL AND os.brand_id = p_brand_id AND os.location_id IS NULL)
        OR (os.brand_id IS NULL AND os.location_id IS NULL)
      )
    ORDER BY
      CASE
        WHEN p_location_id IS NOT NULL AND os.location_id = p_location_id THEN 1
        WHEN p_brand_id IS NOT NULL AND os.brand_id = p_brand_id AND os.location_id IS NULL THEN 2
        ELSE 3
      END,
      os.updated_at DESC NULLS LAST
    LIMIT 1
  ), '{}'::jsonb);
$$;

CREATE OR REPLACE FUNCTION public.enforce_invoice_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vendor_autopay boolean;
  v_settings jsonb;
  v_require_separate_approver boolean;
  v_enforce_approval_limits boolean;
  v_user_limit numeric;
  v_has_unlimited boolean;
  v_amount numeric;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = 'approved' OR NEW.ap_status = 'approved' THEN
      v_settings := public.get_payment_approval_settings(NEW.organization_id, NEW.brand_id, NEW.location_id);
      v_require_separate_approver := COALESCE((v_settings->>'requireSeparateApprover')::boolean, false);
      v_enforce_approval_limits := COALESCE((v_settings->>'enforceApprovalLimits')::boolean, false);

      IF v_require_separate_approver
        AND NEW.created_by IS NOT NULL
        AND NEW.created_by = auth.uid() THEN
        RAISE EXCEPTION 'Invoice submitters cannot approve their own invoices';
      END IF;

      PERFORM public.assert_can_approve_invoice_scope(
        NEW.organization_id,
        NEW.brand_id,
        NEW.location_id
      );

      IF v_enforce_approval_limits THEN
        SELECT invoice_approval_limit, COALESCE(has_unlimited_approval, false)
          INTO v_user_limit, v_has_unlimited
        FROM public.profiles
        WHERE id = auth.uid()
          AND deleted_at IS NULL;

        v_amount := COALESCE(NEW.total_amount, 0);
        IF NOT COALESCE(v_has_unlimited, false)
          AND (v_user_limit IS NULL OR v_amount > v_user_limit) THEN
          RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.',
            COALESCE(v_user_limit, 0), v_amount;
        END IF;
      END IF;

      SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
      IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
        RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF (NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved')
    OR (NEW.ap_status = 'approved' AND OLD.ap_status IS DISTINCT FROM 'approved') THEN
    v_settings := public.get_payment_approval_settings(NEW.organization_id, NEW.brand_id, NEW.location_id);
    v_require_separate_approver := COALESCE((v_settings->>'requireSeparateApprover')::boolean, false);
    v_enforce_approval_limits := COALESCE((v_settings->>'enforceApprovalLimits')::boolean, false);

    IF v_require_separate_approver
      AND COALESCE(OLD.created_by, NEW.created_by) IS NOT NULL
      AND COALESCE(OLD.created_by, NEW.created_by) = auth.uid() THEN
      RAISE EXCEPTION 'Invoice submitters cannot approve their own invoices';
    END IF;

    PERFORM public.assert_can_approve_invoice_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );

    IF v_enforce_approval_limits THEN
      SELECT invoice_approval_limit, COALESCE(has_unlimited_approval, false)
        INTO v_user_limit, v_has_unlimited
      FROM public.profiles
      WHERE id = auth.uid()
        AND deleted_at IS NULL;

      v_amount := COALESCE(NEW.total_amount, OLD.total_amount, 0);
      IF NOT COALESCE(v_has_unlimited, false)
        AND (v_user_limit IS NULL OR v_amount > v_user_limit) THEN
        RAISE EXCEPTION 'Approval limit exceeded. Your limit is $%, but the invoice is $%.',
          COALESCE(v_user_limit, 0), v_amount;
      END IF;
    END IF;

    SELECT autopay_enabled INTO v_vendor_autopay FROM public.vendors WHERE id = NEW.vendor_id;
    IF v_vendor_autopay AND NOT public.is_owner_or_admin() THEN
      RAISE EXCEPTION 'AutoPay invoice approval requires an org manager, tenant super admin, or platform admin';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260723000005_sync_report_unit_source_price.sql
CREATE OR REPLACE FUNCTION public.sync_invoice_products(p_invoice_id UUID, p_user_id UUID DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
  v_item RECORD;
  v_product_id UUID;
  v_vendor_item_id UUID;
  v_mapping_id UUID;
  v_previous_price NUMERIC;
  v_threshold NUMERIC := 10;
  v_price_variance_flag BOOLEAN;
  v_price_variance_percent NUMERIC;
  v_line_hash TEXT;
  v_existing_hash TEXT;
  v_updates_count INT := 0;
  v_report_unit TEXT;
BEGIN
  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id;

  IF v_invoice IS NULL THEN
    RETURN jsonb_build_object('status', 'error', 'message', 'Invoice not found');
  END IF;

  SELECT md5(COALESCE(jsonb_agg(jsonb_build_object(
      'id', ili.id,
      'item_name', ili.item_name,
      'quantity', ili.quantity,
      'unit_price', ili.unit_price,
      'total_price', ili.total_price,
      'vendor_item_code', ili.vendor_item_code,
      'vendor_unit', ili.vendor_unit,
      'pack_size', ili.pack_size
    ) ORDER BY ili.id)::TEXT, '[]'))
    INTO v_line_hash
  FROM public.invoice_line_items ili
  WHERE ili.invoice_id = p_invoice_id;

  SELECT hash INTO v_existing_hash
  FROM public.invoice_sync_log
  WHERE invoice_id = p_invoice_id
    AND operation = 'sync_invoice_products'
  ORDER BY processed_at DESC
  LIMIT 1;

  IF v_existing_hash IS NOT NULL AND v_existing_hash = v_line_hash THEN
    RETURN jsonb_build_object('status', 'success', 'updates_count', 0, 'idempotent', true);
  END IF;

  FOR v_item IN
    SELECT *
    FROM public.invoice_line_items
    WHERE invoice_id = p_invoice_id
      AND NULLIF(trim(COALESCE(item_name, '')), '') IS NOT NULL
  LOOP
    v_product_id := v_item.internal_product_id;
    v_vendor_item_id := NULL;
    v_mapping_id := NULL;
    v_price_variance_flag := false;
    v_price_variance_percent := 0;
    v_report_unit := public.derive_product_report_unit(v_item.vendor_unit, v_item.pack_size);

    IF v_product_id IS NULL THEN
      SELECT id INTO v_product_id
      FROM public.products
      WHERE organization_id = v_invoice.organization_id
        AND lower(name) = lower(v_item.item_name)
        AND deleted_at IS NULL
        AND (
          brand_id IS NOT DISTINCT FROM v_invoice.brand_id
          OR brand_id IS NULL
        )
      ORDER BY CASE WHEN brand_id IS NOT DISTINCT FROM v_invoice.brand_id THEN 0 ELSE 1 END
      LIMIT 1;

      IF v_product_id IS NULL THEN
        INSERT INTO public.products (
          organization_id,
          brand_id,
          location_id,
          product_id,
          name,
          category,
          accounting_category,
          report_by_unit,
          base_unit,
          latest_price,
          report_unit_quantity,
          report_unit_source_price,
          is_inventoried
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.brand_id,
          v_invoice.location_id,
          public.generate_restops_product_id(),
          v_item.item_name,
          public.derive_product_category(NULL, v_item.item_name),
          CASE
            WHEN public.derive_product_category_type(NULL, NULL, v_item.item_name) = 'Beverage' THEN '5200'
            ELSE '5100'
          END,
          COALESCE(v_report_unit, 'Each'),
          COALESCE(v_report_unit, 'Each'),
          COALESCE(v_item.unit_price, 0),
          1,
          COALESCE(v_item.unit_price, 0),
          false
        )
        ON CONFLICT ON CONSTRAINT products_org_name_key
        DO UPDATE SET
          deleted_at = NULL,
          report_by_unit = CASE
            WHEN public.product_unit_is_generic(products.report_by_unit) THEN COALESCE(EXCLUDED.report_by_unit, products.report_by_unit)
            ELSE products.report_by_unit
          END,
          base_unit = CASE
            WHEN public.product_unit_is_generic(products.base_unit) THEN COALESCE(EXCLUDED.base_unit, products.base_unit)
            ELSE products.base_unit
          END,
          report_unit_source_price = CASE
            WHEN COALESCE(EXCLUDED.report_unit_source_price, 0) > 0 THEN EXCLUDED.report_unit_source_price
            ELSE products.report_unit_source_price
          END,
          latest_price = CASE
            WHEN COALESCE(EXCLUDED.latest_price, 0) > 0 THEN EXCLUDED.latest_price
            ELSE products.latest_price
          END,
          updated_at = now()
        RETURNING id INTO v_product_id;
      ELSE
        UPDATE public.products
           SET product_id = COALESCE(NULLIF(product_id, ''), public.generate_restops_product_id()),
               report_by_unit = CASE
                 WHEN public.product_unit_is_generic(report_by_unit) THEN COALESCE(v_report_unit, report_by_unit)
                 ELSE report_by_unit
               END,
               base_unit = CASE
                 WHEN public.product_unit_is_generic(base_unit) THEN COALESCE(v_report_unit, base_unit)
                 ELSE base_unit
               END,
               report_unit_source_price = CASE
                 WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price
                 ELSE report_unit_source_price
               END,
               latest_price = CASE
                 WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price / GREATEST(COALESCE(report_unit_quantity, 1), 0.0001)
                 ELSE latest_price
               END,
               category = CASE
                 WHEN NULLIF(trim(COALESCE(category, '')), '') IS NULL OR lower(category) = 'uncategorized'
                   THEN public.derive_product_category(category, v_item.item_name)
                 ELSE category
               END,
               brand_id = COALESCE(brand_id, v_invoice.brand_id),
               location_id = COALESCE(location_id, v_invoice.location_id),
               updated_at = now()
         WHERE id = v_product_id;
      END IF;
    ELSE
      UPDATE public.products
         SET report_by_unit = CASE
               WHEN public.product_unit_is_generic(report_by_unit) THEN COALESCE(v_report_unit, report_by_unit)
               ELSE report_by_unit
             END,
             base_unit = CASE
               WHEN public.product_unit_is_generic(base_unit) THEN COALESCE(v_report_unit, base_unit)
               ELSE base_unit
             END,
             report_unit_source_price = CASE
               WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price
               ELSE report_unit_source_price
             END,
             latest_price = CASE
               WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price / GREATEST(COALESCE(report_unit_quantity, 1), 0.0001)
               ELSE latest_price
             END,
             updated_at = now()
       WHERE id = v_product_id
         AND deleted_at IS NULL;
    END IF;

    IF v_invoice.vendor_id IS NOT NULL THEN
      SELECT id, last_price, price_variance_threshold_percent
        INTO v_vendor_item_id, v_previous_price, v_threshold
      FROM public.vendor_items
      WHERE organization_id = v_invoice.organization_id
        AND vendor_id = v_invoice.vendor_id
        AND lower(vendor_item_name) = lower(v_item.item_name)
        AND COALESCE(vendor_item_code, '') = COALESCE(v_item.vendor_item_code, '')
      LIMIT 1;

      v_threshold := COALESCE(v_threshold, 10);

      IF v_vendor_item_id IS NOT NULL THEN
        IF COALESCE(v_previous_price, 0) > 0 AND COALESCE(v_item.unit_price, 0) > 0 THEN
          v_price_variance_percent := ((v_item.unit_price - v_previous_price) / v_previous_price) * 100;
          v_price_variance_flag := abs(v_price_variance_percent) >= v_threshold;
        END IF;

        UPDATE public.vendor_items
           SET vendor_unit = COALESCE(NULLIF(v_item.vendor_unit, ''), vendor_unit),
               pack_size = COALESCE(NULLIF(v_item.pack_size, ''), pack_size),
               previous_price = last_price,
               last_price = COALESCE(v_item.unit_price, last_price),
               last_invoice_id = p_invoice_id,
               last_invoice_line_id = v_item.id,
               last_purchased_at = COALESCE(v_invoice.invoice_date, CURRENT_DATE),
               last_price_change_percent = v_price_variance_percent,
               price_variance_flag = v_price_variance_flag,
               updated_at = now()
         WHERE id = v_vendor_item_id;
      ELSE
        INSERT INTO public.vendor_items (
          organization_id,
          vendor_id,
          vendor_item_code,
          vendor_item_name,
          vendor_unit,
          pack_size,
          default_price,
          last_price,
          last_invoice_id,
          last_invoice_line_id,
          last_purchased_at,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_invoice.vendor_id,
          NULLIF(v_item.vendor_item_code, ''),
          v_item.item_name,
          NULLIF(v_item.vendor_unit, ''),
          NULLIF(v_item.pack_size, ''),
          v_item.unit_price,
          v_item.unit_price,
          p_invoice_id,
          v_item.id,
          COALESCE(v_invoice.invoice_date, CURRENT_DATE),
          now()
        )
        RETURNING id INTO v_vendor_item_id;
      END IF;

      IF v_product_id IS NOT NULL AND v_vendor_item_id IS NOT NULL THEN
        INSERT INTO public.vendor_item_mappings (
          organization_id,
          vendor_item_id,
          internal_product_id,
          conversion_multiplier,
          is_verified,
          updated_at
        ) VALUES (
          v_invoice.organization_id,
          v_vendor_item_id,
          v_product_id,
          1,
          false,
          now()
        )
        ON CONFLICT (vendor_item_id, internal_product_id)
        DO UPDATE SET updated_at = now()
        RETURNING id INTO v_mapping_id;
      END IF;
    END IF;

    UPDATE public.invoice_line_items
       SET vendor_id = v_invoice.vendor_id,
           vendor_item_id = v_vendor_item_id,
           internal_product_id = v_product_id,
           price_variance_flag = v_price_variance_flag,
           price_variance_percent = v_price_variance_percent
     WHERE id = v_item.id;

    UPDATE public.inventory inv
       SET unit_cost = CASE
             WHEN COALESCE(v_item.unit_price, 0) > 0 THEN v_item.unit_price / GREATEST((SELECT COALESCE(report_unit_quantity, 1) FROM public.products WHERE id = v_product_id), 0.0001)
             ELSE inv.unit_cost
           END,
           current_unit = CASE
             WHEN public.product_unit_is_generic(inv.current_unit) THEN COALESCE(v_report_unit, inv.current_unit)
             ELSE inv.current_unit
           END,
           report_by = CASE
             WHEN public.product_unit_is_generic(inv.report_by) THEN COALESCE(v_report_unit, inv.report_by)
             ELSE inv.report_by
           END,
           updated_at = now()
     WHERE v_product_id IS NOT NULL
       AND inv.organization_id = v_invoice.organization_id
       AND inv.deleted_at IS NULL
       AND (
         inv.internal_product_id = v_product_id
         OR inv.product_id = (SELECT product_id FROM public.products WHERE id = v_product_id)
       );

    v_updates_count := v_updates_count + 1;
  END LOOP;

  INSERT INTO public.invoice_event_log (invoice_id, event_type, new_value, actor_id)
  VALUES (
    p_invoice_id,
    'product_catalog_synced',
    jsonb_build_object('updates_count', v_updates_count),
    COALESCE(p_user_id, auth.uid())
  );

  INSERT INTO public.invoice_sync_log (invoice_id, operation, hash)
  VALUES (p_invoice_id, 'sync_invoice_products', v_line_hash);

  RETURN jsonb_build_object('status', 'success', 'updates_count', v_updates_count);
END;
$$;

-- Source: 20260723000006_allow_locked_invoice_product_sync_metadata.sql
CREATE OR REPLACE FUNCTION public.guard_locked_invoice_line_items()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invoice record;
  v_invoice_id uuid;
  v_old_protected jsonb;
  v_new_protected jsonb;
BEGIN
  IF current_setting('app.invoice_product_sync', true) = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_invoice_id := COALESCE(NEW.invoice_id, OLD.invoice_id);

  SELECT status, ap_status, payment_status, paid_amount
    INTO v_invoice
  FROM public.invoices
  WHERE id = v_invoice_id;

  IF v_invoice.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
    OR v_invoice.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
    OR COALESCE(v_invoice.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
    OR COALESCE(v_invoice.paid_amount, 0) > 0 THEN

    IF TG_OP = 'UPDATE' THEN
      v_old_protected := to_jsonb(OLD)
        - 'vendor_id'
        - 'vendor_item_id'
        - 'internal_product_id'
        - 'price_variance_flag'
        - 'price_variance_percent'
        - 'updated_at';

      v_new_protected := to_jsonb(NEW)
        - 'vendor_id'
        - 'vendor_item_id'
        - 'internal_product_id'
        - 'price_variance_flag'
        - 'price_variance_percent'
        - 'updated_at';

      IF v_new_protected = v_old_protected THEN
        RETURN NEW;
      END IF;
    END IF;

    RAISE EXCEPTION 'Invoice line items are immutable after approval or payment activity';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;

-- Source: 20260723000007_restore_ui_driven_invoice_payment_workflow.sql
CREATE OR REPLACE FUNCTION public.is_invoice_payment_ready(
  p_status text,
  p_ap_status text,
  p_payment_status text,
  p_paid_amount numeric DEFAULT 0,
  p_total_amount numeric DEFAULT NULL
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT
    COALESCE(p_status, '') <> 'rejected'
    AND COALESCE(p_ap_status, '') <> 'rejected'
    AND COALESCE(p_payment_status, 'unpaid') NOT IN ('paid', 'auto_pay')
    AND (
      p_total_amount IS NULL
      OR COALESCE(p_paid_amount, 0) < COALESCE(p_total_amount, 0)
    )
    AND (
      COALESCE(p_status, '') IN ('approved', 'scheduled', 'partially_paid')
      OR COALESCE(p_ap_status, '') IN ('approved', 'scheduled')
      OR COALESCE(p_payment_status, '') = 'partial'
    );
$$;

CREATE OR REPLACE FUNCTION public.guard_locked_invoice_financial_fields()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_old_protected jsonb;
  v_new_protected jsonb;
BEGIN
  IF OLD.status IN ('approved', 'scheduled', 'partially_paid', 'paid')
    OR OLD.ap_status IN ('approved', 'scheduled', 'paid', 'closed')
    OR COALESCE(OLD.payment_status, 'unpaid') IN ('partial', 'paid', 'auto_pay')
    OR COALESCE(OLD.paid_amount, 0) > 0 THEN

    v_old_protected := to_jsonb(OLD)
      - 'status'
      - 'ap_status'
      - 'payment_status'
      - 'paid_amount'
      - 'payment_reference'
      - 'approved_by'
      - 'approved_date'
      - 'ap_routing_destination'
      - 'ap_routing_resolved_at'
      - 'file_destination'
      - 'payment_account_id'
      - 'scheduled_payment_date'
      - 'validation_results'
      - 'validation_notes'
      - 'ap_metadata'
      - 'action_required_reason'
      - 'action_required_details'
      - 'assigned_reviewer_id'
      - 'closed_at'
      - 'closed_by'
      - 'updated_at'
      - 'version_number';

    v_new_protected := to_jsonb(NEW)
      - 'status'
      - 'ap_status'
      - 'payment_status'
      - 'paid_amount'
      - 'payment_reference'
      - 'approved_by'
      - 'approved_date'
      - 'ap_routing_destination'
      - 'ap_routing_resolved_at'
      - 'file_destination'
      - 'payment_account_id'
      - 'scheduled_payment_date'
      - 'validation_results'
      - 'validation_notes'
      - 'ap_metadata'
      - 'action_required_reason'
      - 'action_required_details'
      - 'assigned_reviewer_id'
      - 'closed_at'
      - 'closed_by'
      - 'updated_at'
      - 'version_number';

    IF v_new_protected IS DISTINCT FROM v_old_protected THEN
      RAISE EXCEPTION 'Approved, scheduled, partially paid, or paid invoice financial fields are immutable';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

