$function$;

-- Source: 20260723000014_admin_manual_vendor_tax_entry.sql
-- Staff-facing counterpart to the vendor's magic-link submit-tax-info: some vendors read tax
-- details over the phone or by email rather than filling out the portal themselves. Reuses the
-- same vault primitive (store_vendor_tax_secret) and produces the same downstream row shape, so
-- the rest of the onboarding panel (review/approve gates) can't tell the two paths apart.
CREATE OR REPLACE FUNCTION public.admin_submit_vendor_tax_info(
  p_vendor_id uuid,
  p_tax_id text,
  p_legal_name text DEFAULT NULL,
  p_tax_classification text DEFAULT NULL,
  p_tax_id_type text DEFAULT NULL,
  p_w9_document_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_tax public.vendor_tax_information%ROWTYPE;
  v_store_result jsonb;
  v_inferred_type text;
BEGIN
  SELECT * INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, NULL::timestamptz, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Same floor as issue_vendor_link_token -- manual entry is functionally "issue a link and
  -- redeem it in the same step," so it shouldn't skip the gate the link-issuing path enforces.
  IF COALESCE(v_vendor.onboarding_status, 'invited') NOT IN (
    'otp_verified', 'pending_tax', 'tax_submitted', 'business_verified', 'verification_failed',
    'documents_on_file', 'pending_bank', 'banking_submitted', 'banking_verified',
    'method_selected', 'pending_approval', 'active', 'completed'
  ) THEN
    RAISE EXCEPTION 'Vendor OTP must be verified before entering tax info';
  END IF;

  IF p_w9_document_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.vendor_documents
    WHERE id = p_w9_document_id
      AND vendor_id = p_vendor_id
      AND document_type = 'w9'
      AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'W-9 document not found for this vendor -- upload it first, then link it here';
  END IF;

  v_inferred_type := COALESCE(
    NULLIF(p_tax_id_type, ''),
    CASE
      -- position() is 1-indexed in Postgres (unlike JS indexOf's 0-indexed 2 for "12-3456789") --
      -- an EIN's dash sits after the first 2 digits, so character position 3.
      WHEN regexp_replace(COALESCE(p_tax_id, ''), '\D', '', 'g') ~ '^\d{9}$' AND position('-' in p_tax_id) = 3 THEN 'ein'
      ELSE 'ssn'
    END
  );

  INSERT INTO public.vendor_tax_information (
    vendor_id, legal_name, tax_classification, tax_id_type,
    verification_status, w9_status, w9_document_id, created_by, updated_by
  ) VALUES (
    p_vendor_id,
    NULLIF(p_legal_name, ''),
    NULLIF(p_tax_classification, ''),
    v_inferred_type,
    'pending',
    CASE WHEN p_w9_document_id IS NOT NULL THEN 'received' ELSE 'requested' END,
    p_w9_document_id,
    auth.uid(),
    auth.uid()
  )
  RETURNING * INTO v_tax;

  v_store_result := public.store_vendor_tax_secret(v_tax.id, p_tax_id);

  UPDATE public.vendors
     SET onboarding_status = 'tax_submitted'
   WHERE id = p_vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, to_status, actor_id, actor_type, metadata
  ) VALUES (
    p_vendor_id,
    'tax_submitted',
    'tax_submitted',
    auth.uid(),
    'admin',
    jsonb_build_object('tax_row_id', v_tax.id, 'w9_document_id', p_w9_document_id, 'entry_method', 'manual')
  );

  RETURN jsonb_build_object(
    'success', true,
    'tax_row_id', v_tax.id,
    'tax_id_last4', v_store_result->>'tax_id_last4'
  );
END;
$function$;

-- Source: 20260723000014_custom_reports_module_builder.sql
DROP FUNCTION IF EXISTS public.run_custom_report(TEXT[], TEXT, DATE, DATE);

DROP FUNCTION IF EXISTS public.run_custom_report(TEXT[], TEXT, DATE, DATE, TEXT[]);

DROP FUNCTION IF EXISTS public.run_custom_report(TEXT[], TEXT, DATE, DATE, TEXT[], UUID);

CREATE OR REPLACE FUNCTION public.run_custom_report(
  p_metrics TEXT[],
  p_dimension TEXT,
  p_start_date DATE DEFAULT NULL,
  p_end_date DATE DEFAULT NULL,
  p_modules TEXT[] DEFAULT NULL,
  p_organization_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org UUID;
  v_start DATE := COALESCE(p_start_date, CURRENT_DATE - INTERVAL '30 days');
  v_end DATE := COALESCE(p_end_date, CURRENT_DATE);
  v_modules TEXT[] := COALESCE(NULLIF(p_modules, ARRAY[]::TEXT[]), ARRAY['invoices','payments','products','inventory','recipes','performance','audit_logs']);
  v_allowed_modules CONSTANT TEXT[] := ARRAY['invoices','payments','products','inventory','recipes','performance','audit_logs'];
  v_allowed_metrics CONSTANT TEXT[] := ARRAY[
    'invoice_count','invoice_total_amount','invoice_approved_count','invoice_unpaid_count','invoice_tax_amount',
    'payment_count','payment_amount','payment_completed_amount','payment_failed_count',
    'product_count','inventoried_product_count','avg_latest_price','products_with_price_count',
    'inventory_value','inventory_quantity','low_stock_count','inventory_waste','cogs',
    'recipe_count','avg_recipe_cost','avg_suggested_price','avg_cost_per_serving',
    'sales_revenue','pos_transaction_count','labor_cost','prime_cost','gross_profit',
    'audit_event_count','audit_insert_count','audit_update_count','audit_delete_count'
  ];
  v_result JSONB;
  v_bad TEXT;
BEGIN
  v_org := CASE WHEN auth.role() = 'service_role' THEN p_organization_id ELSE public.get_auth_org() END;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'organization context is required';
  END IF;

  IF v_start > v_end THEN
    RAISE EXCEPTION 'start date must be on or before end date';
  END IF;

  IF p_dimension NOT IN ('date', 'week', 'month', 'location', 'status', 'category', 'module') THEN
    RAISE EXCEPTION 'unsupported report dimension: %', p_dimension;
  END IF;

  SELECT value INTO v_bad
  FROM unnest(v_modules) AS value
  WHERE value <> ALL(v_allowed_modules)
  LIMIT 1;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'unsupported report module: %', v_bad;
  END IF;

  SELECT value INTO v_bad
  FROM unnest(COALESCE(p_metrics, ARRAY[]::TEXT[])) AS value
  WHERE value <> ALL(v_allowed_metrics)
  LIMIT 1;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'unsupported report metric: %', v_bad;
  END IF;

  WITH invoice_rows AS (
    SELECT
      'invoices'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(COALESCE(i.invoice_date, i.created_at::DATE)::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', COALESCE(i.invoice_date, i.created_at::DATE)::TIMESTAMP), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', COALESCE(i.invoice_date, i.created_at::DATE)::TIMESTAMP), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, NULLIF(i.location, ''), 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(i.status, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(i.source, ''), 'invoice')
        WHEN 'module' THEN 'Invoices'
      END AS dimension,
      jsonb_build_object(
        'invoice_count', COUNT(*)::NUMERIC,
        'invoice_total_amount', COALESCE(SUM(i.total_amount), 0)::NUMERIC,
        'invoice_approved_count', COUNT(*) FILTER (WHERE i.status IN ('approved','paid'))::NUMERIC,
        'invoice_unpaid_count', COUNT(*) FILTER (WHERE COALESCE(i.payment_status, 'unpaid') <> 'paid')::NUMERIC,
        'invoice_tax_amount', COALESCE(SUM(i.tax_amount), 0)::NUMERIC
      ) AS metrics
    FROM public.invoices i
    LEFT JOIN public.locations l ON l.id = i.location_id
    WHERE 'invoices' = ANY(v_modules)
      AND i.organization_id = v_org
      AND COALESCE(i.invoice_date, i.created_at::DATE) BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), payment_rows AS (
    SELECT
      'payments'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(COALESCE(p.payment_date, p.created_at::DATE)::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', COALESCE(p.payment_date, p.created_at::DATE)::TIMESTAMP), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', COALESCE(p.payment_date, p.created_at::DATE)::TIMESTAMP), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(p.status, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(p.payment_method, ''), 'payment')
        WHEN 'module' THEN 'Payments'
      END AS dimension,
      jsonb_build_object(
        'payment_count', COUNT(*)::NUMERIC,
        'payment_amount', COALESCE(SUM(p.amount), 0)::NUMERIC,
        'payment_completed_amount', COALESCE(SUM(p.amount) FILTER (WHERE p.status = 'completed'), 0)::NUMERIC,
        'payment_failed_count', COUNT(*) FILTER (WHERE p.status = 'failed')::NUMERIC
      ) AS metrics
    FROM public.payments p
    LEFT JOIN public.locations l ON l.id = p.location_id
    WHERE 'payments' = ANY(v_modules)
      AND p.organization_id = v_org
      AND COALESCE(p.payment_date, p.created_at::DATE) BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), product_rows AS (
    SELECT
      'products'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(p.created_at::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', p.created_at), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', p.created_at), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Org Catalog')
        WHEN 'status' THEN COALESCE(NULLIF(p.status, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(p.category, ''), NULLIF(p.accounting_category, ''), 'Uncategorized')
        WHEN 'module' THEN 'Products'
      END AS dimension,
      jsonb_build_object(
        'product_count', COUNT(*)::NUMERIC,
        'inventoried_product_count', COUNT(*) FILTER (WHERE COALESCE(p.is_inventoried, false))::NUMERIC,
        'avg_latest_price', COALESCE(AVG(p.latest_price), 0)::NUMERIC,
        'products_with_price_count', COUNT(*) FILTER (WHERE COALESCE(p.latest_price, 0) > 0)::NUMERIC
      ) AS metrics
    FROM public.products p
    LEFT JOIN public.locations l ON l.id = p.location_id
    WHERE 'products' = ANY(v_modules)
      AND p.organization_id = v_org
      AND p.created_at::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), inventory_rows AS (
    SELECT
      'inventory'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(COALESCE(inv.updated_at, inv.created_at)::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', COALESCE(inv.updated_at, inv.created_at)), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', COALESCE(inv.updated_at, inv.created_at)), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, NULLIF(inv.location, ''), 'Unassigned')
        WHEN 'status' THEN CASE WHEN COALESCE(inv.current_quantity, 0) <= COALESCE(inv.reorder_point, inv.par_level, 0) THEN 'low_stock' ELSE 'in_stock' END
        WHEN 'category' THEN COALESCE(NULLIF(inv.category, ''), NULLIF(inv.accounting_category, ''), 'Uncategorized')
        WHEN 'module' THEN 'Inventory'
      END AS dimension,
      jsonb_build_object(
        'inventory_value', COALESCE(SUM(inv.current_value), 0)::NUMERIC,
        'inventory_quantity', COALESCE(SUM(inv.current_quantity), 0)::NUMERIC,
        'low_stock_count', COUNT(*) FILTER (WHERE COALESCE(inv.current_quantity, 0) <= COALESCE(inv.reorder_point, inv.par_level, 0))::NUMERIC,
        'inventory_waste', 0::NUMERIC,
        'cogs', 0::NUMERIC
      ) AS metrics
    FROM public.inventory inv
    LEFT JOIN public.locations l ON l.id = inv.location_id
    WHERE 'inventory' = ANY(v_modules)
      AND inv.organization_id = v_org
      AND COALESCE(inv.updated_at, inv.created_at)::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), inventory_movement_rows AS (
    SELECT
      'inventory'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(im.created_at::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', im.created_at), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', im.created_at), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(im.movement_type, ''), 'movement')
        WHEN 'category' THEN COALESCE(NULLIF(base.category, ''), 'Movement')
        WHEN 'module' THEN 'Inventory'
      END AS dimension,
      jsonb_build_object(
        'inventory_waste', COALESCE(SUM(CASE WHEN im.movement_type IN ('wastage','spoilage') THEN ABS(im.quantity) * COALESCE(base.unit_cost, 0) ELSE 0 END), 0)::NUMERIC,
        'cogs', COALESCE(SUM(CASE WHEN im.quantity < 0 THEN ABS(im.quantity) * COALESCE(base.unit_cost, 0) ELSE 0 END), 0)::NUMERIC
      ) AS metrics
    FROM public.inventory_movements im
    LEFT JOIN public.inventory base ON base.id = im.inventory_id
    LEFT JOIN public.locations l ON l.id = im.location_id
    WHERE 'inventory' = ANY(v_modules)
      AND im.organization_id = v_org
      AND im.created_at::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), recipe_rows AS (
    SELECT
      'recipes'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(r.created_at::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', r.created_at), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', r.created_at), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Recipe Library')
        WHEN 'status' THEN COALESCE(NULLIF(r.status, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(r.category, ''), 'Uncategorized')
        WHEN 'module' THEN 'Recipes'
      END AS dimension,
      jsonb_build_object(
        'recipe_count', COUNT(*)::NUMERIC,
        'avg_recipe_cost', COALESCE(AVG(r.total_cost), 0)::NUMERIC,
        'avg_suggested_price', COALESCE(AVG(r.suggested_price), 0)::NUMERIC,
        'avg_cost_per_serving', COALESCE(AVG(r.cost_per_serving), 0)::NUMERIC
      ) AS metrics
    FROM public.recipes r
    LEFT JOIN public.locations l ON l.id = r.location_id
    WHERE 'recipes' = ANY(v_modules)
      AND r.organization_id = v_org
      AND r.created_at::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), performance_sales_rows AS (
    SELECT
      'performance'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(po.order_date::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', po.order_date), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', po.order_date), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(po.status, ''), 'order')
        WHEN 'category' THEN 'POS Sales'
        WHEN 'module' THEN 'Performance'
      END AS dimension,
      jsonb_build_object(
        'sales_revenue', COALESCE(SUM(po.total_amount), 0)::NUMERIC,
        'pos_transaction_count', COUNT(*)::NUMERIC,
        'gross_profit', COALESCE(SUM(po.total_amount), 0)::NUMERIC
      ) AS metrics
    FROM public.pos_orders po
    LEFT JOIN public.locations l ON l.id = po.location_id
    WHERE 'performance' = ANY(v_modules)
      AND po.organization_id = v_org
      AND po.order_date::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), performance_labor_rows AS (
    SELECT
      'performance'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(es.shift_start::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', es.shift_start), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', es.shift_start), 'YYYY-MM')
        WHEN 'location' THEN COALESCE(l.name, 'Unassigned')
        WHEN 'status' THEN COALESCE(NULLIF(es.status, ''), 'shift')
        WHEN 'category' THEN 'Labor'
        WHEN 'module' THEN 'Performance'
      END AS dimension,
      jsonb_build_object(
        'labor_cost', COALESCE(SUM(es.labor_cost), 0)::NUMERIC,
        'prime_cost', COALESCE(SUM(es.labor_cost), 0)::NUMERIC,
        'gross_profit', -COALESCE(SUM(es.labor_cost), 0)::NUMERIC
      ) AS metrics
    FROM public.employee_shifts es
    LEFT JOIN public.locations l ON l.id = es.location_id
    WHERE 'performance' = ANY(v_modules)
      AND es.organization_id = v_org
      AND es.shift_start::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), audit_rows AS (
    SELECT
      'audit_logs'::TEXT AS module,
      CASE p_dimension
        WHEN 'date' THEN to_char(a.created_at::DATE::TIMESTAMP, 'YYYY-MM-DD')
        WHEN 'week' THEN to_char(date_trunc('week', a.created_at), 'IYYY-IW')
        WHEN 'month' THEN to_char(date_trunc('month', a.created_at), 'YYYY-MM')
        WHEN 'location' THEN 'Organization'
        WHEN 'status' THEN COALESCE(NULLIF(a.action, ''), 'unknown')
        WHEN 'category' THEN COALESCE(NULLIF(a.table_name, ''), 'unknown_table')
        WHEN 'module' THEN 'Audit Logs'
      END AS dimension,
      jsonb_build_object(
        'audit_event_count', COUNT(*)::NUMERIC,
        'audit_insert_count', COUNT(*) FILTER (WHERE upper(a.action) = 'INSERT')::NUMERIC,
        'audit_update_count', COUNT(*) FILTER (WHERE upper(a.action) = 'UPDATE')::NUMERIC,
        'audit_delete_count', COUNT(*) FILTER (WHERE upper(a.action) = 'DELETE')::NUMERIC
      ) AS metrics
    FROM public.audit_logs a
    WHERE 'audit_logs' = ANY(v_modules)
      AND a.organization_id = v_org
      AND a.created_at::DATE BETWEEN v_start AND v_end
    GROUP BY 1, 2
  ), unioned AS (
    SELECT * FROM invoice_rows
    UNION ALL SELECT * FROM payment_rows
    UNION ALL SELECT * FROM product_rows
    UNION ALL SELECT * FROM inventory_rows
    UNION ALL SELECT * FROM inventory_movement_rows
    UNION ALL SELECT * FROM recipe_rows
    UNION ALL SELECT * FROM performance_sales_rows
    UNION ALL SELECT * FROM performance_labor_rows
    UNION ALL SELECT * FROM audit_rows
  ), merged AS (
    SELECT
      module,
      dimension,
      SUM(COALESCE((metrics->>'invoice_count')::NUMERIC, 0)) AS invoice_count,
      SUM(COALESCE((metrics->>'invoice_total_amount')::NUMERIC, 0)) AS invoice_total_amount,
      SUM(COALESCE((metrics->>'invoice_approved_count')::NUMERIC, 0)) AS invoice_approved_count,
      SUM(COALESCE((metrics->>'invoice_unpaid_count')::NUMERIC, 0)) AS invoice_unpaid_count,
      SUM(COALESCE((metrics->>'invoice_tax_amount')::NUMERIC, 0)) AS invoice_tax_amount,
      SUM(COALESCE((metrics->>'payment_count')::NUMERIC, 0)) AS payment_count,
      SUM(COALESCE((metrics->>'payment_amount')::NUMERIC, 0)) AS payment_amount,
      SUM(COALESCE((metrics->>'payment_completed_amount')::NUMERIC, 0)) AS payment_completed_amount,
      SUM(COALESCE((metrics->>'payment_failed_count')::NUMERIC, 0)) AS payment_failed_count,
      SUM(COALESCE((metrics->>'product_count')::NUMERIC, 0)) AS product_count,
      SUM(COALESCE((metrics->>'inventoried_product_count')::NUMERIC, 0)) AS inventoried_product_count,
      SUM(COALESCE((metrics->>'avg_latest_price')::NUMERIC, 0)) AS avg_latest_price,
      SUM(COALESCE((metrics->>'products_with_price_count')::NUMERIC, 0)) AS products_with_price_count,
      SUM(COALESCE((metrics->>'inventory_value')::NUMERIC, 0)) AS inventory_value,
      SUM(COALESCE((metrics->>'inventory_quantity')::NUMERIC, 0)) AS inventory_quantity,
      SUM(COALESCE((metrics->>'low_stock_count')::NUMERIC, 0)) AS low_stock_count,
      SUM(COALESCE((metrics->>'inventory_waste')::NUMERIC, 0)) AS inventory_waste,
      SUM(COALESCE((metrics->>'cogs')::NUMERIC, 0)) AS cogs,
      SUM(COALESCE((metrics->>'recipe_count')::NUMERIC, 0)) AS recipe_count,
      SUM(COALESCE((metrics->>'avg_recipe_cost')::NUMERIC, 0)) AS avg_recipe_cost,
      SUM(COALESCE((metrics->>'avg_suggested_price')::NUMERIC, 0)) AS avg_suggested_price,
      SUM(COALESCE((metrics->>'avg_cost_per_serving')::NUMERIC, 0)) AS avg_cost_per_serving,
      SUM(COALESCE((metrics->>'sales_revenue')::NUMERIC, 0)) AS sales_revenue,
      SUM(COALESCE((metrics->>'pos_transaction_count')::NUMERIC, 0)) AS pos_transaction_count,
      SUM(COALESCE((metrics->>'labor_cost')::NUMERIC, 0)) AS labor_cost,
      SUM(COALESCE((metrics->>'prime_cost')::NUMERIC, 0)) + SUM(COALESCE((metrics->>'cogs')::NUMERIC, 0)) AS prime_cost,
      SUM(COALESCE((metrics->>'gross_profit')::NUMERIC, 0)) - SUM(COALESCE((metrics->>'cogs')::NUMERIC, 0)) AS gross_profit,
      SUM(COALESCE((metrics->>'audit_event_count')::NUMERIC, 0)) AS audit_event_count,
      SUM(COALESCE((metrics->>'audit_insert_count')::NUMERIC, 0)) AS audit_insert_count,
      SUM(COALESCE((metrics->>'audit_update_count')::NUMERIC, 0)) AS audit_update_count,
      SUM(COALESCE((metrics->>'audit_delete_count')::NUMERIC, 0)) AS audit_delete_count
    FROM unioned
    WHERE dimension IS NOT NULL
    GROUP BY module, dimension
  )
  SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
    'module', module,
    'dimension', dimension,
    'invoice_count', CASE WHEN 'invoice_count' = ANY(p_metrics) THEN invoice_count END,
    'invoice_total_amount', CASE WHEN 'invoice_total_amount' = ANY(p_metrics) THEN invoice_total_amount END,
    'invoice_approved_count', CASE WHEN 'invoice_approved_count' = ANY(p_metrics) THEN invoice_approved_count END,
    'invoice_unpaid_count', CASE WHEN 'invoice_unpaid_count' = ANY(p_metrics) THEN invoice_unpaid_count END,
    'invoice_tax_amount', CASE WHEN 'invoice_tax_amount' = ANY(p_metrics) THEN invoice_tax_amount END,
    'payment_count', CASE WHEN 'payment_count' = ANY(p_metrics) THEN payment_count END,
    'payment_amount', CASE WHEN 'payment_amount' = ANY(p_metrics) THEN payment_amount END,
    'payment_completed_amount', CASE WHEN 'payment_completed_amount' = ANY(p_metrics) THEN payment_completed_amount END,
    'payment_failed_count', CASE WHEN 'payment_failed_count' = ANY(p_metrics) THEN payment_failed_count END,
    'product_count', CASE WHEN 'product_count' = ANY(p_metrics) THEN product_count END,
    'inventoried_product_count', CASE WHEN 'inventoried_product_count' = ANY(p_metrics) THEN inventoried_product_count END,
    'avg_latest_price', CASE WHEN 'avg_latest_price' = ANY(p_metrics) THEN avg_latest_price END,
    'products_with_price_count', CASE WHEN 'products_with_price_count' = ANY(p_metrics) THEN products_with_price_count END,
    'inventory_value', CASE WHEN 'inventory_value' = ANY(p_metrics) THEN inventory_value END,
    'inventory_quantity', CASE WHEN 'inventory_quantity' = ANY(p_metrics) THEN inventory_quantity END,
    'low_stock_count', CASE WHEN 'low_stock_count' = ANY(p_metrics) THEN low_stock_count END,
    'inventory_waste', CASE WHEN 'inventory_waste' = ANY(p_metrics) THEN inventory_waste END,
    'cogs', CASE WHEN 'cogs' = ANY(p_metrics) THEN cogs END,
    'recipe_count', CASE WHEN 'recipe_count' = ANY(p_metrics) THEN recipe_count END,
    'avg_recipe_cost', CASE WHEN 'avg_recipe_cost' = ANY(p_metrics) THEN avg_recipe_cost END,
    'avg_suggested_price', CASE WHEN 'avg_suggested_price' = ANY(p_metrics) THEN avg_suggested_price END,
    'avg_cost_per_serving', CASE WHEN 'avg_cost_per_serving' = ANY(p_metrics) THEN avg_cost_per_serving END,
    'sales_revenue', CASE WHEN 'sales_revenue' = ANY(p_metrics) THEN sales_revenue END,
    'pos_transaction_count', CASE WHEN 'pos_transaction_count' = ANY(p_metrics) THEN pos_transaction_count END,
    'labor_cost', CASE WHEN 'labor_cost' = ANY(p_metrics) THEN labor_cost END,
    'prime_cost', CASE WHEN 'prime_cost' = ANY(p_metrics) THEN prime_cost END,
    'gross_profit', CASE WHEN 'gross_profit' = ANY(p_metrics) THEN gross_profit END,
    'audit_event_count', CASE WHEN 'audit_event_count' = ANY(p_metrics) THEN audit_event_count END,
    'audit_insert_count', CASE WHEN 'audit_insert_count' = ANY(p_metrics) THEN audit_insert_count END,
    'audit_update_count', CASE WHEN 'audit_update_count' = ANY(p_metrics) THEN audit_update_count END,
    'audit_delete_count', CASE WHEN 'audit_delete_count' = ANY(p_metrics) THEN audit_delete_count END
  )) ORDER BY module, dimension), '[]'::JSONB)
  INTO v_result
  FROM merged;

  RETURN v_result;
END;
$$;

-- Source: 20260723000015_admin_manual_vendor_banking_entry.sql
-- Staff-facing counterpart to the vendor's magic-link submit-bank-info, for vendors who read
-- routing/account numbers over the phone rather than using the portal. Mirrors
-- submit_vendor_banking_via_link's body (same format validation, same vault call, same
-- change-request/reason logic) but keys off p_vendor_id directly instead of resolving it from a
-- token, since there's no token here. Deliberately does NOT skip the phone-callback verification
-- step downstream (VO-RULE-015's anti-fraud control) -- manual entry only changes how the
-- numbers arrived, not whether the account still needs confirming before it's payable.
CREATE OR REPLACE FUNCTION public.admin_submit_vendor_banking_info(
  p_vendor_id uuid,
  p_account text,
  p_routing text,
  p_intent text DEFAULT 'add'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_vendor public.vendors%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_store_result jsonb;
  v_reason text;
  v_intent text := COALESCE(NULLIF(btrim(p_intent), ''), 'add');
BEGIN
  IF v_intent NOT IN ('add', 'replace') THEN
    RAISE EXCEPTION 'Invalid vendor banking intent: %', p_intent;
  END IF;

  SELECT * INTO v_vendor
  FROM public.vendors
  WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, NULL::timestamptz, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  -- Same precondition issue_vendor_banking_link enforces (VO-RULE-005) -- the UI already greys
  -- this button out via canIssueBanking, but per this codebase's own rule that enforcement must
  -- be DB-side, not UI-only, the RPC needs its own copy of the check, not just a disabled prop.
  IF NOT EXISTS (
    SELECT 1
    FROM public.vendor_tax_information vti
    WHERE vti.vendor_id = p_vendor_id
      AND vti.verification_status = 'verified'
      AND vti.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Business is not verified';
  END IF;

  IF NOT public.vendor_has_required_onboarding_documents(p_vendor_id) THEN
    RAISE EXCEPTION 'Required vendor documents are not on file';
  END IF;

  IF regexp_replace(COALESCE(p_account, ''), '\D', '', 'g') !~ '^\d{4,17}$' THEN
    RAISE EXCEPTION 'A valid bank account number (4-17 digits) is required';
  END IF;

  IF regexp_replace(COALESCE(p_routing, ''), '\D', '', 'g') !~ '^\d{9}$' THEN
    RAISE EXCEPTION 'A valid 9-digit routing number is required';
  END IF;

  IF v_intent = 'replace' THEN
    v_reason := 'vendor_requested_update';
  ELSIF EXISTS (
    SELECT 1
    FROM public.vendor_banking_details existing
    WHERE existing.vendor_id = p_vendor_id
      AND existing.is_default = true
      AND existing.is_active = true
      AND existing.deleted_at IS NULL
  ) THEN
    v_reason := 'admin_correction';
  ELSE
    v_reason := 'onboarding';
  END IF;

  INSERT INTO public.vendor_banking_details (
    vendor_id,
    organization_id,
    brand_id,
    location_id,
    verification_state,
    callback_status,
    is_default,
    created_by,
    updated_by
  ) VALUES (
    p_vendor_id,
    v_vendor.organization_id,
    v_vendor.brand_id,
    v_vendor.location_id,
    'pending',
    'pending',
    false,
    auth.uid(),
    auth.uid()
  )
  RETURNING * INTO v_bank;

  v_store_result := public.store_vendor_banking_secret(v_bank.id, p_account, p_routing);

  INSERT INTO public.vendor_banking_change_requests (
    vendor_id,
    banking_detail_id,
    request_reason,
    requested_by,
    callback_phone_source,
    created_by,
    updated_by
  ) VALUES (
    p_vendor_id,
    v_bank.id,
    v_reason,
    auth.uid(),
    'on_file_contact',
    auth.uid(),
    auth.uid()
  )
  RETURNING * INTO v_request;

  UPDATE public.vendors
     SET onboarding_status = 'banking_submitted'
   WHERE id = p_vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, from_status, to_status, actor_id, actor_type, metadata
  ) VALUES (
    p_vendor_id,
    'banking_submitted',
    NULL,
    'banking_submitted',
    auth.uid(),
    'admin',
    jsonb_build_object(
      'banking_row_id', v_bank.id,
      'change_request_id', v_request.id,
      'intent', v_intent,
      'entry_method', 'manual'
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', p_vendor_id,
    'banking_row_id', v_bank.id,
    'banking_change_request_id', v_request.id,
    'banking_secret_id', v_store_result->>'banking_secret_id',
    'account_last4', v_store_result->>'account_last4',
    'intent', v_intent,
    'is_default', v_bank.is_default,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status
  );
END;
$function$;

-- Source: 20260724000000_hard_delete_invoice_workflow.sql
-- 20260724000000: Change invoice workflow deletion from soft delete to hard delete.

CREATE OR REPLACE FUNCTION public.hard_delete_invoice_workflow(p_invoice_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_invoice RECORD;
BEGIN
  SELECT id, organization_id
    INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF v_invoice.id IS NULL THEN
    RAISE EXCEPTION 'Invoice not found';
  END IF;

  PERFORM public.assert_financial_actor(v_invoice.organization_id);

  -- Cascading deletes of approved/paid invoice_line_items pass through the
  -- same internal bypass used by product sync. This keeps edit protection in
  -- place while allowing an intentional invoice hard delete to complete.
  PERFORM set_config('app.invoice_product_sync', 'on', true);

  DELETE FROM public.invoices
   WHERE id = p_invoice_id;

  PERFORM set_config('app.invoice_product_sync', '', true);

  RETURN FOUND;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('app.invoice_product_sync', '', true);
  RAISE;
END;
$$;

COMMENT ON FUNCTION public.hard_delete_invoice_workflow(UUID)
IS 'Permanently deletes an invoice row after financial actor authorization. Related rows follow their foreign key cascade/set-null rules.';

-- Backward compatibility for older clients that still call the previous RPC name.
CREATE OR REPLACE FUNCTION public.soft_delete_invoice_workflow(p_invoice_id UUID)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  RETURN public.hard_delete_invoice_workflow(p_invoice_id);
END;
$$;

COMMENT ON FUNCTION public.soft_delete_invoice_workflow(UUID)
IS 'Compatibility wrapper. Invoice deletion is now hard delete via hard_delete_invoice_workflow.';

-- Source: 20260724000001_menu_item_authoring_edit.sql
create or replace function public.save_menu_item_phase1(
  p_recipe jsonb,
  p_yields jsonb,
  p_visibility jsonb,
  p_equipment_names jsonb,
  p_steps jsonb,
  p_location_prices jsonb
)
returns public.recipes
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_org uuid := nullif(p_recipe->>'organization_id', '')::uuid;
  v_id uuid := nullif(p_recipe->>'id', '')::uuid;
  v_recipe public.recipes;
  v_row jsonb;
  v_equipment_id uuid;
begin
  if auth.uid() is null or v_org is null or v_org <> public.get_my_org() or not public.is_manager_or_above() then
    raise exception 'Not authorized to save menu items';
  end if;
  if coalesce(trim(p_recipe->>'name'), '') = '' then raise exception 'Name is required'; end if;
  if jsonb_typeof(p_yields) <> 'array' or jsonb_array_length(p_yields) = 0 then raise exception 'At least one yield is required'; end if;

  if v_id is null then
    insert into public.recipes (
      organization_id, brand_id, location_id, name, description, category, status,
      recipe_type_id, yield_quantity, yield_unit, yield_percentage, ingredients,
      instructions, selling_price, target_margin_percent, margin_alert_enabled,
      total_ingredient_cost, total_packaging_cost, labor_cost, total_cost,
      cost_per_serving, is_batch, shelf_life_quantity, shelf_life_unit, created_by
    ) values (
      v_org, nullif(p_recipe->>'brand_id', '')::uuid, nullif(p_recipe->>'location_id', '')::uuid,
      trim(p_recipe->>'name'), nullif(p_recipe->>'description', ''), coalesce(nullif(p_recipe->>'category', ''), 'other'),
      coalesce(nullif(p_recipe->>'status', ''), 'active'), nullif(p_recipe->>'recipe_type_id', '')::uuid,
      (p_yields->0->>'quantity')::numeric, p_yields->0->>'unit', 100,
      coalesce(p_recipe->'ingredients', '[]'::jsonb), coalesce(p_recipe->>'instructions', ''),
      coalesce(nullif(p_recipe->>'selling_price', '')::numeric, 0),
      coalesce(nullif(p_recipe->>'target_margin_percent', '')::numeric, 70),
      coalesce((p_recipe->>'margin_alert_enabled')::boolean, true),
      coalesce(nullif(p_recipe->>'total_ingredient_cost', '')::numeric, 0), 0, 0,
      coalesce(nullif(p_recipe->>'total_cost', '')::numeric, 0),
      coalesce(nullif(p_recipe->>'cost_per_serving', '')::numeric, 0), false,
      nullif(p_recipe->>'shelf_life_quantity', '')::numeric, nullif(p_recipe->>'shelf_life_unit', ''), auth.uid()
    ) returning * into v_recipe;
    v_id := v_recipe.id;
  else
    update public.recipes
    set
      brand_id = nullif(p_recipe->>'brand_id', '')::uuid,
      location_id = nullif(p_recipe->>'location_id', '')::uuid,
      name = trim(p_recipe->>'name'),
      description = nullif(p_recipe->>'description', ''),
      category = coalesce(nullif(p_recipe->>'category', ''), 'other'),
      status = coalesce(nullif(p_recipe->>'status', ''), 'active'),
      recipe_type_id = nullif(p_recipe->>'recipe_type_id', '')::uuid,
      yield_quantity = (p_yields->0->>'quantity')::numeric,
      yield_unit = p_yields->0->>'unit',
      yield_percentage = 100,
      ingredients = coalesce(p_recipe->'ingredients', '[]'::jsonb),
      instructions = coalesce(p_recipe->>'instructions', ''),
      selling_price = coalesce(nullif(p_recipe->>'selling_price', '')::numeric, 0),
      target_margin_percent = coalesce(nullif(p_recipe->>'target_margin_percent', '')::numeric, 70),
      margin_alert_enabled = coalesce((p_recipe->>'margin_alert_enabled')::boolean, true),
      total_ingredient_cost = coalesce(nullif(p_recipe->>'total_ingredient_cost', '')::numeric, 0),
      total_cost = coalesce(nullif(p_recipe->>'total_cost', '')::numeric, 0),
      cost_per_serving = coalesce(nullif(p_recipe->>'cost_per_serving', '')::numeric, 0),
      is_batch = false,
      shelf_life_quantity = nullif(p_recipe->>'shelf_life_quantity', '')::numeric,
      shelf_life_unit = nullif(p_recipe->>'shelf_life_unit', ''),
      updated_at = now()
    where id = v_id
      and organization_id = v_org
      and not coalesce(is_batch, false)
    returning * into v_recipe;

    if v_recipe.id is null then
      raise exception 'Menu Item not found';
    end if;
  end if;

  delete from public.recipe_yields where recipe_id = v_id;
  for v_row in select value from jsonb_array_elements(p_yields)
  loop
    insert into public.recipe_yields (organization_id, recipe_id, quantity, unit, is_primary, cost_per_unit)
    values (v_org, v_id, (v_row->>'quantity')::numeric, trim(v_row->>'unit'), coalesce((v_row->>'is_primary')::boolean, false), nullif(v_row->>'cost_per_unit', '')::numeric);
  end loop;

  delete from public.recipe_location_visibility where recipe_id = v_id;
  if coalesce(p_visibility->>'mode', 'all') = 'selected' then
    for v_row in select value from jsonb_array_elements(coalesce(p_visibility->'location_ids', '[]'::jsonb))
    loop
      insert into public.recipe_location_visibility (organization_id, recipe_id, location_id, is_visible)
      select v_org, v_id, trim(both '"' from v_row::text)::uuid, true
      from public.locations l
      where l.id = trim(both '"' from v_row::text)::uuid and l.organization_id = v_org;
    end loop;
  end if;

  delete from public.recipe_equipment_assignments where recipe_id = v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_equipment_names, '[]'::jsonb))
  loop
    insert into public.recipe_equipment_catalog (organization_id, name)
    values (v_org, trim(both '"' from v_row::text))
    on conflict (organization_id, lower(name)) do update set is_active = true, updated_at = now()
    returning id into v_equipment_id;
    insert into public.recipe_equipment_assignments (organization_id, recipe_id, equipment_id)
    values (v_org, v_id, v_equipment_id) on conflict do nothing;
  end loop;

  delete from public.recipe_preparation_steps where recipe_id = v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_steps, '[]'::jsonb))
  loop
    insert into public.recipe_preparation_steps (organization_id, recipe_id, step_number, instruction, notes)
    values (v_org, v_id, (v_row->>'step_number')::integer, trim(v_row->>'instruction'), nullif(v_row->>'notes', ''));
  end loop;

  delete from public.recipe_location_prices where recipe_id = v_id;
  for v_row in select value from jsonb_array_elements(coalesce(p_location_prices, '[]'::jsonb))
  loop
    insert into public.recipe_location_prices (organization_id, recipe_id, location_id, price)
    select v_org, v_id, (v_row->>'location_id')::uuid, (v_row->>'price')::numeric
    from public.locations l
    where l.id = (v_row->>'location_id')::uuid and l.organization_id = v_org;
  end loop;

  return v_recipe;
end;
$$;

comment on function public.save_menu_item_phase1(jsonb, jsonb, jsonb, jsonb, jsonb, jsonb) is
  'Atomically creates or updates a tenant-scoped Menu Item and its Recipe-owned child records.';

-- Source: 20260724000001_repair_invite_module_entitlements.sql
CREATE OR REPLACE FUNCTION public.normalize_invited_module_keys(p_modules jsonb)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
SET search_path TO ''
AS $$
  WITH allowed_modules(module_key) AS (
    VALUES
      ('dashboard'),
      ('dashboard_reports'),
      ('performance'),
      ('executive_bi'),
      ('custom_reports'),
      ('invoices'),
      ('payments'),
      ('billing'),
      ('products'),
      ('inventory'),
      ('orders'),
      ('smartprep'),
      ('commissary'),
      ('recipes'),
      ('vendors'),
      ('labor'),
      ('accounting'),
      ('admin'),
      ('setup'),
      ('food_safety'),
      ('kitchen_displays'),
      ('integrations'),
      ('crm_marketing'),
      ('ai_insights')
  ), normalized AS (
    SELECT DISTINCT lower(btrim(module_key.value)) AS module_key
    FROM jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(p_modules) = 'array' THEN p_modules ELSE '[]'::jsonb END
    ) AS module_key(value)
    WHERE NULLIF(btrim(module_key.value), '') IS NOT NULL
  )
  SELECT NULLIF(COALESCE(jsonb_agg(normalized.module_key ORDER BY normalized.module_key), '[]'::jsonb), '[]'::jsonb)
  FROM normalized
  JOIN allowed_modules USING (module_key);
$$;

CREATE OR REPLACE FUNCTION public.get_invited_enabled_modules(p_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_modules jsonb;
  v_user_email text;
BEGIN
  IF p_user_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT lower(email) INTO v_user_email
  FROM auth.users
  WHERE id = p_user_id;

  WITH latest_invite AS (
    SELECT public.normalize_invited_module_keys(i.metadata->'modules') AS modules
    FROM public.invitations i
    WHERE (
        i.accepted_by = p_user_id
        OR lower(i.email) = v_user_email
        OR i.id::text = (
          SELECT t.metadata->>'invitation_id'
          FROM public.tenants t
          WHERE t.owner_id = p_user_id
          ORDER BY t.created_at DESC
          LIMIT 1
        )
      )
      AND jsonb_typeof(i.metadata->'modules') = 'array'
    ORDER BY COALESCE(i.accepted_at, i.created_at) DESC, i.created_at DESC
    LIMIT 1
  )
  SELECT modules INTO v_modules
  FROM latest_invite
  WHERE modules IS NOT NULL;

  RETURN v_modules;
END;
$$;

CREATE OR REPLACE FUNCTION public.get_tenant_enabled_modules(p_tenant_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_modules jsonb;
BEGIN
  IF p_tenant_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(
    public.normalize_invited_module_keys(metadata->'enabled_modules'),
    public.normalize_invited_module_keys(metadata->'invite_modules')
  )
  INTO v_modules
  FROM public.tenants
  WHERE id = p_tenant_id;

  RETURN v_modules;
END;
$$;

CREATE OR REPLACE FUNCTION public.sync_invited_modules_to_tenant(p_user_id uuid, p_tenant_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_modules jsonb;
BEGIN
  IF p_user_id IS NULL OR p_tenant_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_modules := COALESCE(
    public.get_tenant_enabled_modules(p_tenant_id),
    public.get_invited_enabled_modules(p_user_id)
  );

  IF v_modules IS NULL THEN
    RETURN NULL;
  END IF;

  UPDATE public.tenants
  SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'enabled_modules', v_modules,
        'invite_modules', v_modules,
        'module_source', 'platform_invitation'
      ),
      updated_at = now()
  WHERE id = p_tenant_id;

  RETURN v_modules;
END;
$$;

CREATE OR REPLACE FUNCTION public.apply_invited_modules_to_organization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_modules jsonb;
BEGIN
  IF NEW.owner_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.tenant_id IS NOT NULL THEN
    v_modules := public.sync_invited_modules_to_tenant(NEW.owner_id, NEW.tenant_id);
  ELSE
    v_modules := public.get_invited_enabled_modules(NEW.owner_id);
  END IF;

  IF v_modules IS NOT NULL
     AND COALESCE(jsonb_array_length(
       CASE
         WHEN jsonb_typeof(NEW.enabled_modules) = 'array' THEN NEW.enabled_modules
         ELSE '[]'::jsonb
       END
     ), 0) = 0 THEN
    NEW.enabled_modules := v_modules;
  END IF;

  RETURN NEW;
END;
$$;

-- Source: 20260724000002_fix_vendor_metrics_paid_status_reversal.sql
-- update_vendor_metrics_on_invoice only ever recognized status='approved' as the "counts toward
-- total_spent" state. normalize_invoice_ap_state (added later) force-rewrites NEW.status to
-- 'paid' whenever payment_status becomes 'paid', in the SAME update statement -- so paying an
-- approved invoice makes this trigger see OLD.status='approved', NEW.status='paid' and treat it
-- as a REVERSAL (invoice rejected/flagged), incorrectly backing total_spent out to zero on the
-- vendor. A paid invoice is still money spent; it should never have left the "spent" bucket.
-- Confirmed live: vendor_metrics_reversal_acceptance.sql's approve-then-pay assertion failed
-- with total_spent=0 instead of the expected 500 before this fix.
CREATE OR REPLACE FUNCTION public.update_vendor_metrics_on_invoice()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $function$
BEGIN
  -- Entering the "spent" lifecycle (approved or paid -- normalize_invoice_ap_state can jump an
  -- update straight from approved to paid in the same statement, so NEW.status may already be
  -- 'paid' the first time this invoice is ever seen as spent).
  IF NEW.status IN ('approved', 'paid') AND (OLD.status IS NULL OR OLD.status NOT IN ('approved', 'paid')) THEN
    UPDATE public.vendors
    SET total_spent = total_spent + NEW.total_amount,
        unpaid_ap = unpaid_ap + NEW.total_amount
    WHERE id = NEW.vendor_id;
  END IF;

  -- Leaving the "spent" lifecycle entirely (rejected/flagged/reverted -- NOT just moving between
  -- approved and paid) while not soft-deleted: back out total spend, and back out unpaid_ap too
  -- if it hadn't already been paid off.
  IF OLD.status IN ('approved', 'paid') AND NEW.status NOT IN ('approved', 'paid') AND NEW.deleted_at IS NULL THEN
    UPDATE public.vendors
    SET total_spent = GREATEST(total_spent - OLD.total_amount, 0),
        unpaid_ap = CASE WHEN OLD.payment_status IS DISTINCT FROM 'paid'
                          THEN GREATEST(unpaid_ap - OLD.total_amount, 0)
                          ELSE unpaid_ap END
    WHERE id = OLD.vendor_id;
  END IF;

  -- Entering paid: remove from outstanding AP.
  IF NEW.payment_status = 'paid' AND (OLD.payment_status IS NULL OR OLD.payment_status != 'paid') THEN
    UPDATE public.vendors
    SET unpaid_ap = GREATEST(unpaid_ap - NEW.total_amount, 0)
    WHERE id = NEW.vendor_id;
  END IF;

  -- Payment reversed on a still-approved-or-paid invoice: it's outstanding again.
  IF OLD.payment_status = 'paid' AND NEW.payment_status IS DISTINCT FROM 'paid'
     AND NEW.status IN ('approved', 'paid') AND NEW.deleted_at IS NULL THEN
    UPDATE public.vendors
    SET unpaid_ap = unpaid_ap + NEW.total_amount
    WHERE id = NEW.vendor_id;
  END IF;

  -- Soft-deleting an approved-or-paid invoice: back out the same as leaving that lifecycle.
  IF NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL AND OLD.status IN ('approved', 'paid') THEN
    UPDATE public.vendors
    SET total_spent = GREATEST(total_spent - OLD.total_amount, 0),
        unpaid_ap = CASE WHEN OLD.payment_status IS DISTINCT FROM 'paid'
                          THEN GREATEST(unpaid_ap - OLD.total_amount, 0)
                          ELSE unpaid_ap END
    WHERE id = OLD.vendor_id;
  END IF;

  RETURN NEW;
END;
$function$;

-- Source: 20260724000002_sync_auth_metadata_from_profile_after_invite.sql
CREATE OR REPLACE FUNCTION public.sync_auth_metadata_from_profile(p_user_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_profile record;
BEGIN
  SELECT
    role,
    tenant_id,
    organization_id,
    brand_id,
    location_id
  INTO v_profile
  FROM public.profiles
  WHERE id = p_user_id
    AND deleted_at IS NULL;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  UPDATE auth.users
  SET raw_app_meta_data = COALESCE(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
    'role', COALESCE(v_profile.role, ''),
    'tenant_id', COALESCE(v_profile.tenant_id::text, ''),
    'organization_id', COALESCE(v_profile.organization_id::text, ''),
    'brand_id', COALESCE(v_profile.brand_id::text, ''),
    'location_id', COALESCE(v_profile.location_id::text, '')
  )
  WHERE id = p_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_invitation(p_token text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_invite record;
  v_user_id uuid;
  v_user_email text;
  v_user_name text;
  v_role text;
  v_tenant_id uuid;
  v_business_verification_required boolean := true;
  v_coupon_code text;
  v_profile_context record;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT
    email,
    COALESCE(raw_user_meta_data->>'full_name', raw_user_meta_data->>'name', split_part(email, '@', 1))
  INTO v_user_email, v_user_name
  FROM auth.users
  WHERE id = v_user_id;

  SELECT * INTO v_invite
  FROM public.invitations
  WHERE token::text = p_token
    AND accepted_at IS NULL
    AND closed_at IS NULL
    AND lower(email) = lower(v_user_email)
    AND (expires_at IS NULL OR expires_at > now())
  FOR UPDATE;

  IF v_invite IS NULL THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  v_role := public.normalize_app_role(v_invite.role);
  v_tenant_id := v_invite.tenant_id;
  v_business_verification_required := COALESCE((v_invite.metadata->>'business_verification_required')::boolean, true);
  v_coupon_code := COALESCE(v_invite.metadata->>'coupon_code', v_invite.metadata#>>'{coupon,code}');

  IF v_tenant_id IS NULL AND v_invite.organization_id IS NOT NULL THEN
    SELECT tenant_id INTO v_tenant_id FROM public.organizations WHERE id = v_invite.organization_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NULL THEN
    INSERT INTO public.tenants (name, owner_id, metadata)
    VALUES (
      COALESCE(v_invite.metadata->>'tenant_name', split_part(v_user_email, '@', 1), 'Tenant'),
      v_user_id,
      jsonb_build_object(
        'source', 'accept_invitation',
        'invitation_id', v_invite.id,
        'invited_email', v_invite.email,
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
    )
    RETURNING id INTO v_tenant_id;
  END IF;

  IF v_role = 'tenant_super_admin' AND v_tenant_id IS NOT NULL THEN
    INSERT INTO public.tenant_members (tenant_id, user_id, role)
    VALUES (v_tenant_id, v_user_id, 'tenant_super_admin')
    ON CONFLICT (tenant_id, user_id) DO UPDATE SET role = EXCLUDED.role;

    UPDATE public.tenants
    SET owner_id = COALESCE(owner_id, v_user_id),
        metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
          'business_verification_required', v_business_verification_required,
          'coupon_code', v_coupon_code
        ),
        updated_at = now()
    WHERE id = v_tenant_id;
  END IF;

  IF v_invite.organization_id IS NOT NULL THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES (v_invite.organization_id, v_user_id, v_role)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.brand_id IS NOT NULL THEN
    INSERT INTO public.brand_members (brand_id, user_id, role)
    VALUES (v_invite.brand_id, v_user_id, v_role)
    ON CONFLICT (brand_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  IF v_invite.location_id IS NOT NULL THEN
    INSERT INTO public.location_members (location_id, user_id, role)
    VALUES (v_invite.location_id, v_user_id, v_role)
    ON CONFLICT (location_id, user_id) DO UPDATE SET role = EXCLUDED.role;
  END IF;

  PERFORM set_config('app.trusted_profile_write', 'on', true);

  INSERT INTO public.profiles (
    id,
    email,
    full_name,
    tenant_id,
    role,
    organization_id,
    brand_id,
    location_id,
    coupon_code,
    payment_verified,
    business_verification_status,
    onboarding_status,
    onboarding_current_step,
    is_active
  )
  VALUES (
    v_user_id,
    v_user_email,
    COALESCE(v_user_name, split_part(v_user_email, '@', 1), 'User'),
    v_tenant_id,
    v_role,
    v_invite.organization_id,
    v_invite.brand_id,
    v_invite.location_id,
    v_coupon_code,
    false,
    CASE
      WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
      ELSE 'not_started'
    END,
    'not_started',
    CASE
      WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
      ELSE 'business_verification'
    END,
    true
  )
  ON CONFLICT (id) DO UPDATE
  SET email = EXCLUDED.email,
      full_name = COALESCE(NULLIF(public.profiles.full_name, ''), EXCLUDED.full_name),
      tenant_id = COALESCE(EXCLUDED.tenant_id, public.profiles.tenant_id),
      role = EXCLUDED.role,
      organization_id = COALESCE(EXCLUDED.organization_id, public.profiles.organization_id),
      brand_id = COALESCE(EXCLUDED.brand_id, public.profiles.brand_id),
      location_id = COALESCE(EXCLUDED.location_id, public.profiles.location_id),
      coupon_code = COALESCE(EXCLUDED.coupon_code, public.profiles.coupon_code),
      business_verification_status = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'verified'
        ELSE public.profiles.business_verification_status
      END,
      onboarding_current_step = CASE
        WHEN v_role = 'tenant_super_admin' AND v_business_verification_required IS FALSE THEN 'hierarchy_setup'
        ELSE public.profiles.onboarding_current_step
      END,
      is_active = true,
      updated_at = now();

  UPDATE public.invitations
  SET accepted_at = now(),
      accepted_by = v_user_id,
      role = v_role,
      tenant_id = COALESCE(tenant_id, v_tenant_id),
      metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
        'business_verification_required', v_business_verification_required,
        'coupon_code', v_coupon_code
      )
  WHERE id = v_invite.id
    AND accepted_at IS NULL
    AND closed_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid, expired, or already-accepted invitation';
  END IF;

  SELECT
    role,
    tenant_id,
    organization_id,
    brand_id,
    location_id
  INTO v_profile_context
  FROM public.profiles
  WHERE id = v_user_id;

  PERFORM public.sync_auth_metadata_from_profile(v_user_id);

  RETURN jsonb_build_object(
    'success', true,
    'role', v_profile_context.role,
    'tenant_id', v_profile_context.tenant_id,
    'organization_id', v_profile_context.organization_id,
    'brand_id', v_profile_context.brand_id,
    'location_id', v_profile_context.location_id,
    'business_verification_required', v_business_verification_required,
    'coupon_code', v_coupon_code
  );
END;
$$;

-- Source: 20260724000003_product_module_production_hardening.sql
CREATE OR REPLACE FUNCTION public.enforce_products_product_id_unique()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.deleted_at IS NULL AND NULLIF(btrim(COALESCE(NEW.product_id, '')), '') IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM public.products p
      WHERE p.id IS DISTINCT FROM NEW.id
        AND p.deleted_at IS NULL
        AND lower(btrim(p.product_id)) = lower(btrim(NEW.product_id))
    ) THEN
      RAISE EXCEPTION 'Product ID "%" is already in use. Choose a different one.', NEW.product_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

-- ===== Product-specific audit and price history =====

CREATE OR REPLACE FUNCTION public.audit_product_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_action text;
BEGIN
  v_action := CASE TG_OP
    WHEN 'INSERT' THEN 'product_created'
    WHEN 'UPDATE' THEN 'product_updated'
    ELSE 'product_deleted'
  END;

  INSERT INTO public.audit_logs (
    organization_id, brand_id, location_id, user_id, action, table_name,
    record_id, old_data, new_data, created_at
  ) VALUES (
    COALESCE(NEW.organization_id, OLD.organization_id),
    COALESCE(NEW.brand_id, OLD.brand_id),
    COALESCE(NEW.location_id, OLD.location_id),
    auth.uid(),
    v_action,
    'products',
    COALESCE(NEW.id, OLD.id),
    CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
    CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END,
    now()
  );

  RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE OR REPLACE FUNCTION public.capture_product_price_history()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_history jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.average_price := COALESCE(NEW.average_price, NEW.latest_price);
    NEW.price_history := COALESCE(NEW.price_history, '[]'::jsonb);
    RETURN NEW;
  END IF;

  IF NEW.latest_price IS DISTINCT FROM OLD.latest_price THEN
    v_history := COALESCE(OLD.price_history, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'price', OLD.latest_price,
      'changed_at', now(),
      'changed_by', auth.uid(),
      'source', 'product_update'
    ));

    NEW.price_history := v_history;
    SELECT avg((entry->>'price')::numeric)
      INTO NEW.average_price
    FROM jsonb_array_elements(v_history || jsonb_build_array(jsonb_build_object('price', NEW.latest_price))) entry
    WHERE NULLIF(entry->>'price', '') IS NOT NULL;
  END IF;

  NEW.version_number := COALESCE(OLD.version_number, 1) + 1;
  RETURN NEW;
END;
$$;

-- ===== Rich taxonomy restored =====

DROP FUNCTION IF EXISTS public.derive_product_category_type(text, text, text);

CREATE OR REPLACE FUNCTION public.derive_product_category_type(
  p_accounting_category text,
  p_category text,
  p_name text
)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  WITH src AS (
    SELECT
      lower(COALESCE(p_accounting_category, '')) AS accounting,
      lower(COALESCE(p_category, '')) AS category,
      lower(COALESCE(p_name, '')) AS name
  )
  SELECT CASE
    WHEN accounting = '5230' OR category ~ '(beer|ale|lager|ipa|stout|porter|pilsner|cider|seltzer)' OR name ~ '(beer|ale|lager|ipa|stout|porter|pilsner|cider|seltzer)' THEN 'Beer'
    WHEN accounting = '5240' OR category ~ '(wine|pinot|chardonnay|cabernet|merlot|sauvignon|riesling|prosecco|champagne|moscato|malbec|zinfandel)' OR name ~ '(wine|pinot|chardonnay|cabernet|merlot|sauvignon|riesling|prosecco|champagne|moscato|malbec|zinfandel)' THEN 'Wine'
    WHEN accounting = '5220' OR category ~ '(liquor|spirit|vodka|gin|rum|tequila|whiskey|whisky|bourbon|scotch|brandy|cognac|mezcal|liqueur)' OR name ~ '(liquor|spirit|vodka|gin|rum|tequila|whiskey|whisky|bourbon|scotch|brandy|cognac|mezcal|liqueur)' THEN 'Liquor'
    WHEN accounting IN ('5200','5210') OR category ~ '(n-a bev|n/a bev|na bev|non[- ]?alcohol|beverage|soda|juice|tea|coffee|lemonade|water|fountain|syrup)' OR name ~ '(n-a bev|n/a bev|na bev|non[- ]?alcohol|beverage|soda|juice|tea|coffee|lemonade|water|fountain|syrup)' THEN 'N-A Bev'
    WHEN accounting = '5300' OR category ~ '(retail|merchandise|apparel|shirt|hat|gift ?card|merch)' OR name ~ '(retail|merchandise|apparel|shirt|hat|gift ?card|merch)' THEN 'Retail'
    WHEN accounting LIKE '51%' OR accounting IN ('food','food_cogs','5100') OR category ~ '(bakery|meat|poultry|seafood|dairy|produce|frozen|grocery|food)' THEN 'Food'
    ELSE 'Other'
  END
  FROM src;
$$;

DROP FUNCTION IF EXISTS public.product_accounting_category_for_type(text, text);

CREATE OR REPLACE FUNCTION public.product_accounting_category_for_type(p_category_type text, p_category text DEFAULT NULL)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE COALESCE(NULLIF(btrim(p_category_type), ''), 'Other')
    WHEN 'Beer' THEN '5230'
    WHEN 'Wine' THEN '5240'
    WHEN 'Liquor' THEN '5220'
    WHEN 'N-A Bev' THEN '5210'
    WHEN 'Retail' THEN '5300'
    WHEN 'Food' THEN CASE
      WHEN lower(COALESCE(p_category, '')) LIKE '%poultry%' THEN '5120'
      WHEN lower(COALESCE(p_category, '')) LIKE '%seafood%' THEN '5130'
      WHEN lower(COALESCE(p_category, '')) LIKE '%dairy%' THEN '5140'
      WHEN lower(COALESCE(p_category, '')) LIKE '%produce%' THEN '5150'
      WHEN lower(COALESCE(p_category, '')) LIKE '%frozen%' THEN '5160'
      WHEN lower(COALESCE(p_category, '')) LIKE '%grocery%' THEN '5170'
      ELSE '5110'
    END
    ELSE '5110'
  END;
$$;

CREATE OR REPLACE FUNCTION public.find_duplicate_products(
  p_organization_id uuid,
  p_name text,
  p_limit integer DEFAULT 10
)
RETURNS TABLE (id uuid, product_id text, name text, similarity numeric)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT p.id, p.product_id, p.name,
         CASE
           WHEN lower(p.name) = lower(COALESCE(p_name, '')) THEN 1::numeric
           WHEN lower(p.name) LIKE '%' || lower(COALESCE(p_name, '')) || '%'
             OR lower(COALESCE(p_name, '')) LIKE '%' || lower(p.name) || '%' THEN 0.85::numeric
           ELSE 0.5::numeric
         END AS similarity
  FROM public.products p
  WHERE p.organization_id = p_organization_id
    AND p.deleted_at IS NULL
    AND NULLIF(btrim(COALESCE(p_name, '')), '') IS NOT NULL
    AND (
      lower(p.name) = lower(p_name)
      OR lower(p.name) LIKE '%' || lower(p_name) || '%'
      OR lower(p_name) LIKE '%' || lower(p.name) || '%'
    )
    AND public.reference_scope_visible(p.organization_id, p.brand_id, p.location_id, p.deleted_at)
  ORDER BY similarity DESC, p.name
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 10), 1), 50);
$$;

CREATE OR REPLACE FUNCTION public.restore_product(p_product_id uuid)
RETURNS public.products
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
BEGIN
  SELECT * INTO v_product
  FROM public.products
  WHERE id = p_product_id
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to restore this product';
  END IF;

  UPDATE public.products
     SET deleted_at = NULL,
         deleted_by = NULL,
         restored_at = now(),
         restored_by = auth.uid(),
         status = COALESCE(NULLIF(status, ''), 'active'),
         updated_at = now()
   WHERE id = p_product_id
   RETURNING * INTO v_product;

  UPDATE public.inventory
     SET deleted_at = NULL,
         deleted_by = NULL,
         updated_at = now()
   WHERE organization_id = v_product.organization_id
     AND (
       internal_product_id = v_product.id
       OR (NULLIF(product_id, '') IS NOT NULL AND product_id = v_product.product_id)
     );

  RETURN v_product;
END;
$$;

CREATE OR REPLACE FUNCTION public.upsert_product_barcode(
  p_product_id uuid,
  p_barcode text,
  p_symbology text DEFAULT 'unknown'
)
RETURNS public.product_barcodes
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_row public.product_barcodes%ROWTYPE;
BEGIN
  SELECT * INTO v_product FROM public.products WHERE id = p_product_id AND deleted_at IS NULL;
  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;
  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to edit product barcodes';
  END IF;
  IF NULLIF(btrim(COALESCE(p_barcode, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Barcode is required';
  END IF;

  INSERT INTO public.product_barcodes (
    organization_id, brand_id, location_id, product_id, barcode, symbology, created_by, deleted_at, deleted_by
  ) VALUES (
    v_product.organization_id, v_product.brand_id, v_product.location_id, v_product.id,
    btrim(p_barcode), COALESCE(NULLIF(btrim(p_symbology), ''), 'unknown'), auth.uid(), NULL, NULL
  )
  ON CONFLICT (organization_id, barcode)
  DO UPDATE SET
    product_id = EXCLUDED.product_id,
    brand_id = EXCLUDED.brand_id,
    location_id = EXCLUDED.location_id,
    symbology = EXCLUDED.symbology,
    deleted_at = NULL,
    deleted_by = NULL
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;

CREATE OR REPLACE FUNCTION public.remove_product_barcode(p_barcode_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_row public.product_barcodes%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.product_barcodes WHERE id = p_barcode_id AND deleted_at IS NULL;
  IF v_row.id IS NULL THEN
    RETURN true;
  END IF;
  IF NOT public.product_write_allowed(v_row.organization_id, v_row.brand_id, v_row.location_id) THEN
    RAISE EXCEPTION 'Not authorized to remove product barcodes';
  END IF;
  UPDATE public.product_barcodes
     SET deleted_at = now(), deleted_by = auth.uid()
   WHERE id = p_barcode_id;
  RETURN true;
END;
$$;

CREATE OR REPLACE FUNCTION public.verify_vendor_item_mapping(
  p_mapping_id uuid,
  p_conversion_multiplier numeric DEFAULT NULL
)
RETURNS public.vendor_item_mappings
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_mapping public.vendor_item_mappings%ROWTYPE;
BEGIN
  SELECT * INTO v_mapping
  FROM public.vendor_item_mappings
  WHERE id = p_mapping_id
  FOR UPDATE;

  IF v_mapping.id IS NULL THEN
    RAISE EXCEPTION 'Vendor item mapping not found';
  END IF;
  IF NOT public.product_write_allowed(v_mapping.organization_id, NULL, NULL) THEN
    RAISE EXCEPTION 'Not authorized to verify this mapping';
  END IF;

  UPDATE public.vendor_item_mappings
     SET is_verified = true,
         conversion_multiplier = GREATEST(COALESCE(p_conversion_multiplier, conversion_multiplier, 1), 0.0001),
         updated_at = now()
   WHERE id = p_mapping_id
   RETURNING * INTO v_mapping;

  RETURN v_mapping;
END;
$$;

CREATE OR REPLACE FUNCTION public.merge_products(
  p_source_product_id uuid,
  p_target_product_id uuid,
  p_reason text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_source public.products%ROWTYPE;
  v_target public.products%ROWTYPE;
BEGIN
  IF p_source_product_id IS NULL OR p_target_product_id IS NULL OR p_source_product_id = p_target_product_id THEN
    RAISE EXCEPTION 'Source and target products must be different';
  END IF;

  SELECT * INTO v_source FROM public.products WHERE id = p_source_product_id FOR UPDATE;
  SELECT * INTO v_target FROM public.products WHERE id = p_target_product_id FOR UPDATE;

  IF v_source.id IS NULL OR v_target.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;
  IF v_source.organization_id IS DISTINCT FROM v_target.organization_id THEN
    RAISE EXCEPTION 'Products must belong to the same organization';
  END IF;
  IF NOT public.product_write_allowed(v_target.organization_id, v_target.brand_id, v_target.location_id) THEN
    RAISE EXCEPTION 'Not authorized to merge products';
  END IF;

  UPDATE public.inventory
     SET internal_product_id = v_target.id,
         product_id = COALESCE(NULLIF(v_target.product_id, ''), product_id),
         product_name = v_target.name,
         updated_at = now()
   WHERE organization_id = v_source.organization_id
     AND (internal_product_id = v_source.id OR product_id = v_source.product_id);

  UPDATE public.invoice_line_items
     SET internal_product_id = v_target.id
   WHERE organization_id = v_source.organization_id
     AND internal_product_id = v_source.id;

  UPDATE public.vendor_item_mappings
     SET internal_product_id = v_target.id,
         updated_at = now()
   WHERE organization_id = v_source.organization_id
     AND internal_product_id = v_source.id
     AND NOT EXISTS (
       SELECT 1
       FROM public.vendor_item_mappings existing
       WHERE existing.vendor_item_id = vendor_item_mappings.vendor_item_id
         AND existing.internal_product_id = v_target.id
     );

  DELETE FROM public.vendor_item_mappings
   WHERE organization_id = v_source.organization_id
     AND internal_product_id = v_source.id;

  UPDATE public.recipe_ingredients
     SET product_id = v_target.id,
         updated_at = now()
   WHERE organization_id = v_source.organization_id
     AND product_id = v_source.id;

  UPDATE public.products
     SET deleted_at = now(),
         deleted_by = auth.uid(),
         merged_into_product_id = v_target.id,
         merge_metadata = jsonb_build_object('reason', p_reason, 'merged_at', now(), 'merged_by', auth.uid()),
         updated_at = now()
   WHERE id = v_source.id;

  RETURN jsonb_build_object('success', true, 'source_product_id', v_source.id, 'target_product_id', v_target.id);
END;
$$;

CREATE OR REPLACE FUNCTION public.stage_product_import(
  p_organization_id uuid,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL,
  p_file_name text DEFAULT NULL,
  p_file_hash text DEFAULT NULL,
  p_rows jsonb DEFAULT '[]'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_job public.product_import_jobs%ROWTYPE;
  v_row jsonb;
  v_row_number integer := 0;
  v_errors text[];
  v_status text;
  v_valid_count integer := 0;
  v_invalid_count integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;
  IF NOT public.product_write_allowed(p_organization_id, p_brand_id, p_location_id) THEN
    RAISE EXCEPTION 'Not authorized to import products for this scope';
  END IF;
  IF jsonb_typeof(COALESCE(p_rows, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Rows must be a JSON array';
  END IF;

  INSERT INTO public.product_import_jobs (
    organization_id, brand_id, location_id, file_name, file_hash, created_by, summary
  ) VALUES (
    p_organization_id, p_brand_id, p_location_id, p_file_name, p_file_hash, auth.uid(), '{}'::jsonb
  )
  ON CONFLICT (organization_id, file_hash)
  DO UPDATE SET
    file_name = EXCLUDED.file_name,
    brand_id = EXCLUDED.brand_id,
    location_id = EXCLUDED.location_id,
    status = 'validated',
    created_by = auth.uid(),
    created_at = now(),
    committed_at = NULL,
    summary = '{}'::jsonb
  RETURNING * INTO v_job;

  DELETE FROM public.product_import_rows WHERE job_id = v_job.id;

  FOR v_row IN SELECT * FROM jsonb_array_elements(p_rows)
  LOOP
    v_row_number := v_row_number + 1;
    v_errors := ARRAY[]::text[];

    IF NULLIF(btrim(COALESCE(v_row->>'name', v_row->>'Product Name', v_row->>'product_name', '')), '') IS NULL THEN
      v_errors := array_append(v_errors, 'Product name is required');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'product_id', v_row->>'Product ID', v_row->>'sku', '')), '') IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.products p
        WHERE p.organization_id = p_organization_id
          AND p.deleted_at IS NULL
          AND lower(btrim(p.product_id)) = lower(btrim(COALESCE(v_row->>'product_id', v_row->>'Product ID', v_row->>'sku')))
      ) THEN
      v_errors := array_append(v_errors, 'Product ID already exists');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'latest_price', v_row->>'Latest Price', '')), '') IS NOT NULL
      AND btrim(COALESCE(v_row->>'latest_price', v_row->>'Latest Price')) !~ '^(0|[1-9][0-9]*)(\.[0-9]+)?$' THEN
      v_errors := array_append(v_errors, 'Latest price must be a non-negative number');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'is_inventoried', v_row->>'On Inventory', '')), '') IS NOT NULL
      AND lower(btrim(COALESCE(v_row->>'is_inventoried', v_row->>'On Inventory'))) <> ALL (ARRAY['true','false','yes','no','1','0']) THEN
      v_errors := array_append(v_errors, 'On Inventory must be true/false, yes/no, or 1/0');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'is_tax_exempt', v_row->>'Tax Exempt', '')), '') IS NOT NULL
      AND lower(btrim(COALESCE(v_row->>'is_tax_exempt', v_row->>'Tax Exempt'))) <> ALL (ARRAY['true','false','yes','no','1','0']) THEN
      v_errors := array_append(v_errors, 'Tax Exempt must be true/false, yes/no, or 1/0');
    END IF;
    IF NULLIF(btrim(COALESCE(v_row->>'accounting_category', v_row->>'Accounting Category', '')), '') IS NOT NULL
      AND btrim(COALESCE(v_row->>'accounting_category', v_row->>'Accounting Category')) <> ALL (ARRAY[
        'food','beverage','supplies','equipment','packaging','cleaning','other',
        'food_cogs','beverage_cogs','merchandise_cogs',
        '5100','5110','5120','5130','5140','5150','5160','5170',
        '5200','5210','5220','5230','5240','5300'
      ]::text[]) THEN
      v_errors := array_append(v_errors, 'Accounting category is not allowed');
    END IF;

    v_status := CASE WHEN array_length(v_errors, 1) IS NULL THEN 'valid' ELSE 'invalid' END;
    IF v_status = 'valid' THEN
      v_valid_count := v_valid_count + 1;
    ELSE
      v_invalid_count := v_invalid_count + 1;
    END IF;

    INSERT INTO public.product_import_rows (job_id, row_number, payload, status, errors)
    VALUES (v_job.id, v_row_number, v_row, v_status, v_errors);
  END LOOP;

  UPDATE public.product_import_jobs
     SET summary = jsonb_build_object(
       'total_rows', v_row_number,
       'valid_rows', v_valid_count,
       'invalid_rows', v_invalid_count
     )
   WHERE id = v_job.id
   RETURNING * INTO v_job;

  RETURN jsonb_build_object(
    'job_id', v_job.id,
    'summary', v_job.summary,
    'rows', (
      SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.row_number), '[]'::jsonb)
      FROM public.product_import_rows r
      WHERE r.job_id = v_job.id
    )
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.commit_product_import(p_job_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_job public.product_import_jobs%ROWTYPE;
  v_import_row public.product_import_rows%ROWTYPE;
  v_product public.products%ROWTYPE;
  v_committed integer := 0;
  v_skipped integer := 0;
BEGIN
  SELECT * INTO v_job FROM public.product_import_jobs WHERE id = p_job_id FOR UPDATE;
  IF v_job.id IS NULL THEN
    RAISE EXCEPTION 'Product import job not found';
  END IF;
  IF NOT public.product_write_allowed(v_job.organization_id, v_job.brand_id, v_job.location_id) THEN
    RAISE EXCEPTION 'Not authorized to commit this product import';
  END IF;

  FOR v_import_row IN
    SELECT * FROM public.product_import_rows
    WHERE job_id = v_job.id
    ORDER BY row_number
  LOOP
    IF v_import_row.status <> 'valid' THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    INSERT INTO public.products (
      organization_id, brand_id, location_id, product_id, name, description,
      category, accounting_category, report_by_unit, base_unit, latest_price,
      is_inventoried, is_tax_exempt, location_specific, created_by, updated_at
    ) VALUES (
      v_job.organization_id,
      v_job.brand_id,
      v_job.location_id,
      NULLIF(btrim(COALESCE(v_import_row.payload->>'product_id', v_import_row.payload->>'Product ID', v_import_row.payload->>'sku', '')), ''),
      upper(btrim(COALESCE(v_import_row.payload->>'name', v_import_row.payload->>'Product Name', v_import_row.payload->>'product_name'))),
      NULLIF(btrim(COALESCE(v_import_row.payload->>'description', v_import_row.payload->>'Description', '')), ''),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'category', v_import_row.payload->>'Category', '')), ''), 'Uncategorized'),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'accounting_category', v_import_row.payload->>'Accounting Category', '')), ''), '5110'),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'report_by_unit', v_import_row.payload->>'Report By Unit', '')), ''), 'Each'),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'base_unit', v_import_row.payload->>'Base Unit', '')), ''), 'Each'),
      COALESCE(NULLIF(btrim(COALESCE(v_import_row.payload->>'latest_price', v_import_row.payload->>'Latest Price', '')), '')::numeric, 0),
      CASE lower(btrim(COALESCE(v_import_row.payload->>'is_inventoried', v_import_row.payload->>'On Inventory', '')))
        WHEN 'true' THEN true
        WHEN 'yes' THEN true
        WHEN '1' THEN true
        ELSE false
      END,
      CASE lower(btrim(COALESCE(v_import_row.payload->>'is_tax_exempt', v_import_row.payload->>'Tax Exempt', '')))
        WHEN 'true' THEN true
        WHEN 'yes' THEN true
        WHEN '1' THEN true
        ELSE false
      END,
      v_job.location_id IS NOT NULL,
      auth.uid(),
      now()
    )
    RETURNING * INTO v_product;

    UPDATE public.product_import_rows
       SET status = 'committed', product_id = v_product.id
     WHERE id = v_import_row.id;

    IF v_product.is_inventoried THEN
      PERFORM public.set_product_inventory_tracking(v_product.id, true);
    END IF;

    v_committed := v_committed + 1;
  END LOOP;

  UPDATE public.product_import_jobs
     SET status = 'committed',
         committed_at = now(),
         summary = COALESCE(summary, '{}'::jsonb) || jsonb_build_object('committed_rows', v_committed, 'skipped_rows', v_skipped)
   WHERE id = v_job.id;

  RETURN jsonb_build_object('success', true, 'job_id', v_job.id, 'committed_rows', v_committed, 'skipped_rows', v_skipped);
END;
$$;

-- ===== Product write RPCs with one callable update signature =====

DROP FUNCTION IF EXISTS public.update_product_details(uuid, text, text, text, text, text, boolean, boolean, text, text, numeric, boolean);

DROP FUNCTION IF EXISTS public.update_product_details(uuid, text, text, text, text, text, boolean, boolean, text, text, numeric, boolean, numeric, numeric);

DROP FUNCTION IF EXISTS public.create_product_details(text, text, text, text, text, boolean, boolean, text, text, numeric, boolean, uuid, uuid, uuid);

CREATE OR REPLACE FUNCTION public.create_product_details(
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT true,
  p_is_tax_exempt boolean DEFAULT false,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT NULL,
  p_location_specific boolean DEFAULT false,
  p_organization_id uuid DEFAULT NULL,
  p_brand_id uuid DEFAULT NULL,
  p_location_id uuid DEFAULT NULL
)
RETURNS public.products
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_org_id uuid := COALESCE(p_organization_id, public.get_auth_org());
  v_brand_id uuid := p_brand_id;
  v_location_id uuid := p_location_id;
  v_product_id text := NULLIF(btrim(COALESCE(p_restops_product_id, '')), '');
  v_created public.products%ROWTYPE;
  v_needs_approval boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NULLIF(btrim(COALESCE(p_name, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'Organization context is required';
  END IF;

  IF v_brand_id IS NULL OR v_location_id IS NULL THEN
    SELECT COALESCE(v_brand_id, p.brand_id), COALESCE(v_location_id, p.location_id)
      INTO v_brand_id, v_location_id
    FROM public.profiles p
    WHERE p.id = auth.uid()
      AND p.organization_id = v_org_id
      AND p.deleted_at IS NULL;
  END IF;

  IF NOT public.product_write_allowed(v_org_id, v_brand_id, v_location_id) THEN
    RAISE EXCEPTION 'Not authorized to create products for this scope';
  END IF;

  IF v_product_id IS NULL THEN
    v_product_id := public.generate_restops_product_id();
  END IF;

  v_needs_approval := public.get_auth_role() = 'location_manager'
    AND public.get_product_approval_setting(v_org_id);

  INSERT INTO public.products (
    organization_id, brand_id, location_id, product_id, name, description,
    category, accounting_category, is_inventoried, is_tax_exempt,
    report_by_unit, base_unit, latest_price, location_specific,
    pending_approval, pending_action, submitted_by, submitted_at,
    created_by, updated_at
  ) VALUES (
    v_org_id, v_brand_id, v_location_id, v_product_id, upper(btrim(p_name)),
    NULLIF(btrim(COALESCE(p_description, '')), ''),
    NULLIF(btrim(COALESCE(p_category, '')), ''),
    NULLIF(btrim(COALESCE(p_accounting_category, '')), ''),
    COALESCE(p_is_inventoried, false), COALESCE(p_is_tax_exempt, false),
    NULLIF(btrim(COALESCE(p_report_by_unit, '')), ''),
    NULLIF(btrim(COALESCE(p_base_unit, '')), ''),
    COALESCE(p_latest_price, 0), COALESCE(p_location_specific, false),
    v_needs_approval, CASE WHEN v_needs_approval THEN 'create' ELSE NULL END,
    CASE WHEN v_needs_approval THEN auth.uid() ELSE NULL END,
    CASE WHEN v_needs_approval THEN now() ELSE NULL END,
    auth.uid(), now()
  )
  RETURNING * INTO v_created;

  IF COALESCE(p_is_inventoried, false) THEN
    PERFORM public.set_product_inventory_tracking(v_created.id, true);
    SELECT * INTO v_created FROM public.products WHERE id = v_created.id;
  END IF;

  RETURN v_created;
END;
$$;

CREATE OR REPLACE FUNCTION public.update_product_details(
  p_product_id uuid,
  p_name text,
  p_restops_product_id text DEFAULT NULL,
  p_description text DEFAULT NULL,
  p_category text DEFAULT NULL,
  p_accounting_category text DEFAULT NULL,
  p_is_inventoried boolean DEFAULT NULL,
  p_is_tax_exempt boolean DEFAULT NULL,
  p_report_by_unit text DEFAULT NULL,
  p_base_unit text DEFAULT NULL,
  p_latest_price numeric DEFAULT NULL,
  p_location_specific boolean DEFAULT NULL,
  p_report_unit_quantity numeric DEFAULT NULL,
  p_report_unit_source_price numeric DEFAULT NULL,
  p_expected_version integer DEFAULT NULL
)
RETURNS public.products
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product public.products%ROWTYPE;
  v_updated public.products%ROWTYPE;
  v_category text;
  v_accounting_category text;
  v_category_changed boolean;
  v_needs_approval boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT * INTO v_product
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_product.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;
  IF p_expected_version IS NOT NULL AND p_expected_version <> COALESCE(v_product.version_number, 1) THEN
    RAISE EXCEPTION 'Product was changed by another session. Refresh and try again.';
  END IF;
  IF NOT public.product_write_allowed(v_product.organization_id, v_product.brand_id, v_product.location_id) THEN
    RAISE EXCEPTION 'Not authorized to update this product';
  END IF;
  IF NULLIF(btrim(p_name), '') IS NULL THEN
    RAISE EXCEPTION 'Product name is required';
  END IF;

  v_category := NULLIF(btrim(COALESCE(p_category, '')), '');
  v_accounting_category := NULLIF(btrim(COALESCE(p_accounting_category, '')), '');
  v_category_changed :=
    COALESCE(v_product.category, '') IS DISTINCT FROM COALESCE(v_category, '')
    OR COALESCE(v_product.accounting_category, '') IS DISTINCT FROM COALESCE(v_accounting_category, '');
  v_needs_approval := public.get_auth_role() = 'location_manager'
    AND public.get_product_approval_setting(v_product.organization_id)
    AND NOT COALESCE(v_product.pending_approval, false);

  UPDATE public.products
     SET name = upper(btrim(p_name)),
         product_id = NULLIF(btrim(COALESCE(p_restops_product_id, '')), ''),
         description = NULLIF(btrim(COALESCE(p_description, '')), ''),
         category = v_category,
         accounting_category = v_accounting_category,
         is_tax_exempt = COALESCE(p_is_tax_exempt, false),
         report_by_unit = NULLIF(btrim(COALESCE(p_report_by_unit, '')), ''),
         base_unit = NULLIF(btrim(COALESCE(p_base_unit, '')), ''),
         latest_price = COALESCE(p_latest_price, 0),
         location_specific = COALESCE(p_location_specific, false),
         report_unit_quantity = GREATEST(COALESCE(p_report_unit_quantity, report_unit_quantity, 1), 0.0001),
         report_unit_source_price = COALESCE(p_report_unit_source_price, report_unit_source_price, p_latest_price, latest_price, 0),
         pending_approval = CASE WHEN v_needs_approval THEN true ELSE pending_approval END,
         pending_action = CASE WHEN v_needs_approval THEN 'update' ELSE pending_action END,
         pending_snapshot = CASE WHEN v_needs_approval THEN to_jsonb(v_product) ELSE pending_snapshot END,
         submitted_by = CASE WHEN v_needs_approval THEN auth.uid() ELSE submitted_by END,
         submitted_at = CASE WHEN v_needs_approval THEN now() ELSE submitted_at END,
         category_source = CASE WHEN v_category_changed THEN 'manual' ELSE category_source END,
         category_review_status = CASE WHEN v_category_changed THEN 'approved' ELSE category_review_status END,
         category_reviewed_at = CASE WHEN v_category_changed THEN now() ELSE category_reviewed_at END,
         category_reviewed_by = CASE WHEN v_category_changed THEN auth.uid() ELSE category_reviewed_by END,
         suggested_category = CASE WHEN v_category_changed THEN NULL ELSE suggested_category END,
         suggested_category_type = CASE WHEN v_category_changed THEN NULL ELSE suggested_category_type END,
         suggested_accounting_category = CASE WHEN v_category_changed THEN NULL ELSE suggested_accounting_category END,
         category_reason = CASE WHEN v_category_changed THEN NULL ELSE category_reason END,
         updated_at = now()
   WHERE id = p_product_id
   RETURNING * INTO v_updated;

  IF p_is_inventoried IS NOT NULL AND p_is_inventoried IS DISTINCT FROM v_product.is_inventoried THEN
    PERFORM public.set_product_inventory_tracking(p_product_id, p_is_inventoried);
    SELECT * INTO v_updated FROM public.products WHERE id = p_product_id;
  ELSIF p_is_inventoried IS NOT NULL THEN
    UPDATE public.products
       SET is_inventoried = p_is_inventoried, updated_at = now()
     WHERE id = p_product_id
     RETURNING * INTO v_updated;
  END IF;

  UPDATE public.inventory
     SET unit_cost = COALESCE(v_updated.latest_price, unit_cost),
         current_unit = COALESCE(NULLIF(v_updated.report_by_unit, ''), current_unit),
         report_by = COALESCE(NULLIF(v_updated.report_by_unit, ''), report_by),
         category = COALESCE(NULLIF(v_updated.category, ''), category),
         accounting_category = COALESCE(NULLIF(v_updated.accounting_category, ''), accounting_category),
         updated_at = now()
   WHERE organization_id = v_updated.organization_id
     AND deleted_at IS NULL
     AND (internal_product_id = v_updated.id OR product_id = v_updated.product_id);

  RETURN v_updated;
END;
$$;

DROP FUNCTION IF EXISTS public.soft_delete_product_safe(uuid);

CREATE OR REPLACE FUNCTION public.soft_delete_product_safe(p_product_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_existing public.products%ROWTYPE;
  v_needs_approval boolean;
BEGIN
  SELECT * INTO v_existing
  FROM public.products
  WHERE id = p_product_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_existing.id IS NULL THEN
    RAISE EXCEPTION 'Product not found';
  END IF;
  IF NOT public.product_write_allowed(v_existing.organization_id, v_existing.brand_id, v_existing.location_id) THEN
    RAISE EXCEPTION 'Not authorized to delete this product';
  END IF;

  v_needs_approval := public.get_auth_role() = 'location_manager'
    AND public.get_product_approval_setting(v_existing.organization_id)
    AND NOT COALESCE(v_existing.pending_approval, false);

  IF v_needs_approval THEN
    UPDATE public.products
       SET pending_approval = true,
           pending_action = 'delete',
           pending_snapshot = to_jsonb(v_existing),
           submitted_by = auth.uid(),
           submitted_at = now(),
           updated_at = now()
     WHERE id = p_product_id;

    RETURN jsonb_build_object('success', true, 'pending_approval', true);
  END IF;

  UPDATE public.products
     SET deleted_at = now(), deleted_by = auth.uid(), updated_at = now()
   WHERE id = p_product_id;

  UPDATE public.inventory
     SET deleted_at = now(), deleted_by = auth.uid(), updated_at = now()
   WHERE organization_id = v_existing.organization_id
     AND deleted_at IS NULL
     AND (internal_product_id = v_existing.id OR product_id = v_existing.product_id);

  RETURN jsonb_build_object('success', true, 'pending_approval', false);
END;
$$;

CREATE OR REPLACE FUNCTION public.recalculate_recipe_costs_on_price_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE public.recipes r
     SET total_cost = COALESCE((
           SELECT sum(COALESCE(ri.quantity, 0) * COALESCE(NEW.latest_price, 0))
           FROM public.recipe_ingredients ri
           WHERE ri.recipe_id = r.id
             AND ri.product_id = NEW.id
         ), r.total_cost),
         cost_per_serving = CASE
           WHEN COALESCE(r.yield_quantity, 0) > 0 THEN COALESCE((
             SELECT sum(COALESCE(ri.quantity, 0) * COALESCE(NEW.latest_price, 0))
             FROM public.recipe_ingredients ri
             WHERE ri.recipe_id = r.id
               AND ri.product_id = NEW.id
           ), r.total_cost) / r.yield_quantity
           ELSE r.cost_per_serving
         END,
         updated_at = now()
   WHERE EXISTS (
     SELECT 1 FROM public.recipe_ingredients ri
     WHERE ri.recipe_id = r.id
       AND ri.product_id = NEW.id
   );

  UPDATE public.recipes r
     SET total_cost = public.calculate_recipe_cost(r.id),
         updated_at = now()
   WHERE r.ingredients @> jsonb_build_array(jsonb_build_object('product_id', NEW.id::text));

  RETURN NEW;
END;
$$;

-- Source: 20260724000003_vendor_self_approval_prevention.sql
-- Mirrors enforce_invoice_approval_authorization's existing "submitters cannot approve their
-- own invoices" rule (already live for invoices) -- vendors never got the same rule, so whoever
-- created a vendor could also approve it themselves. Scoped to entering 'approved' specifically,
-- same as the invoice version: rejecting/suspending your own submission isn't a self-approval
-- concern, only approving it is.
CREATE OR REPLACE FUNCTION public.enforce_vendor_approval_authorization()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.approval_status IN ('pending_approval', 'approved', 'suspended', 'rejected') THEN
      IF NEW.approval_status = 'approved' AND NEW.created_by IS NOT NULL AND NEW.created_by = auth.uid() THEN
        RAISE EXCEPTION 'Vendor submitters cannot approve their own vendors';
      END IF;

      PERFORM public.assert_can_approve_vendor_scope(
        NEW.organization_id,
        NEW.brand_id,
        NEW.location_id
      );
    END IF;

    RETURN NEW;
  END IF;

  IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN
    IF NEW.approval_status = 'approved' AND NEW.created_by IS NOT NULL AND NEW.created_by = auth.uid() THEN
      RAISE EXCEPTION 'Vendor submitters cannot approve their own vendors';
    END IF;

    PERFORM public.assert_can_approve_vendor_scope(
      NEW.organization_id,
      NEW.brand_id,
      NEW.location_id
    );
  END IF;

  RETURN NEW;
END;
$function$;

-- Source: 20260724000004_fix_vendor_schema_for_acceptance_tests.sql
-- 2. Fix submit_vendor_banking_via_link which was trying to set updated_at on vendors table

CREATE OR REPLACE FUNCTION public.submit_vendor_banking_via_link(p_token text, p_account text, p_routing text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_token public.vendor_banking_link_tokens%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_store_result jsonb;
  v_reason text;
BEGIN
  SELECT * INTO v_token
  FROM public.vendor_banking_link_tokens
  WHERE token = btrim(COALESCE(p_token, ''))
    AND status = 'pending'
    AND expires_at > now()
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_token.id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired banking link';
  END IF;

  IF regexp_replace(COALESCE(p_account, ''), '\D', '', 'g') !~ '^\d{4,17}$' THEN
    RAISE EXCEPTION 'A valid bank account number (4-17 digits) is required';
  END IF;

  IF regexp_replace(COALESCE(p_routing, ''), '\D', '', 'g') !~ '^\d{9}$' THEN
    RAISE EXCEPTION 'A valid 9-digit routing number is required';
  END IF;

  IF v_token.intent = 'replace' THEN
    v_reason := 'vendor_requested_update';
  ELSIF EXISTS (
    SELECT 1
    FROM public.vendor_banking_details existing
    WHERE existing.vendor_id = v_token.vendor_id
      AND existing.is_default = true
      AND existing.is_active = true
      AND existing.deleted_at IS NULL
  ) THEN
    v_reason := 'admin_correction';
  ELSE
    v_reason := 'onboarding';
  END IF;

  INSERT INTO public.vendor_banking_details (
    vendor_id,
    organization_id,
    brand_id,
    location_id,
    verification_state,
    callback_status,
    is_default,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_token.organization_id,
    v_token.brand_id,
    v_token.location_id,
    'pending',
    'pending',
    false,
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_bank;

  v_store_result := public.store_vendor_banking_secret(v_bank.id, p_account, p_routing);

  INSERT INTO public.vendor_banking_change_requests (
    vendor_id,
    banking_detail_id,
    request_reason,
    requested_by,
    callback_phone_source,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_bank.id,
    v_reason,
    v_token.created_by,
    'on_file_contact',
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_request;

  UPDATE public.vendor_banking_link_tokens
     SET status = 'submitted',
         submitted_at = now(),
         updated_at = now()
   WHERE id = v_token.id;

  UPDATE public.vendors
     SET onboarding_status = 'banking_submitted'
   WHERE id = v_token.vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, from_status, to_status, actor_type, metadata
  ) VALUES (
    v_token.vendor_id,
    'banking_submitted',
    NULL,
    'banking_submitted',
    'vendor',
    jsonb_build_object(
      'banking_row_id', v_bank.id,
      'change_request_id', v_request.id,
      'token_id', v_token.id,
      'intent', v_token.intent
    )
  );

  IF v_token.created_by IS NOT NULL THEN
    INSERT INTO public.notifications (
      user_id,
      organization_id,
      brand_id,
      location_id,
      title,
      message,
      type,
      is_read,
      metadata
    ) VALUES (
      v_token.created_by,
      v_token.organization_id,
      v_token.brand_id,
      v_token.location_id,
      'Vendor banking callback required',
      'A vendor submitted banking details. Call the phone number already on file before paying this account.',
      'system',
      false,
      jsonb_build_object(
        'vendor_id', v_token.vendor_id,
        'banking_row_id', v_bank.id,
        'change_request_id', v_request.id,
        'token_id', v_token.id,
        'intent', v_token.intent
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_token.vendor_id,
    'banking_row_id', v_bank.id,
    'banking_change_request_id', v_request.id,
    'banking_secret_id', v_store_result->>'banking_secret_id',
    'account_last4', v_store_result->>'account_last4',
    'intent', v_token.intent,
    'is_default', v_bank.is_default,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status
  );
END;
$function$;

-- Source: 20260724000004_vendor_archive_mechanism.sql
-- Thin convenience wrappers over a plain UPDATE (which RLS above already permits) so archiving
-- gets the same vendor_onboarding_events audit trail every other significant vendor action
-- already has. Deliberately no business-rule gate (e.g. blocking archive with open invoices) --
-- that's a product decision, not something to invent here.
CREATE OR REPLACE FUNCTION public.archive_vendor(p_vendor_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_vendor public.vendors%ROWTYPE;
BEGIN
  -- SECURITY DEFINER's internal UPDATE bypasses RLS, so this needs its own explicit scope
  -- check -- same floor operational_vendors_update already uses.
  SELECT * INTO v_vendor FROM public.vendors WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, v_vendor.deleted_at, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  IF v_vendor.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Vendor is already archived';
  END IF;

  UPDATE public.vendors SET deleted_at = now() WHERE id = p_vendor_id;

  INSERT INTO public.vendor_onboarding_events (vendor_id, event_type, actor_id, actor_type)
  VALUES (p_vendor_id, 'vendor_archived', auth.uid(), 'admin');
END;
$function$;

CREATE OR REPLACE FUNCTION public.restore_vendor(p_vendor_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_vendor public.vendors%ROWTYPE;
BEGIN
  -- deleted_at IS NOT NULL, so reference_scope_writable would reject it outright (a soft-deleted
  -- row is never writable) -- check org/brand/location authorization directly instead, the same
  -- way the scope helper would for an active row.
  SELECT * INTO v_vendor FROM public.vendors WHERE id = p_vendor_id;

  IF v_vendor.id IS NULL THEN
    RAISE EXCEPTION 'Vendor not found';
  END IF;

  IF v_vendor.deleted_at IS NULL THEN
    RAISE EXCEPTION 'Vendor is not archived';
  END IF;

  IF NOT public.reference_scope_writable(v_vendor.organization_id, v_vendor.brand_id, v_vendor.location_id, NULL, 'location_manager') THEN
    RAISE EXCEPTION 'Access denied';
  END IF;

  UPDATE public.vendors SET deleted_at = NULL WHERE id = p_vendor_id;

  INSERT INTO public.vendor_onboarding_events (vendor_id, event_type, actor_id, actor_type)
  VALUES (p_vendor_id, 'vendor_restored', auth.uid(), 'admin');
END;
$function$;

-- Source: 20260724000005_add_audit_columns_to_vendors.sql
-- 2. Restore updated_at and also add updated_by to submit_vendor_banking_via_link
CREATE OR REPLACE FUNCTION public.submit_vendor_banking_via_link(p_token text, p_account text, p_routing text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_token public.vendor_banking_link_tokens%ROWTYPE;
  v_bank public.vendor_banking_details%ROWTYPE;
  v_request public.vendor_banking_change_requests%ROWTYPE;
  v_store_result jsonb;
  v_reason text;
BEGIN
  SELECT * INTO v_token
  FROM public.vendor_banking_link_tokens
  WHERE token = btrim(COALESCE(p_token, ''))
    AND status = 'pending'
    AND expires_at > now()
    AND deleted_at IS NULL
  FOR UPDATE;

  IF v_token.id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired banking link';
  END IF;

  IF regexp_replace(COALESCE(p_account, ''), '\D', '', 'g') !~ '^\d{4,17}$' THEN
    RAISE EXCEPTION 'A valid bank account number (4-17 digits) is required';
  END IF;

  IF regexp_replace(COALESCE(p_routing, ''), '\D', '', 'g') !~ '^\d{9}$' THEN
    RAISE EXCEPTION 'A valid 9-digit routing number is required';
  END IF;

  IF v_token.intent = 'replace' THEN
    v_reason := 'vendor_requested_update';
  ELSIF EXISTS (
    SELECT 1
    FROM public.vendor_banking_details existing
    WHERE existing.vendor_id = v_token.vendor_id
      AND existing.is_default = true
      AND existing.is_active = true
      AND existing.deleted_at IS NULL
  ) THEN
    v_reason := 'admin_correction';
  ELSE
    v_reason := 'onboarding';
  END IF;

  INSERT INTO public.vendor_banking_details (
    vendor_id,
    organization_id,
    brand_id,
    location_id,
    verification_state,
    callback_status,
    is_default,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_token.organization_id,
    v_token.brand_id,
    v_token.location_id,
    'pending',
    'pending',
    false,
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_bank;

  v_store_result := public.store_vendor_banking_secret(v_bank.id, p_account, p_routing);

  INSERT INTO public.vendor_banking_change_requests (
    vendor_id,
    banking_detail_id,
    request_reason,
    requested_by,
    callback_phone_source,
    created_by,
    updated_by
  ) VALUES (
    v_token.vendor_id,
    v_bank.id,
    v_reason,
    v_token.created_by,
    'on_file_contact',
    v_token.created_by,
    v_token.created_by
  )
  RETURNING * INTO v_request;

  UPDATE public.vendor_banking_link_tokens
     SET status = 'submitted',
         submitted_at = now(),
         updated_at = now()
   WHERE id = v_token.id;

  UPDATE public.vendors
     SET onboarding_status = 'banking_submitted',
         updated_at = now(),
         updated_by = v_token.created_by
   WHERE id = v_token.vendor_id
     AND COALESCE(onboarding_status, 'invited') NOT IN ('active', 'completed', 'rejected');

  INSERT INTO public.vendor_onboarding_events (
    vendor_id, event_type, from_status, to_status, actor_type, metadata
  ) VALUES (
    v_token.vendor_id,
    'banking_submitted',
    NULL,
    'banking_submitted',
    'vendor',
    jsonb_build_object(
      'banking_row_id', v_bank.id,
      'change_request_id', v_request.id,
      'token_id', v_token.id,
      'intent', v_token.intent
    )
  );

  IF v_token.created_by IS NOT NULL THEN
    INSERT INTO public.notifications (
      user_id,
      organization_id,
      brand_id,
      location_id,
      title,
      message,
      type,
      is_read,
      metadata
    ) VALUES (
      v_token.created_by,
      v_token.organization_id,
      v_token.brand_id,
      v_token.location_id,
      'Vendor banking callback required',
      'A vendor submitted banking details. Call the phone number already on file before paying this account.',
      'system',
      false,
      jsonb_build_object(
        'vendor_id', v_token.vendor_id,
        'banking_row_id', v_bank.id,
        'change_request_id', v_request.id,
        'token_id', v_token.id,
        'intent', v_token.intent
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'vendor_id', v_token.vendor_id,
    'banking_row_id', v_bank.id,
    'banking_change_request_id', v_request.id,
    'banking_secret_id', v_store_result->>'banking_secret_id',
    'account_last4', v_store_result->>'account_last4',
    'intent', v_token.intent,
    'is_default', v_bank.is_default,
    'verification_state', v_bank.verification_state,
    'callback_status', v_bank.callback_status
  );
END;
$function$;

-- Source: 20260725000002_client_feedback_issue_suggestions.sql
CREATE OR REPLACE FUNCTION public.touch_platform_feedback_settings_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.touch_client_feedback_submissions_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
